export const DOC_PAGES: DocPage[] = [{"slug":"feature","path":"/docs/feature","title":"Everything it does","description":"Post, follow and reply across Mastodon, Pixelfed, PeerTube, GoToSocial and Akkoma — from the same place your files, calendar and chat already live. No new account. No new app. No…","group":"features","html":"<div align=\"center\"><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/nextcloud.png\" alt=\"\" width=\"72\"><h2 id=\"aloha-social\">Aloha Social</h2>\n<h3 id=\"your-aloha-is-a-fediverse-server\">Your Aloha is a Fediverse server.</h3>\n<p>Post, follow and reply across Mastodon, Pixelfed, PeerTube, GoToSocial and Akkoma —\nfrom the same place your files, calendar and chat already live.\nNo new account. No new app. No algorithm. No advertising.</p>\n</div><p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/home.png\" alt=\"The home timeline\"></p>\n<p>Aloha Social gives every user on your server a real Fediverse identity —\n<code>@you@your.cloud</code> — that anyone on Mastodon can follow, mention and reply to. What you\nwrite leaves your server signed, and lands in their timeline. What they write comes\nback into yours. Nobody else holds it, nobody sells it, and nobody reorders it.</p>\n<p>It is a <strong>partial</strong> implementation of ActivityPub and of the Mastodon client API:\nenough to post, follow, read, converse, moderate and run an instance — and honest\nabout what it is not. Read <a href=\"/docs/feature\">Not implemented yet</a> before you\nmake it somebody&#39;s only Fediverse client.</p>\n<hr>\n","toc":[{"id":"aloha-social","text":"Aloha Social","level":2},{"id":"your-aloha-is-a-fediverse-server","text":"Your Aloha is a Fediverse server.","level":3}],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":[{"path":"/docs/feature-write","title":"✍️ Write","description":"One box, and everything a post can carry.","parent":false},{"path":"/docs/feature-read","title":"📖 Read","description":"My Feed, Local and Global are a switcher above the posts rather than three places to navigate to — one pill slides between them, and the arrow keys move through them. Photos and Videos…","parent":false},{"path":"/docs/feature-converse","title":"🧵 Converse","description":"A post opened from a timeline gets a page of its own: the post, a reply box already pointed at it, the faces behind the boost and favourite counts, and the details a card leaves out — when…","parent":false},{"path":"/docs/feature-discover","title":"🧭 Discover","description":"The sidebar has its own way in: Explore, one collapsible entry holding the hashtags you follow, your lists, and what this server is busy with right now — in that order, because the first…","parent":false},{"path":"/docs/feature-your-profile","title":"👤 Your profile","description":"A profile field naming a web page gets the tick when that page links back with rel=\"me\" — from an <a> anywhere on it or a <link> in its head. The editor says which of your fields are…","parent":false},{"path":"/docs/feature-notifications","title":"🔔 Notifications","description":"A page, not a list of everything. Filters across the top (All, Mentions, Favourites, Boosts, Follows, Polls, Edits), a New line where you left off, and a run of likes of the same post…","parent":false},{"path":"/docs/feature-your-account-your-data","title":"⚙️ Your account, your data","description":"Everything about your account in one page: whether people must ask before they follow you, whether other servers may suggest you and index your public posts, whether this is an automated…","parent":false},{"path":"/docs/feature-on-a-phone-and-in-the-dark","title":"📱 On a phone, and in the dark","description":"Under 600px the avatar moves inside the card, the card takes the width of the screen, the composer's toolbar wraps instead of pushing Post off the edge, and a post's page gives up the…","parent":false},{"path":"/docs/feature-it-is-an-aloha-app-so-it-behaves-like-one","title":"🧩 It is an Aloha app, so it behaves like one","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","parent":false},{"path":"/docs/feature-safety-and-privacy-that-is-the-default","title":"🛡️ Safety, and privacy that is the default","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","parent":false},{"path":"/docs/feature-for-administrators","title":"🏛️ For administrators","description":"Everything in Administration → Aloha Social, in six groups — Overview, Moderation, Sign-ups, Explore and features, Federation and Server — with a search across all of them. It opens on…","parent":false},{"path":"/docs/feature-for-developers","title":"🔑 For developers","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","parent":false},{"path":"/docs/feature-not-implemented-yet","title":"🚧 Not implemented yet","description":"These are absent from the code today, not merely rough edges:","parent":false},{"path":"/docs/feature-quickstart-install-and-develop","title":"📦 Quickstart (install & develop)","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","parent":false},{"path":"/docs/feature--well-known-webfinger-isnt-properly-set-up-troubleshooting","title":"🧭 \".well-known/webfinger isn't properly set up!\" — Troubleshooting","description":"That banner has two quite different causes, and the app now tells them apart.","parent":false},{"path":"/docs/feature-banner-header-upload-troubleshooting","title":"🖼️ Banner / Header upload — Troubleshooting","description":"Banner/header uploads work: the image is stored in the app's document cache, the local actor's cached header is updated, and the change is federated as an actor Update…","parent":false},{"path":"/docs/feature-tests","title":"✅ Tests","description":"Backend and frontend unit tests run without an Aloha server or database.","parent":false},{"path":"/docs/feature-contributing","title":"🛠️ Contributing","description":"This prompts twice and then empties every Aloha Social table. occ social:reset --uninstall additionally drops the tables, migrations, background jobs and app config. See…","parent":false},{"path":"/docs/feature-license","title":"License","description":"Admin guide · User guide · API · occ commands · Architecture · Mastodon compatibility · Bluesky specification","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/feature-write","title":"✍️ Write"},"parent":null},{"slug":"feature-write","path":"/docs/feature-write","title":"✍️ Write","description":"One box, and everything a post can carry.","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/composer.jpg\" alt=\"The composer\"></p>\n<p>One box, and everything a post can carry.</p>\n<ul>\n<li><strong>A place on a post</strong> — the pin in the composer names where a picture was taken,\nfrom the places people here have already posted from or a name you type; the\nmarker under the post opens a page of everything public taken there. Nothing is ever\nsent to a map service to work a location out.</li>\n<li><strong>Say who sees it.</strong> Public, unlisted, followers-only or direct, chosen per post from\nthe default you set once. A reply inherits the audience of the post it answers, and\nstarts addressed to everyone in the conversation rather than to one person.</li>\n<li><strong>Pictures, video and audio.</strong> JPEG, PNG, GIF, WebP, AVIF and <strong>HEIC/HEIF straight\noff an iPhone</strong> (transcoded on the way in), MP4, WebM and QuickTime, MP3, AAC, Opus,\nWAV and FLAC. Video is streamed to storage a chunk at a time, so it gets a <strong>2 GB</strong>\nceiling rather than the 10 MB a picture is held to; where the server has ffmpeg, a\n<code>.mov</code> or an HEVC video is converted to H.264 MP4 afterwards (see below), and an\nH.264 MP4 is never re-encoded.</li>\n<li><strong>And the files people actually have.</strong> PDF, text, Markdown, CSV, ZIP, EPUB, ODF\nand the Office formats ride on a post too (<code>DOCUMENT_MIME_TYPES</code> in\n<code>lib/Service/CacheDocumentService.php</code>), stored as they are and drawn as a card you\npress to download. On the wire they are an ActivityPub <code>Document</code> carrying its mime\ntype, which Mastodon shows as a link and another Aloha shows as a file.</li>\n<li><strong>Every picture is stripped of its metadata</strong> before it is stored or sent — Exif,\nXMP, IPTC, and the GPS coordinates a phone quietly attaches. Done on the container\nrather than by re-encoding, so nothing loses a generation of quality, and the colour\nprofile is deliberately kept.</li>\n<li><strong>Alt text that actually gets written.</strong> Every attachment has a description field,\nand a post carrying an undescribed picture says so before it goes. A nudge, never a\nrefusal.</li>\n<li><strong>A focal point.</strong> Click or drag a crosshair over a picture to say where the subject\nis, so a square crop never cuts somebody&#39;s head off. It federates, so other servers\ncrop it correctly too.</li>\n<li><strong>Seven adjustments</strong>, previewed live and baked into the copy that is posted.</li>\n<li><strong>Polls.</strong> Up to four options, single or multiple choice. Votes federate both ways\nand the new totals come back as an <code>Update</code>.</li>\n<li><strong>Content warnings</strong> that fold the post away — and keep it out of the page entirely\nuntil a reader asks for it.</li>\n<li><strong>Custom emoji.</strong> Type <code>:shortcode:</code> and the post travels with a matching <code>Emoji</code>\ntag, so it renders on servers that have never heard of it.</li>\n<li><strong>A GIF picker with 881 animated emoji in it from the day you install the app</strong>,\nand no Giphy, no Tenor, nobody&#39;s tracker. They are Google&#39;s Noto Animated Emoji,\nCC BY 4.0. Only the <em>list</em> ships — half a gigabyte of pictures does not — so your\nserver fetches each one the first time somebody here uses it and keeps it from\nthen on. The grid points at your own Aloha throughout: no search term leaves\nthe instance and no reader&#39;s browser ever talks to anybody else. An administrator\ncan add their own on top with <code>occ social:gif add</code>, or turn the shipped set off\nwith <code>occ config:app:set social gif_pack --value=0</code>.</li>\n<li><strong>Quote a post</strong>, with the original author&#39;s permission carried on the wire (FEP-044f).</li>\n<li><strong>Say what language it is in</strong>, starting from your Aloha language.</li>\n<li><strong>Send it later.</strong> Pick a time at least five minutes out and Post becomes Schedule.</li>\n<li><strong>A short post as a card.</strong> Anything up to 120 characters, with nothing attached, can\ngo out drawn big on colour — six backgrounds, the first in your own colour. It is\nsent as a picture of the words with the words as its description, and the words stay\nin the post too, so every server shows the card and every reader can still search it\nand hear it read aloud.</li>\n<li><strong><code>/dice</code>, <code>/flip</code> and <code>/pick</code>.</strong> Type <code>/dice</code> (or <code>/dice 20</code>), <code>/flip</code>, or\n<code>/pick pizza, pasta, sushi</code> and the game is played when the post goes out: the dice\ntumble in the composer for half a second and land, and what is posted is plain\ntext — <code>🎲 4</code>, <code>🪙 heads</code>, <code>🎯 pasta</code> — so a Mastodon reader sees the same result.</li>\n<li><strong>Posting feels like posting.</strong> The box answers with a quick sweep of light, and the\nnew post drops into place at the top of the timeline with a glow in your colour,\ninstead of simply being there.</li>\n<li><strong>Mentions and hashtags</strong> typed by hand become real recipients and real tags.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"write","manual":false,"prev":{"path":"/docs/feature","title":"Everything it does"},"next":{"path":"/docs/feature-read","title":"📖 Read"},"parent":null},{"slug":"feature-read","path":"/docs/feature-read","title":"📖 Read","description":"My Feed, Local and Global are a switcher above the posts rather than three places to navigate to — one pill slides between them, and the arrow keys move through them. Photos and Videos…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/photos.jpg\" alt=\"Photos\"></p>\n<p><strong>My Feed</strong>, <strong>Local</strong> and <strong>Global</strong> are a switcher above the posts rather than three\nplaces to navigate to — one pill slides between them, and the arrow keys move through\nthem. <strong>Photos</strong> and <strong>Videos</strong> carry the same switcher, so the pictures of the people\nyou follow, of this instance and of the whole Fediverse are one click apart.</p>\n<img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/post-actions.gif\" alt=\"Hovering a post opens its actions\" width=\"680\"><p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/interests.png\" alt=\"For you in the settings\"></p>\n<ul>\n<li><strong>Bluesky</strong> — every account is a Bluesky account too, hosted here: <code>alice.&lt;your host&gt;</code> resolves to a\n<code>did:plc</code> identity (or a domain you own, as your custom handle), every public post goes to Bluesky as it is made (cut to 300 characters with a link\nwhen it is longer, the first four pictures with it, a video made into a Bluesky video by Bluesky&#39;s\nvideo service, a content warning as a self-label), and a relay crawls the instance&#39;s firehose. The\nother way too: follow <code>alice.bsky.social</code> by its bare handle and read it in your home feed, badged,\nits videos playing here; your likes and boosts reach Bluesky, and their follows, likes, replies and\nmentions reach your Activities. Bluesky apps sign in here with Bluesky sign-in, or with an app\npassword made in your settings, and post videos as they would on Bluesky. A Bluesky account of your\nown moves here with its followers and its posts — from Bluesky, from Bridgy Fed&#39;s bridge of your Fediverse account,\nor with any migration tool — and can move away again. Switched on by the administrator once the requirements\nare met; see <a href=\"/docs/atproto\">docs/Atproto-Compatibility.md</a> for what is done and\nwhat is next.</li>\n<li><strong>For you</strong> — the second feed in the switcher, right after My Feed, made of the hashtags you actually\nread. Aloha Social notices what you stay on, what you scroll past, and what you like,\nboost, reply to, bookmark and open, and keeps a list of hashtags from it; the feed\nis the last week&#39;s posts carrying them, the best matches and the freshest first, no\nauthor allowed to fill it, and now and then a hashtag that often travels with yours.\nEvery post says why it is there, and <strong>Less like this</strong> in its menu takes it out.\n<strong>Photos</strong>, <strong>Videos</strong> and <strong>Shorts</strong> offer it too, narrowed to pictures or videos\nand looking back two weeks; where that is too little, the rest is what is popular\nin the same kind right now, marked <em>Popular right now</em>. Shorts opens on it once\nyour reading has taught it something, and learns from how much of each video you\nwatch.\n<strong>Settings → For you</strong> draws the list as a cloud — the bigger the hashtag, the\nmore it counts — where you drag, pin, remove and add them, choose languages, pause\nor turn it off. It never leaves this server and nobody else sees it.\nAdministrators can switch it off or make it opt-in.</li>\n</ul>\n<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/stories.png\" alt=\"The Shorts bar above the feed\"></p>\n<h2 id=\"shorts-kept-or-for-24-hours\">Shorts, kept or for 24 hours</h2>\n<p> A short is kept on your profile like any other\npost, or lasts <strong>24 hours</strong>: one picture, video or card of words that only your\nfollowers see, gone after a day. Above your feed is the <strong>Shorts</strong> bar — your own\ntile first with a <strong>+</strong> to make one, then the people you follow who have a 24-hour\nshort up, a ring on the face while there is something you have not seen, and an\n<strong>All shorts</strong> tile at the end. The bar is there only while somebody you follow has a\n24-hour short up; the camera at the end of the post composer makes a <strong>New short</strong>\nfor 24 hours whether the bar is there or not. One player plays both kinds (videos with sound, a\nspeaker to mute them, a &quot;Tap for sound&quot; hint where the browser will not start with\nit; a picture or a card for the seconds its poster gave it). On your own 24-hour\nshort you see <strong>Who has seen it</strong> and what was said, and can take it down early;\nnobody else sees either. Anybody who can see one can answer it with an emoji or a\nline of text, which goes to the poster alone. 24-hour shorts federate to Pixelfed,\nand Pixelfed shows them in its stories bar — in the shape Pixelfed actually reads,\nan <code>Add</code> carrying a capability its inbox fetches the short with, measured field by\nfield against Pixelfed&#39;s own source rather than against the specification. One\nthat arrives is held no longer than a day here whatever the sender says; watching\none posted elsewhere sends a receipt to its author, so their own server can count\nit. The other direction is not ours to fix: Pixelfed sends its own only to\ninstances it has identified as Pixelfed.</p>\n<h2 id=\"words-on-a-card-and-stickers\">Words on a card, and stickers</h2>\n<p> A 24-hour short can be a few words on a coloured\ncard instead of a picture — the type shrinks as you write, the way the picture will\n— and a picture can carry stickers: eight emoji and a line of your own words, dragged\nwhere you want them (or moved with the arrow keys) and baked into the picture before\nit goes up, so they arrive on Pixelfed where you put them.</p>\n<ul>\n<li><p><strong>Photos and Videos are timelines of their own</strong>, drawn as grids and asked of the\nserver rather than filtered out of a page you already have.</p>\n</li>\n<li><p><strong>Shorts</strong>, in the sidebar under Videos, is a stack: one at a\ntime, full height, playing as it comes past and stopping as it goes — the shape\nsomebody arriving from TikTok or YouTube Shorts already knows. The 24-hour shorts of\nthe people you follow come first, each person&#39;s together and the unseen ones ahead,\nmarked <strong>24h</strong> with the hours they have left; then the kept ones, which are the\nvideos of the Videos timeline. A switch in the corner\npicks whose videos: the people you follow, this server, or everywhere. It plays with\nsound, or muted with a &quot;Tap for sound&quot; hint when the browser will not start with it,\none video at a time in a single player that moves from video to video (so the sound\none tap allowed stays on as you scroll, iPhone included) while the others show their\ncover, and reachable\nwith the arrow keys and the space bar. The <strong>+</strong> opens a composer made for a short,\nwhich first asks how long it lasts — <strong>Keep it on my profile</strong> or <strong>Only for 24\nhours, for my followers</strong> (a 24-hour one may also be a picture or words), then lets you\nupload a video, drop one on it, or record one with the camera (a 3-2-1 countdown,\nfront or back camera, 15 s, 60 s or 3 min; browsers offer the camera over https\nonly). Then trim it with two handles over a\nstrip of stills, pick the frame people see before it plays as its cover, write a\ncaption with one-press trending hashtags, choose who can watch and whether it is\nsensitive, and post, with progress while it is cut, uploaded and published. The\ntrimming happens in the browser, so what goes up is what you watched; a browser\nthat cannot cut a video posts the whole one and says so. A heart button likes the video and sends hearts up the edge;\na double tap on the video likes it and puts a heart where your finger was (and never\ntakes a like back); <code>l</code> does the same from the keyboard.\n<img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/videos.jpg\" alt=\"Videos, including federated PeerTube channels\"></p>\n</li>\n</ul>\n<h2 id=\"peertube-properly-in-both-directions\">PeerTube, properly — in both directions</h2>\n<p> A PeerTube video arrives with its\ntitle, its channel, its thumbnail and something to play. The video <strong>streams from\nthe instance that holds it</strong> — a two-hour talk is not something to mirror onto\nsomebody&#39;s Aloha — and is proxied, so nobody&#39;s IP address reaches a server they\nnever chose to talk to. Going the other way, a post that is one video is published\nas an ActivityPub <code>Video</code> <strong>filed under a channel</strong>, which is the thing PeerTube\ncannot take a video without: it resolves one by looking for a <code>Group</code> in the video&#39;s\n<code>attributedTo</code> and refuses the video outright when there is none. One is made for an\naccount the first time it posts a video, so nobody has to learn the word.</p>\n<h2 id=\"a-watch-page-not-a-post-with-a-rectangle-in-it\">A watch page, not a post with a rectangle in it</h2>\n<p> A video opens on its title, the\nchannel that published it with a Subscribe button, the counters, and its chapters as\nlinks that seek. Where you stopped is remembered per video and offered back as\n<strong>continue watching</strong> — a fact about a reader, never federated and never shown to\nanybody else — and a video watched to the end is forgotten rather than bookmarked at\nthe credits. Every channel and every account has an <strong>RSS feed</strong> with an enclosure\nper video, so a podcast client can subscribe to one from outside.</p>\n<h2 id=\"a-ladder-of-sizes-if-an-administrator-wants-it\">A ladder of sizes, if an administrator wants it</h2>\n<p> The same video written two or\nthree more times, smaller, as HLS, so a player picks what the connection can carry.\nEach rung is <strong>one file</strong> rather than a directory of segments, which is also the\nshape PeerTube publishes — so a laddered video reaches a PeerTube reader the way a\nnative one does. Off by default; the original is kept and is what plays without it.</p>\n<h2 id=\"bring-a-channel-over\">Bring a channel over</h2>\n<p> PeerTube&#39;s own export is read — from the half that carries\nthe files, so the server you are leaving does not have to still be running — and a\nsingle video can be brought over by its address. Nothing is federated on the way in:\nre-publishing somebody&#39;s back catalogue would put it into every follower&#39;s timeline\nin one afternoon.</p>\n<h2 id=\"no-scores-by-default\">No scores by default</h2>\n<p> How many likes, dislikes, boosts and followers\nsomething has is hidden unless you turn the numbers on — on posts, profiles and in\nyour phone apps alike. Less of a scoreboard, less pressure.</p>\n<h2 id=\"how-many-people-read-it\">How many people read it</h2>\n<p>on your own posts and nobody else&#39;s, counted when\nsomebody opens the post rather than scrolls past it, and never sent to another\nserver. Three likes means something different out of five readers than out of four\nhundred, and until now there was no way to know which.</p>\n<ul>\n<li><p><strong>Blurhash placeholders</strong>, so a timeline never jumps as pictures load, and blurred\npreviews for anything marked sensitive.</p>\n</li>\n<li><p><strong>An ALT badge on every described picture</strong>, wherever it is drawn, that shows the\ndescription when pressed.</p>\n</li>\n<li><p><strong>Lists</strong>, made and filled in Settings or from anybody&#39;s profile — and <strong>the\nAloha groups your administrator chose</strong> are lists of their own, built and\nmaintained by nobody.</p>\n</li>\n</ul>\n<h2 id=\"follow-a-hashtag\">Follow a hashtag</h2>\n<p> and it reads exactly like following a person.</p>\n<h2 id=\"filter-out-words-you-would-rather-not-read\">Filter out words you would rather not read</h2>\n<p><strong>Blocking → Filtered words</strong>. A\nfilter is a handful of words, the timelines it applies in, and whether a matching\npost is <strong>folded away behind the filter&#39;s name</strong>, with a <em>Show anyway</em>, or taken out\nof the timeline altogether; it can be set to expire on its own. A folded post is not\nin the page at all until you ask for it, so nothing is read by accident. Nobody is\ntold, nothing is deleted, and what is currently being taken away is said at the top\nof the page rather than left to be noticed as gaps in a conversation.</p>\n<ul>\n<li><p><strong>Bookmarks and favourites</strong>, each with a page of their own.</p>\n</li>\n</ul>\n<h2 id=\"announcements-from-your-administrators\">Announcements from your administrators</h2>\n<p> at the top of the timeline, above the\ncomposer. An unread one interrupts; <strong>Got it</strong> marks it read for your account on\nevery device, and it does not come back. What you have already read is kept out of\nthe way behind one line, and an emoji reaction is the one thing you can say back.</p>\n<ul>\n<li><p><strong>Keyboard throughout</strong>: <code>j</code> <code>k</code> <code>l</code> <code>f</code> <code>b</code> <code>r</code> <code>o</code> <code>n</code> <code>g</code>, and <code>?</code> for the list.</p>\n</li>\n</ul>\n<h2 id=\"live\">Live</h2>\n<p> when <a href=\"https://github.com/nextcloud/notify_push\">notify_push</a> is installed;\npolling every 30 seconds when it is not.</p>\n","toc":[{"id":"shorts-kept-or-for-24-hours","text":"Shorts, kept or for 24 hours","level":2},{"id":"words-on-a-card-and-stickers","text":"Words on a card, and stickers","level":2},{"id":"peertube-properly-in-both-directions","text":"PeerTube, properly — in both directions","level":2},{"id":"a-watch-page-not-a-post-with-a-rectangle-in-it","text":"A watch page, not a post with a rectangle in it","level":2},{"id":"a-ladder-of-sizes-if-an-administrator-wants-it","text":"A ladder of sizes, if an administrator wants it","level":2},{"id":"bring-a-channel-over","text":"Bring a channel over","level":2},{"id":"no-scores-by-default","text":"No scores by default","level":2},{"id":"how-many-people-read-it","text":"How many people read it","level":2},{"id":"follow-a-hashtag","text":"Follow a hashtag","level":2},{"id":"filter-out-words-you-would-rather-not-read","text":"Filter out words you would rather not read","level":2},{"id":"announcements-from-your-administrators","text":"Announcements from your administrators","level":2},{"id":"live","text":"Live","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"read","manual":false,"prev":{"path":"/docs/feature-write","title":"✍️ Write"},"next":{"path":"/docs/feature-converse","title":"🧵 Converse"},"parent":null},{"slug":"feature-converse","path":"/docs/feature-converse","title":"🧵 Converse","description":"A post opened from a timeline gets a page of its own: the post, a reply box already pointed at it, the faces behind the boost and favourite counts, and the details a card leaves out — when…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/thread.png\" alt=\"A post&#39;s own page\"></p>\n<p>A post opened from a timeline gets a page of its own: the post, a reply box already\npointed at it, the faces behind the boost and favourite counts, and the details a card\nleaves out — when exactly, to whom, in what language, whether it has been edited, and a\nlink to the original for a post from another server.</p>\n<p>Replies read as a conversation. Each reply is followed by the replies to it, oldest\nfirst, stepped in by how deep it sits with a line down its side. A reply whose parent\nthis server does not hold keeps its place in time rather than disappearing. When the\nthread shown is shorter than the reply count, the page says so instead of presenting\nwhat it has as the whole conversation.</p>\n<p><strong>Four things you can do to a post</strong>: reply, boost, favourite, and <strong>react with an\nemoji</strong> — which federates as <code>EmojiReact</code> and shows who reacted with what.</p>\n<p><strong>Archive it</strong> — off your profile and out of every timeline, hashtag page and search\non this server, with nothing sent to anybody and a way back from Settings. It is the\nanswer to &quot;this no longer belongs on my profile&quot; that is not destroying it: other\nservers keep what they already have, which is what deleting is for.</p>\n<p><strong>And two more to your own.</strong> Edit it, or <strong>delete and write it again</strong> — the correction\npeople actually make. The post goes everywhere it reached, and its words, content\nwarning, audience, language and pictures come back in the composer; the pictures by\nreference, so nothing is uploaded twice. What you post next is a new post, and the\ndialog says so before anything happens: the boosts, likes and replies the old one\ncollected stay with it and are gone.</p>\n<p><strong>A post in another language offers to be translated</strong>, where this Aloha has a\ntranslation provider — the same one Talk, Mail and the assistant use. The translation\nappears in place of the post and says which provider produced it, because a reader is\nentitled to know they are reading a machine. A server without a provider draws no\nbutton at all rather than handing back the original text.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"converse","manual":false,"prev":{"path":"/docs/feature-read","title":"📖 Read"},"next":{"path":"/docs/feature-discover","title":"🧭 Discover"},"parent":null},{"slug":"feature-discover","path":"/docs/feature-discover","title":"🧭 Discover","description":"The sidebar has its own way in: Explore, one collapsible entry holding the hashtags you follow, your lists, and what this server is busy with right now — in that order, because the first…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/discover.png\" alt=\"Discover\"></p>\n<p>The hardest part of a new Fediverse account is the first ten follows. This answers it\nsix ways:</p>\n<ul>\n<li><strong>A search across other servers&#39; directories.</strong> Type a name, a handle or a subject\nand this server asks several directories at once — its own, then the ones its\nadministrator configured — and offers a Follow on every row. It uses the APIs those\nservers publish for strangers to read and holds no credentials for any of them,\naggregates nothing and stores nobody. Directories that did not answer are named\nunder the results, so a short list is never mistaken for an empty Fediverse.</li>\n<li><strong>The people you already share an Aloha with.</strong> Every Aloha profile has a\n<code>fediverse</code> field; this app fills in yours and reads everybody else&#39;s, so your\ncolleagues are suggested before any algorithm has a thing to say.</li>\n<li><strong>Starter packs</strong> — a named handful of accounts with one button that follows all of\nthem. Administrators curate their own.</li>\n<li><strong>Trending hashtags</strong>, ranked over a window you choose from one hour to ten days. The\nbusiest hour and the busiest ten days are genuinely different lists, not one list\nrelabelled.</li>\n<li><strong>What other servers are talking about</strong>, under the trending list, and a box that\n<strong>finds a hashtag</strong> across them. A small server&#39;s own trending list is a list of\nwhat the few people on it posted today, and a new one&#39;s is empty; this asks other\nservers the same question and says whose answer it is — &quot;busy on mastodon.social\nand misskey.io&quot; rather than a number from nowhere. Ranked by how many servers named\na tag, because instances differ in size by four orders of magnitude and adding their\ncounts together would make the biggest one&#39;s opinion everybody&#39;s. Nothing is fetched\nor stored: a hashtag is a string, and following one from here brings in posts the\nsame way following any hashtag does.</li>\n<li><strong>Trending pictures and videos.</strong></li>\n</ul>\n<p>The sidebar has its own way in: <strong>Explore</strong>, one collapsible entry holding the\nhashtags you follow, your lists, and what this server is busy with right now — in that\norder, because the first two are things you chose and the third is not. It shows as\nmuch as the rail has room for, and what you follow is never pushed out by what happens\nto be trending.</p>\n<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/search.png\" alt=\"Search\"></p>\n<p>Search covers people, hashtags and the <strong>full text of every post you are allowed to\nsee</strong> — your own, public content and anything addressed to you — through Aloha&#39;s\nown unified search. No external search engine to run.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"discover","manual":false,"prev":{"path":"/docs/feature-converse","title":"🧵 Converse"},"next":{"path":"/docs/feature-your-profile","title":"👤 Your profile"},"parent":null},{"slug":"feature-your-profile","path":"/docs/feature-your-profile","title":"👤 Your profile","description":"A profile field naming a web page gets the tick when that page links back with rel=\"me\" — from an <a> anywhere on it or a <link> in its head. The editor says which of your fields are…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/profile.jpg\" alt=\"A profile\"></p>\n<h2 id=\"posts-photos-and-videos\">Posts, Photos and Videos</h2>\n<p> as three tabs, each one a question asked of the server.</p>\n<ul>\n<li><p><strong>A banner, a bio and four metadata fields</strong>, federated the way Mastodon does it and\nedited in <strong>Edit profile</strong> on your own profile.</p>\n</li>\n</ul>\n<h2 id=\"verified-links\">Verified links</h2>\n<p> A profile field naming a web page gets the tick when that page\nlinks back with <code>rel=&quot;me&quot;</code> — from an <code>&lt;a&gt;</code> anywhere on it or a <code>&lt;link&gt;</code> in its head.\nThe editor says which of your fields are verified and when each was last proved, and\nhands you the line to paste on the far end. The page is fetched in the background,\nonce a day per account.</p>\n<h2 id=\"featured-hashtags\">Featured hashtags</h2>\n<p> Up to ten tags pinned under the bio, saying what the account is\nabout in its own words; a visitor clicks one and reads what was posted under it, with\nthe count taken from the posts rather than stored. You set your own in <strong>Settings →\nFeatured hashtags</strong>, which starts from the tags you already post with most instead of\nan empty box, and your profile links straight there.</p>\n<h2 id=\"highlights\">Highlights</h2>\n<p>a twelve-week posting chart and the tags somebody keeps coming back\nto.\n<img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/collections.png\" alt=\"Collections\"></p>\n<h2 id=\"collections\">Collections</h2>\n<p>Pixelfed&#39;s albums, as a tab of a profile: a shelf of the\naccount&#39;s collections, each a page of its posts drawn as the profile grid. You make\none on your own shelf, put a post into it from the post&#39;s menu (<strong>… → Add to a\ncollection</strong>), and edit, empty or delete it on its page. A collection holds only\nits owner&#39;s own posts with a picture or a video in them, and a followers-only one\nis shown to followers and nobody else.</p>\n<h2 id=\"team-accounts\">Team accounts</h2>\n<p>an administrator can give an Aloha group an account to\npost from, and everybody in the group finds it in the composer beside the\naudience picker. It is an actor like any other: followable from Mastodon and\nPixelfed, moderatable, with its own followers. The membership is the group,\nasked live, so leaving it takes the account away with it. Who wrote each post\nis recorded and shown to the team and to moderators, and to nobody else.</p>\n<h2 id=\"your-year-as-a-report\">Your year, as a report</h2>\n<p>Mastodon&#39;s <code>#Wrapstodon</code>, through the API only\n(<code>/api/v1/annual_reports</code>; the web client has no page for it yet): twelve\nmonths of what you posted and who arrived, the hashtags you used, the three\nposts that travelled furthest, and a one-word description of how you use the\naccount. Computed from the posts already here, so it cannot go stale and needs\nno job to run.</p>\n<h2 id=\"quote-controls\">Quote controls</h2>\n<p>who may quote each of your posts (anybody, your\nfollowers, nobody), who already has, and a button that detaches one and tells\ntheir server. Mastodon 4.5&#39;s <code>quote_approval_policy</code>, its quote list and its\nrevoke, over FEP-044f.</p>\n<h2 id=\"relays\">Relays</h2>\n<p>subscribe to one and a new server&#39;s federated timeline stops\nbeing empty: a relay rebroadcasts the public posts of every server on it, and\ncarries this server&#39;s public posts out to all of them. Public posts only, and\na relayed post arrives as the post it is rather than as a boost by the relay.</p>\n<h2 id=\"delete-your-aloha-social-account\">Delete your Aloha Social account</h2>\n<p> from Settings, keeping your Aloha one —\nthe posts, the follows and a <code>Delete</code> to every server that knew you. No\nadministrator, and no password to type for an account signed in through SSO. A\nself-registered external user, who has nothing here but Aloha Social, loses the whole\naccount with it.</p>\n<h2 id=\"authorized-apps\">Authorized apps</h2>\n<p>every app holding a key to your account, with what it\nmay do and when it was last used, and a button that signs one out. The page\nto open after losing a phone.</p>\n<h2 id=\"requests\">Requests</h2>\n<p>at the top of Activities, &quot;3 people are waiting — Review&quot;: the\npeople your notification policy is holding, one row each, with Show these and\nDismiss. The waiting people are part of the Activities count in the sidebar, and\nnever ring the bell.</p>\n<h2 id=\"hide-a-whole-server\">Hide a whole server</h2>\n<p> from yourself, beside the blocked and muted accounts.</p>\n<h2 id=\"edit-history\">Edit history</h2>\n<p>the &quot;Edited&quot; line under a post opens every version of it.</p>\n<h2 id=\"a-portfolio\">A portfolio</h2>\n<p>a page of your work with its own public address, to put on a\nCV. A title, a sentence, a grid or one picture at a time, and the pictures\nchosen from your recent public photos or one of your collections. A draft until\nyou publish it; readable without signing in once you do, and built only out of\npublic posts whatever else is set.</p>\n<h2 id=\"built-for-a-large-instance\">Built for a large instance</h2>\n<p> The home timeline pages over an indexed sort\nkey rather than joining and sorting everything you have ever been sent — on a\nseeded instance of 400,000 posts that is 50 ms against 1,661. An account&#39;s\ncounters are added to rather than recomputed, so a follow no longer counts a\nmillion rows to move a number by one. The cron walks the accounts a page at a\ntime instead of loading all of them into memory. <code>occ social:worker</code> delivers\ncontinuously and several may run at once, where the cron manages about a\nthousand deliveries an hour. Polls that have not changed are answered <code>304</code>,\nand the page arrives with its first screenful already in it.</p>\n<h2 id=\"videos-that-play-elsewhere\">Videos that play elsewhere</h2>\n<p>where ffmpeg is installed, a background job\nconverts stored videos to H.264 in an MP4, which is the one format the rest of\nthe network plays: Pixelfed&#39;s default accepts <code>video/mp4</code> and nothing else, so a\n<code>.mov</code> straight off a phone was being dropped by its inbox without a word, and\nthe HEVC phones write into an <code>.mp4</code> plays in Safari alone. On by default; an\nadministrator can switch it off, since re-encoding is lossy and the converted\nfile replaces the original. Never during an upload: a new post with such a video\nwaits up to ten minutes for its conversion before it is sent, so it arrives as an\nMP4, and a setup check says when ffmpeg is missing.</p>\n<h2 id=\"storage-that-fits-video\">Storage that fits video</h2>\n<p>a per-account video quota beside the per-file ceiling,\nbecause a limit on one upload says nothing about a year of them, and a Storage card\nthat says <strong>who</strong> is holding the disk rather than only how much of it is gone. Off\nby default: an instance that acquired a quota on upgrade would start refusing\nuploads from exactly the accounts that use it most.</p>\n<h2 id=\"moderation-defaults-for-video\">Moderation defaults for video</h2>\n<p>the three policies for media somebody marked\nsensitive (shown, covered, hidden) as an instance default that anybody can override\nfor themselves, and a switch that holds every post with a video on it for a\nmoderator. That one is not about the account: a trusted account is held by it too,\nevery time, because what it is about is the video.</p>\n<h2 id=\"tag-people-in-a-photo\">Tag people in a photo</h2>\n<p>name the people in one of your own pictures from the\npost&#39;s menu (<strong>… → Tag people</strong>), and their names show up under it, linked to their\nprofiles. Everybody named is told, and the photo appears under <strong>Tagged</strong> on their\nown profile — including on another server, because each name is written onto the\npost as a mention and the post is sent again. It does not change who may see the\npost. Anybody named can take their own name off, which needs nobody&#39;s permission.</p>\n<ul>\n<li><p><strong>Pinned posts</strong>, up to five, published in the actor&#39;s <code>featured</code> collection. Remote\naccounts&#39; pins arrive too.</p>\n</li>\n<li><p><strong>A grid or a timeline</strong>, whichever you last chose, cropped to each picture&#39;s focal\npoint.</p>\n</li>\n</ul>\n<h2 id=\"a-private-note\">A private note</h2>\n<p> about somebody, for you alone. It never leaves this server and the\nperson it is about is never told.</p>\n<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/your-statistics.png\" alt=\"Your own statistics\"></p>\n<ul>\n<li><strong>Your own statistics</strong>, behind your face in the sidebar. <strong>The last 30 days beside\nthe 30 before them</strong> — estimated reach, interactions, likes and boosts, each as a\nfigure, the percentage it moved by and a line drawn over the window with the previous\none behind it — and then <strong>every post of the window, one by one</strong>, with what it\nreached and what it collected, ordered by date, reach or engagement. Under that: which\nkind of post does better, the weekday and the hour that work, the tags worth using,\nwhere your followers are and when they arrived. Everything is counted from this\nserver&#39;s own rows the moment you open the page, so nothing can be stale, and the page\nsays what it cannot know — reach is your followers plus the followers of whoever\nboosted you, overlapping audiences counted twice, and it names how many boosters&#39;\naudiences this server has never been told about. Beside the estimate it also reports\nthe number of servers your posts were actually delivered to, which is measured.</li>\n</ul>\n<h2 id=\"choose-the-window\">Choose the window</h2>\n<p>all time, or the last 30, 90 or 365 days — and the page says\nwhich one it counted. The result is held for fifteen minutes so a reload is free, with\na button to count it again, and another to <strong>take the numbers with you</strong> as a CSV or a\nJSON file: nothing here is stored on the server, so the only copy of a month&#39;s figures\nis the one you keep.</p>\n<ul>\n<li><strong>What you did</strong>, beside what came back: posts of your own, replies and boosts, month\nby month. A quiet month in the other chart means either you were quiet or nobody\nanswered, and this is how you tell which. With it, <strong>how steadily you post</strong> — the\ndays you posted on, your longest run and your longest silence.</li>\n<li><strong>Who you talk with</strong>, from the replies rather than from who you follow: the people\nwho answer you and the people you answer, and how many of the first are people you do\nnot follow. <strong>Your pictures and whether they describe themselves</strong>, which is the one\nnumber on the page you can move on your own. And what you write in and where your\nlinks go.</li>\n</ul>\n","toc":[{"id":"posts-photos-and-videos","text":"Posts, Photos and Videos","level":2},{"id":"verified-links","text":"Verified links","level":2},{"id":"featured-hashtags","text":"Featured hashtags","level":2},{"id":"highlights","text":"Highlights","level":2},{"id":"collections","text":"Collections","level":2},{"id":"team-accounts","text":"Team accounts","level":2},{"id":"your-year-as-a-report","text":"Your year, as a report","level":2},{"id":"quote-controls","text":"Quote controls","level":2},{"id":"relays","text":"Relays","level":2},{"id":"delete-your-aloha-social-account","text":"Delete your Aloha Social account","level":2},{"id":"authorized-apps","text":"Authorized apps","level":2},{"id":"requests","text":"Requests","level":2},{"id":"hide-a-whole-server","text":"Hide a whole server","level":2},{"id":"edit-history","text":"Edit history","level":2},{"id":"a-portfolio","text":"A portfolio","level":2},{"id":"built-for-a-large-instance","text":"Built for a large instance","level":2},{"id":"videos-that-play-elsewhere","text":"Videos that play elsewhere","level":2},{"id":"storage-that-fits-video","text":"Storage that fits video","level":2},{"id":"moderation-defaults-for-video","text":"Moderation defaults for video","level":2},{"id":"tag-people-in-a-photo","text":"Tag people in a photo","level":2},{"id":"a-private-note","text":"A private note","level":2},{"id":"choose-the-window","text":"Choose the window","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"your-profile","manual":false,"prev":{"path":"/docs/feature-discover","title":"🧭 Discover"},"next":{"path":"/docs/feature-notifications","title":"🔔 Notifications"},"parent":null},{"slug":"feature-notifications","path":"/docs/feature-notifications","title":"🔔 Notifications","description":"A page, not a list of everything. Filters across the top (All, Mentions, Favourites, Boosts, Follows, Polls, Edits), a New line where you left off, and a run of likes of the same post…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/notifications.jpg\" alt=\"Notifications\"></p>\n<p>A page, not a list of everything. Filters across the top (All, Mentions, Favourites,\nBoosts, Follows, Polls, Edits), a <strong>New</strong> line where you left off, and a run of likes of\nthe same post drawn as <strong>one card with the faces stacked</strong> rather than the same post\nquoted twelve times.</p>\n<p>It marks itself read after it has been in front of you for two seconds, not the instant\nit renders — so it stops clearing the badge on your phone for things nobody saw.</p>\n<p><strong>Who may reach you.</strong> Five questions about whoever is writing to you — do I follow\nthem, do they follow me, are they new here (less than 30 days), is this a private\nmention I didn&#39;t ask for, has this server limited them — each answered <strong>Allow</strong> or\n<strong>Hold for review</strong>, in Settings → Notifications next to the digests and quiet hours.\nA held person can still write to you: everything they do waits together at the top of\nActivities, and raises no bell, push or mail. You decide about the person once —\naccept, and they are always allowed until you stop allowing them; dismiss, and what\nthey sent is gone. New accounts start calm (strangers, new accounts, unsolicited\nprivate mentions and limited accounts held); existing accounts keep accepting\neverybody until they choose. Clients read it as Mastodon 4.3&#39;s notification policy,\nwhere <em>drop</em> stays available, and read the same notifications grouped — &quot;eight people\nfavourited your post&quot; rather than eight rows.</p>\n<p><strong>Mute a conversation</strong>, from any post&#39;s menu or a mention in Activities: the thread\nstays on your timelines, and stops notifying you until you unmute it.</p>\n<p><strong>Aloha&#39;s own bell rings too.</strong> Mentions, favourites, boosts, new followers, follow\nrequests, edits of posts you boosted and polls you voted in all reach Aloha\nnotifications and its mail digest, each linking into this app rather than out to a\nremote server. A <strong>follow request carries Accept and Decline on the bell entry itself</strong>.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"notifications","manual":false,"prev":{"path":"/docs/feature-your-profile","title":"👤 Your profile"},"next":{"path":"/docs/feature-your-account-your-data","title":"⚙️ Your account, your data"},"parent":null},{"slug":"feature-your-account-your-data","path":"/docs/feature-your-account-your-data","title":"⚙️ Your account, your data","description":"Everything about your account in one page: whether people must ask before they follow you, whether other servers may suggest you and index your public posts, whether this is an automated…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/settings.png\" alt=\"Settings\"></p>\n<p>Everything about your account in one page: whether people must ask before they follow\nyou, whether other servers may suggest you and index your public posts, whether this is\nan automated account, and the audience every new post starts with. Only what you changed\nis sent. The name you publish under is not here — it belongs to your Aloha account\nand the page links to where it is changed, rather than offering a second place to edit\nit that would do nothing on an instance whose accounts come from LDAP.</p>\n<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/scheduled.png\" alt=\"Scheduled posts\"></p>\n<p>Below it: your <strong>lists</strong>, your <strong>scheduled posts</strong> with a way to cancel one, your\n<strong>blocked and muted accounts</strong> with unblock and unmute inline, and <strong>migration</strong>.</p>\n<p><strong>Migration takes your account with you.</strong> Moving in starts from your old handle:\nthe page looks the account up, shows what its server lets us read, and then follows\neveryone it follows and brings its public posts over in the background; the one step\nleft is the move on the old server, and the page names the menu. Export writes your profile, follows,\nfollowers, blocks, mutes, bookmarks, likes and every post you have written to a zip —\nand <strong>the pictures and videos come with it</strong>, copied into the archive in the layout\nMastodon&#39;s own export uses, with each attachment pointing at the copy rather than at\nthe server you are leaving. Import reads one back, including an archive from\n<code>occ user:export</code>. A third section brings your follows over from Mastodon, Pixelfed,\nGoToSocial or Akkoma via their <code>following_accounts.csv</code> or <code>pixelfed-following.json</code>.\nEvery import runs in the background and the page shows where it has got to, so a\nlong follow list or a decade of posts is one upload rather than a race against the\nweb server&#39;s timeout. Your private key is deliberately not in the archive. Naming the account you are\nmoving from — the <code>alsoKnownAs</code> the old server insists on before it will hand over\nyour followers — is a field in the same page rather than an <code>occ</code> command, because\nit federates nothing and is yours to set.</p>\n<p><strong>And a fourth brings the posts</strong> — the one thing moving between Fediverse servers has\nnever carried. Upload the export from your old server (this app&#39;s archive, Mastodon&#39;s\nor GoToSocial&#39;s <code>outbox.json</code>, or Pixelfed&#39;s <code>pixelfed-statuses.json</code>) and the posts in\nit are written here as yours, dated when you wrote them, with their pictures: out of\nthe archive where it holds the files, and off the old server where the export only\nlists their addresses. <strong>Nothing is published again</strong> — not one delivery is queued, so\nyour followers do not get years of posts in an afternoon — boosts and direct messages\nare left out, a reply keeps the post it answers where the file holds both, and\nimporting the same file twice changes nothing the second time. An archive too large\nfor a browser goes through <code>occ social:account:import-posts</code>.</p>\n<p>  <strong>Instagram&#39;s archive is read too</strong> — the way most people arrive at Pixelfed. Ask\n  Instagram for your information <em>in JSON</em> (the HTML download holds the pages and not\n  the posts, and says so if you try it), and the posts, reels and their pictures come\n  across with their captions and the hashtags written in them. Instagram&#39;s archive says\n  nothing about who could see a post, so they are posted with <strong>your own default\n  visibility</strong>; posts Instagram showed for only a day, archived posts and deleted ones\n  are deliberately left where they are.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"your-account-your-data","manual":false,"prev":{"path":"/docs/feature-notifications","title":"🔔 Notifications"},"next":{"path":"/docs/feature-on-a-phone-and-in-the-dark","title":"📱 On a phone, and in the dark"},"parent":null},{"slug":"feature-on-a-phone-and-in-the-dark","path":"/docs/feature-on-a-phone-and-in-the-dark","title":"📱 On a phone, and in the dark","description":"Under 600px the avatar moves inside the card, the card takes the width of the screen, the composer's toolbar wraps instead of pushing Post off the edge, and a post's page gives up the…","group":"features","html":"<p align=\"center\">\n  <img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/phone.png\" alt=\"The timeline on a phone\" width=\"300\">\n  &nbsp;&nbsp;\n  <img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/dark.jpg\" alt=\"The timeline in dark mode\" width=\"620\">\n</p><p>Under 600px the avatar moves inside the card, the card takes the width of the screen,\nthe composer&#39;s toolbar wraps instead of pushing Post off the edge, and a post&#39;s page\ngives up the column it kept for an avatar that is no longer beside it. Dark mode is\nthe same app, not a second design.</p>\n<p><strong>Sound and touch</strong>, in Settings: a soft tick on a like, a breath of air when a post\ngoes out, a two-note chime when a direct message arrives, and a short tap in the hand\non a phone. Sound is off until you turn it on; vibration is on, and your system&#39;s\nsetting for less motion turns it off too. A third switch says whether Shorts\nstart with their sound on. All three are kept on the device rather than the\naccount, so the laptop at work can stay quiet while your phone taps back. The sounds\nare synthesised in the browser, so there is nothing to download.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"on-a-phone-and-in-the-dark","manual":false,"prev":{"path":"/docs/feature-your-account-your-data","title":"⚙️ Your account, your data"},"next":{"path":"/docs/feature-it-is-an-aloha-app-so-it-behaves-like-one","title":"🧩 It is an Aloha app, so it behaves like one"},"parent":null},{"slug":"feature-it-is-an-aloha-app-so-it-behaves-like-one","path":"/docs/feature-it-is-an-aloha-app-so-it-behaves-like-one","title":"🧩 It is an Aloha app, so it behaves like one","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","group":"features","html":"<ul>\n<li><strong>Share to Aloha Social, from Files.</strong> Select a picture or a video — up to ten — pick\n<em>Share to Aloha Social</em> from the menu, and the composer opens with them already attached.\nNothing is uploaded a second time.</li>\n<li><strong>Replies show up in Files.</strong> Public replies to a picture you posted from Files appear\nin the file&#39;s Comments tab, and a comment you write there goes out as your reply.\nOther people&#39;s comments on the file stay on your server.</li>\n<li><strong>Links unfurl.</strong> Paste a link to a post or a profile into a Talk message, a Text\ndocument or a Deck card and it becomes a card with the author, the text and the first\npicture. Only what anybody could read is rendered, because the card is cached once\nfor everyone who sees the link.</li>\n<li><strong>Dashboard widgets</strong> and an entry in the <strong>contacts menu</strong>.</li>\n<li><strong>The Activity app</strong> lists your follows, mentions, boosts and favourites, and puts\nthem in the Activity digest mail. Activity&#39;s own notifications stay off: the bell is\nthe bell.</li>\n<li><strong>Unified search</strong>, so Aloha Social posts turn up where every other search result does.</li>\n<li><strong>Deleting an Aloha user takes their Fediverse account with it</strong> — tombstoned,\ndropped, and a <code>Delete</code> federated so other servers drop their copies too.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"it-is-an-aloha-app-so-it-behaves-like-one","manual":false,"prev":{"path":"/docs/feature-on-a-phone-and-in-the-dark","title":"📱 On a phone, and in the dark"},"next":{"path":"/docs/feature-safety-and-privacy-that-is-the-default","title":"🛡️ Safety, and privacy that is the default"},"parent":null},{"slug":"feature-safety-and-privacy-that-is-the-default","path":"/docs/feature-safety-and-privacy-that-is-the-default","title":"🛡️ Safety, and privacy that is the default","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","group":"features","html":"<ul>\n<li><strong>Block</strong> to sever a relationship in both directions and hide somebody everywhere.</li>\n<li><strong>Mute</strong> to hide them from your timelines and optionally your notifications without\nthem ever knowing — <strong>for an hour, a day, seven days, thirty, or until you lift it</strong>.\nA profile says when a timed mute runs out.</li>\n<li>Both are offered on the profile <strong>and in the menu of any post they wrote</strong>, which is\nusually where you decided.</li>\n<li><strong>Report</strong> an account or a post. With forwarding on, a report about a remote account\nalso reaches the instance that hosts it — anonymised, and signed as this server\nrather than as the person who filed it, because they would otherwise be handing their\nhandle to the very instance they are complaining about.</li>\n<li><strong>Locked accounts</strong>, so follows must be approved, with a Follow requests page.</li>\n<li><strong>Keyword filters</strong>, written and read in <strong>Blocking → Filtered words</strong>: they are\nyours alone, they apply to every timeline this app draws, and a filter set months ago\nfrom a phone is finally visible from here.</li>\n<li><strong>What you see from an account you follow</strong>, on its profile: the bell that says\n&quot;tell me when they post&quot;, and its opposite number — <strong>hide their boosts</strong>, which\nkeeps what somebody passes on out of your timelines while leaving everything they\nwrite themselves.</li>\n<li><strong>Per-user domain blocks</strong> — <strong>Blocking → Hidden servers</strong> — and conversation\nmute, in the menu of any post.</li>\n<li><strong>Nothing is sent to a third party.</strong> No geocoder — a place on a post is one this\ninstance has seen or one you name yourself, because sending somebody&#39;s location to a\nstranger at the moment they are deciding whether to publish it is exactly the failure\nthe Exif stripping exists to prevent. Link previews are read by this server, never\nfederated, and never fetched from a local address.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"safety-and-privacy-that-is-the-default","manual":false,"prev":{"path":"/docs/feature-it-is-an-aloha-app-so-it-behaves-like-one","title":"🧩 It is an Aloha app, so it behaves like one"},"next":{"path":"/docs/feature-for-administrators","title":"🏛️ For administrators"},"parent":null},{"slug":"feature-for-administrators","path":"/docs/feature-for-administrators","title":"🏛️ For administrators","description":"Everything in Administration → Aloha Social, in six groups — Overview, Moderation, Sign-ups, Explore and features, Federation and Server — with a search across all of them. It opens on…","group":"features","html":"<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/admin.png\" alt=\"The administration page\"></p>\n<p>Everything in Administration → Aloha Social, in six groups — Overview, Moderation,\nSign-ups, Explore and features, Federation and Server — with a search across all of them.\nIt opens on what needs you: open reports, posts waiting for review, sign-ups to approve,\ndeliveries about to be given up on and late background jobs, each a link to where it is\ndealt with.</p>\n<ul>\n<li><strong>Reports</strong> with <strong>Silence</strong>, <strong>Suspend</strong>, <strong>Lift</strong> and take-a-post-down, each\nrecorded with the moderator who did it and written to Aloha&#39;s audit log.\nSuspending deletes what the account posted here, and the confirmation says so.</li>\n<li><strong>A review queue before anything goes out.</strong> The first post of an account that has\npublished nothing here yet, and posts that trip a very short list of spam rules —\na wall of links, a scatter of mentions from an account nobody follows — wait for a\nmoderator instead of reaching anybody. A held post is stored as the request the\nclient sent and is written to no timeline at all, so there is no read path that\ncould leak one; its author is told at once, can see it in their own settings, and\ncan take it back. Publishing sends it as an ordinary post; refusing deletes it and\ntells them. Both rules are switches — the spam rules on by default, first-post review off\nuntil an administrator with open registration turns it on — and a <strong>direct message is\nnever held</strong>.</li>\n<li><strong>An account browser</strong> over every account this instance knows, with the standing\ndecision and the strike history against each one.</li>\n<li><strong>Let people without an account join — for Aloha Social only.</strong> Switch on external users\nand people register themselves from a &quot;Create an account&quot; button on the login page:\na username that becomes their handle, an email address they confirm, the server rules\nand an age to confirm. You choose how many such accounts may exist, how much media each\nmay upload, and who gets one — anybody, anybody you approve from a queue on the same\npage, or only the holders of an invitation link you (or, if you allow it, anybody\nhere) sent. They log in through the normal login page, two-factor authentication\nincluded and enforceable with one switch, and reach Aloha Social and nothing else: no\nFiles, no Talk, no WebDAV, no other app, and nobody outside Aloha Social finds them in the\nshare dialog, the contacts menu or the address book. Mastodon apps work for them. One\nclick makes one an ordinary account of this server, password and Aloha Social account kept.\n<code>occ social:external</code> lists, adds and promotes them.</li>\n<li><strong>Deliveries</strong> — how many deliveries are waiting, how many keep failing, which\ninstances they are stacked up against, how close each is to being abandoned (<strong>16\nattempts</strong>), and which instances have been given up on in the last seven days.\n<code>occ social:queue:status</code> prints the same summary and\n<code>occ social:queue:retry --instance HOST</code> puts one host&#39;s deliveries back.</li>\n<li><strong>Server settings with an interface</strong> — contact address, instance description, upload\nceilings, inbox rate limit, secure mode, whether the block list is published, whether\nself-signed certificates are accepted. Every one of these used to be an\n<code>occ config:app:set</code> key that almost nobody set.</li>\n<li><strong>Announcements</strong> — a notice to the whole instance, optionally between a start and\nan end, that everybody reads at the top of their timeline and dismisses once.\n<strong>Retention</strong> and the <strong>instance access list</strong> (an allow-list or a deny-list of\nremote hosts, enforced both ways) are here too.</li>\n<li><strong>Domain blocks that clean up.</strong> Adding a host to the deny list also removes what it\nalready sent: its accounts, their posts, the follows in both directions and the\ndeliveries still queued towards it.</li>\n<li><strong>Setup checks in Administration → Overview</strong> — whether <code>.well-known/webfinger</code>\nanswers, whether the address Aloha Social builds its ids from is still the server&#39;s,\nwhether the delivery job has run lately, whether anything is stuck, whether\nMastodon apps can reach the API, and more (see\n<a href=\"/docs/admin-the-setup-checks#the-setup-checks\">docs/Admin.md</a>). <code>occ social:check:install</code> runs\nthe WebFinger, address, delivery-job, queue and client-API ones and exits\nnon-zero on an error, so a deployment script can ask.</li>\n</ul>\n<p><img src=\"https://raw.githubusercontent.com/AlohaSocial/social/master/img/readme/statistics.png\" alt=\"Statistics\"></p>\n<p>A <strong>statistics</strong> page for the instance, and Mastodon&#39;s admin API — accounts, reports,\ndomain blocks, IP and email-domain blocks, trends, measures and retention — for\nanything you would rather automate.</p>\n<p>Retention keeps the database honest: remote statuses older than <code>retention_days</code> that\nnobody here interacted with are pruned with their attachments, and cached accounts\nnobody follows are evicted after <code>cache_actor_days</code>. Local content is never touched.\n<code>occ social:media:usage</code> says what the media is costing and how much of it is somebody\nelse&#39;s.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"for-administrators","manual":false,"prev":{"path":"/docs/feature-safety-and-privacy-that-is-the-default","title":"🛡️ Safety, and privacy that is the default"},"next":{"path":"/docs/feature-for-developers","title":"🔑 For developers"},"parent":null},{"slug":"feature-for-developers","path":"/docs/feature-for-developers","title":"🔑 For developers","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","group":"features","html":"<ul>\n<li><strong>The Mastodon client API</strong>, core surface plus OAuth 2: every timeline, posting with\nmedia and polls, follows, favourites, boosts, bookmarks, search, follow requests,\nreports, filters (both halves — keywords and per-status), conversations, markers,\nannouncements, edit history, translation, Mastodon 4.3&#39;s grouped notifications with\ntheir policy and requests inbox, and the admin API. See\n<a href=\"docs/API.md\">docs/API.md</a> for exactly which routes exist.</li>\n<li><strong>Pixelfed&#39;s own routes</strong> — the <code>/api/v2/config</code> bootstrap its app reads on launch,\nthe <code>v1.1</code>/<code>v1.2</code> discover, story, collection, account, report and direct-message\nroutes its screens call, its <code>push/*</code> routes answered honestly as off, and its\n<code>/api/admin/*</code> screens behind the same gate as Mastodon&#39;s admin API. Every limit in\nthe config is derived from the one the server actually enforces. Of the forty\nPixelfed-specific calls the official app makes, thirty-four are answered; the rest are\nWeb Push and in-app registration.</li>\n<li><strong>Full ActivityPub delivery</strong>: signed HTTP for <code>Create</code>, <code>Update</code>, <code>Delete</code>, <code>Like</code>,\n<code>Announce</code>, <code>Follow</code>, <code>Accept</code>, <code>Undo</code>, <code>Block</code>, <code>Flag</code> and <code>EmojiReact</code>, an outbound\nqueue and a stream queue, both drained by background jobs and by\n<code>occ social:queue:process</code>.</li>\n<li><strong>Inbox forwarding</strong>, so a reply from a stranger&#39;s instance reaches your followers —\nforwarded untouched and only when it carries its author&#39;s linked-data signature.</li>\n<li><strong><code>occ</code> commands</strong>, documented in <a href=\"/docs/occ\">docs/OCC-Commands.md</a>.</li>\n</ul>\n<blockquote>\n<p>[!IMPORTANT]\n<strong>Mastodon apps work once the web server maps <code>/api</code> and <code>/oauth</code> onto the app.</strong>\nEvery route is served under <code>/apps/social/</code>, and a Mastodon app given your domain\nlooks for <code>/api/v1/...</code> at its root. The rules for Apache and nginx are in\n<a href=\"contrib/webserver\"><code>contrib/webserver/</code></a>, explained in\n<a href=\"/docs/admin-mastodon-apps-cannot-connect#mastodon-apps-cannot-connect\">docs/Admin.md</a>, and\nAdministration → Overview says whether they are in place. It is a web-server\nchange, not an app setting.</p>\n</blockquote>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"for-developers","manual":false,"prev":{"path":"/docs/feature-for-administrators","title":"🏛️ For administrators"},"next":{"path":"/docs/feature-not-implemented-yet","title":"🚧 Not implemented yet"},"parent":null},{"slug":"feature-not-implemented-yet","path":"/docs/feature-not-implemented-yet","title":"🚧 Not implemented yet","description":"These are absent from the code today, not merely rough edges:","group":"features","html":"<p>These are absent from the code today, not merely rough edges:</p>\n<ul>\n<li><strong>No streaming API and no push subscriptions.</strong> Third-party clients poll. (The web\nclient does get live timelines when\n<a href=\"https://github.com/nextcloud/notify_push\">notify_push</a> is installed — that is a\nAloha channel, not a Mastodon one.)</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"not-implemented-yet","manual":false,"prev":{"path":"/docs/feature-for-developers","title":"🔑 For developers"},"next":{"path":"/docs/feature-quickstart-install-and-develop","title":"📦 Quickstart (install & develop)"},"parent":null},{"slug":"feature-quickstart-install-and-develop","path":"/docs/feature-quickstart-install-and-develop","title":"📦 Quickstart (install & develop)","description":"The feature tour from the project README: writing, reading, conversations, your profile, notifications, safety and the rest — one page per topic.","group":"features","html":"<ol>\n<li>Clone this repository into your Aloha <code>apps/</code> directory.</li>\n<li>Install the dependencies and build the frontend:</li>\n</ol>\n<pre><code class=\"language-bash\">cd /var/www/nextcloud/apps/social\ncomposer install     # PHP dependencies\nnpm ci\nnpm run build        # production bundle into js/\n</code></pre>\n<ol start=\"3\">\n<li>Enable the app in Aloha (<code>occ app:enable social</code>) and check the install with\n<code>occ social:check:install</code>.</li>\n<li>While working on the UI, use <code>npm run dev</code> for a development build or\n<code>npm run watch</code> to rebuild on change. The <code>Makefile</code> wraps the same scripts\n(<code>make build-js</code>, <code>make build-js-production</code>, <code>make watch-js</code>, <code>make lint</code>).</li>\n<li>To produce a release archive, run <code>make appstore</code> (or <code>./build-package.sh</code>,\nwhich is now a three-line wrapper around it — two copies of the exclusion list\nhad already drifted apart, so there is one). It installs from the lock files,\nbuilds the frontend, stages the app without its development files and writes\n<code>build/artifacts/social.tar.gz</code>. It refuses to package when <code>js/.htaccess</code> is\nmissing: that is a committed file rather than webpack output, and the target\nused to delete <code>js/</code> wholesale before building. Despite the <code>sign_dir</code> name it\nonly stages and tars, it does not sign anything.</li>\n</ol>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"quickstart-install-and-develop","manual":false,"prev":{"path":"/docs/feature-not-implemented-yet","title":"🚧 Not implemented yet"},"next":{"path":"/docs/feature--well-known-webfinger-isnt-properly-set-up-troubleshooting","title":"🧭 \".well-known/webfinger isn't properly set up!\" — Troubleshooting"},"parent":null},{"slug":"feature--well-known-webfinger-isnt-properly-set-up-troubleshooting","path":"/docs/feature--well-known-webfinger-isnt-properly-set-up-troubleshooting","title":"🧭 \".well-known/webfinger isn't properly set up!\" — Troubleshooting","description":"That banner has two quite different causes, and the app now tells them apart.","group":"features","html":"<p>That banner has two quite different causes, and the app now tells them apart.</p>\n<p>The first is the one it names: the server does not answer <code>/.well-known/webfinger</code>.\nFollow the <a href=\"https://docs.nextcloud.com/server/latest/go.php?to=admin-setup-well-known-URL\">documented redirects</a>.</p>\n<p>The second is that <strong>Aloha Social is set up for a different address than the server now\nuses</strong>. Aloha Social reads <code>overwrite.cli.url</code> once, the first time the app is opened, and\nbuilds every account id, post id and WebFinger answer from that stored copy\n(<code>social.cloud_url</code>). Change the server&#39;s URL afterwards and the two drift apart in\nsilence: WebFinger answers for a host nobody asks about, and the app blames\n<code>.well-known</code> when <code>.well-known</code> is fine.</p>\n<p>Aloha Social reports the mismatch with both addresses but will not correct it, because the\nstored address is baked into every id already written. Either point\n<code>overwrite.cli.url</code> back at the address Aloha Social knows, or accept the rename and run\n<code>occ social:reset --uri=&lt;new address&gt;</code>, which deletes everything Aloha Social holds. It\nasks twice; add <code>--force</code> to run it from a script (without it, <code>--no-interaction</code>\nrefuses rather than quietly doing nothing).</p>\n<p>To see the two values:</p>\n<pre><code class=\"language-bash\">occ config:app:get social cloud_url\nocc config:system:get overwrite.cli.url\n</code></pre>\n<p>Administration → Overview reports both of these — and two more things that break\nfederation quietly — without anybody having to open Aloha Social. See\n<a href=\"/docs/admin\">docs/Admin.md</a>\nfor the whole setup, every configuration key and what to watch.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"-well-known-webfinger-isnt-properly-set-up-troubleshooting","manual":false,"prev":{"path":"/docs/feature-quickstart-install-and-develop","title":"📦 Quickstart (install & develop)"},"next":{"path":"/docs/feature-banner-header-upload-troubleshooting","title":"🖼️ Banner / Header upload — Troubleshooting"},"parent":null},{"slug":"feature-banner-header-upload-troubleshooting","path":"/docs/feature-banner-header-upload-troubleshooting","title":"🖼️ Banner / Header upload — Troubleshooting","description":"Banner/header uploads work: the image is stored in the app's document cache, the local actor's cached header is updated, and the change is federated as an actor Update…","group":"features","html":"<p>Banner/header uploads work: the image is stored in the app&#39;s document cache, the\nlocal actor&#39;s cached <code>header</code> is updated, and the change is federated as an actor\n<code>Update</code> (<code>lib/Controller/LocalController.php</code>, <code>uploadBanner()</code>). A banner can also\nbe set from a URL. The upload goes through the same <code>filterMimeTypes()</code> list as an\nattachment (<code>lib/Service/CacheDocumentService.php</code>), so every image type an\nattachment may have is accepted — JPEG, PNG, GIF, WebP, AVIF and HEIC/HEIF (the\nlast converted on the way in); nothing narrows that list to pictures for a banner.</p>\n<p>If an uploaded banner does not appear immediately:</p>\n<ul>\n<li>Reload the profile page (clear the browser cache if necessary).</li>\n<li>Check the server log for <code>[LocalController] uploadBanner failed</code> and for\n<code>Failed to federate banner change</code>, which is only a warning and does not undo the\nlocal upload.</li>\n<li>Re-fetch the account data, or run <code>occ social:cache:refresh</code>, to refresh the cached\nactor.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"banner-header-upload-troubleshooting","manual":false,"prev":{"path":"/docs/feature--well-known-webfinger-isnt-properly-set-up-troubleshooting","title":"🧭 \".well-known/webfinger isn't properly set up!\" — Troubleshooting"},"next":{"path":"/docs/feature-tests","title":"✅ Tests"},"parent":null},{"slug":"feature-tests","path":"/docs/feature-tests","title":"✅ Tests","description":"Backend and frontend unit tests run without an Aloha server or database.","group":"features","html":"<p>Backend and frontend unit tests run without an Aloha server or database.</p>\n<pre><code class=\"language-bash\">composer install            # PHPUnit + OCP interface stubs\ncomposer run test:unit      # PHP: vendor/bin/phpunit -c tests/phpunit.xml\n\nnpm ci\nnpm test                    # JS: vitest run (tests/js/** and src/**/*.test.js)\nnpm run test:coverage       # with a coverage report in coverage/js\nnpm run typecheck           # tsc over the plain-JS half of src/, then vue-tsc over all of it\n</code></pre>\n<p><code>npm run typecheck</code> runs two checks, and neither allows an error. <code>tsc</code> holds the\ntypes, services, stores and utilities to the JSDoc typedefs in <code>src/types/</code>\n(<code>jsconfig.json</code>). <code>vue-tsc</code> then checks every <code>.js</code> and <code>.vue</code> file in <code>src/</code>\nwith the same options (<code>jsconfig.vue.json</code>). A <code>$refs</code> entry or an event target\nis an element the checker cannot see, so it is given its type where it is read:\n<code>/** @type {HTMLInputElement} */ (this.$refs.file)</code>.</p>\n<p>PHP tests live in <code>tests/</code> mirroring <code>lib/</code> (<code>lib/Service/PostService.php</code> →\n<code>tests/Service/PostServiceTest.php</code>). Everything a class needs is mocked; the\nserver code that resolves a service statically — <code>OCP\\Server::get()</code>, which\n<code>Response</code> itself calls on every render — finds a <code>TestContainer</code> instead, which\nknows a silent logger and a session with nobody in it and raises a named error\nfor anything else (see <code>tests/Helper/TestContainer.php</code>). Migration steps are\ngiven a <code>FakeTable</code> that records the schema they ask for rather than building it\n(<code>tests/Migration/</code>). Frontend tests use Vitest with\n<code>@vue/test-utils</code> and jsdom; <code>tests/js/setup.js</code> provides the Aloha globals\n(<code>t</code>, <code>n</code>, <code>OC</code>, <code>OCA</code>, <code>localStorage</code>, router webroots).</p>\n<p>A second PHP suite in <code>tests/Integration/</code> runs against a real Aloha and\ndatabase — migrations, query SQL and storage boundaries the mocks cannot reach.\nCI runs it on SQLite, MySQL and PostgreSQL; locally, point it at an installed\nserver:</p>\n<pre><code class=\"language-bash\">NEXTCLOUD_ROOT=/path/to/nextcloud composer run test:integration\n</code></pre>\n<p>See <code>tests/Integration/README.md</code> for what it covers.</p>\n<h2 id=\"interop-tests\">Interop tests</h2>\n<p>A third PHP suite in <code>tests/Interop/</code> delivers this app&#39;s activities to a <strong>real\nMastodon</strong> and a <strong>real PeerTube</strong> and reads them back out of each one&#39;s own API — a <code>Create</code>, a post\nwith a content warning, an <code>Update</code>, a <code>Delete</code> and an <code>Announce</code>, through the\nreal queue and the real signer, to an instance that has been made to follow the\naccount. Neither of the other two suites can prove the thing that decides\nwhether federation works: that the other end <em>accepts</em> what we send. That gap\nis where a silent drop lives, and the Pixelfed work found three of them.</p>\n<p>Every test skips with a reason when there is no Mastodon to talk to, so running\nit without one is a pass that says so:</p>\n<pre><code class=\"language-bash\">MASTODON_BASE_URL=http://localhost:3000 MASTODON_TOKEN=… \\\nPEERTUBE_BASE_URL=http://localhost:9000 PEERTUBE_USER=… PEERTUBE_PASSWORD=… \\\ncomposer run test:interop\n</code></pre>\n<p><code>.github/workflows/interop.yml</code> stands the whole thing up — Postgres, Redis,\nMastodon, PeerTube, an Aloha and an account on each side — weekly and on\ndemand. Deliberately\nnot on every pull request: it depends on a third-party image whose startup this\nrepository does not control. See <code>tests/Interop/README.md</code>, including what it\ncannot prove.</p>\n<h2 id=\"browser-tests\">Browser tests</h2>\n<p><code>tests/e2e/</code> drives a real Aloha with the app installed, in Chromium,\nthrough <a href=\"https://playwright.dev\">Playwright</a>: sign in, open the app, write a\npost and see it in the feed, walk the Discover page, switch scopes, open a\ngroup list, add and remove a keyword filter, and check that a post of your own\noffers to be deleted and written again. Nothing is mocked, and the bundle under test is the committed one\nin <code>js/</code>. <code>.github/workflows/e2e.yml</code> sets up a throwaway server for every pull\nrequest; against an instance of your own:</p>\n<pre><code>npx playwright install chromium\nE2E_BASE_URL=https://cloud.example E2E_USER=alice E2E_PASSWORD=… E2E_GROUP=&quot;Design&quot; npm run test:e2e\n</code></pre>\n<p><code>E2E_GROUP</code> is optional — the display name of an Aloha group the account is\nin, for the list test; without it that test is skipped.</p>\n","toc":[{"id":"interop-tests","text":"Interop tests","level":2},{"id":"browser-tests","text":"Browser tests","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"tests","manual":false,"prev":{"path":"/docs/feature-banner-header-upload-troubleshooting","title":"🖼️ Banner / Header upload — Troubleshooting"},"next":{"path":"/docs/feature-contributing","title":"🛠️ Contributing"},"parent":null},{"slug":"feature-contributing","path":"/docs/feature-contributing","title":"🛠️ Contributing","description":"This prompts twice and then empties every Aloha Social table. occ social:reset --uninstall additionally drops the tables, migrations, background jobs and app config. See…","group":"features","html":"<ul>\n<li>Contributions welcome — open a pull request and run the build and tests locally\nfirst (<code>npm run lint</code>, <code>npm test</code>, <code>composer run test:unit</code>).</li>\n<li>Reset local Aloha Social data for development with:</li>\n</ul>\n<pre><code class=\"language-bash\">occ social:reset\n</code></pre>\n<p>  This prompts twice and then empties every Aloha Social table. <code>occ social:reset   --uninstall</code> additionally drops the tables, migrations, background jobs and app\n  config. See <a href=\"/docs/occ\">docs/OCC-Commands.md</a> for all commands.</p>\n<ul>\n<li><a href=\"/docs/admin\">docs/Admin.md</a>\nis the administrator&#39;s guide: what federation needs before it works, every app\nconfiguration key with its meaning and default, the sections of the\nadministration page, how moderation is recorded, and the occ commands by task.</li>\n<li><a href=\"/docs/mastodon\">docs/Mastodon-Compatibility.md</a></li>\n<li><a href=\"/docs/atproto\">docs/Atproto-Compatibility.md</a> — the specification for native Bluesky / AT Protocol identities, with what each phase built\nanswers how close this is to Mastodon in the three senses that can mean —\nwhether its clients work, whether peers can tell the difference, and whether an\ninstance could move onto it. Its last section is the backlog that follows:\neverything still between this app and a full replacement, in tiers, with what\neach item actually fixes and whether it is done.</li>\n<li><a href=\"/docs/user\">docs/User-Guide.md</a></li>\n<li><a href=\"/docs/moving\">docs/Moving.md</a> — moving to Aloha Social from another server, and away again, in the order it happens\nis the guide for the people using the app: getting an account, following,\nposting, reading, managing the account, keyboard shortcuts.</li>\n<li><a href=\"/docs/for-you\">docs/For-You.md</a>\nis a specification, not a description of anything that exists: a feed built\nfrom the hashtags somebody&#39;s reading shows they care about, with every learned\ninterest visible and editable. It records the decisions an interview settled —\nwhat is learned, what is deliberately not, how a user turns it off and what\nhappens to what was learned — so that whoever implements it does not have to\ntake them again. Nothing in it is built; the header says so.</li>\n<li>Before picking up refactoring work, read\n<a href=\"/docs/debt\">docs/Technical-Debt.md</a>\n— what in the app is old, borrowed or load-bearing, and what changing it would\ncost — and\n<a href=\"/docs/performance\">docs/Performance.md</a>,\nwhich lists the query and scalability problems that are still open and the\nones that have been fixed. Neither is checked by a test, so re-verify a claim\nbefore acting on it and update the file in the same change as the code.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"contributing","manual":false,"prev":{"path":"/docs/feature-tests","title":"✅ Tests"},"next":{"path":"/docs/feature-license","title":"License"},"parent":null},{"slug":"feature-license","path":"/docs/feature-license","title":"License","description":"Admin guide · User guide · API · occ commands · Architecture · Mastodon compatibility · Bluesky specification","group":"features","html":"<p>See the repository&#39;s license files in the <code>LICENSES/</code> directory.</p>\n<hr>\n<div align=\"center\"><p><strong><a href=\"/docs/admin\">Admin guide</a></strong> ·\n<strong><a href=\"/docs/user\">User guide</a></strong> ·\n<strong><a href=\"docs/API.md\">API</a></strong> ·\n<strong><a href=\"/docs/occ\">occ commands</a></strong> ·\n<strong><a href=\"docs/Architecture.md\">Architecture</a></strong> ·\n<strong><a href=\"/docs/mastodon\">Mastodon compatibility</a></strong> ·\n<strong><a href=\"/docs/atproto\">Bluesky specification</a></strong></p>\n<p>Screenshots are of a development instance with seeded demo accounts.</p>\n</div>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/README.md","sections":null,"anchor":"license","manual":false,"prev":{"path":"/docs/feature-contributing","title":"🛠️ Contributing"},"next":null,"parent":null},{"slug":"start","path":"/docs/start","title":"Getting started with Aloha Social","description":"The good guide for your first day: an account, a first post, the people you want to follow, and the few settings worth changing straight away.","group":"start","html":"<p>Everything on this page happens in the Aloha Social app inside your Aloha. If your organisation has not set up Aloha Social yet, the <a href=\"/install\">installation guide</a> is the page to send your administrator — it takes about ten minutes.</p>\n<h2 id=\"before-you-start\">Before you start</h2>\n<p>You need an Aloha account on a server that runs Aloha Social. That is the whole requirement: the same login, the same password, the same two-factor authentication you already use for files, calendar and chat. There is no second account to create and no separate password to remember.</p>\n<p>Open the app menu in Aloha and choose <strong>Aloha</strong>. The first screen asks whether you want a fediverse identity here. Nothing is created until you answer.</p>\n<h2 id=\"step-1-pick-your-handle\">Step 1 — Pick your handle</h2>\n<p>Your address will be <code>@handle@your.cloud</code>. The handle is suggested from your Aloha user name and accepts letters, digits, underscore, dot and dash.</p>\n<p>Pick it carefully: <strong>the handle cannot be changed later.</strong> Your display name and avatar come from your Aloha account and can be changed there whenever you like.</p>\n<p>Where the administrator allows open registration, the login page also has a <strong>Create an account</strong> button for people who are not Aloha users yet. Such an account is for Aloha Social only.</p>\n<h2 id=\"step-2-take-the-four-step-introduction\">Step 2 — Take the four-step introduction</h2>\n<p>On your first visit the app shows four short screens:</p>\n<ol>\n<li>your address, with a copy button for it;</li>\n<li>people to follow;</li>\n<li>a way to bring the follows you already have from another server;</li>\n<li>a button that puts you in the composer.</li>\n</ol>\n<p>Every step can be skipped. Once closed it stays closed, and <strong>Settings → Help → Introduction</strong> shows it again.</p>\n<h2 id=\"step-3-follow-a-handful-of-people\">Step 3 — Follow a handful of people</h2>\n<p>A timeline with nobody in it tells you nothing. The introduction offers a starting set, and <a href=\"/docs/user-finding-and-following-people\">Discover</a> searches across several fediverse directories at once — the results name which directory answered, so a short list is never mistaken for an empty fediverse.</p>\n<p>Three things worth knowing:</p>\n<ul>\n<li><strong>Starter packs</strong> follow a whole named group of accounts with one click. Your administrator curates the ones for this server.</li>\n<li><strong>Colleagues are suggested</strong> from the Aloha you share, so the people you already work with are the first results.</li>\n<li><strong>Followed hashtags</strong> work like a subscription: follow <code>#photography</code> and those posts arrive in your timeline without anybody following anybody.</li>\n</ul>\n<h2 id=\"step-4-write-your-first-post\">Step 4 — Write your first post</h2>\n<p>Open the composer and write. The four things worth deciding on that first post:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Decision</th>\n<th>What it does</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Audience</strong></td>\n<td>Public, unlisted, followers-only or direct. A reply inherits the audience of the post it answers.</td>\n</tr>\n<tr>\n<td><strong>Content warning</strong></td>\n<td>Collapses the post behind a line of your choosing.</td>\n</tr>\n<tr>\n<td><strong>Alt text</strong></td>\n<td>The composer asks before a picture without a description goes out. A nudge, never a refusal.</td>\n</tr>\n<tr>\n<td><strong>Language</strong></td>\n<td>Labels the post so readers and translation know what to expect.</td>\n</tr>\n</tbody></table></div>\n<p>Anything up to 120 characters can go out drawn big on colour as a short text post. Pictures, video, polls, files and scheduled posts all live behind the same toolbar — see the <a href=\"/features/write\">Write feature page</a>.</p>\n<h2 id=\"step-5-change-these-four-settings\">Step 5 — Change these four settings</h2>\n<p>Everything works with the defaults, but these four are worth two minutes:</p>\n<ol>\n<li><strong>Settings → Appearance</strong> — light, dark, or follow your device. The dark design is the same design, not an afterthought.</li>\n<li><strong>Settings → Notifications → Who may reach you</strong> — five questions, each answered <em>Allow</em> or <em>Hold for review</em>. New accounts start with the calm policy: strangers and brand-new accounts wait quietly instead of ringing the bell.</li>\n<li><strong>Settings → Filters</strong> — add the words you would rather not see. Filters fold matching posts behind the filter&#39;s name or take them out altogether.</li>\n<li><strong>Settings → For you</strong> — the optional second feed, built only from the hashtags you actually read. It explains why every post is there, and it never leaves this server.</li>\n</ol>\n<h2 id=\"where-to-go-next\">Where to go next</h2>\n<ul>\n<li><a href=\"/docs/user\">The full user guide</a> — posting, reading, following, filtering and your account, topic by topic.</li>\n<li><a href=\"/docs/user-keyboard-shortcuts\">Keyboard shortcuts</a> — <code>j</code>, <code>k</code>, <code>l</code>, <code>f</code>, <code>b</code>, and <code>?</code> for the whole list.</li>\n<li><a href=\"/docs/moving\">Moving an account</a> — bringing your posts and follows from another server.</li>\n<li><a href=\"/clients\">Apps and downloads</a> — the web app today, and the Aloha apps for iPhone, Android and desktop.</li>\n</ul>\n","toc":[{"id":"before-you-start","text":"Before you start","level":2},{"id":"step-1-pick-your-handle","text":"Step 1 — Pick your handle","level":2},{"id":"step-2-take-the-four-step-introduction","text":"Step 2 — Take the four-step introduction","level":2},{"id":"step-3-follow-a-handful-of-people","text":"Step 3 — Follow a handful of people","level":2},{"id":"step-4-write-your-first-post","text":"Step 4 — Write your first post","level":2},{"id":"step-5-change-these-four-settings","text":"Step 5 — Change these four settings","level":2},{"id":"where-to-go-next","text":"Where to go next","level":2}],"source":null,"sections":[],"anchor":null,"manual":false,"prev":null,"next":null,"parent":null},{"slug":"user","path":"/docs/user","title":"User Guide","description":"Welcome to Aloha Social! This guide helps you get started and make the most of your account.","group":"user","html":"<p>Welcome to Aloha Social! This guide helps you get started and make the most of your account.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":[{"path":"/docs/user-getting-an-account","title":"Getting an Account","description":"Your Aloha account is your Aloha Social account. Just open the app from your app menu — no new password, no new signup. Your handle (e.g. @you@your-cloud.org) is created automatically from…","parent":false},{"path":"/docs/user-finding-and-following-people","title":"Finding & Following People","description":"Your island and its neighbours shows a visual map: your server in the center, connected servers as islands around it, joined by canoe routes. Larger islands = more connections.","parent":false},{"path":"/docs/user-writing-a-post","title":"Writing a Post","description":"Click New post (top of sidebar) or press n. The composer also sits above most timelines.","parent":false},{"path":"/docs/user-reading-posts","title":"Reading Posts","description":"A thin line in My Feed shows where you last read (Up to date since 14:02). Posts below are dimmed. Syncs with Mastodon apps.","parent":false},{"path":"/docs/user-filtering-and-control","title":"Filtering & Control","description":"Settings → Filters — Add words/phrases to hide or fold matching posts. Set expiry if you want.","parent":false},{"path":"/docs/user-your-profile-and-settings","title":"Your Profile & Settings","description":"Settings → Profile — Display name, bio, avatar, banner, profile fields (links, pronouns, etc.)","parent":false},{"path":"/docs/user-keyboard-shortcuts","title":"Keyboard Shortcuts","description":"Everything a person with an account does in Aloha Social — posting, reading, following, filtering and looking after the account.","parent":false},{"path":"/docs/user-what-the-web-client-doesnt-do-yet","title":"What the Web Client Doesn't Do (Yet)","description":"Everything a person with an account does in Aloha Social — posting, reading, following, filtering and looking after the account.","parent":false},{"path":"/docs/user-need-help","title":"Need Help?","description":"Welcome to a calmer, healthier social network!","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/user-getting-an-account","title":"Getting an Account"},"parent":null},{"slug":"user-getting-an-account","path":"/docs/user-getting-an-account","title":"Getting an Account","description":"Your Aloha account is your Aloha Social account. Just open the app from your app menu — no new password, no new signup. Your handle (e.g. @you@your-cloud.org) is created automatically from…","group":"user","html":"<h2 id=\"if-your-organisation-uses-aloha\">If your organisation uses Aloha</h2>\n<p>Your Aloha account <strong>is</strong> your Aloha Social account. Just open the app from your app menu — no new password, no new signup. Your handle (e.g. <code>@you@your-cloud.org</code>) is created automatically from your Aloha username.</p>\n<h2 id=\"if-youre-joining-a-public-server\">If you&#39;re joining a public server</h2>\n<p>Click &quot;Create an account&quot; on the login page or use an invitation link. Choose your handle carefully — <strong>it cannot be changed later</strong>. You&#39;ll get an address like <code>@username@server.org</code>.</p>\n<h2 id=\"first-steps-after-logging-in\">First steps after logging in</h2>\n<p>A short introduction shows you:</p>\n<ol>\n<li>Your address (with a copy button)</li>\n<li>People to follow</li>\n<li>How to bring follows from another server</li>\n<li>The composer to write your first post</li>\n</ol>\n<p>You can skip any step and reopen it later in <strong>Settings → Help → Introduction</strong>.</p>\n<hr>\n","toc":[{"id":"if-your-organisation-uses-aloha","text":"If your organisation uses Aloha","level":2},{"id":"if-youre-joining-a-public-server","text":"If you're joining a public server","level":2},{"id":"first-steps-after-logging-in","text":"First steps after logging in","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"getting-an-account","manual":false,"prev":{"path":"/docs/user","title":"User Guide"},"next":{"path":"/docs/user-finding-and-following-people","title":"Finding & Following People"},"parent":null},{"slug":"user-finding-and-following-people","path":"/docs/user-finding-and-following-people","title":"Finding & Following People","description":"Your island and its neighbours shows a visual map: your server in the center, connected servers as islands around it, joined by canoe routes. Larger islands = more connections.","group":"user","html":"<h2 id=\"search\">Search</h2>\n<p>Type a name, handle (e.g. <code>@user@example.org</code>), or topic in the search box. The app searches:</p>\n<ul>\n<li>People on your server</li>\n<li>People on servers your admin connected</li>\n<li>Public directories across the fediverse</li>\n</ul>\n<h2 id=\"discover\">Discover</h2>\n<p>The <strong>Discover</strong> page (in the sidebar) has tabs:</p>\n<ul>\n<li><strong>People</strong> — Suggestions, starting with people on your Aloha</li>\n<li><strong>Starter packs</strong> — Curated groups to follow with one click</li>\n<li><strong>Pictures</strong> &amp; <strong>Videos</strong> — Popular media right now</li>\n<li><strong>Hashtags</strong> — Trending topics</li>\n</ul>\n<h2 id=\"your-fediverse-map\">Your Fediverse Map</h2>\n<p><strong>Your island and its neighbours</strong> shows a visual map: your server in the center, connected servers as islands around it, joined by canoe routes. Larger islands = more connections.</p>\n<h2 id=\"follow-hashtags\">Follow hashtags</h2>\n<p>Click any hashtag (e.g. <code>#photography</code>) and hit <strong>Follow</strong> — public posts with that tag appear in your home feed.</p>\n<h2 id=\"moving-from-another-server\">Moving from another server?</h2>\n<p>Export your follows from Mastodon (<code>following_accounts.csv</code>) or Pixelfed (<code>pixelfed-following.json</code>) and upload in <strong>Settings → Migration</strong>.</p>\n<hr>\n","toc":[{"id":"search","text":"Search","level":2},{"id":"discover","text":"Discover","level":2},{"id":"your-fediverse-map","text":"Your Fediverse Map","level":2},{"id":"follow-hashtags","text":"Follow hashtags","level":2},{"id":"moving-from-another-server","text":"Moving from another server?","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"finding-and-following-people","manual":false,"prev":{"path":"/docs/user-getting-an-account","title":"Getting an Account"},"next":{"path":"/docs/user-writing-a-post","title":"Writing a Post"},"parent":null},{"slug":"user-writing-a-post","path":"/docs/user-writing-a-post","title":"Writing a Post","description":"Click New post (top of sidebar) or press n. The composer also sits above most timelines.","group":"user","html":"<h2 id=\"the-composer\">The Composer</h2>\n<p>Click <strong>New post</strong> (top of sidebar) or press <code>n</code>. The composer also sits above most timelines.</p>\n<p><strong>Your post can include:</strong></p>\n<ul>\n<li><strong>Text</strong> — up to 5,000 characters</li>\n<li><strong>Photos</strong> — drag in, or <strong>Add from Files</strong> to use files already in your Aloha (no re-upload!)</li>\n<li><strong>Videos</strong> — up to 2 GB, converted automatically for other servers</li>\n<li><strong>Audio</strong> — MP3, AAC, OGG, FLAC, WAV</li>\n<li><strong>Polls</strong> — 2-4 options, multiple choice, 30 min to 7 days</li>\n<li><strong>Alt text</strong> — Describe images for accessibility (nudged if missing)</li>\n<li><strong>Content warning</strong> — Hide sensitive content behind a &quot;Show more&quot; button</li>\n<li><strong>Location</strong> — Add a place name (never sent to a map service)</li>\n<li><strong>Scheduled posts</strong> — Clock button → pick a time (min 5 min from now)</li>\n<li><strong>Games</strong> — Type <code>/dice</code>, <code>/flip</code>, or <code>/pick tea, coffee</code></li>\n<li><strong>Custom emoji</strong> — Click the GIF button for 881 built-in animated emoji</li>\n<li><strong>Cards</strong> — Short text (≤120 chars, no attachments) as a styled card</li>\n</ul>\n<h2 id=\"visibility-who-receives-your-post\">Visibility (who receives your post)</h2>\n<p>Click the <strong>globe icon</strong> next to Post:</p>\n<ul>\n<li><strong>Public</strong> — Everyone, appears in Local/Global timelines</li>\n<li><strong>Unlisted</strong> — Anyone with the link or who follows you, not in public timelines</li>\n<li><strong>Followers only</strong> — Only your followers, cannot be boosted/quoted</li>\n<li><strong>Direct message</strong> — Only people you @mention</li>\n</ul>\n<h2 id=\"replying-and-quoting\">Replying &amp; Quoting</h2>\n<ul>\n<li><strong>Reply</strong> — Opens composer addressed to the author</li>\n<li><strong>Quote</strong> — Embeds the post in yours (public/unlisted posts only)</li>\n</ul>\n<h2 id=\"your-post-menu\">Your Post Menu (⋯)</h2>\n<ul>\n<li><strong>Edit</strong> — Updates sent to servers that received it</li>\n<li><strong>Delete</strong> — Removes everywhere, cannot be undone</li>\n<li><strong>Pin to profile</strong> — Up to 5 public/unlisted posts</li>\n<li><strong>Archive</strong> — Hides from your profile/timelines here, keeps it on other servers</li>\n<li><strong>Delivery status</strong> — Shows which servers received it</li>\n</ul>\n<hr>\n","toc":[{"id":"the-composer","text":"The Composer","level":2},{"id":"visibility-who-receives-your-post","text":"Visibility (who receives your post)","level":2},{"id":"replying-and-quoting","text":"Replying & Quoting","level":2},{"id":"your-post-menu","text":"Your Post Menu (⋯)","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"writing-a-post","manual":false,"prev":{"path":"/docs/user-finding-and-following-people","title":"Finding & Following People"},"next":{"path":"/docs/user-reading-posts","title":"Reading Posts"},"parent":null},{"slug":"user-reading-posts","path":"/docs/user-reading-posts","title":"Reading Posts","description":"A thin line in My Feed shows where you last read (Up to date since 14:02). Posts below are dimmed. Syncs with Mastodon apps.","group":"user","html":"<h2 id=\"your-feeds-switch-at-top-of-sidebar\">Your Feeds (switch at top of sidebar)</h2>\n<ul>\n<li><strong>My Feed</strong> — Posts from people &amp; hashtags you follow</li>\n<li><strong>Local</strong> — All public posts on your server</li>\n<li><strong>Global</strong> — All public posts your server knows</li>\n<li><strong>For You</strong> — Personalized feed based on what you read (explains why each post appears)</li>\n<li><strong>Photos</strong> / <strong>Videos</strong> — Filtered views with the same feed switcher</li>\n</ul>\n<h2 id=\"read-marker\">Read Marker</h2>\n<p>A thin line in <strong>My Feed</strong> shows where you last read (<em>Up to date since 14:02</em>). Posts below are dimmed. Syncs with Mastodon apps.</p>\n<h2 id=\"shorts\">Shorts</h2>\n<p>Full-screen vertical videos. Swipe to watch. Two types:</p>\n<ul>\n<li><strong>24-hour Shorts</strong> — Seen by followers only, disappear after a day</li>\n<li><strong>Kept Shorts</strong> — Stay on profile like regular posts</li>\n</ul>\n<hr>\n","toc":[{"id":"your-feeds-switch-at-top-of-sidebar","text":"Your Feeds (switch at top of sidebar)","level":2},{"id":"read-marker","text":"Read Marker","level":2},{"id":"shorts","text":"Shorts","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"reading-posts","manual":false,"prev":{"path":"/docs/user-writing-a-post","title":"Writing a Post"},"next":{"path":"/docs/user-filtering-and-control","title":"Filtering & Control"},"parent":null},{"slug":"user-filtering-and-control","path":"/docs/user-filtering-and-control","title":"Filtering & Control","description":"Settings → Filters — Add words/phrases to hide or fold matching posts. Set expiry if you want.","group":"user","html":"<h2 id=\"filtered-words\">Filtered Words</h2>\n<p><strong>Settings → Filters</strong> — Add words/phrases to hide or fold matching posts. Set expiry if you want.</p>\n<h2 id=\"mute-a-conversation\">Mute a Conversation</h2>\n<p>Click <strong>Mute</strong> on any post in a thread — stops all notifications for that thread.</p>\n<h2 id=\"hide-a-server\">Hide a Server</h2>\n<p><strong>Settings → Domain blocks</strong> — Block everything from a specific server, just for you.</p>\n<h2 id=\"block-and-mute-users\">Block &amp; Mute Users</h2>\n<ul>\n<li><strong>Block</strong> — Severs relationship both ways, hides them everywhere (they&#39;re not told)</li>\n<li><strong>Mute</strong> — Hides from your timelines &amp; optionally notifications (1 hour to forever)</li>\n</ul>\n<h2 id=\"who-may-reach-you\">Who May Reach You</h2>\n<p><strong>Settings → Notifications</strong> — Five choices: Allow or Hold for review:</p>\n<ol>\n<li>People you don&#39;t follow</li>\n<li>People who don&#39;t follow you</li>\n<li>Accounts under 30 days old</li>\n<li>Private mentions you didn&#39;t ask for</li>\n<li>Accounts your server limited</li>\n</ol>\n<p>Held notifications wait silently in <strong>Activities</strong> — no bell, no push, no email.</p>\n<h2 id=\"ai-content\">AI Content</h2>\n<p><strong>Settings → One switch</strong> hides all posts that declare themselves AI-generated.</p>\n<hr>\n","toc":[{"id":"filtered-words","text":"Filtered Words","level":2},{"id":"mute-a-conversation","text":"Mute a Conversation","level":2},{"id":"hide-a-server","text":"Hide a Server","level":2},{"id":"block-and-mute-users","text":"Block & Mute Users","level":2},{"id":"who-may-reach-you","text":"Who May Reach You","level":2},{"id":"ai-content","text":"AI Content","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"filtering-and-control","manual":false,"prev":{"path":"/docs/user-reading-posts","title":"Reading Posts"},"next":{"path":"/docs/user-your-profile-and-settings","title":"Your Profile & Settings"},"parent":null},{"slug":"user-your-profile-and-settings","path":"/docs/user-your-profile-and-settings","title":"Your Profile & Settings","description":"Settings → Profile — Display name, bio, avatar, banner, profile fields (links, pronouns, etc.)","group":"user","html":"<h2 id=\"edit-your-profile\">Edit Your Profile</h2>\n<p><strong>Settings → Profile</strong> — Display name, bio, avatar, banner, profile fields (links, pronouns, etc.)</p>\n<h2 id=\"your-posts\">Your Posts</h2>\n<ul>\n<li><strong>Settings → Your posts</strong> — See all your posts, scheduled posts, archived posts, waiting-for-review posts</li>\n</ul>\n<h2 id=\"notifications\">Notifications</h2>\n<ul>\n<li><strong>Quiet hours</strong> — Set when notifications are delivered</li>\n<li><strong>Digest</strong> — Daily summary instead of instant alerts</li>\n<li><strong>Per-conversation</strong> — Mute notifications for specific threads</li>\n</ul>\n<h2 id=\"appearance\">Appearance</h2>\n<ul>\n<li><strong>Dark/Light/System</strong> theme</li>\n<li><strong>Reduced motion</strong> respected</li>\n<li><strong>Sound &amp; haptics</strong> optional</li>\n</ul>\n<h2 id=\"apps-and-sessions\">Apps &amp; Sessions</h2>\n<ul>\n<li><strong>Settings → Apps and account</strong> — See active sessions, revoke access</li>\n<li><strong>Mastodon apps</strong> — Connect via <strong>Settings → Apps and account → Your apps</strong></li>\n</ul>\n<hr>\n","toc":[{"id":"edit-your-profile","text":"Edit Your Profile","level":2},{"id":"your-posts","text":"Your Posts","level":2},{"id":"notifications","text":"Notifications","level":2},{"id":"appearance","text":"Appearance","level":2},{"id":"apps-and-sessions","text":"Apps & Sessions","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"your-profile-and-settings","manual":false,"prev":{"path":"/docs/user-filtering-and-control","title":"Filtering & Control"},"next":{"path":"/docs/user-keyboard-shortcuts","title":"Keyboard Shortcuts"},"parent":null},{"slug":"user-keyboard-shortcuts","path":"/docs/user-keyboard-shortcuts","title":"Keyboard Shortcuts","description":"Everything a person with an account does in Aloha Social — posting, reading, following, filtering and looking after the account.","group":"user","html":"<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Shortcut</th>\n<th>Action</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>n</code></td>\n<td>New post</td>\n</tr>\n<tr>\n<td><code>/</code></td>\n<td>Search</td>\n</tr>\n<tr>\n<td><code>g</code> then <code>h</code></td>\n<td>Go to My Feed</td>\n</tr>\n<tr>\n<td><code>g</code> then <code>l</code></td>\n<td>Go to Local</td>\n</tr>\n<tr>\n<td><code>g</code> then <code>g</code></td>\n<td>Go to Global</td>\n</tr>\n<tr>\n<td><code>g</code> then <code>n</code></td>\n<td>Go to Notifications</td>\n</tr>\n<tr>\n<td><code>g</code> then <code>p</code></td>\n<td>Go to Profile</td>\n</tr>\n<tr>\n<td><code>g</code> then <code>s</code></td>\n<td>Go to Settings</td>\n</tr>\n<tr>\n<td><code>j</code> / <code>k</code></td>\n<td>Next / Previous post</td>\n</tr>\n<tr>\n<td><code>Enter</code></td>\n<td>Open post</td>\n</tr>\n<tr>\n<td><code>b</code></td>\n<td>Boost</td>\n</tr>\n<tr>\n<td><code>f</code></td>\n<td>Favourite</td>\n</tr>\n<tr>\n<td><code>r</code></td>\n<td>Reply</td>\n</tr>\n<tr>\n<td><code>q</code></td>\n<td>Quote</td>\n</tr>\n<tr>\n<td><code>m</code></td>\n<td>Mute conversation</td>\n</tr>\n<tr>\n<td><code>?</code></td>\n<td>Show all shortcuts</td>\n</tr>\n</tbody></table></div>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"keyboard-shortcuts","manual":false,"prev":{"path":"/docs/user-your-profile-and-settings","title":"Your Profile & Settings"},"next":{"path":"/docs/user-what-the-web-client-doesnt-do-yet","title":"What the Web Client Doesn't Do (Yet)"},"parent":null},{"slug":"user-what-the-web-client-doesnt-do-yet","path":"/docs/user-what-the-web-client-doesnt-do-yet","title":"What the Web Client Doesn't Do (Yet)","description":"Everything a person with an account does in Aloha Social — posting, reading, following, filtering and looking after the account.","group":"user","html":"<ul>\n<li>No multi-account switching</li>\n<li>No custom emoji management (admin only)</li>\n<li>No advanced moderation tools (use Mastodon app or web)</li>\n<li>Some Mastodon 4.3+ features not yet implemented</li>\n</ul>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"what-the-web-client-doesnt-do-yet","manual":false,"prev":{"path":"/docs/user-keyboard-shortcuts","title":"Keyboard Shortcuts"},"next":{"path":"/docs/user-need-help","title":"Need Help?"},"parent":null},{"slug":"user-need-help","path":"/docs/user-need-help","title":"Need Help?","description":"Welcome to a calmer, healthier social network!","group":"user","html":"<ul>\n<li><strong>Settings → Help → Introduction</strong> — Replay the welcome tour</li>\n<li><strong>Settings → Help → Keyboard shortcuts</strong> — Full list</li>\n<li><strong>Report a problem</strong> — Post menu (⋯) → Report</li>\n<li><strong>Ask your admin</strong> — For server-specific questions</li>\n</ul>\n<hr>\n<p><em>Welcome to a calmer, healthier social network!</em></p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/User-Guide.md","sections":null,"anchor":"need-help","manual":false,"prev":{"path":"/docs/user-what-the-web-client-doesnt-do-yet","title":"What the Web Client Doesn't Do (Yet)"},"next":null,"parent":null},{"slug":"for-you","path":"/docs/for-you","title":"For you — feature specification","description":"Status: specified 2026-09-24, implemented on feat/my-interests (not yet released) · App: Aloha Social","group":"for-you","html":"<p>Status: specified 2026-09-24, implemented on <code>feat/my-interests</code> (not yet released) · App: Aloha Social</p>\n<p>Where the implementation settled something differently from the first draft, this document says what was built; the API reference is the <code>For you</code> section of <a href=\"API.md\">API.md</a>. The feature was first called <em>For you</em>; every word a reader sees now says <strong>For you</strong> (German <em>Für dich</em>), while the code, the routes, the settings keys and the tables keep the name <code>interests</code>, which is an API and stored data.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/For-You.md","sections":[{"path":"/docs/for-you-overview","title":"What For You is","description":"Aloha Social learns which hashtags a user cares about from how they read. It looks at how long they linger on a post, what they skip, and what they like, boost, reply to, bookmark, open or…","parent":false},{"path":"/docs/for-you-experience","title":"The experience and the signal behind it","description":"A new section in src/views/Settings.vue with id interests, placed after the followed-hashtags section.","parent":false},{"path":"/docs/for-you-ranking","title":"Scoring and ranking","description":"All scoring lives in one pure class, InterestScorer, with no database access, so it can be unit-tested exhaustively.","parent":false},{"path":"/docs/for-you-technical","title":"API, data model and administration","description":"Every mutation answers the full state, so the page never works out ranks itself. \"Less like this\" lives under /api/v1/interests/ rather than beside the status actions, because POST…","parent":false},{"path":"/docs/for-you-privacy","title":"Privacy, performance and delivery","description":"The README, info.xml description (with a fresh screenshot of the feed and the settings section), Architecture.md (tables, scorer, tracker), Mastodon-Compatibility.md (new endpoints) must…","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/for-you-overview","title":"What For You is"},"parent":null},{"slug":"for-you-overview","path":"/docs/for-you-overview","title":"What For You is","description":"Aloha Social learns which hashtags a user cares about from how they read. It looks at how long they linger on a post, what they skip, and what they like, boost, reply to, bookmark, open or…","group":"for-you","html":"<p>Aloha Social learns which hashtags a user cares about from how they read. It looks at\nhow long they linger on a post, what they skip, and what they like, boost,\nreply to, bookmark, open or play. From that it keeps a private, ranked list of\n<strong>interest hashtags</strong>. A new <strong>For you</strong> feed shows posts carrying those\nhashtags, ranked by relevance blended with recency. In Settings the user can\nsee the list and add, remove, reorder and pin its entries.</p>\n<h2 id=\"goals-and-non-goals\">2. Goals and non-goals</h2>\n<p>Goals</p>\n<ul>\n<li>A feed that surfaces interesting posts from everything the server knows, not\nonly from followed accounts.</li>\n<li>Every post in the feed can say why it is there (a matching hashtag).</li>\n<li>The user can see and control the model completely: every learned interest is\nvisible, editable and resettable.</li>\n<li>Learning never leaves the server and is never visible to anyone else.</li>\n</ul>\n<p>Non-goals (v1)</p>\n<ul>\n<li>Topics inferred from untagged text. What is learned is hashtags; the only\nuntagged posts in the feed are the popular ones that fill a short photo or\nvideo ranking (7.5), and they say so.</li>\n<li>Fetching posts from peer servers to fill the feed. v1 uses the local cache.</li>\n<li>Learning from accounts or links. Only hashtags are learned.</li>\n<li>Hiding posts already seen in other feeds.</li>\n</ul>\n<h2 id=\"decisions\">17. Decisions</h2>\n<p>Resolved 2026-09-24:</p>\n<ol>\n<li><strong>GDPR / on-by-default tracking</strong>: an admin setting <em>Learning default for\nusers</em> is added (§10). Out of the box it is on.</li>\n<li><strong>Remove = reset only</strong>: confirmed. A removed tag can be learned again;\nlasting suppression comes from &quot;less like this&quot; or a filter.</li>\n<li><strong>Admin disable keeps data</strong>: confirmed (§10).</li>\n<li><strong>How the feed reaches Mastodon apps</strong>: it does not. The feed is shown by\nAloha Social&#39;s own web interface only; a pseudo-list for apps was tried and\nremoved as confusing (§8). Actions taken in apps still count.</li>\n</ol>\n<p>No open points remain.</p>\n","toc":[{"id":"goals-and-non-goals","text":"2. Goals and non-goals","level":2},{"id":"decisions","text":"17. Decisions","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/For-You.md","sections":null,"anchor":"summary","manual":false,"prev":{"path":"/docs/for-you","title":"For you — feature specification"},"next":{"path":"/docs/for-you-experience","title":"The experience and the signal behind it"},"parent":null},{"slug":"for-you-experience","path":"/docs/for-you-experience","title":"The experience and the signal behind it","description":"A new section in src/views/Settings.vue with id interests, placed after the followed-hashtags section.","group":"for-you","html":"<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Topic</th>\n<th>Decision</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Where signals are collected</td>\n<td>Home, Local, Global, hashtag pages, Explore/Discover, post detail/thread</td>\n</tr>\n<tr>\n<td>Signals</td>\n<td>Dwell time, explicit actions, negative actions, media interaction</td>\n</tr>\n<tr>\n<td>Storage</td>\n<td>Server-side, private per user, aggregated scores only (no raw event log)</td>\n</tr>\n<tr>\n<td>Consent</td>\n<td>Opt-out per user; the default (on/off) is an admin setting, on out of the box</td>\n</tr>\n<tr>\n<td>&quot;Looked at extra long&quot;</td>\n<td>Relative to the user&#39;s own baseline, adjusted for post length and media</td>\n</tr>\n<tr>\n<td>Change over time</td>\n<td>Exponential decay (half-life, default 30 days)</td>\n</tr>\n<tr>\n<td>Listed interest</td>\n<td>Score above a threshold, capped at top N (default 30); manual tags always listed</td>\n</tr>\n<tr>\n<td>Multi-tag posts</td>\n<td>A post&#39;s signal is split evenly across its hashtags</td>\n</tr>\n<tr>\n<td>Candidate pool</td>\n<td>Every post the viewer may see in the local cache</td>\n</tr>\n<tr>\n<td>Ordering</td>\n<td>Relevance × recency</td>\n</tr>\n<tr>\n<td>Untagged posts</td>\n<td>Excluded</td>\n</tr>\n<tr>\n<td>Feed extras</td>\n<td>&quot;Why am I seeing this&quot; chip, diversity/exploration, inline &quot;less like this&quot;</td>\n</tr>\n<tr>\n<td>Settings display</td>\n<td>A tag cloud: size and emphasis show priority, flowing in rank order</td>\n</tr>\n<tr>\n<td>Reprioritize</td>\n<td>Drag within the cloud, or Higher/Lower in a per-tag popover; pin</td>\n</tr>\n<tr>\n<td>Remove</td>\n<td>Resets the score to zero; the tag can be learned again</td>\n</tr>\n<tr>\n<td>Followed hashtags</td>\n<td>Kept as a separate list; followed tags seed interests</td>\n</tr>\n<tr>\n<td>Settings controls</td>\n<td>Pause learning, reset all, include in data export</td>\n</tr>\n<tr>\n<td>Cold start</td>\n<td>Followed tags, featured tags and local trending, topped up with what is popular here, with a &quot;still learning&quot; hint</td>\n</tr>\n<tr>\n<td>Placement</td>\n<td>Timeline switcher, second after My Feed; the web interface only — no Mastodon API for it</td>\n</tr>\n<tr>\n<td>Safety</td>\n<td>Mutes, blocks, domain blocks and filters respected; language filter</td>\n</tr>\n<tr>\n<td>Admin</td>\n<td>Enable/disable the feature; default for users; tuning parameters</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"user-experience\">4. User experience</h2>\n<h2 id=\"4-1-feed\">4.1 Feed</h2>\n<ul>\n<li><strong>For you</strong> is the second option in the timeline switcher: My Feed /\nFor you / Local / Global (<a href=\"https://github.com/AlohaSocial/social/blob/master/src/views/Timeline.vue\">src/views/Timeline.vue</a>).\nRoute <code>/timeline/interests</code>, which the existing <code>/timeline/{path}</code> server\nroute already serves. The path keeps the internal name.</li>\n<li><strong>Photos</strong> and <strong>Videos</strong> offer <strong>For you</strong> as a fourth scope beside My Feed,\nLocal and Global (<code>?scope=interests</code>), and so does the <strong>Shorts</strong> stack,\nwhich opens on it once reading has taught the feed something (7.5).</li>\n<li>Each post shows a small chip: &quot;Because you follow #photography&quot; (for a\nfollowed tag) or &quot;Because you&#39;re interested in #photography&quot; (learned or\nmanual). With two or more matches: &quot;#photography, #analog +1&quot;. Tapping the\nchip opens the hashtag timeline.</li>\n<li>The post menu gains <strong>Less like this</strong> (see 5.2). In this feed, using it\nalso hides the post at once and shows a toast with an Undo.</li>\n<li>While learning is thin (see 6.5), a dismissible banner at the top says:\n&quot;Still learning what you like. Showing posts from hashtags you follow and\nwhat&#39;s trending here. [Manage interests]&quot;.</li>\n<li>Empty state (no interests, nothing trending, and no public post on the\ninstance to fill with): explains how the feed learns\nand links to Settings → Interests.</li>\n</ul>\n<h2 id=\"4-2-first-use-notice\">4.2 First-use notice</h2>\n<p>Tracking is on by default, so users must be told about it. The first time the\nweb UI records a signal for a user, it shows a one-time notice once per\naccount. The acknowledgement is stored server-side:</p>\n<blockquote>\n<p>Aloha Social now learns which hashtags interest you from how you read, to build\nyour For you feed. This stays on this server and is only visible to\nyou. [Manage] [Turn off] [Got it]</p>\n</blockquote>\n<h2 id=\"4-3-settings-interests\">4.3 Settings → Interests</h2>\n<p>A new section in <a href=\"https://github.com/AlohaSocial/social/blob/master/src/views/Settings.vue\">src/views/Settings.vue</a> with id\n<code>interests</code>, placed after the followed-hashtags section.</p>\n<ul>\n<li><strong>Learn from my browsing</strong> (toggle, default on). Off = opt-out: no signals\nare collected, the feed tab is hidden, the list is kept but frozen.</li>\n<li><strong>Pause learning</strong> (toggle). The feed keeps working on the current list, but\nno new signals are recorded and decay stops. It is for &quot;I&#39;m browsing\nsomething unusual today&quot;. It is disabled while learning is off.</li>\n<li><strong>Interest cloud</strong>: the interests are shown as a tag cloud, the main visual\nelement of the section (see 4.4).</li>\n<li><strong>Add interest</strong>: a hashtag input with autocomplete from known hashtags, at\nthe end of the cloud (an inline &quot;+ Add&quot; pill that turns into the input). The\ntag is added as a manual interest. It floats with the listing threshold as\nits score, so it usually lands low in the cloud; the cloud brings it into\nview so the reader sees where it went.</li>\n<li><strong>Languages for For you</strong>: multi-select, empty = all languages. This is\na new preference; Aloha Social has no language preference yet.</li>\n<li><strong>Reset all interests</strong>: clears learned scores, manual entries, pins and the\ndwell baseline. Needs a confirmation step built into the page (the viewer has\nno <code>confirm()</code>).</li>\n</ul>\n<p>Removing a learned tag resets its score to 0 (it may be learned again). The\nrow disappears and a toast offers Undo for 10 s. Removing a followed tag&#39;s\ninterest only removes the interest; the follow stays. Its seed (6.4) keeps it\nlisted while it is followed, so the settings page says &quot;Unfollow #x to remove\nit from interests&quot; for followed tags.</p>\n<h2 id=\"4-4-the-interest-cloud\">4.4 The interest cloud</h2>\n<p>The cloud shows priority at a glance and lets the user change it in place.</p>\n<p><strong>Layout.</strong> Tags flow left to right and wrap, in effective rank order (6.5),\nso the reading order is the priority order and the top interest comes first.\nThe layout is deliberately not a random scatter: an ordered flow keeps drag\ntargets predictable, works with a keyboard and a screen reader, and reflows\ncleanly at phone width.</p>\n<p><strong>Encoding.</strong></p>\n<ul>\n<li><em>Size</em> follows the rank weight <code>w(rank)</code> (6.6): six steps from 2.0 rem for\nthe top entries down to 0.85 rem for the tail, so the size change between\nneighbouring ranks is gradual rather than jumpy.</li>\n<li><em>Weight and colour intensity</em> follow the same step: the top tags are bold\non the primary colour, the tail is regular on a muted tint. Both themes are\ncovered with Aloha colour variables, never fixed colours.</li>\n<li><em>Source</em> is a small leading glyph rather than a badge, to keep the cloud\ncalm: a pin for pinned, a hand/pencil for added by you, a bell for followed,\nno glyph for learned.</li>\n<li><em>Trend</em> (learned tags only): a subtle up/down arrow when the score moved by\nmore than 20 % since the week began. <code>score_week</code> holds the score as the\ncurrent week of activity began: it is set when a signal arrives in a week\nafter the previous one, so no job is needed.</li>\n<li>Tags with a negative score are not shown in the cloud.</li>\n<li>Hover/focus shows a tooltip: &quot;Rank 4 · learned · score 12.3&quot;.</li>\n</ul>\n<p><strong>Changing priority.</strong></p>\n<ul>\n<li><em>Drag</em> a tag onto a new position in the flow. The other tags make room with\na short animation, and the dropped tag resizes to its new rank. Dropping an\nunpinned learned tag pins it (6.5), shown by the pin glyph appearing.</li>\n<li><em>Tag popover</em>: clicking a tag opens a small popover with<ul>\n<li><strong>Higher priority</strong> / <strong>Lower priority</strong> (moves one rank, pins it),</li>\n<li><strong>Move to top</strong>,</li>\n<li><strong>Pin / Unpin</strong>,</li>\n<li><strong>Open #tag</strong> (the hashtag timeline),</li>\n<li><strong>Remove</strong>.\nThis is how touch and keyboard users reprioritize without dragging.</li>\n</ul>\n</li>\n<li>Keyboard: the cloud is one roving-tabindex group. Arrow keys move focus,\nEnter opens the popover, and Alt+←/→ moves the focused tag one rank.\nEvery move is announced through <code>aria-live</code> (&quot;#photography, now priority\n3 of 24&quot;).</li>\n</ul>\n<p><strong>Removing.</strong> A small × appears on hover/focus (always visible on touch) and\nin the popover. The tag fades out, the cloud reflows, and a toast offers Undo\nfor 10 s.</p>\n<p><strong>States.</strong> Empty: a faint placeholder cloud with the text &quot;Your interests\nappear here as you read&quot; and the Add pill. Thin learning (6.5): the cloud\nshows what exists plus a &quot;Still learning&quot; note. The temporary trending seeds\nare not shown. Learning off: the cloud is shown dimmed, still editable, with\na note that it is frozen.</p>\n<p><strong>Size cap.</strong> The cloud shows the listed entries (at most <code>N</code>, default 30).\nBelow the cloud, a &quot;Show more candidates&quot; disclosure lists learned tags that\nare just under the threshold as small pills. Tapping one adds it as a manual\ninterest, which is a quick way to promote a tag.</p>\n<p><strong>Motion.</strong> Reordering and resizing animate with FLIP transitions of about\n200 ms, which are turned off under <code>prefers-reduced-motion</code>.</p>\n<p>Implementation: <code>src/components/InterestCloud.vue</code> (cloud + popover) inside\n<code>InterestsSettings.vue</code>. It uses the existing <code>NcPopover</code>/<code>NcActions</code> and no new\ndrag library unless the one already in the bundle is insufficient. Check this\nagainst the dependency list before adding one.</p>\n<h2 id=\"signal-collection\">5. Signal collection</h2>\n<h2 id=\"5-1-dwell-web-ui-only\">5.1 Dwell (web UI only)</h2>\n<p>Tracked in <code>TimelineList.vue</code>, which already runs an <code>IntersectionObserver</code>\n(<a href=\"https://github.com/AlohaSocial/social/blob/master/src/components/TimelineList.vue#L931\">TimelineList.vue:931</a>), plus\n<code>TimelineSinglePost.vue</code> for the detail view. Collection lives in one\n<code>src/services/interestTracker.js</code> module so every view uses the same rules.</p>\n<ul>\n<li>A post is <strong>in view</strong> while ≥ 50 % of it is visible, <code>document.visibilityState</code>\nis <code>visible</code> and the window has focus.</li>\n<li>Dwell pauses after 20 s without scroll, pointer or key input (reading\nstopped) and resumes on input. One view&#39;s dwell is capped at 30 s.</li>\n<li>A post collapsed behind a content warning counts only after it is expanded.</li>\n<li>A post counts as <strong>skipped</strong> when it passed fully through the viewport with\n&lt; 0.3× the expected dwell (see 6.1) while the user was scrolling.</li>\n<li>Nothing is recorded for the user&#39;s own posts, for posts without hashtags, or\nfor posts shown only as a filter warning.</li>\n<li>The tracker buffers events and flushes them every 30 s, on\n<code>visibilitychange → hidden</code> and on <code>pagehide</code> (via <code>navigator.sendBeacon</code>).\nAt most 100 events per request.</li>\n</ul>\n<p>Event sent to the server (the client never sends hashtags; the server reads\nthem from the stored post, so a client cannot inject tags):</p>\n<pre><code class=\"language-json\">{ &quot;status_id&quot;: &quot;113…&quot;, &quot;kind&quot;: &quot;dwell&quot;, &quot;ms&quot;: 5400, &quot;context&quot;: &quot;home&quot; }\n{ &quot;status_id&quot;: &quot;113…&quot;, &quot;kind&quot;: &quot;skip&quot;, &quot;context&quot;: &quot;federated&quot; }\n{ &quot;status_id&quot;: &quot;113…&quot;, &quot;kind&quot;: &quot;media&quot;, &quot;context&quot;: &quot;tag&quot; }\n</code></pre>\n<p><code>kind</code> ∈ <code>dwell | skip | open | media | link</code>. <code>context</code> ∈ <code>home | local | federated | tag | explore | detail | interests | photos | videos | shorts</code>\n(<code>reels</code>, which older cached bundles send for the Shorts stack, is accepted\nas <code>shorts</code>).</p>\n<p>In the Photos and Videos grids every tile is on screen at once, so time in\nview says nothing about any one of them: there only opening a tile counts,\nas <code>media</code>. The Shorts stack (<code>src/services/shortSignals.js</code>) measures the\nplayer instead of the screen, under <code>shorts</code>: a slide left within 2 s that had\nnot played through is a <code>skip</code>; otherwise a <code>dwell</code> whose <code>ms</code> is how much of\nthe video played — all of it once it ended or looped. The server weighs that\nagainst the video&#39;s running time (6.1).</p>\n<h2 id=\"5-2-explicit-and-negative-actions-server-side\">5.2 Explicit and negative actions (server-side)</h2>\n<p>These are recorded on the server where the action happens, so they also count\nwhen the action comes from a Mastodon app:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>Where it is recorded</th>\n<th>Signal</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Favourite</td>\n<td><code>LikeService</code></td>\n<td>+2</td>\n</tr>\n<tr>\n<td>Boost</td>\n<td><code>BoostService</code></td>\n<td>+3</td>\n</tr>\n<tr>\n<td>Reply</td>\n<td>status creation with <code>inReplyTo</code></td>\n<td>+3</td>\n</tr>\n<tr>\n<td>Bookmark</td>\n<td>bookmark endpoint</td>\n<td>+3</td>\n</tr>\n<tr>\n<td>Open detail/thread</td>\n<td>web <code>open</code> event</td>\n<td>+1.5</td>\n</tr>\n<tr>\n<td>Expand media / play video / open link</td>\n<td>web <code>media</code>, <code>link</code> events</td>\n<td>+1</td>\n</tr>\n<tr>\n<td>Long dwell / normal dwell / skip</td>\n<td>web <code>dwell</code>, <code>skip</code> events</td>\n<td>+1 / +0.3 / −0.2 (see 6.1)</td>\n</tr>\n<tr>\n<td>Less like this</td>\n<td>new endpoint</td>\n<td>−3</td>\n</tr>\n<tr>\n<td>Mute author (from a post)</td>\n<td><code>MuteDialog</code> sends a <code>mute</code> signal after a successful mute</td>\n<td>−1</td>\n</tr>\n</tbody></table></div>\n<p>Undoing an action (unfavourite, unboost, unbookmark) does not subtract. It is\nnot worth the bookkeeping, and decay covers it.</p>\n<p>Dedupe: each <code>(user, post, kind)</code> counts at most once per 24 h, so rereading\na post does not inflate its tags. This uses a short-lived cache key\n(<code>ICache</code>, TTL 24 h) instead of a table.</p>\n<p>Nothing is recorded while learning is off or paused, or while the feature is\ndisabled by the admin.</p>\n","toc":[{"id":"user-experience","text":"4. User experience","level":2},{"id":"4-1-feed","text":"4.1 Feed","level":2},{"id":"4-2-first-use-notice","text":"4.2 First-use notice","level":2},{"id":"4-3-settings-interests","text":"4.3 Settings → Interests","level":2},{"id":"4-4-the-interest-cloud","text":"4.4 The interest cloud","level":2},{"id":"signal-collection","text":"5. Signal collection","level":2},{"id":"5-1-dwell-web-ui-only","text":"5.1 Dwell (web UI only)","level":2},{"id":"5-2-explicit-and-negative-actions-server-side","text":"5.2 Explicit and negative actions (server-side)","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/For-You.md","sections":null,"anchor":"decisions-from-the-interview","manual":false,"prev":{"path":"/docs/for-you-overview","title":"What For You is"},"next":{"path":"/docs/for-you-ranking","title":"Scoring and ranking"},"parent":null},{"slug":"for-you-ranking","path":"/docs/for-you-ranking","title":"Scoring and ranking","description":"All scoring lives in one pure class, InterestScorer, with no database access, so it can be unit-tested exhaustively.","group":"for-you","html":"<p>All scoring lives in one pure class, <code>InterestScorer</code>, with no database access,\nso it can be unit-tested exhaustively.</p>\n<h2 id=\"6-1-dwell-normalisation\">6.1 Dwell normalisation</h2>\n<p>Expected dwell for a post:</p>\n<pre><code>expected_ms = 1200 + 35 × visible_text_chars + 1500 × media_count\n</code></pre>\n<p>(capped at 20 000). The ratio <code>r = dwell_ms / expected_ms</code> is compared with the\nuser&#39;s own baseline <code>b</code>, an exponential moving average of <code>r</code> over their dwell\nevents (α = 0.05, starting at 1.0, stored per user):</p>\n<ul>\n<li><code>r ≥ 2b</code> → long dwell, +1</li>\n<li><code>b ≤ r &lt; 2b</code> → normal dwell, +0.3</li>\n<li><code>r &lt; b</code> and not a skip → 0</li>\n<li>skip → −0.2</li>\n</ul>\n<p>The baseline is updated only by <code>dwell</code> events, never by skips.</p>\n<p>A <code>dwell</code> from the Shorts stack (<code>context</code> <code>shorts</code>) on a video that says how\nlong it runs is watch time, not reading time, and is judged differently:</p>\n<pre><code>expected_ms = min(30 000, duration_ms)\nshare       = dwell_ms / expected_ms\n</code></pre>\n<p><code>share ≥ 0.9</code> → +1, <code>0.5 ≤ share &lt; 0.9</code> → +0.3, less → 0, and the baseline\nis not touched: how fast someone watches says nothing about how fast they read.</p>\n<h2 id=\"6-2-distribution-across-hashtags\">6.2 Distribution across hashtags</h2>\n<p>A post with <code>n</code> hashtags (from <code>social_stream_tag</code>, normalised with\n<code>FollowedTagsRequest::normalise</code>) gives each tag <code>signal / n</code>. Posts with more\nthan 15 hashtags produce no signal at all, because they are tag spam.</p>\n<h2 id=\"6-3-decay\">6.3 Decay</h2>\n<p>Scores decay exponentially with half-life <code>H</code> (admin, default 30 days). Decay\nis applied lazily: a row stores <code>score</code> and <code>scored_at</code>, and</p>\n<pre><code>score_now = score × 2^(−(now − scored_at) / H)\n</code></pre>\n<p>is computed on read and when a new signal is folded in (the result is written\nback with <code>scored_at = now</code>). No background job is needed. While learning is\npaused, <code>scored_at</code> is shifted forward on resume by the paused duration, so a\npause does not decay the list.</p>\n<p>Scores are clamped to [−10, 50]. Negative scores are kept: they push a tag&#39;s\nposts down in the feed and stop weak positive signals from listing it again\nright away. Pinned and manual entries do not decay.</p>\n<h2 id=\"6-4-followed-hashtags-as-seeds\">6.4 Followed hashtags as seeds</h2>\n<p>While a tag is followed, its effective score is <code>max(score, T)</code>, where <code>T</code> is\nthe listing threshold. It is always listed, but real reading still moves it\nabove other entries. Unfollowing removes the floor; the learned score stays.</p>\n<h2 id=\"6-5-the-listed-interests\">6.5 The listed interests</h2>\n<p>A <strong>pinned</strong> tag holds an absolute rank: the rank it was moved or pinned to.\nEvery other listed tag floats and fills the free ranks by score:</p>\n<ul>\n<li>manual and followed tags, with at least <code>T</code> (admin, default 3.0) as their\nscore;</li>\n<li>learned tags whose score is at least <code>T</code>;</li>\n</ul>\n<p>up to <code>N</code> (admin, default 30) listed tags. A pin is the reader&#39;s word and is\nnot counted against the cap. Two pins asking for one rank land next to each\nother; a pin beyond the end of the list lands at its end.</p>\n<p>Moving a tag to rank <em>p</em> (dragging it there, <em>Higher/Lower priority</em> or <em>Move\nto top</em>) pins it at <em>p</em> and moves every pin at <em>p</em> or below down one, so it\nlands exactly where it was dropped. Unpinning lets it float again. Learned tags\nabove the threshold that did not fit under the cap are the first candidates.</p>\n<p>Learning is <strong>thin</strong> while fewer than 3 entries are listed. The feed then adds\nthe reader&#39;s featured tags and the top 10 local trending tags\n(<code>HashtagService</code> trends) as temporary seeds with weight 0.5. These do not\nappear in Settings.</p>\n<h2 id=\"6-6-feed-weight-per-tag\">6.6 Feed weight per tag</h2>\n<p>Weight follows rank rather than raw score, so dragging has a predictable\neffect: <code>w(rank) = 1 / (1 + 0.15 × rank)</code> (rank 0 = top), which gives 1.0 for\nthe top entry, about 0.5 at rank 7, and 0.18 at rank 30. Tags with a negative\neffective score get weight <code>−0.5</code>.</p>\n<h2 id=\"feed-ranking\">7. Feed ranking</h2>\n<h2 id=\"7-1-candidates\">7.1 Candidates</h2>\n<p>Posts the viewer is allowed to see (the same visibility limits as the public\nand home timelines), created within the last <code>W</code> days (admin, default 7),\ncarrying at least one tag from the effective list. The query joins\n<code>social_stream_tag</code> on <code>hashtag IN (…)</code> (index <code>social_st_ht</code> exists), and at\nmost 1 000 candidates are fetched, newest first.</p>\n<p>Excluded: the user&#39;s own posts; posts from blocked or muted accounts and\nblocked domains; posts matched by a filter with the <em>hide</em> action (a <em>warn</em>\nfilter shows the usual warning); posts marked &quot;less like this&quot;; posts not in\nthe chosen languages (posts without a language are kept); replies to posts the\nviewer cannot see.</p>\n<h2 id=\"7-2-score\">7.2 Score</h2>\n<pre><code>relevance = Σ w(tag) over matched tags, at most 3 tags counted\nrecency   = 2^(−age_hours / 24)\nrank      = relevance × recency\n</code></pre>\n<p>Candidates with <code>relevance ≤ 0</code> are dropped.</p>\n<h2 id=\"7-3-diversity-and-exploration\">7.3 Diversity and exploration</h2>\n<p>Applied when a page is assembled:</p>\n<ul>\n<li>at most 2 posts per author per 20;</li>\n<li>at most 40 % of a page from the same top-matched tag;</li>\n<li>about 1 in 10 slots is an <strong>exploration</strong> post: a post with a tag that\nfrequently co-occurs with the user&#39;s top 5 interests but is not listed\nitself. Its chip says &quot;Related to #photography&quot;. Exploration is left out\nwhile learning is thin.</li>\n</ul>\n<h2 id=\"7-4-pagination\">7.4 Pagination</h2>\n<p>Ranking is not chronological, so a page is cut from a <strong>ranked snapshot</strong> of\npost ids, kept per reader in the distributed cache for an hour; every read\nextends it. With <code>max_id</code> the page continues after that id&#39;s position in the\nsnapshot, so clients that page with the last post&#39;s id work unchanged;\n<code>offset</code> works too. A request with no cursor builds a new snapshot. When no\nsnapshot is kept — it expired, or the instance has no memory cache — the\nranking is made again and the cursor looked up in it, and a cursor that is no\nlonger in it ends the feed. The <code>Link</code> header carries <code>next</code> only.</p>\n<h2 id=\"7-5-photos-videos-and-shorts\">7.5 Photos, videos and Shorts</h2>\n<p>The same ranking comes narrowed to one kind: <code>media=photos</code> (a post with a\npicture: <code>limitToMediaType(&#39;image&#39;)</code>), <code>media=videos</code> (a video post,\nPeerTube&#39;s included: <code>limitToVideo()</code>), or Mastodon&#39;s <code>only_media=true</code> for\nboth (<code>limitToMedia()</code>) — the Photos and Videos timelines&#39; own filters on the\nindexed <code>media_kind</code> column. Anything else is ignored, as the other media\nparameters ignore an unknown kind.</p>\n<ul>\n<li>Each kind is a snapshot of its own (<code>feed/{media}/{viewer}</code>), so paging one\nnever lands in another.</li>\n<li>Pictures and videos carry fewer hashtags and are rarer, so a narrowed\nranking looks back twice the window; hides are kept that long too.</li>\n<li><strong>Popular fill.</strong> A newcomer has no reading yet, and few pictures carry the\ntags someone reads. Where a ranking — the plain feed as much as a narrowed\none — holds fewer than 40 posts, the rest is what is trending in the same\nkind (<code>TrendService</code>, which feeds Explore; on a young instance the media\nrankings are topped up with the newest media and the plain feed with the\nnewest public posts), less the reader&#39;s own, hidden and already ranked\nposts. Those carry <code>reason</code> <code>popular</code> and no tags, and the chip says\n<em>Popular right now</em>, links nowhere and names no hashtag. The whole feed is\nnever filled this way.</li>\n<li><strong>Watching.</strong> For a <code>shorts</code> dwell the expected time is the video&#39;s running\ntime, capped at the 30 s one look can be worth: 90 % of it or more is +1,\nhalf +0.3, less nothing, and the reading pace is left alone. A video whose\nrunning time is unknown is weighed as a post.</li>\n<li><strong>Shorts default.</strong> The page is told whether a reading pace has been\nwritten (<code>profile</code> in the page state); once it has, Shorts opens on For you.</li>\n<li>Nothing in the data says &quot;short&quot;: a kept short is every video. A length or\norientation filter would need those stored.</li>\n<li><strong>24-hour shorts are not ranked.</strong> The Shorts stack puts the followed\npeople&#39;s 24-hour shorts ahead of the ranked videos, in their own order (per\nperson, unseen first). They live in their own table rather than the stream,\nso no For you ranking ever holds one.</li>\n</ul>\n","toc":[{"id":"6-1-dwell-normalisation","text":"6.1 Dwell normalisation","level":2},{"id":"6-2-distribution-across-hashtags","text":"6.2 Distribution across hashtags","level":2},{"id":"6-3-decay","text":"6.3 Decay","level":2},{"id":"6-4-followed-hashtags-as-seeds","text":"6.4 Followed hashtags as seeds","level":2},{"id":"6-5-the-listed-interests","text":"6.5 The listed interests","level":2},{"id":"6-6-feed-weight-per-tag","text":"6.6 Feed weight per tag","level":2},{"id":"feed-ranking","text":"7. Feed ranking","level":2},{"id":"7-1-candidates","text":"7.1 Candidates","level":2},{"id":"7-2-score","text":"7.2 Score","level":2},{"id":"7-3-diversity-and-exploration","text":"7.3 Diversity and exploration","level":2},{"id":"7-4-pagination","text":"7.4 Pagination","level":2},{"id":"7-5-photos-videos-and-shorts","text":"7.5 Photos, videos and Shorts","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/For-You.md","sections":null,"anchor":"scoring","manual":false,"prev":{"path":"/docs/for-you-experience","title":"The experience and the signal behind it"},"next":{"path":"/docs/for-you-technical","title":"API, data model and administration"},"parent":null},{"slug":"for-you-technical","path":"/docs/for-you-technical","title":"API, data model and administration","description":"Every mutation answers the full state, so the page never works out ranks itself. \"Less like this\" lives under /api/v1/interests/ rather than beside the status actions, because POST…","group":"for-you","html":"<p>All under the app&#39;s API routing, all the viewer&#39;s own, all a 404 while the\nadministrator has the feature off:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Path</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET</td>\n<td><code>/api/v1/interests</code></td>\n<td>settings, listed interests in rank order, candidates, <code>thin</code>, <code>cap</code></td>\n</tr>\n<tr>\n<td>POST</td>\n<td><code>/api/v1/interests</code></td>\n<td>add a manual interest <code>{ tag }</code></td>\n</tr>\n<tr>\n<td>POST</td>\n<td><code>/api/v1/interests/{tag}/move</code></td>\n<td>pin at rank <code>{ position }</code></td>\n</tr>\n<tr>\n<td>POST</td>\n<td><code>/api/v1/interests/{tag}/pin</code>, <code>/unpin</code></td>\n<td>pin where it stands / let it float</td>\n</tr>\n<tr>\n<td>DELETE</td>\n<td><code>/api/v1/interests/{tag}</code></td>\n<td>forget it; 422 for a followed tag</td>\n</tr>\n<tr>\n<td>POST</td>\n<td><code>/api/v1/interests/reset</code></td>\n<td>forget everything</td>\n</tr>\n<tr>\n<td>PUT</td>\n<td><code>/api/v1/interests/settings</code></td>\n<td>learning, paused, languages, notice acknowledged</td>\n</tr>\n<tr>\n<td>POST</td>\n<td><code>/api/v1/interests/signals</code></td>\n<td>web events (5.1); 204; 30 a minute</td>\n</tr>\n<tr>\n<td>POST / DELETE</td>\n<td><code>/api/v1/interests/less/{nid}</code></td>\n<td>less like this / undo</td>\n</tr>\n<tr>\n<td>GET</td>\n<td><code>/api/v1/timelines/interests</code></td>\n<td>the feed; <code>limit</code>, <code>max_id</code>, <code>offset</code>, <code>media</code>, <code>only_media</code></td>\n</tr>\n<tr>\n<td>POST</td>\n<td><code>/admin/interests</code></td>\n<td>the admin card (administrators only)</td>\n</tr>\n</tbody></table></div>\n<p>Every mutation answers the full state, so the page never works out ranks\nitself. &quot;Less like this&quot; lives under <code>/api/v1/interests/</code> rather than beside\nthe status actions, because <code>POST /api/v1/statuses/{nid}/{act}</code> would match\nit. The feed is a literal route of its own rather than a name for\n<code>TimelineApiController::timelines()</code>: the router matches it exactly before it tries\nthe slashed <code>/api/v1/timelines/{timeline}/</code>, so which controller is read first\ndoes not decide it.</p>\n<p>Mastodon apps: there is no standard endpoint for this, and the feed is not\noffered to them — it belongs to this app&#39;s own web interface. A pseudo-list\nwas built and taken out again: in a list the feed looked like something it is\nnot, and apps offered edits that could only fail. What a reader does in an app\nstill teaches their interests, through the explicit actions in 5.2; apps send\nno dwell.</p>\n<h2 id=\"data-model\">9. Data model</h2>\n<p>Two new tables, in a migration step of their own\n(<code>Version1000Date20260925000020</code>) rather than in the squash: the squash is\nrecorded as run on every existing instance, so a table added to it would reach\nfresh installs only.</p>\n<p><code>social_interest</code></p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Column</th>\n<th>Type</th>\n<th>Notes</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>id</td>\n<td>bigint, autoincrement</td>\n<td></td>\n</tr>\n<tr>\n<td>actor_id_prim</td>\n<td>string(32)</td>\n<td>the reader, as every other table keys it</td>\n</tr>\n<tr>\n<td>hashtag</td>\n<td>string(127)</td>\n<td>normalised</td>\n</tr>\n<tr>\n<td>score</td>\n<td>float</td>\n<td>clamped [−10, 50]</td>\n</tr>\n<tr>\n<td>scored_at</td>\n<td>bigint</td>\n<td>unix time, for lazy decay</td>\n</tr>\n<tr>\n<td>manual</td>\n<td>smallint</td>\n<td>added by the reader</td>\n</tr>\n<tr>\n<td>position</td>\n<td>int, nullable</td>\n<td>the pinned rank; null floats</td>\n</tr>\n<tr>\n<td>score_week</td>\n<td>float, nullable</td>\n<td>the score as the current week began, for the trend arrow</td>\n</tr>\n</tbody></table></div>\n<p>Unique index <code>(actor_id_prim, hashtag)</code>. Every read is one reader&#39;s whole set,\nwhich stays small: past 500 rows the faintest learned ones are forgotten.</p>\n<p><code>social_interest_hide</code> — posts marked &quot;less like this&quot;: <code>actor_id_prim</code>,\n<code>stream_nid</code>, <code>creation</code>, unique <code>(actor_id_prim, stream_nid)</code>. A daily job\n(<code>Cron\\InterestHides</code>) forgets rows older than <code>W</code> days, which can no longer\nkeep anything out of the feed.</p>\n<p>Per-user preferences (user config, app <code>social</code>): <code>interests_learning</code>\n(empty until the reader chooses, then <code>1</code>/<code>0</code>), <code>interests_paused_at</code>,\n<code>interests_languages</code> (JSON), <code>interests_baseline</code> (float),\n<code>interests_notice_ack</code>.</p>\n<p>Folding a signal into a score is an update, then an insert that skips a\nconflicting row, then the update again — never an insert that catches a unique\nviolation, which aborts the whole transaction on PostgreSQL.</p>\n<h2 id=\"administration\">10. Administration</h2>\n<p>In <code>AdminSettings</code> (Aloha Social admin page):</p>\n<ul>\n<li><strong>Enable For you</strong> (default on). Off: the switcher tab and settings\nsection are hidden, all <code>/interests</code> endpoints return\n404, and nothing is collected. Existing data is kept, so\nswitching the feature back on restores everyone&#39;s interests.</li>\n<li><strong>Learning default for users</strong> (on / off, default on). It applies to every\nuser who has not changed the <em>Learn from my browsing</em> toggle themselves; a\nuser&#39;s own choice always wins. It lets operators who read the GDPR as\nrequiring consent for profiling make learning opt-in. With the default off,\nthe first-use notice (4.2) becomes an invitation (&quot;Turn on&quot; / &quot;Not now&quot;)\ninstead of an announcement.</li>\n<li><strong>Tuning</strong>: half-life <code>H</code> (days, 7–180, default 30); listing threshold <code>T</code>\n(default 3.0); list cap <code>N</code> (5–100, default 30); candidate window <code>W</code> (1–30\ndays, default 7). Validated server-side and exposed through <code>ConfigService</code>.</li>\n</ul>\n","toc":[{"id":"data-model","text":"9. Data model","level":2},{"id":"administration","text":"10. Administration","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/For-You.md","sections":null,"anchor":"api","manual":false,"prev":{"path":"/docs/for-you-ranking","title":"Scoring and ranking"},"next":{"path":"/docs/for-you-privacy","title":"Privacy, performance and delivery"},"parent":null},{"slug":"for-you-privacy","path":"/docs/for-you-privacy","title":"Privacy, performance and delivery","description":"The README, info.xml description (with a fresh screenshot of the feed and the settings section), Architecture.md (tables, scorer, tracker), Mastodon-Compatibility.md (new endpoints) must…","group":"for-you","html":"<ul>\n<li>Scores are private: never federated, never in the public profile, never in\nany API response for another user, and not visible to admins in the UI.</li>\n<li>No raw event log: signals are folded into scores and discarded. Dedupe keys\nexpire after 24 h.</li>\n<li><strong>Data export</strong> (<code>lib/UserMigration/SocialMigrator.php</code>): interests\n(hashtag, score, scored_at, manual, position) and the preferences in\n§9 are exported and imported. Imported scores keep their <code>scored_at</code>, so\ndecay continues correctly. <code>social_interest_hide</code> is not exported.</li>\n<li><strong>Account deletion</strong> (<code>ActorCascadeService</code>): both tables are purged for the\nactor.</li>\n<li><strong>Reset all</strong> deletes the user&#39;s rows in both tables and the baseline.</li>\n<li>Opting out keeps the data (so opting back in restores the list), and the\nsettings section offers <strong>Reset all</strong> next to the toggle.</li>\n</ul>\n<h2 id=\"performance\">12. Performance</h2>\n<ul>\n<li>The signal endpoint does at most one lookup of post hashtags for the whole\nbatch (<code>stream_id IN (…)</code> on <code>social_stream_tag</code>) and one upsert per\naffected tag. Target: &lt; 30 ms for 100 events.</li>\n<li>The feed query is bounded by the top-N tag list, the <code>W</code>-day window and a\n1 000-row cap. Ranking happens in PHP on that set. The snapshot cache means\none ranking per user per 15 minutes of scrolling. Target: first page &lt; 150 ms\nat 1M users / 10M posts (the same scale as the #2210 perf work). This has to\nbe measured with <code>log_query</code> on devel before merge.</li>\n<li>The tracker adds no request per post: batched, beacon on unload.</li>\n</ul>\n<h2 id=\"accessibility-and-i18n\">13. Accessibility and i18n</h2>\n<ul>\n<li>Cloud reordering has keyboard and touch equivalents (4.4: popover\nHigher/Lower/Move to top, Alt+arrow keys, <code>aria-live</code> announcements). Rank\nis never conveyed by size alone: it is in each tag&#39;s accessible name\n(&quot;#photography, priority 3 of 24, pinned&quot;).</li>\n<li>The chip is a real link with an accessible name (&quot;Why you&#39;re seeing this:\ninterested in #photography&quot;).</li>\n<li>All new strings go through <code>t(&#39;social&#39;, …)</code>. A new label in Navigation,\nTimelinePost or similar trips <code>TranslatableStringsTest</code>, so phpunit runs as\nwell as the JS build.</li>\n</ul>\n<h2 id=\"testing\">14. Testing</h2>\n<ul>\n<li><code>InterestScorer</code>: normalisation against the baseline, skip, splitting,\n15-tag cutoff, decay and pause shift, clamping, followed floor, list\nassembly (pinned / manual / learned / cap), rank weights, thin-learning\nseeds.</li>\n<li>Feed ranking: relevance × recency, diversity caps, exploration slot,\nexclusion rules (mutes, blocks, filters, language, hidden, own posts),\nsnapshot pagination by <code>offset</code> and by <code>max_id</code>.</li>\n<li>Controllers: every endpoint, including the disabled-by-admin and opted-out\npaths, rate limiting, and that one user can\nnever read or change another user&#39;s interests.</li>\n<li>Signal hooks in Like/Boost/Bookmark/reply services, including dedupe.</li>\n<li>Migrator export/import round trip; cascade on account deletion.</li>\n<li><code>interestTracker.js</code>: fake timers + a mocked IntersectionObserver for the\nvisibility, focus, idle pause, 30 s cap, CW-collapsed and skip rules, and\nthe flush on <code>pagehide</code>.</li>\n<li><code>InterestCloud.vue</code>: rank → size step mapping, drag reorder, popover\nactions, keyboard moves and announcements, reduced-motion.</li>\n<li>Playwright on devel: switcher tab, chip, less like this + undo, the cloud\n(drag, popover higher/lower/pin/remove, add, candidates, reset) at desktop\nand phone width, in light and dark themes.</li>\n</ul>\n<h2 id=\"documentation\">15. Documentation</h2>\n<p>The README, <code>info.xml</code> description (with a fresh screenshot of the feed and\nthe settings section), <code>Architecture.md</code> (tables, scorer, tracker),\n<code>Mastodon-Compatibility.md</code> (new endpoints) must be updated in\nthe same change as the code; <code>DocumentationTest</code> guards the checkable parts.</p>\n<h2 id=\"delivery\">16. Delivery</h2>\n<p>Built as one branch in the order above — the scoring core and the server\nhooks, the web tracker, the feed and its controls, the settings cloud, the\nadmin card. It is large; if it is to be reviewed in pieces, the server half\nand the two frontend halves are separate commits.</p>\n","toc":[{"id":"performance","text":"12. Performance","level":2},{"id":"accessibility-and-i18n","text":"13. Accessibility and i18n","level":2},{"id":"testing","text":"14. Testing","level":2},{"id":"documentation","text":"15. Documentation","level":2},{"id":"delivery","text":"16. Delivery","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/For-You.md","sections":null,"anchor":"privacy-and-data-lifecycle","manual":false,"prev":{"path":"/docs/for-you-technical","title":"API, data model and administration"},"next":null,"parent":null},{"slug":"notify","path":"/docs/notify","title":"Who may reach you, and muting a conversation","description":"Specification for #2463: the notification policy and conversation muting in the Aloha Social web app. It records the product decisions, what the server already does, and what has to be…","group":"notifications","html":"<p>Specification for <a href=\"https://github.com/AlohaSocial/social/issues/2463\">#2463</a>: the notification policy and conversation muting in the Aloha Social web app. It records the product decisions, what the server already does, and what has to be built. The implementation follows this document; where they disagree, the document is fixed first.</p>\n<p>Status: agreed 2026-10-07 and implemented. Where the implementation chose differently from the first draft — its own routes for the always-allowed list, the notice and the admin defaults; dismiss and drop keeping their earlier meaning — this document says what was built.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Notification-Policy.md","sections":[{"path":"/docs/notify-why","title":"Why notifications are policed","description":"Negative interactions on social media go with more depressive symptoms. Being reachable by anybody, and being pulled back into a thread that went wrong, are the two moments where the app…","parent":false},{"path":"/docs/notify-behaviour","title":"Behaviour, API and strings","description":"Accounts that existed before this release see one dismissible notice at the top of Activities: \"You can now choose who reaches your notifications — new accounts and people you don't follow…","parent":false},{"path":"/docs/notify-rollout","title":"Tests, scope and rollout","description":"Muting hides nothing from timelines (decided: notifications only). Timed conversation mutes. A bell notification for requests. Changing existing accounts' policies. An admin settings card…","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/notify-why","title":"Why notifications are policed"},"parent":null},{"slug":"notify-why","path":"/docs/notify-why","title":"Why notifications are policed","description":"Negative interactions on social media go with more depressive symptoms. Being reachable by anybody, and being pulled back into a thread that went wrong, are the two moments where the app…","group":"notifications","html":"<p>Negative interactions on social media go with more depressive symptoms. Being reachable by anybody, and being pulled back into a thread that went wrong, are the two moments where the app can help most. The server already has the tools (<code>/api/v1|v2/notifications/policy</code>, the requests inbox, <code>POST /api/v1/statuses/{id}/mute</code>); the web app exposes almost none of them, and the bell ignores them.</p>\n<h2 id=\"decisions\">2. Decisions</h2>\n<h2 id=\"defaults-for-a-new-account\">Defaults for a new account</h2>\n<p><strong>Calm:</strong> hold people you don&#39;t follow, new accounts and unsolicited private mentions for review; accept everyone else. Limited (moderated) accounts are held as well.</p>\n<h2 id=\"existing-accounts\">Existing accounts</h2>\n<p><strong>Unchanged</strong> (everything accepted) until the person chooses. A one-time notice points them to the setting.</p>\n<h2 id=\"choices-in-the-web-ui\">Choices in the web UI</h2>\n<p><strong>Allow</strong> / <strong>Hold for review</strong>. <em>Drop</em> stays available through the API for Mastodon apps but is not offered in the web UI.</p>\n<h2 id=\"what-is-held\">What is held</h2>\n<p><strong>Everything a held sender does</strong> — mentions, replies, direct messages, likes, boosts, follows, poll results — waits together.</p>\n<h2 id=\"a-new-account\">A &quot;new account&quot;</h2>\n<p><strong>Younger than 30 days</strong>, from the account&#39;s published creation date (remote accounts included).</p>\n<h2 id=\"accept\">Accept</h2>\n<p><strong>Releases what was waiting and always allows that person</strong> from then on, until revoked in Settings. Accepting does not follow them.</p>\n<h2 id=\"dismiss\">Dismiss</h2>\n<p>Discards what was waiting from that person; they stay held from then on (as before this change).</p>\n<h2 id=\"finding-out-someone-waits\">Finding out someone waits</h2>\n<p>A <strong>line at the top of Activities</strong>, a mention <strong>in the digest</strong>, and the <strong>count on Activities in the sidebar</strong>. No bell notification.</p>\n<h2 id=\"mute-a-conversation\">Mute a conversation</h2>\n<p><strong>Stops notifications only</strong> (as Mastodon): the thread stays on the timelines.</p>\n<h2 id=\"mute-duration\">Mute duration</h2>\n<p><strong>Until unmuted.</strong></p>\n<h2 id=\"where-mute-is-offered\">Where mute is offered</h2>\n<p>The <strong>post menu</strong> and the <strong>mention/reply cards in Activities</strong>.</p>\n<h2 id=\"where-the-policy-lives\">Where the policy lives</h2>\n<p><strong>Inside the Notifications section of Settings</strong>, together with digests and quiet hours: one place for everything about being interrupted.</p>\n<h2 id=\"what-exists-today\">3. What exists today</h2>\n<ul>\n<li><code>NotificationPolicy</code> (<code>lib/Model/Client/NotificationPolicy.php</code>): five keys (<code>for_not_following</code>, <code>for_not_followers</code>, <code>for_new_accounts</code>, <code>for_private_mentions</code>, <code>for_limited_accounts</code>), each <code>accept</code> / <code>filter</code> / <code>drop</code>; <strong>every key defaults to <code>accept</code></strong> in the model&#39;s constructor.</li>\n<li><code>NotificationPolicyService</code>: stores the policy as the user value <code>notification_policy</code>; <code>partition()</code> splits a page of notifications into shown and held <strong>when the list is read</strong>; <code>accept()</code> / <code>dismiss()</code> record a per-sender decision through <code>AccountRelationService</code>; <code>NEW_ACCOUNT_DAYS = 30</code>; limited = silenced by the instance&#39;s moderation.</li>\n<li>Routes: <code>GET/PATCH /api/v1|v2/notifications/policy</code>, <code>GET /api/v1/notifications/requests</code>, accept/dismiss (single and bulk). The policy answer carries <code>summary.pending_requests_count</code>.</li>\n<li>Web: <code>NotificationRequests.vue</code> (the requests list) on the Blocking page only. Nothing reads or changes the policy.</li>\n<li>Conversation mute: <code>POST /api/v1/statuses/{id}/mute|unmute</code> → <code>ActionService::muteConversation()</code> stores the mute against the thread&#39;s root (<code>social_convo_state</code>).</li>\n<li>Delivery: <code>NotificationService::emit()</code> raises the Aloha notification (bell, push, mail) and applies the digest/quiet-hours hold (<code>NotificationDeliveryService</code>).</li>\n</ul>\n<h2 id=\"gaps-this-specification-closes\">4. Gaps this specification closes</h2>\n<ol>\n<li><strong>The bell ignores the policy and the mute.</strong> A held sender, and a reply in a muted thread, are filtered out of the Activities <em>list</em>, but <code>emit()</code> still rings the bell, sends push and mail. Holding has to apply where the interruption happens.</li>\n<li><strong>The status&#39;s <code>muted</code> is hard-coded <code>false</code></strong>, so no client can show or toggle the state. (Fixed on <code>feat/notification-policy-web</code>.)</li>\n<li><strong>New accounts cannot start calm without changing everybody</strong>, because the defaults live in the model.</li>\n<li><strong>Nothing in the web app</strong> reads or changes the policy, shows that people are waiting, or mutes a conversation.</li>\n</ol>\n","toc":[{"id":"decisions","text":"2. Decisions","level":2},{"id":"defaults-for-a-new-account","text":"Defaults for a new account","level":2},{"id":"existing-accounts","text":"Existing accounts","level":2},{"id":"choices-in-the-web-ui","text":"Choices in the web UI","level":2},{"id":"what-is-held","text":"What is held","level":2},{"id":"a-new-account","text":"A \"new account\"","level":2},{"id":"accept","text":"Accept","level":2},{"id":"dismiss","text":"Dismiss","level":2},{"id":"finding-out-someone-waits","text":"Finding out someone waits","level":2},{"id":"mute-a-conversation","text":"Mute a conversation","level":2},{"id":"mute-duration","text":"Mute duration","level":2},{"id":"where-mute-is-offered","text":"Where mute is offered","level":2},{"id":"where-the-policy-lives","text":"Where the policy lives","level":2},{"id":"what-exists-today","text":"3. What exists today","level":2},{"id":"gaps-this-specification-closes","text":"4. Gaps this specification closes","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Notification-Policy.md","sections":null,"anchor":"why","manual":false,"prev":{"path":"/docs/notify","title":"Who may reach you, and muting a conversation"},"next":{"path":"/docs/notify-behaviour","title":"Behaviour, API and strings"},"parent":null},{"slug":"notify-behaviour","path":"/docs/notify-behaviour","title":"Behaviour, API and strings","description":"Accounts that existed before this release see one dismissible notice at the top of Activities: \"You can now choose who reaches your notifications — new accounts and people you don't follow…","group":"notifications","html":"<h2 id=\"5-1-policy-and-defaults\">5.1 Policy and defaults</h2>\n<ul>\n<li><p>The model&#39;s built-in defaults stay <code>accept</code> for every key. They are what an account without a stored policy has, so existing accounts are unchanged.</p>\n</li>\n<li><p><strong>When a local account is created</strong> (<code>AccountService</code> account creation; the first-run screen, <code>occ social:account:create</code>, external users), the calm policy is stored for it:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Key</th>\n<th>Value</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>for_not_following</code></td>\n<td><code>filter</code></td>\n</tr>\n<tr>\n<td><code>for_not_followers</code></td>\n<td><code>accept</code></td>\n</tr>\n<tr>\n<td><code>for_new_accounts</code></td>\n<td><code>filter</code></td>\n</tr>\n<tr>\n<td><code>for_private_mentions</code></td>\n<td><code>filter</code></td>\n</tr>\n<tr>\n<td><code>for_limited_accounts</code></td>\n<td><code>filter</code></td>\n</tr>\n</tbody></table></div>\n</li>\n<li><p>An administrator can change these defaults for new accounts in the admin settings (one row per key, same two choices). The stored defaults are an app value; changing it does not touch existing accounts.</p>\n</li>\n<li><p>A key a Mastodon app set to <code>drop</code> is shown in the web UI as <strong>Hold for review</strong> with a note &quot;An app set this to discard; choosing here replaces it&quot;. Saving from the web never writes <code>drop</code>.</p>\n</li>\n</ul>\n<h2 id=\"5-2-what-is-held-and-where\">5.2 What is held, and where</h2>\n<ul>\n<li>A notification is held when <strong>any</strong> policy key that is <code>filter</code> applies to its sender (or the notification, for <code>for_private_mentions</code>), and the sender is not on the viewer&#39;s accepted list. <code>drop</code> (API only) holds it for good, as today; neither ever rings.</li>\n<li>Held applies to <strong>every notification type</strong> from that sender.</li>\n<li><strong>A held notification is stored, never raised:</strong> <code>emit()</code> checks the policy (the same rules as <code>partition()</code>, shared code, not a copy) before the digest/quiet-hours check; a held notification raises nothing — no bell, no push, no mail, and it is not counted in a digest&#39;s notification total.</li>\n<li>The Activities list and <code>/api/v1/notifications</code> keep excluding held notifications (as today); <code>/api/v1/notifications/requests</code> lists the waiting senders.</li>\n<li><strong>Accept</strong> releases the sender&#39;s held notifications into Activities <strong>without ringing the bell for them now</strong> (they are old news; the count in the sidebar reflects them as unread) and records the sender as always allowed. <strong>Dismiss</strong> discards them.</li>\n<li>The always-allowed list is shown in Settings (5.4) with a &quot;Stop allowing&quot; action per person; stopping returns that person to the policy.</li>\n</ul>\n<h2 id=\"5-3-telling-the-reader-somebody-waits\">5.3 Telling the reader somebody waits</h2>\n<ul>\n<li><strong>Activities</strong>: a line at the top, above the first notification, while <code>pending_requests_count &gt; 0</code>: &quot;{count} people are waiting — Review&quot; (plural-aware). Review opens the requests list in place (the existing <code>NotificationRequests</code> component, moved from the Blocking page, which keeps a link to it).</li>\n<li><strong>Sidebar</strong>: the count on Activities includes waiting requests (unread notifications + waiting senders). It never shows a separate badge.</li>\n<li><strong>Digest</strong>: when a digest is raised and requests are waiting, its message ends with &quot;{count} people are waiting to reach you&quot; (plural-aware). A digest is not raised for requests alone.</li>\n<li>No bell notification is ever raised for a request.</li>\n</ul>\n<h2 id=\"5-4-settings-notifications\">5.4 Settings → Notifications</h2>\n<p>The existing Notifications section (digests, quiet hours) gains a second part, <strong>Who may reach you</strong>:</p>\n<ul>\n<li>Five rows, each <strong>Allow</strong> / <strong>Hold for review</strong>:<ul>\n<li>People you don&#39;t follow</li>\n<li>People who don&#39;t follow you</li>\n<li>New accounts (less than 30 days old)</li>\n<li>Private mentions you didn&#39;t ask for</li>\n<li>Accounts this server limited</li>\n</ul>\n</li>\n<li>Under the rows: <strong>Always allowed</strong> — the senders accepted from requests, each with <strong>Stop allowing</strong>; empty state &quot;Nobody yet. People you accept from your requests appear here.&quot;</li>\n<li>A sentence explains what <em>held</em> means: &quot;Held people can still write to you. Their posts, likes and follows wait in Activities until you look; they do not ring, push or mail.&quot;</li>\n<li>Saves on change, like the rest of the section; a refused value reverts with the server&#39;s reason.</li>\n</ul>\n<h2 id=\"5-5-one-time-notice-for-existing-accounts\">5.5 One-time notice for existing accounts</h2>\n<p>Accounts that existed before this release see one dismissible notice at the top of Activities: &quot;You can now choose who reaches your notifications — new accounts and people you don&#39;t follow can wait for your review. Choose in Settings.&quot; Dismissing it, or saving the policy once, removes it for good (user value). New accounts never see it.</p>\n<h2 id=\"5-6-mute-a-conversation\">5.6 Mute a conversation</h2>\n<ul>\n<li><strong>Post menu</strong>: &quot;Mute conversation&quot; on any post of a thread; &quot;Unmute conversation&quot; when the status&#39;s <code>muted</code> is true. Hidden for an anonymous reader and on public pages.</li>\n<li><strong>Activities</strong>: the same action in the menu of a mention or reply card.</li>\n<li>Muting records the mute against the thread&#39;s root (as today). From then on, notifications whose post belongs to that thread are <strong>not raised</strong> (bell, push, mail — <code>emit()</code> checks the mute) <strong>and not listed</strong> in Activities; posts in the thread stay on every timeline. Unmuting restores listing of what arrived meanwhile, without ringing for it.</li>\n<li>The status entity carries the real <code>muted</code> for the viewer, computed for a page of statuses in one pass (walk reply chains to their roots, compare with the viewer&#39;s muted roots; the muted-roots memo is static per request and is dropped by every mute/unmute write — <code>ConversationsRequest::setMuted()</code> must drop it before its early return).</li>\n<li>A short confirmation after the action: &quot;Conversation muted — you won&#39;t be notified about it&quot; / &quot;Conversation unmuted&quot;.</li>\n</ul>\n<h2 id=\"api\">6. API</h2>\n<p>Changes visible to clients:</p>\n<ul>\n<li><code>muted</code> on statuses is real (was always <code>false</code>).</li>\n<li>New accounts have a stored policy with the calm values (<code>GET /api/v2/notifications/policy</code> shows them).</li>\n<li>Held senders no longer cause Aloha push notifications to phone apps either, because those come from the same <code>emit()</code>.</li>\n<li>Routes of this app&#39;s own: <code>GET /api/v1/social/notifications/allowed</code> and <code>DELETE /api/v1/social/notifications/allowed/{account_id}</code> (the always-allowed list), <code>POST /api/v1/social/notifications/policy/notice/dismiss</code> (the one-time notice; the policy answer carries <code>notice</code>), and <code>GET</code>/<code>POST /admin/notification-policy</code> (the defaults for new accounts).</li>\n<li><code>/api/v1/notifications/unread_count</code> leaves held and muted notifications out.</li>\n<li><code>docs/API.md</code> and <code>docs/Mastodon-Compatibility.md</code> describe these; the &quot;drop is API-only&quot; rule is stated.</li>\n</ul>\n<h2 id=\"strings-english-german-in-all-four-catalogues-in-the-same-commit\">7. Strings (English; German in all four catalogues in the same commit)</h2>\n<p>&quot;Who may reach you&quot;, &quot;Allow&quot;, &quot;Hold for review&quot;, &quot;People you don&#39;t follow&quot;, &quot;People who don&#39;t follow you&quot;, &quot;New accounts (less than 30 days old)&quot;, &quot;Private mentions you didn&#39;t ask for&quot;, &quot;Accounts this server limited&quot;, &quot;Always allowed&quot;, &quot;Stop allowing&quot;, &quot;{count} people are waiting — Review&quot;, &quot;{count} people are waiting to reach you&quot;, &quot;Mute conversation&quot;, &quot;Unmute conversation&quot;, &quot;Conversation muted — you won&#39;t be notified about it&quot;, &quot;Conversation unmuted&quot;, the one-time notice, the held explanation, and &quot;An app set this to discard; choosing here replaces it&quot;.</p>\n","toc":[{"id":"5-1-policy-and-defaults","text":"5.1 Policy and defaults","level":2},{"id":"5-2-what-is-held-and-where","text":"5.2 What is held, and where","level":2},{"id":"5-3-telling-the-reader-somebody-waits","text":"5.3 Telling the reader somebody waits","level":2},{"id":"5-4-settings-notifications","text":"5.4 Settings → Notifications","level":2},{"id":"5-5-one-time-notice-for-existing-accounts","text":"5.5 One-time notice for existing accounts","level":2},{"id":"5-6-mute-a-conversation","text":"5.6 Mute a conversation","level":2},{"id":"api","text":"6. API","level":2},{"id":"strings-english-german-in-all-four-catalogues-in-the-same-commit","text":"7. Strings (English; German in all four catalogues in the same commit)","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Notification-Policy.md","sections":null,"anchor":"behaviour","manual":false,"prev":{"path":"/docs/notify-why","title":"Why notifications are policed"},"next":{"path":"/docs/notify-rollout","title":"Tests, scope and rollout"},"parent":null},{"slug":"notify-rollout","path":"/docs/notify-rollout","title":"Tests, scope and rollout","description":"Muting hides nothing from timelines (decided: notifications only). Timed conversation mutes. A bell notification for requests. Changing existing accounts' policies. An admin settings card…","group":"notifications","html":"<ul>\n<li><strong>PHP unit:</strong> calm policy stored at account creation and not for existing accounts; admin defaults; <code>emit()</code> raises nothing for a held sender (each key) and for a muted thread, and still raises for an always-allowed sender; accept releases without raising; dismiss discards; digest line only when requests wait and never a digest for requests alone; <code>muted</code> export per viewer incl. the update-path cache drop; <code>drop</code> never written from the web save path.</li>\n<li><strong>Web (vitest):</strong> the policy rows and always-allowed list; Activities waiting line and requests panel; sidebar count includes requests; Mute/Unmute in the post menu and on mention/reply cards; the one-time notice.</li>\n<li><strong>Interop (real servers, every PR):</strong> a Mastodon account we don&#39;t follow mentions a calm-default local user → held: not in <code>/api/v1/notifications</code>, listed in requests, no Aloha notification raised; accept → released and the next mention notifies; mute a thread, a Mastodon reply in it raises nothing, unmute.</li>\n</ul>\n<h2 id=\"out-of-scope\">9. Out of scope</h2>\n<p>Muting hides nothing from timelines (decided: notifications only). Timed conversation mutes. A bell notification for requests. Changing existing accounts&#39; policies. An admin settings card for the new-account defaults (the route exists; the card is a follow-up).</p>\n<h2 id=\"implementation-order\">10. Implementation order</h2>\n<ol>\n<li>Shared hold rules + <code>emit()</code> checks the policy and the conversation mute (closes gap 1, server only, with tests).</li>\n<li>Calm defaults for new accounts + admin defaults (gap 3).</li>\n<li>Port <code>feat/notification-policy-web</code> onto master: <code>muted</code> export, Mute/Unmute in the post menu, requests line atop Activities — adapted to this document (placement in Notifications, two choices, mute on mention/reply cards, sidebar count, digest line, always-allowed list, one-time notice).</li>\n<li>Docs (User-Guide, API, Mastodon-Compatibility, Admin) and the interop tests.</li>\n</ol>\n","toc":[{"id":"out-of-scope","text":"9. Out of scope","level":2},{"id":"implementation-order","text":"10. Implementation order","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Notification-Policy.md","sections":null,"anchor":"tests","manual":false,"prev":{"path":"/docs/notify-behaviour","title":"Behaviour, API and strings"},"next":null,"parent":null},{"slug":"moving","path":"/docs/moving","title":"Moving to Aloha Social, and moving away","description":"One page for the whole move, in the order it happens. Each button it names is described on its own in the User Guide and each route in the API reference; this is the order, and what does…","group":"moving","html":"<p>One page for the whole move, in the order it happens. Each button it names\nis described on its own in the <a href=\"/docs/user\">User Guide</a> and\neach route in the <a href=\"API.md#migration\">API reference</a>; this is the order, and\nwhat does not move.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Moving.md","sections":[{"path":"/docs/moving-what-a-move-is-on-the-fediverse","title":"What a move is, on the fediverse","description":"A move carries followers, never posts. Your old server tells every server that knows you to follow your new account instead; your posts stay where they were written, under the old server's…","parent":false},{"path":"/docs/moving-moving-to-aloha-social","title":"Moving to Aloha Social","description":"Pixelfed cannot do step 3: it has no account migration. Your follows and your posts come over; your followers have to follow you again.","parent":false},{"path":"/docs/moving-moving-away","title":"Moving away","description":"You can move again after thirty days. Undo the move takes the redirect off and lets you post and follow from here again — but your followers do not come back by themselves, because their…","parent":false},{"path":"/docs/moving-what-does-not-move-whatever-you-do","title":"What does not move, whatever you do","description":"Coming to Aloha Social from another server, and leaving again without losing the people who follow you.","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/moving-what-a-move-is-on-the-fediverse","title":"What a move is, on the fediverse"},"parent":null},{"slug":"moving-what-a-move-is-on-the-fediverse","path":"/docs/moving-what-a-move-is-on-the-fediverse","title":"What a move is, on the fediverse","description":"A move carries followers, never posts. Your old server tells every server that knows you to follow your new account instead; your posts stay where they were written, under the old server's…","group":"moving","html":"<p>A move carries <strong>followers</strong>, never posts. Your old server tells every server\nthat knows you to follow your new account instead; your posts stay where they\nwere written, under the old server&#39;s addresses. That is how Mastodon does it\ntoo, and it is the right design: a post is signed by the server it was written\non, and nobody else can re-issue it.</p>\n<p>Two things follow from that. Your new account can <strong>copy</strong> your old posts, as\nnew posts of its own, so your profile here is not empty — but they are copies,\nnothing is sent to anybody, and the replies and boosts on the originals stay on\nthe originals. And the old server has to be <strong>running</strong> for any of this: it\nsends the move, and it serves your posts and the people you follow. An account\non a server that is gone cannot be moved; only a follows file exported in time\nsurvives it.</p>\n<p>The same happens in the other direction when somebody <em>you</em> follow moves:\ntheir old server sends the move here, this server checks that the new account\nnames the old one, follows the new account on your behalf, and shows the\nredirect on the old account&#39;s profile from then on.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Moving.md","sections":null,"anchor":"what-a-move-is-on-the-fediverse","manual":false,"prev":{"path":"/docs/moving","title":"Moving to Aloha Social, and moving away"},"next":{"path":"/docs/moving-moving-to-aloha-social","title":"Moving to Aloha Social"},"parent":null},{"slug":"moving-moving-to-aloha-social","path":"/docs/moving-moving-to-aloha-social","title":"Moving to Aloha Social","description":"Pixelfed cannot do step 3: it has no account migration. Your follows and your posts come over; your followers have to follow you again.","group":"moving","html":"<p>Three steps, two of them here.</p>\n<ol>\n<li><p><strong>Make your account here</strong>, on the setup screen. On its third step,\n<em>Already somewhere else?</em>, type the handle of your old account —\n<code>@you@mastodon.example</code> — and press <strong>Move here</strong>. You can do the same\nlater, at the top of <strong>Settings → Migration</strong>, where you are first shown\nwho that account is and what its server lets us read.</p>\n<p>What happens: this account is marked as also being the old one (the\n<code>alsoKnownAs</code> the old server will ask for), and in the background everyone\nthe old account follows is followed from here and its public posts are\nwritten here as yours, dated when you wrote them, with their pictures.\nNothing is sent to anybody. The list on the Migration page shows where the\nrun has got to. Posts you write on the old account after that are not\npicked up by anything: <strong>Copy newer posts</strong>, under the finished run, runs\nthe copy again and brings over only what is new.</p>\n</li>\n<li><p><strong>If the old server hides your follows or your posts</strong> — Mastodon does\nwhen you turned on <em>Hide your social graph</em>, Pixelfed always does — the\npage says so, and the file imports further down are for that: upload the\nold server&#39;s <code>following_accounts.csv</code> (Pixelfed: <code>pixelfed-following.json</code>)\nand, for the posts, its archive. Blocks, mutes, lists, bookmarks and blocked\ndomains come the same way.\nEvery upload runs in the background too.</p>\n</li>\n<li><p><strong>On the old server, move your followers here.</strong> On Mastodon that is\n<em>Preferences → Account → Move to a different account</em>; enter your handle\nhere. The Migration page shows it once the run is done. Your old server\nthen tells every server that knows you to follow this account instead, and\nyou are moved.</p>\n</li>\n</ol>\n<p>Pixelfed cannot do step 3: it has no account migration. Your follows and your\nposts come over; your followers have to follow you again.</p>\n<p><strong>From another Aloha Social server, step 3 is here too.</strong> Mastodon has no way\nto ask for a move from outside, which is why the last step is always done on\nthe old server. Another Aloha Social does: once the run is through, the\nMigration page offers <strong>Finish the move from here</strong>. You are sent to your old\nAloha to log in and to agree — the only permission asked for is to move\nthe account, nothing else — and the old server moves your followers here.\nIt checks, as it would for its own button, that this account names the old\none; the thirty days between moves apply there as everywhere.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Moving.md","sections":null,"anchor":"moving-to-aloha-social","manual":false,"prev":{"path":"/docs/moving-what-a-move-is-on-the-fediverse","title":"What a move is, on the fediverse"},"next":{"path":"/docs/moving-moving-away","title":"Moving away"},"parent":null},{"slug":"moving-moving-away","path":"/docs/moving-moving-away","title":"Moving away","description":"You can move again after thirty days. Undo the move takes the redirect off and lets you post and follow from here again — but your followers do not come back by themselves, because their…","group":"moving","html":"<ol>\n<li><p><strong>On the new account, name this one</strong> as an account you also answer to.\nOn Mastodon: <em>Preferences → Account → Moving from a different account</em>,\nwith your handle here.</p>\n</li>\n<li><p><strong>Here, in Settings → Migration → Move your account away</strong>, type the new\naccount&#39;s handle, type your own handle to confirm, and give your password\nwhen asked. Every server that knows you is told to follow the new account\ninstead; this account is marked as moved, shows where you went, and refuses\nto post or follow while it stays moved. Your posts stay here.</p>\n</li>\n</ol>\n<p>You can move again after thirty days. <strong>Undo the move</strong> takes the redirect off\nand lets you post and follow from here again — but your followers do not come\nback by themselves, because their servers acted on the move when it arrived.\nTake an export from the same page first if you want a copy of everything.</p>\n<p>An administrator can move an account for somebody with\n<code>occ social:account:move</code>, which skips the thirty days.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Moving.md","sections":null,"anchor":"moving-away","manual":false,"prev":{"path":"/docs/moving-moving-to-aloha-social","title":"Moving to Aloha Social"},"next":{"path":"/docs/moving-what-does-not-move-whatever-you-do","title":"What does not move, whatever you do"},"parent":null},{"slug":"moving-what-does-not-move-whatever-you-do","path":"/docs/moving-what-does-not-move-whatever-you-do","title":"What does not move, whatever you do","description":"Coming to Aloha Social from another server, and leaving again without losing the people who follow you.","group":"moving","html":"<ul>\n<li><strong>Posts.</strong> Copied, never moved: see above.</li>\n<li><strong>Followers from a server that does not implement <code>Move</code>.</strong> Pixelfed is the\none that matters.</li>\n<li><strong>Your handle.</strong> <code>@you@old.example</code> stays on the old server; here you are\n<code>@you@this.server</code>. Keeping a handle across a change of domain is a server\nmigration, not an account one — see\n<a href=\"/docs/mastodon\">Mastodon-Compatibility.md</a>.</li>\n<li><strong>Direct messages and boosts</strong> are left out of the post copy on purpose.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Moving.md","sections":null,"anchor":"what-does-not-move-whatever-you-do","manual":false,"prev":{"path":"/docs/moving-moving-away","title":"Moving away"},"next":null,"parent":null},{"slug":"admin","path":"/docs/admin","title":"Administering Aloha Social","description":"What an administrator has to set up, what they can change, and what tells them something is wrong. For the routes behind the settings page see API.md, for the commands OCC-Commands.md, and…","group":"admin","html":"<p>What an administrator has to set up, what they can change, and what tells them\nsomething is wrong. For the routes behind the settings page see\n<a href=\"API.md\">API.md</a>, for the commands <a href=\"/docs/occ\">OCC-Commands.md</a>, and for\nhow the pieces fit together <a href=\"Architecture.md\">Architecture.md</a>.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":[{"path":"/docs/admin-before-it-federates","title":"Before it federates","description":"Aloha Social is a fediverse server that happens to live inside Aloha, so the things it needs are the things any fediverse server needs: a stable public address, a .well-known answer, and a…","parent":false},{"path":"/docs/admin-the-setup-checks","title":"The setup checks","description":"Aloha Social registers its own checks in Administration → Overview, beside Aloha's own. They are the things that break federation, or stop clients connecting, without anything else saying…","parent":false},{"path":"/docs/admin-mastodon-apps-cannot-connect","title":"Mastodon apps cannot connect","description":"A Mastodon app is given a domain and builds https://<domain>/api/v1/... from it. Not one of them accepts a path, and Aloha Social's routes live under /index.php/apps/social, so out of the…","parent":true},{"path":"/docs/admin-webfinger-does-not-answer","title":"WebFinger does not answer","description":"Nothing answers /.well-known/webfinger for an account of this instance, so no other server can find anybody here — searches for a local account fail everywhere else, and follows from…","parent":true},{"path":"/docs/admin-the-address-aloha-social-is-set-up-for","title":"The address Aloha Social is set up for","description":"Aloha Social builds every id from its stored cloud_url and the server now reports something else. Accounts here cannot be found under the address the server advertises, and every new post…","parent":true},{"path":"/docs/admin-the-delivery-job-has-not-run","title":"The delivery job has not run","description":"Cron\\Queue is what sends. It is meant to run every 12 minutes; the check warns once an hour has passed without it, and errors if the job is not registered at all (disabling and re-enabling…","parent":true},{"path":"/docs/admin-deliveries-are-stuck","title":"Deliveries are stuck","description":"Two things in the outbound queue do not move on their own: a delivery the drain has given up on after every retry (16 attempts over a widening delay, the last gap fourteen hours), and one…","parent":true},{"path":"/docs/admin-no-memory-cache","title":"No memory cache","description":"APCu (memcache.local = \\OC\\Memcache\\APCu) is enough for all of it on a single web server; Redis is what several need.","parent":true},{"path":"/docs/admin-videos-do-not-play-elsewhere","title":"Videos do not play elsewhere","description":"An iPhone records .mov; Android phones, and iPhones exporting through some apps, write HEVC inside an .mp4. Pixelfed's default media_types accepts video/mp4 and nothing else and drops the…","parent":true},{"path":"/docs/admin-raising-the-upload-limit","title":"Raising the upload limit","description":"A client is told, and held to, the smaller of Aloha Social's own ceilings and PHP's. PHP's is the smaller of upload_max_filesize and post_max_size; its own default is 2 MB and 8 MB. A…","parent":true},{"path":"/docs/admin-bluesky","title":"Bluesky","description":"Every account on this instance can be a Bluesky account as well: this Aloha is its personal data server (PDS), alice.<host> its handle, and a Bluesky relay reads what it publishes. Nothing…","parent":false},{"path":"/docs/admin-the-administration-page","title":"The administration page","description":"On a wide screen the groups are a list beside the page, each with a line saying what is in it, and the sections of the open group are listed under it. On a narrow one they are a row of…","parent":false},{"path":"/docs/admin-external-users","title":"External users","description":"People without an account on this server can register one themselves, when an administrator switches it on. They log in through the normal login page and reach Aloha Social and nothing…","parent":false},{"path":"/docs/admin-moderating","title":"Moderating","description":"Reports arrive from two directions: a local user reporting somebody through a client, and a peer instance sending POST /api/v1/reports about one of its own users' complaints. Both land in…","parent":false},{"path":"/docs/admin-configuration","title":"Configuration","description":"Nothing here is reachable through core's app-config API: the settings page writes through its own validated endpoints, and a delegate can write only what the moderation routes accept.","parent":false},{"path":"/docs/admin-set-by-the-app-not-by-you","title":"Set by the app, not by you","description":"The base address every id is built from, copied from overwrite.cli.url the first time the app is opened. Changing it by hand does not rewrite the ids already issued.","parent":true},{"path":"/docs/admin-server-settings","title":"Server settings","description":"Instance-wide settings. Most of them are on the Server section of the settings page, which validates the ranges given here; every one can be set with occ.","parent":true},{"path":"/docs/admin-moderation-and-federation","title":"Moderation and federation","description":"all_but — federate with everyone except the listed instances (block list). none_but — federate only with the listed ones (allow list).","parent":true},{"path":"/docs/admin-external-users-2","title":"External users","description":"Set from the External users cards; these are the keys they write.","parent":true},{"path":"/docs/admin-system-configuration","title":"System configuration","description":"And one of Aloha's own that matters here: allow_local_remote_servers, which must be on for an instance to federate with anything on a private address. That is a development arrangement.","parent":true},{"path":"/docs/admin-commands-by-task","title":"Commands by task","description":"The full reference is OCC-Commands.md; these are the ones an administrator reaches for.","parent":false},{"path":"/docs/admin-running-a-large-instance","title":"Running a large instance","description":"Everything below is optional and nothing on a small instance needs any of it. These are the three things that stop working first as an instance grows, and what to do about each.","parent":false},{"path":"/docs/admin-what-to-watch","title":"What to watch","description":"Running an Aloha Social server: the checks before you federate, moderation, external users, configuration and scale.","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/admin-before-it-federates","title":"Before it federates"},"parent":null},{"slug":"admin-before-it-federates","path":"/docs/admin-before-it-federates","title":"Before it federates","description":"Aloha Social is a fediverse server that happens to live inside Aloha, so the things it needs are the things any fediverse server needs: a stable public address, a .well-known answer, and a…","group":"admin","html":"<p>Aloha Social is a fediverse server that happens to live inside Aloha, so the\nthings it needs are the things any fediverse server needs: a stable public\naddress, a <code>.well-known</code> answer, and a cron that runs.</p>\n<p><strong>A stable address.</strong> Aloha Social copies <code>overwrite.cli.url</code> into its own\n<code>cloud_url</code> the first time somebody opens the app, derives <code>social_url</code> (that\naddress followed by <code>/apps/social/</code>) from it, and builds every account id,\npost id and WebFinger answer from those copies. It never reads the system value\nagain. Set <code>overwrite.cli.url</code> — and get it right — before anyone opens Aloha Social;\nchanging the server&#39;s address afterwards is the single most expensive mistake\navailable here, because the old address is inside every id already federated.\nSee <a href=\"/docs/admin-the-address-aloha-social-is-set-up-for#the-address-aloha-social-is-set-up-for\"><em>the address Aloha Social is set up for</em></a>.</p>\n<p><strong><code>.well-known</code> redirects.</strong> Another server looking for <code>@alice@example.com</code>\nasks <code>https://example.com/.well-known/webfinger</code>. Aloha serves that from\n<code>/index.php/.well-known/webfinger</code>, and the redirect from the domain root is\nsomething the web server has to do; Aloha&#39;s\n<a href=\"https://docs.nextcloud.com/server/latest/go.php?to=admin-setup-well-known-URL\">documented redirects</a>\nare exactly the ones needed. Without them nobody outside can find an account\nhere, however well everything inside works.</p>\n<p><strong>Pretty URLs are not required</strong>, but an instance reachable only at\n<code>https://example.com/index.php/apps/social/...</code> federates under ids with\n<code>index.php</code> in them, which some peers handle poorly. If <code>.htaccess</code>-based URL\nrewriting is available, turn it on before the first account is created rather\nthan after.</p>\n<p><strong>Behind a reverse proxy</strong>, set <code>trusted_proxies</code> and <code>overwritehost</code>,\n<code>overwriteprotocol</code> and <code>overwrite.cli.url</code> as the Aloha documentation\ndescribes. Aloha Social signs its outbound requests over the <code>Host</code> and <code>Date</code>\nheaders and verifies the signatures on what arrives, so a proxy that rewrites\nthe host without Aloha knowing produces signature failures on both sides\nthat look like nothing else.</p>\n<p><strong>Cron.</strong> Background jobs must be set to <em>Cron</em> (system cron), not <em>AJAX</em> and\nnot <em>Webcron</em>. Everything this instance sends leaves through <code>Cron\\Queue</code>,\nwhich runs every 12 minutes; with AJAX jobs, delivery happens only when\nsomebody happens to load a page, and on a quiet instance that can be hours.\nSee <a href=\"/docs/admin-the-delivery-job-has-not-run#the-delivery-job-has-not-run\"><em>the delivery job has not run</em></a>.</p>\n<p><strong>Outbound HTTP.</strong> The server must be able to reach the rest of the fediverse\nover HTTPS. Requests to local and private addresses are refused unless\nAloha&#39;s <code>allow_local_remote_servers</code> is on, which is a development setting\nand not one to carry into production.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"before-it-federates","manual":false,"prev":{"path":"/docs/admin","title":"Administering Aloha Social"},"next":{"path":"/docs/admin-the-setup-checks","title":"The setup checks"},"parent":null},{"slug":"admin-the-setup-checks","path":"/docs/admin-the-setup-checks","title":"The setup checks","description":"Aloha Social registers its own checks in Administration → Overview, beside Aloha's own. They are the things that break federation, or stop clients connecting, without anything else saying…","group":"admin","html":"<p>Aloha Social registers its own checks in <strong>Administration → Overview</strong>, beside\nAloha&#39;s own. They are the things that break federation, or stop clients\nconnecting, without anything else saying so, and each links back to this page.</p>\n<p><code>occ social:check:install</code> runs the same classes (<code>lib/SetupChecks/</code>),\nprints each with its severity and exits <code>1</code> if any of them reports an error, so\na deployment script can run it. <code>--offline</code> leaves out the WebFinger probe, the\nonly one that goes out on the network.</p>\n<p><strong>Aloha Social: upload size.</strong> Whether PHP will accept the uploads this app promises\nto. PHP&#39;s <code>upload_max_filesize</code> and <code>post_max_size</code> are enforced before a byte\nreaches this app&#39;s code, so <code>/api/v1/instance</code> and <code>/api/v2/instance</code> advertise\n<code>image_size_limit</code> and <code>video_size_limit</code> as the smaller of the app&#39;s own\n(<code>max_size</code>, <code>max_video_size</code>) and PHP&#39;s. When PHP&#39;s is the smaller, every\nclient is held to it: an upload over it is refused with a 422 naming the limit\n(<code>the file is larger than this server accepts (2 MB)</code>), and a warning in the\nAloha log names the setting it went over. To let the app&#39;s own ceiling\napply, raise both PHP values; see\n<a href=\"/docs/admin-raising-the-upload-limit#raising-the-upload-limit\">Raising the upload limit</a>.</p>\n<p><strong>Aloha Social: video conversion.</strong> Whether the videos posted here will play\nanywhere else. A warning when <strong>ffmpeg is missing</strong>: iPhone <code>.mov</code> videos and\nHEVC videos are then stored and sent as they were uploaded, and will not play\non other servers — Pixelfed refuses anything that is not an MP4 — or in Chrome\nand Firefox. Information, not a warning, when ffmpeg is there and\n<code>video_transcode</code> has been switched off, because that is a decision. See\n<a href=\"/docs/admin-videos-do-not-play-elsewhere#videos-do-not-play-elsewhere\">Videos do not play elsewhere</a>.</p>\n<p><strong>Aloha Social: reachable by other servers.</strong> Whether the strict peers will talk to\nthis instance at all. Federation does not fail all at once: a plain-HTTP\ninstance, or one on a private address, federates happily with a permissive\nserver and is refused at the first gate by a strict one. The strictest in\ncommon use is <strong>Pixelfed</strong>, which is also the network a photo server most wants\nto reach — it refuses any peer that is not HTTPS on a publicly resolvable name,\nbefore it checks a signature, from its inbox, its delivery and its actor fetch,\nwith nothing to configure. This is expected on a development or intranet\ninstance and is a warning rather than an error.</p>\n<p><strong>Aloha Social: client API.</strong> Whether a Mastodon app can reach this instance at all.\nSee below — this is the one check that is about apps rather than about\nfederation, and it is a warning rather than an error, because everything else\nworks without it.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":[{"path":"/docs/admin-mastodon-apps-cannot-connect","title":"Mastodon apps cannot connect","description":"A Mastodon app is given a domain and builds https://<domain>/api/v1/... from it. Not one of them accepts a path, and Aloha Social's routes live under /index.php/apps/social, so out of the…","parent":true},{"path":"/docs/admin-webfinger-does-not-answer","title":"WebFinger does not answer","description":"Nothing answers /.well-known/webfinger for an account of this instance, so no other server can find anybody here — searches for a local account fail everywhere else, and follows from…","parent":true},{"path":"/docs/admin-the-address-aloha-social-is-set-up-for","title":"The address Aloha Social is set up for","description":"Aloha Social builds every id from its stored cloud_url and the server now reports something else. Accounts here cannot be found under the address the server advertises, and every new post…","parent":true},{"path":"/docs/admin-the-delivery-job-has-not-run","title":"The delivery job has not run","description":"Cron\\Queue is what sends. It is meant to run every 12 minutes; the check warns once an hour has passed without it, and errors if the job is not registered at all (disabling and re-enabling…","parent":true},{"path":"/docs/admin-deliveries-are-stuck","title":"Deliveries are stuck","description":"Two things in the outbound queue do not move on their own: a delivery the drain has given up on after every retry (16 attempts over a widening delay, the last gap fourteen hours), and one…","parent":true},{"path":"/docs/admin-no-memory-cache","title":"No memory cache","description":"APCu (memcache.local = \\OC\\Memcache\\APCu) is enough for all of it on a single web server; Redis is what several need.","parent":true},{"path":"/docs/admin-videos-do-not-play-elsewhere","title":"Videos do not play elsewhere","description":"An iPhone records .mov; Android phones, and iPhones exporting through some apps, write HEVC inside an .mp4. Pixelfed's default media_types accepts video/mp4 and nothing else and drops the…","parent":true},{"path":"/docs/admin-raising-the-upload-limit","title":"Raising the upload limit","description":"A client is told, and held to, the smaller of Aloha Social's own ceilings and PHP's. PHP's is the smaller of upload_max_filesize and post_max_size; its own default is 2 MB and 8 MB. A…","parent":true}],"anchor":"the-setup-checks","manual":false,"prev":{"path":"/docs/admin-before-it-federates","title":"Before it federates"},"next":{"path":"/docs/admin-mastodon-apps-cannot-connect","title":"Mastodon apps cannot connect"},"parent":null},{"slug":"admin-mastodon-apps-cannot-connect","path":"/docs/admin-mastodon-apps-cannot-connect","title":"Mastodon apps cannot connect","description":"A Mastodon app is given a domain and builds https://<domain>/api/v1/... from it. Not one of them accepts a path, and Aloha Social's routes live under /index.php/apps/social, so out of the…","group":"admin","html":"<p>A Mastodon app is given a domain and builds <code>https://&lt;domain&gt;/api/v1/...</code> from\nit. Not one of them accepts a path, and Aloha Social&#39;s routes live under\n<code>/index.php/apps/social</code>, so out of the box adding this instance to an app\nfails at its first request with nothing in the log to show for it. The web\ninterface and federation with other servers are unaffected.</p>\n<p>An administrator opening Aloha Social sees this at the top of the app, with the\nApache rules to paste, until the web server answers; it is the same check as\nin <strong>Administration → Overview</strong>, and it goes quiet within five minutes of the\nrules being in place.</p>\n<p>Aloha only lets a short list of apps claim URLs at the root of the domain,\nand Aloha Social is not on it, so this has to be done in the web server. Ready-made\nrules are in <a href=\"https://github.com/AlohaSocial/social/blob/master/contrib/webserver\"><code>contrib/webserver/</code></a>: include\n<code>apache-social-root.conf</code> from the <code>&lt;VirtualHost&gt;</code> that serves Aloha, or\n<code>nginx-social-root.conf</code> from its <code>server</code> block, and reload. For Apache that\nis:</p>\n<pre><code class=\"language-apache\">ProxyPreserveHost On\nRequestHeader set X-Forwarded-Proto &quot;https&quot;\n\nRewriteEngine On\nRewriteRule ^/?api/(.*)$   http://127.0.0.1/index.php/apps/social/api/$1   [P,QSA,L]\nRewriteRule ^/?oauth/(.*)$ http://127.0.0.1/index.php/apps/social/oauth/$1 [P,QSA,L]\nRewriteRule ^/?\\.well-known/host-meta$ http://127.0.0.1/index.php/.well-known/host-meta [P,QSA,L]\nRewriteRule ^/?\\.well-known/oauth-authorization-server$ http://127.0.0.1/index.php/apps/social/.well-known/oauth-authorization-server [P,QSA,L]\nRewriteRule ^/?\\.well-known/oauth-protected-resource$ http://127.0.0.1/index.php/apps/social/.well-known/oauth-protected-resource [P,QSA,L]\n</code></pre>\n<p><code>mod_proxy</code>, <code>mod_proxy_http</code>, <code>mod_rewrite</code> and <code>mod_headers</code> have to be enabled. This cannot\ngo in an <code>.htaccess</code> file, because <code>ProxyPreserveHost</code> is not allowed there and\nwithout it the app is handed <code>Host: 127.0.0.1</code> and refuses the request as an\nuntrusted domain.</p>\n<p><strong>Check what <code>127.0.0.1:80</code> actually serves.</strong> These rules proxy to plain HTTP\non the loopback address, which only works if something there serves <em>this</em>\nAloha. A server whose virtual hosts are all on <code>:443</code> — what a\ncertbot-managed config looks like once the HTTP ones have been commented out —\nhas no <code>:80</code> virtual host for the domain at all, so the request falls through\nto the main server and its <code>DocumentRoot</code>, and every proxied request answers\n404 from there.</p>\n<p>That 404 is indistinguishable from having no rules at all, which is the trap:\nthe rules are correct, they fire, and the warning stays up. The way to tell them\napart is that an Apache error page names the port it came from —</p>\n<pre><code>/api/v1/instance  →  &quot;Server at example.com Port 80&quot;    the rules fired, the target is wrong\n/login            →  &quot;Server at example.com Port 443&quot;   served by the HTTPS vhost itself\n</code></pre>\n<p>— and <code>apachectl -S</code> will show no <code>*:80</code> section. The app says which of the two\nit is as well: the warning carries what the probe got back.</p>\n<p>The fix is to give the proxy something to land on. A loopback-only listener\nkeeps plain HTTP off the public interface:</p>\n<pre><code class=\"language-apache\">Listen 127.0.0.1:8081\n\n&lt;VirtualHost 127.0.0.1:8081&gt;\n    ServerName example.com\n    DocumentRoot /path/to/nextcloud\n    &lt;Directory /path/to/nextcloud&gt;\n        Options FollowSymLinks\n        AllowOverride All\n        Require ip 127.0.0.1\n    &lt;/Directory&gt;\n&lt;/VirtualHost&gt;\n</code></pre>\n<p>then point the three rules at <code>http://127.0.0.1:8081</code> instead. <code>AllowOverride All</code> is not optional here: Aloha&#39;s own <code>.htaccess</code> is what hands the\n<code>Authorization</code> header to PHP, so without it the client API answers <em>the\naccess_token was revoked</em> for every signed-in request — see below.</p>\n<p>They map three things onto the app:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Path</th>\n<th>Why</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>/api/…</code></td>\n<td>every client call, from <code>/api/v1/instance</code> onwards</td>\n</tr>\n<tr>\n<td><code>/oauth/…</code></td>\n<td>registering the app, the consent screen, the token</td>\n</tr>\n<tr>\n<td><code>/.well-known/host-meta</code></td>\n<td>some clients ask for it before anything else</td>\n</tr>\n<tr>\n<td><code>/.well-known/oauth-authorization-server</code></td>\n<td>RFC 8414 discovery; a Mastodon 4.3 client asks for it before it registers anything, and reads a 404 as &quot;not a server I can sign in to&quot;</td>\n</tr>\n<tr>\n<td><code>/.well-known/oauth-protected-resource</code></td>\n<td>Bluesky apps signing in with Bluesky sign-in (OAuth) ask it which authorization server the accounts here use; with Bluesky on, <code>/.well-known/oauth-authorization-server</code> then describes both kinds of sign-in</td>\n</tr>\n</tbody></table></div>\n<p><strong>Use an internal rewrite, not a redirect.</strong> Aloha routes on the address\nthe request arrived at, so a plain internal rewrite to <code>/index.php/apps/social</code>\nreaches PHP but not the route, and answers 404. Sending a redirect instead does\nreach the route, but many HTTP clients drop the <code>Authorization</code> header when\nthey follow one, so every signed-in request then answers 401. The Apache rules\ntherefore proxy internally (<code>mod_proxy</code>, <code>mod_proxy_http</code> and <code>ProxyPreserveHost On</code>), which keeps both the address and the header.</p>\n<p>Apache also has to hand the <code>Authorization</code> header to PHP. Aloha&#39;s own\n<code>.htaccess</code> does that, but only where <code>AllowOverride</code> lets it be read; with\n<code>AllowOverride None</code> the rule never runs and every request from a signed-in app\nanswers <code>the access_token was revoked</code>. The shipped rules set it themselves for\nthe same reason.</p>\n<p><strong>The discovery document describes the addresses it was reached at.</strong> RFC 8414\nrequires the <code>issuer</code> in <code>/.well-known/oauth-authorization-server</code> to be the URL\nthe document was fetched from, minus the well-known suffix. A client that asks\nthe domain root and is told the issuer is <code>https://cloud.example/index.php/apps/social/</code>\nhas been handed a mismatch and rejects it — before it opens a browser, so\nnothing here sees it fail. So while the rewrite is working, the document\nadvertises the root addresses the client used; where it is not, it advertises\nthe app&#39;s own, which is the only reachable answer. Which of the two it is comes\nfrom the check below, read from its cache — an internal proxy hands PHP the app\npath either way, so the request itself cannot say.</p>\n<p><strong><code>X-Forwarded-Proto</code> is not optional.</strong> <code>mod_proxy</code> sends <code>X-Forwarded-For</code> and\n<code>X-Forwarded-Host</code> by itself and stops there, and the rules above proxy to plain\nHTTP — so without that header Aloha believes every proxied request arrived\nover <code>http</code> and builds every absolute URL it answers with accordingly. A client\nis then handed <code>http://</code> addresses for avatars, posts and the instance\nthumbnail, on a site that is <code>https</code>. An <strong>iOS client refuses them outright</strong>\n(App Transport Security), and its sign-in stops dead after registering the app,\nwith nothing in any log to show for it. The nginx rules set the equivalent\n(<code>proxy_set_header X-Forwarded-Proto $scheme</code>) and always did.</p>\n<p>The symptom is visible without a client: <code>/api/v2/instance</code> fetched through the\nroot answers a <code>thumbnail.url</code> beginning <code>http://</code>, where the same document\nfetched at <code>/index.php/apps/social/api/v2/instance</code> begins <code>https://</code>.</p>\n<p><strong>Add <code>127.0.0.1</code> to <code>trusted_proxies</code>.</strong> Client requests reach PHP from the\nproxy afterwards, so without it every app in the world shares one address for\nrate limiting, brute-force protection and the log — one client tripping a limit\nlocks out all of them. The real address arrives in <code>X-Forwarded-For</code>, which\nApache&#39;s <code>mod_proxy</code> sends by itself and the nginx rules set explicitly.</p>\n<p>The check probes <code>/api/v1/instance</code> at the address Aloha Social is configured for,\nthen at the host the request came in on, then at the server&#39;s base URL, and\nreads the answer rather than only its status, so a login page or a catch-all\n<code>index</code> at the root does not pass for a client API. A success is remembered for\nan hour and a failure for five minutes.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"mastodon-apps-cannot-connect","manual":false,"prev":{"path":"/docs/admin-the-setup-checks","title":"The setup checks"},"next":{"path":"/docs/admin-webfinger-does-not-answer","title":"WebFinger does not answer"},"parent":"admin-the-setup-checks"},{"slug":"admin-webfinger-does-not-answer","path":"/docs/admin-webfinger-does-not-answer","title":"WebFinger does not answer","description":"Nothing answers /.well-known/webfinger for an account of this instance, so no other server can find anybody here — searches for a local account fail everywhere else, and follows from…","group":"admin","html":"<p>Nothing answers <code>/.well-known/webfinger</code> for an account of this instance, so no\nother server can find anybody here — searches for a local account fail\neverywhere else, and follows from outside never arrive.</p>\n<p>Two quite different causes, and the check cannot tell them apart from outside:</p>\n<ol>\n<li>The redirects are missing. Add the\n<a href=\"https://docs.nextcloud.com/server/latest/go.php?to=admin-setup-well-known-URL\">documented ones</a>\nand reload the web server.</li>\n<li>Aloha Social is set up for a different address than the one the request arrives\non, so it answers for a host nobody asks about. The next check is about\nthat.</li>\n</ol>\n<p>The probe is tried at the address Aloha Social is configured for, then at the host\nthe request came in on, then at the server&#39;s base URL, and a success is\nremembered for an hour. If the instance uses a certificate the server itself\ndoes not trust — a private CA during setup — set <code>social.checkssl</code> to <code>false</code>\nin <code>config.php</code> to stop the probe verifying it. That switch is for the probe\nonly, not for federation.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"webfinger-does-not-answer","manual":false,"prev":{"path":"/docs/admin-mastodon-apps-cannot-connect","title":"Mastodon apps cannot connect"},"next":{"path":"/docs/admin-the-address-aloha-social-is-set-up-for","title":"The address Aloha Social is set up for"},"parent":"admin-the-setup-checks"},{"slug":"admin-the-address-aloha-social-is-set-up-for","path":"/docs/admin-the-address-aloha-social-is-set-up-for","title":"The address Aloha Social is set up for","description":"Aloha Social builds every id from its stored cloud_url and the server now reports something else. Accounts here cannot be found under the address the server advertises, and every new post…","group":"admin","html":"<p>Aloha Social builds every id from its stored <code>cloud_url</code> and the server now reports\nsomething else. Accounts here cannot be found under the address the server\nadvertises, and every new post carries an id that resolves nowhere.</p>\n<p>To see the two values:</p>\n<pre><code class=\"language-bash\">occ config:app:get social cloud_url\nocc config:system:get overwrite.cli.url\n</code></pre>\n<p>The same check compares the scheme, host and port of <code>social_url</code> — the base\nthe ids are actually minted from — with <code>cloud_url</code>. They can only disagree on\nan instance set up by an earlier version, which took <code>social_url</code> from the\nfirst request that opened the app: an internal hostname, or <code>http</code> behind a\nproxy that does not pass the scheme on. If nothing has federated yet,\n<code>occ config:app:delete social social_url</code> and it is derived from <code>cloud_url</code>\nthe next time the app is opened; otherwise <code>occ social:reset --uri=&lt;address&gt;</code>\nmoves both.</p>\n<p>Aloha Social reports the mismatch and will not correct it, because the stored address\nis inside every id already written. Either point <code>overwrite.cli.url</code> back at\nthe address Aloha Social knows, or accept the rename and run <code>occ social:reset --uri=&lt;new address&gt;</code>, <strong>which deletes everything Aloha Social holds</strong> — every post,\nfollow and cached account, local and remote alike.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"the-address-aloha-social-is-set-up-for","manual":false,"prev":{"path":"/docs/admin-webfinger-does-not-answer","title":"WebFinger does not answer"},"next":{"path":"/docs/admin-the-delivery-job-has-not-run","title":"The delivery job has not run"},"parent":"admin-the-setup-checks"},{"slug":"admin-the-delivery-job-has-not-run","path":"/docs/admin-the-delivery-job-has-not-run","title":"The delivery job has not run","description":"Cron\\Queue is what sends. It is meant to run every 12 minutes; the check warns once an hour has passed without it, and errors if the job is not registered at all (disabling and re-enabling…","group":"admin","html":"<p><code>Cron\\Queue</code> is what sends. It is meant to run every 12 minutes; the check\nwarns once an hour has passed without it, and errors if the job is not\nregistered at all (disabling and re-enabling the app registers it again).</p>\n<p>Nothing posted here leaves the server while it is not running, and nobody is\ntold: the author sees their post in their own timeline and nowhere else. Check\nthat background jobs are set to Cron, that the system cron is actually running\n<code>cron.php</code>, and that no other job is monopolising the runs.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"the-delivery-job-has-not-run","manual":false,"prev":{"path":"/docs/admin-the-address-aloha-social-is-set-up-for","title":"The address Aloha Social is set up for"},"next":{"path":"/docs/admin-deliveries-are-stuck","title":"Deliveries are stuck"},"parent":"admin-the-setup-checks"},{"slug":"admin-deliveries-are-stuck","path":"/docs/admin-deliveries-are-stuck","title":"Deliveries are stuck","description":"Two things in the outbound queue do not move on their own: a delivery the drain has given up on after every retry (16 attempts over a widening delay, the last gap fourteen hours), and one…","group":"admin","html":"<p>Two things in the outbound queue do not move on their own: a delivery the drain\nhas given up on after every retry (16 attempts over a widening delay, the last\ngap fourteen hours), and one it should have come back for a day ago and has\nnot. The first usually means an instance that is gone or refusing us; the\nsecond means the drain is not draining.</p>\n<pre><code class=\"language-bash\">occ social:queue:status                  # the same summary the settings page shows\nocc social:queue:retry --min-tries 16    # give the abandoned ones the full run again\nocc social:queue:retry --flush --min-tries 16   # or drop them, for a peer that is gone\n</code></pre>\n<p>The <strong>Deliveries</strong> section of the Aloha Social settings names the instances\nthe failures are stacked against, with the highest attempt count so far and\nwhen each was last tried.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"deliveries-are-stuck","manual":false,"prev":{"path":"/docs/admin-the-delivery-job-has-not-run","title":"The delivery job has not run"},"next":{"path":"/docs/admin-no-memory-cache","title":"No memory cache"},"parent":"admin-the-setup-checks"},{"slug":"admin-no-memory-cache","path":"/docs/admin-no-memory-cache","title":"No memory cache","description":"APCu (memcache.local = \\OC\\Memcache\\APCu) is enough for all of it on a single web server; Redis is what several need.","group":"admin","html":"<p>Without <code>memcache.local</code> or <code>memcache.distributed</code> in <code>config.php</code>, every cache\nAloha Social asks Aloha for is one that forgets each write. Aloha&#39;s own check\nalready says a memcache would be faster; this one is there because, for this\napp, some of what is lost is protection:</p>\n<ul>\n<li><strong>Kept in the database instead</strong> (<code>social_durable_cache</code>, expired rows\ndeleted by <code>Cron\\Cache</code>): the inbox throttle (<code>inbox_throttle</code>), the\nrecords of Linked Data signatures and of signed requests already accepted,\nwhich are what refuse a replayed activity, the <code>Idempotency-Key</code> record that\nkeeps a client&#39;s retried post from being published twice, and the\nstatistics page&#39;s fifteen-minute copy. All of it works; each costs a few\nqueries.</li>\n<li><strong>Always in the database</strong>, memcache or not: the per-server delivery\nbreaker (<code>social_host_breaker</code>), which every process and the cron share.</li>\n<li><strong>Worked out again on every request</strong>: the network figures, peer trends\nand follow suggestions.</li>\n</ul>\n<p>APCu (<code>memcache.local = \\OC\\Memcache\\APCu</code>) is enough for all of it on a\nsingle web server; Redis is what several need.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"no-memory-cache","manual":false,"prev":{"path":"/docs/admin-deliveries-are-stuck","title":"Deliveries are stuck"},"next":{"path":"/docs/admin-videos-do-not-play-elsewhere","title":"Videos do not play elsewhere"},"parent":"admin-the-setup-checks"},{"slug":"admin-videos-do-not-play-elsewhere","path":"/docs/admin-videos-do-not-play-elsewhere","title":"Videos do not play elsewhere","description":"An iPhone records .mov; Android phones, and iPhones exporting through some apps, write HEVC inside an .mp4. Pixelfed's default media_types accepts video/mp4 and nothing else and drops the…","group":"admin","html":"<p>An iPhone records <code>.mov</code>; Android phones, and iPhones exporting through some\napps, write <strong>HEVC</strong> inside an <code>.mp4</code>. Pixelfed&#39;s default <code>media_types</code> accepts\n<code>video/mp4</code> and nothing else and drops the rest the moment it arrives, and\nChrome and Firefox do not play HEVC. Aloha Social converts such videos to H.264 in an\nMP4 (<code>video_transcode</code>, on by default) — <strong>but only where ffmpeg is installed</strong>.\nInstall it from the distribution&#39;s packages (<code>apt install ffmpeg</code>,\n<code>dnf install ffmpeg</code>, …); ffprobe comes with it, and is what tells an H.264\nMP4, which is never touched, from an HEVC one. Aloha looks for both on the\n<code>PATH</code> of the PHP process and in the directories <code>binary_search_paths</code> in\n<code>config.php</code> names, only where PHP&#39;s <code>exec</code> is not disabled, and remembers the\nanswer for five minutes.</p>\n<p>Nothing needs restarting. Videos uploaded before ffmpeg was there are picked up\nby the background sweep, one every quarter of an hour, or all at once with\n<code>occ social:media:transcode</code>. Posts that already went out with the old file are\nnot sent again.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"videos-do-not-play-elsewhere","manual":false,"prev":{"path":"/docs/admin-no-memory-cache","title":"No memory cache"},"next":{"path":"/docs/admin-raising-the-upload-limit","title":"Raising the upload limit"},"parent":"admin-the-setup-checks"},{"slug":"admin-raising-the-upload-limit","path":"/docs/admin-raising-the-upload-limit","title":"Raising the upload limit","description":"A client is told, and held to, the smaller of Aloha Social's own ceilings and PHP's. PHP's is the smaller of upload_max_filesize and post_max_size; its own default is 2 MB and 8 MB. A…","group":"admin","html":"<p>A client is told, and held to, the smaller of Aloha Social&#39;s own ceilings and\nPHP&#39;s. PHP&#39;s is the smaller of <code>upload_max_filesize</code> and <code>post_max_size</code>; its\nown default is 2 MB and 8 MB. A refused upload leaves a warning in the\nAloha log saying which of the two it went over (<code>file upload refused: larger than this server accepts, over upload_max_filesize</code>, or <code>… the request body is over post_max_size</code>).</p>\n<p>Raise both, with <code>post_max_size</code> a little above <code>upload_max_filesize</code> so the\nrest of the form fits beside the file, wherever this PHP reads its settings:\nthe <code>php.ini</code> of the PHP-FPM pool or Apache module, a <code>.user.ini</code> in\nAloha&#39;s directory (PHP-FPM, picked up within five minutes), or\n<code>php_value</code> lines in Aloha&#39;s <code>.htaccess</code> (Apache with <code>mod_php</code>). For\nvideos up to 2 GB:</p>\n<pre><code class=\"language-ini\">upload_max_filesize = 2G\npost_max_size = 2050M\n</code></pre>\n<p>Restart PHP-FPM or Apache after editing <code>php.ini</code>. A reverse proxy or web\nserver in front has a body limit of its own (<code>client_max_body_size</code> in nginx,\n<code>LimitRequestBody</code> in Apache) that refuses a larger request before PHP sees\nit. A refusal there never reaches Aloha&#39;s log.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"raising-the-upload-limit","manual":false,"prev":{"path":"/docs/admin-videos-do-not-play-elsewhere","title":"Videos do not play elsewhere"},"next":{"path":"/docs/admin-bluesky","title":"Bluesky"},"parent":"admin-the-setup-checks"},{"slug":"admin-bluesky","path":"/docs/admin-bluesky","title":"Bluesky","description":"Every account on this instance can be a Bluesky account as well: this Aloha is its personal data server (PDS), alice.<host> its handle, and a Bluesky relay reads what it publishes. Nothing…","group":"admin","html":"<p>Every account on this instance can be a Bluesky account as well: this Aloha\nis its personal data server (PDS), <code>alice.&lt;host&gt;</code> its handle, and a Bluesky\nrelay reads what it publishes. Nothing is asked of the person; the\nadministrator switches it on once, on the administration page, after the\nrequirements below are met. The design and what each phase delivers is in\n<a href=\"/docs/atproto\">docs/Atproto-Compatibility.md</a>.</p>\n<p><strong>Requirements</strong>, each a check on the Bluesky card and in the Overview&#39;s setup\nchecks, and the card refuses to switch Bluesky on while one fails:</p>\n<ul>\n<li><p><strong>https</strong> on the instance host. A PDS is reached by relays and apps on the\npublic network, and a plain-http one is not a PDS to them; the one exception is\na development server nobody else talks to.</p>\n</li>\n<li><p><strong>A wildcard host for the handles.</strong> Every account&#39;s handle is\n<code>alice.&lt;host&gt;</code> and is resolved by <code>GET https://alice.&lt;host&gt;/.well-known/atproto-did</code>,\nso a DNS record <code>*.&lt;host&gt;</code> must point at this server and the certificate must\ncover it (a Let&#39;s Encrypt wildcard needs the DNS-01 challenge). The\nweb-server rules for that host are in <code>contrib/webserver</code> (the handles block\nat the end of each file).</p>\n</li>\n<li><p><strong><code>*.&lt;host&gt;</code> in <code>trusted_domains</code>.</strong> Aloha answers a request for a host it\ndoes not trust with an error page, before the app sees it:</p>\n<pre><code>php occ config:system:set trusted_domains 3 --value=&#39;*.social.example.com&#39;\n</code></pre>\n</li>\n<li><p><strong>The root rules.</strong> The DID document names the bare host as the PDS, so\n<code>/xrpc/</code> has to be served at the root exactly as <code>/api/</code> is for Mastodon apps,\nalong with <code>/.well-known/did.json</code>. The rules are in the same files:</p>\n<pre><code>RewriteRule ^/?xrpc/com\\.atproto\\.sync\\.subscribeRepos$ ws://127.0.0.1:8787/xrpc/com.atproto.sync.subscribeRepos [P,QSA,L]\nRewriteRule ^/?xrpc/(.*)$ http://127.0.0.1/index.php/apps/social/xrpc/$1 [P,QSA,L]\nRewriteRule ^/?\\.well-known/did\\.json$ http://127.0.0.1/index.php/apps/social/.well-known/did.json [P,QSA,L]\n</code></pre>\n<p>Apache needs <code>mod_proxy_wstunnel</code> for the first of them; nginx the\n<code>Upgrade</code>/<code>Connection</code> headers the shipped block sets.</p>\n</li>\n<li><p><strong>The firehose daemon.</strong> <code>occ social:atproto:serve</code> is a long-running process\nthat serves the event stream relays subscribe to. Under systemd:</p>\n<pre><code>[Unit]\nDescription=Aloha Social Bluesky firehose\nAfter=network.target mariadb.service\n\n[Service]\nUser=www-data\nWorkingDirectory=/var/www/nextcloud\nExecStart=/usr/bin/php occ social:atproto:serve --bind 127.0.0.1:8787\nRestart=always\nRestartSec=5\n\n[Install]\nWantedBy=multi-user.target\n</code></pre>\n<p>In a container, the same command under the container&#39;s supervisor. The daemon\nreports to the card every fifteen seconds; a report older than a minute shows\nas &quot;not running&quot;.</p>\n</li>\n<li><p><strong>Cron.</strong> The maintenance job (every five minutes) brings Bluesky up to\ndate with the last day&#39;s public posts — a post the listener missed is\npublished, an edit within the grace period is replaced, a deleted post&#39;s\nrecord is removed — resends directory operations, prunes the firehose\npast its window, drops retired keys, and removes Bluesky posts read here\nthat their authors deleted there. The ordinary cron requirement\ncovers it.</p>\n</li>\n</ul>\n<p><strong>Switching on.</strong> The Bluesky card checks the requirements and flips the switch.\nThen <code>php occ social:atproto:identities</code> gives every existing account its\nidentity (new accounts, and any account the command missed, get one on their\nfirst public post), and <code>php occ social:atproto:crawl</code> tells the relays to\nsubscribe. From then on every public post of every account goes to Bluesky as\nit is made, edits within five minutes replace the Bluesky copy and later ones\nleave it standing with its link to the current post here, and a deleted post is\ndeleted there. Direct, followers-only and unlisted posts never leave. The other\nway, people here follow Bluesky accounts by their bare handle\n(<code>alice.bsky.social</code>) and read them in their home feed; the sync job reads the\nfollowed authors&#39; feeds from Bluesky&#39;s public AppView, and asks the AppView,\nas each local account, what Bluesky did to it — follows, likes, reposts,\nreplies, mentions — which arrive in Activities like anything else. Each\nperson can pause their own Bluesky presence in Settings → Apps and account → Bluesky.</p>\n<p><strong>What the card shows.</strong> The handle host, the PDS endpoint and the instance&#39;s\n<code>did:web</code>; the relays (<code>https://bsky.network</code> by default; &quot;Tell the relays now&quot;\nsends the crawl request again); the PLC directory and the AppView the instance\ntalks to (the defaults are Bluesky&#39;s; the interop job points them at its own —\n<code>atproto_appview</code> for public reads, <code>atproto_appview_auth</code> and\n<code>atproto_appview_did</code> for the reads made as a user, which the public AppView\nrefuses); how many identities and repositories there are, how many events the\nreplay window holds and the head sequence number; the daemon&#39;s last report;\nthe age of the instance rotation key; and the reading side — how many Bluesky\nauthors are followed, how many accounts&#39; notifications are asked for, and how\nfar behind the slowest of each is. <code>atproto_sync_ceiling</code> (default 200) caps\nthe AppView requests one sync pass makes.</p>\n<p><strong>Blocking on Bluesky.</strong> The card&#39;s <em>Blocked on Bluesky</em> list (or <code>occ social:atproto:block</code>) blocks a Bluesky account by its DID, or a whole PDS\nhost and the hosts under it. A blocked account is not resolved, read or heard\nfrom, and one that people here follow is removed with its posts — the\nBluesky counterpart of a domain block. Reports people file about Bluesky\naccounts with <em>forward</em> ticked go to Bluesky&#39;s moderation service\n(<code>atproto_moderation_did</code>, Bluesky&#39;s own by default), sent by this server, not\nin the reporter&#39;s name.</p>\n<p><strong>Video.</strong> A video posted here goes to Bluesky as a Bluesky video: it is sent\nto Bluesky&#39;s video service (<code>atproto_video_service</code>, <code>https://video.bsky.app</code>\nby default, and <code>atproto_video_service_did</code>) in the poster&#39;s name, and the\npost follows once the service has made it, usually within a few minutes.\nA video Bluesky does not take — over 100 MB or three minutes, or past the\naccount&#39;s daily limit — goes out as a link to the post here. Set\n<code>atproto_video_service</code> to an empty value to publish every video as a link.</p>\n<p><strong>Keys and backups.</strong> Each account&#39;s signing key and the instance&#39;s rotation and\nservice keys are stored sealed with the instance secret, like actor keys. They\nare the identities: a DID whose keys are lost can no longer be updated, and the\nperson&#39;s recovery phrase (Settings → Apps and account → Bluesky) is their own way back. Back\nup the database <em>and</em> <code>config.php</code>&#39;s <code>secret</code> together. After a restore from an\nolder backup the firehose sequence goes backwards; run <code>php occ social:atproto:crawl</code> and the relays re-read every repository.\n<code>php occ social:atproto:rotate-key</code> replaces the instance rotation key; the old\none stays valid for the directory&#39;s 72-hour window.</p>\n<p><strong>Switching off</strong> keeps every identity and repository and stops the daemon&#39;s\nwork, the maintenance job and the publisher; the handles stop resolving until\nit is switched on again.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"bluesky","manual":false,"prev":{"path":"/docs/admin-raising-the-upload-limit","title":"Raising the upload limit"},"next":{"path":"/docs/admin-the-administration-page","title":"The administration page"},"parent":null},{"slug":"admin-the-administration-page","path":"/docs/admin-the-administration-page","title":"The administration page","description":"On a wide screen the groups are a list beside the page, each with a line saying what is in it, and the sections of the open group are listed under it. On a narrow one they are a row of…","group":"admin","html":"<p><strong>Administration → Aloha Social.</strong> The sections are in six groups, by what an\nadministrator came to do, and one group is shown at a time:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Sections</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Overview</strong></td>\n<td>Needs attention, Activity here</td>\n</tr>\n<tr>\n<td><strong>Moderation</strong></td>\n<td>Reports, Posts waiting for review, Accounts, Refused pictures, Server rules</td>\n</tr>\n<tr>\n<td><strong>Sign-ups</strong></td>\n<td>Who may sign up, Waiting and invited, External accounts (only when the server sends them, see <a href=\"/docs/admin-external-users#external-users\">External users</a>)</td>\n</tr>\n<tr>\n<td><strong>Explore and features</strong></td>\n<td>About this server, What may trend, Custom emoji, Announcements, Features, For you</td>\n</tr>\n<tr>\n<td><strong>Federation</strong></td>\n<td>Allowed and blocked servers, Block lists, Relays, Deliveries</td>\n</tr>\n<tr>\n<td><strong>Server</strong></td>\n<td>Server settings, Retention, Storage, Background jobs</td>\n</tr>\n</tbody></table></div>\n<p>On a wide screen the groups are a list beside the page, each with a line saying\nwhat is in it, and the sections of the open group are listed under it. On a\nnarrow one they are a row of tabs above it. <strong>Find a setting</strong> searches every\ngroup at once, by a section&#39;s name, its description or a word it is known by\n(&quot;cron&quot;, &quot;spam&quot;, &quot;blocklist&quot;).</p>\n<p>The page opens on <strong>Overview</strong>, and <strong>Needs attention</strong> at the top of it lists\nwhat is waiting, most urgent first, each line a link to the section that deals\nwith it: background jobs that are late or not registered, deliveries close to\nbeing given up on, open reports, posts waiting for review, sign-ups waiting for\napproval, and deliveries that failed and will be tried again. The groups with\nsomething waiting carry the number beside their name; a retried delivery is\nlisted but not counted, because it needs nobody yet.</p>\n<p>Each section has an id, and the address names the one on screen:\n<code>/settings/admin/social#reports</code> opens Moderation at Reports. The report\nnotification and the Reports dashboard widget link to <code>#reports</code>, the\nFederation health widget to <code>#federation</code>.</p>\n<h2 id=\"reports\">Reports</h2>\n<p>what people here and peers elsewhere have complained about.\nThe open ones are the table; the resolved ones are folded away below them and\nread a page at a time when the fold is opened. Fifty to a page, server-side,\nwith a <em>Show more</em> under each.</p>\n<h2 id=\"activity-here\">Activity here</h2>\n<p>posts written on this server in the last day and the last\nweek, and how many accounts wrote them. Local posts only: a count that\nincluded what arrived would be a number about other servers and about this\none&#39;s retention setting.</p>\n<h2 id=\"posts-waiting-for-review\">Posts waiting for review</h2>\n<p>the review queue: the first post of a\nnew account, and posts that tripped one of the spam rules. Each row carries\nthe text, because a held post is in no timeline and there is nowhere else to\ngo and read it. <em>Publish</em> sends it out; <em>Refuse</em> deletes it and tells its\nauthor. Three switches at the top turn first-post review, the spam rules and\nholding every post with a video on it on and off.</p>\n<h2 id=\"features\">Features</h2>\n<p>what this instance offers the people using it. Three switches,\n<strong>all on by default</strong>: <em>24-hour shorts</em> (shorts that only followers see\nand that are gone after a day), and the <em>Photos</em> and <em>Videos</em>\ntimelines. Turning one off takes it out of the sidebar and stops it being\noffered; nothing already posted is touched, so a video posted while Videos\nwas off is still a video and appears again the moment it is turned back on.\nThe fourth setting is the Aloha groups that become Aloha Social lists, and it is\n<strong>empty by default</strong>: everybody in a chosen group gets a list for it holding\nthe members who have an Aloha Social account, nobody is followed by it and nothing\nfederates, but a group list does tell everybody in the group who else is in\nit -- which is why no group becomes one until an administrator chooses.\nDeselecting a group takes its lists away on the next cron reconcile.\nAdministrators only, not delegates.</p>\n<h2 id=\"accounts\">Accounts</h2>\n<p>every account this instance knows, whether or not anybody has\ncomplained. Search by username, by handle or by instance, filter by origin\nand by what stands against them, and act on any of them.</p>\n<h2 id=\"refused-pictures\">Refused pictures</h2>\n<p>files this instance will not store, named by their\nsha256. The one thing the account-level tools do not do is stop a <em>file</em>\ncoming back; a refused one is turned away wherever it arrives, an upload here\nor an attachment fetched from another server. The list shows the newest 100;\nwhen there are more it says how many, and <strong>Show more</strong> adds the next 100\nbelow. <strong>Allow again</strong> works on any row, on whichever page.</p>\n<h2 id=\"about-this-server\">About this server</h2>\n<p>a few named subjects, each a handful of\nhashtags, shown at the top of Explore above the trending lists. Trending on\na small server is four hashtags and a wedding; this is the part of that page\nchosen rather than counted, and it is what makes Explore look like somewhere\nto start. Nothing is named by default and the section of the page is absent\nuntil something is.</p>\n<h2 id=\"what-may-trend\">What may trend</h2>\n<p>Explore shows whatever is being talked about, counted\nand nothing else, so the first ugly hashtag to catch on does so on\neverybody&#39;s Explore page and the only remedy used to be waiting. Keeping one\nout hides it from every trending list here and from the discover grid; the\ncounters keep counting, so letting it back in restores the number it would\nhave had. Hashtags can be kept out from the live trending list beside them;\na link or a post is kept out by pasting its address. What is kept out is one\nlist whatever kind it is, because the question is &quot;what am I keeping out of\nExplore&quot;.</p>\n<h2 id=\"custom-emoji\">Custom emoji</h2>\n<p>the pictures people here can write into a post as\n<code>:shortcode:</code>. They travel with the post, so somebody on another server sees\nthem too. The upload goes through the same code <code>occ social:emoji</code> uses, so\nwhat is refused here is exactly what the command refuses.</p>\n<h2 id=\"server-rules\">Server rules</h2>\n<p>one per line. Every client shows them to\nsomebody deciding whether to join, and <code>/api/v1/instance/rules</code> serves them.\nBoth this and the emoji were <code>occ</code>-only until now, which is why most\ninstances had neither.</p>\n<h2 id=\"retention\">Retention</h2>\n<p>how long remote statuses nobody here cares about are kept.</p>\n<h2 id=\"storage\">Storage</h2>\n<p>what is on disk, split into what was posted here (somebody&#39;s\nown work, not going anywhere) and what is cached from other servers (what\nRetention removes). Added up by the background job once a day, because\ncounting it is one file lookup per stored file; the page says when it was\nmeasured. <code>occ social:media:usage</code> measures it on demand.</p>\n<p>Not a card, but the thing to know beside this one: a <strong>rejected remote\nattachment</strong> — after changing this instance&#39;s media limits or fixing a\ntemporary origin problem, retry just that file with\n<code>occ social:media:retry &lt;remote_url&gt;</code>. Use the exact <code>remote_url</code> reported\nby the attachment; Aloha Social clears the stored refusal for that one uncached\nrow and tries it immediately. The normal media checks still apply, so a\nretry can be refused again. A picture that simply took too long to arrive\nwhile its post was being received is not refused: the background job fetches\nit again, and it and the retry command allow a download two minutes.</p>\n<h2 id=\"deliveries\">Deliveries</h2>\n<p>what the outbound queue is doing, including how long\nthe longest-failing delivery has been failing: the counts say how much and\nwhere, and that says whether it started an hour ago or a week ago, which is\nthe difference between a peer rebooting and a delivery that is never going to\nhappen.</p>\n<h2 id=\"background-jobs\">Background jobs</h2>\n<p>when each of this app&#39;s cron jobs last ran, and whether\nthat is later than it should be. Almost everything the app does away from a\npage happens on a schedule: posts go out, 24-hour shorts expire, media is swept,\nvideos are transcoded, the storage figures are taken. When cron stops, the\nsymptom is a post that never arrives and a disk that never shrinks, and\nnothing in the app said so. A job is called late after <strong>three</strong> of its own\nintervals, because Aloha&#39;s cron is itself periodic and a five-minute job\non a fifteen-minute timer is always two intervals behind with nothing wrong\nwith it. A job missing from the list altogether is what an upgrade whose\nmigrations have not run looks like; the page says so rather than showing a\nzero. Read from Aloha&#39;s own job list, so it cannot drift from what\nactually happened.</p>\n<h2 id=\"allowed-and-blocked-servers\">Allowed and blocked servers</h2>\n<p>the block list or the allow list, the same\none <code>occ social:fediverse</code> manages.</p>\n<h2 id=\"block-lists\">Block lists</h2>\n<p>import a list of servers to block, with a preview of what it\nwould do, or follow one somebody else publishes; see\n<a href=\"/docs/admin-commands-by-task#commands-by-task\"><em>following a published list</em></a> under Moderation below.</p>\n<h2 id=\"announcements\">Announcements</h2>\n<p>a notice every account here is shown once.</p>\n<h2 id=\"server-settings\">Server settings</h2>\n<p>the instance-wide settings below, which had no interface at all\nbefore and could only be set with <code>occ config:app:set</code>.</p>\n<h2 id=\"relays\">Relays</h2>\n<p>the relays this server subscribes to. A new server sees only\nwhat the people on it follow, so its federated timeline is empty on the first\nday and thin for months, and nobody out there has heard of it either. A relay\nbreaks that circle: it rebroadcasts the public posts of every server\nsubscribed to it, and sends this server&#39;s public posts on to all of them.\nPaste the relay&#39;s address — relays publish it on their own front page, and it\nusually ends in <code>/actor</code> — and the row will say <strong>Waiting for an answer</strong>\nuntil the relay replies, which for some relays means when a human has looked\nat the request. <strong>Public posts and nothing else</strong> are shared: a\nfollowers-only post has an audience that was chosen, and a relay is the\nopposite of a chosen audience. A relayed post is fetched from the server that\nwrote it rather than believed from the relay, so it arrives as the post it is\nand not as &quot;relay.example boosted this&quot;.</p>\n<p>Each section is one card with its name and a line saying what it is for, and\nthe three things that cannot be taken back — suspending an\naccount, taking a post down, removing an announcement — ask in a dialog that\nsays what they will cost before they do it.</p>\n<p>The page can be <strong>delegated</strong>: hand the Aloha Social section to a group under\n<em>Administration privileges</em> and that group can moderate without administering\nthe server. Server settings and Relays are the exception — neither is rendered for a\ndelegate and their endpoints refuse them, because what they hold is a decision\nabout the server rather than about a report: a relay changes what every\nfederated timeline here holds and where every public post written here is\nsent. A delegate cannot act on an Aloha administrator&#39;s account, and\nnobody — administrator or delegate — can silence, suspend, lift or purge their\nown.</p>\n<hr>\n","toc":[{"id":"reports","text":"Reports","level":2},{"id":"activity-here","text":"Activity here","level":2},{"id":"posts-waiting-for-review","text":"Posts waiting for review","level":2},{"id":"features","text":"Features","level":2},{"id":"accounts","text":"Accounts","level":2},{"id":"refused-pictures","text":"Refused pictures","level":2},{"id":"about-this-server","text":"About this server","level":2},{"id":"what-may-trend","text":"What may trend","level":2},{"id":"custom-emoji","text":"Custom emoji","level":2},{"id":"server-rules","text":"Server rules","level":2},{"id":"retention","text":"Retention","level":2},{"id":"storage","text":"Storage","level":2},{"id":"deliveries","text":"Deliveries","level":2},{"id":"background-jobs","text":"Background jobs","level":2},{"id":"allowed-and-blocked-servers","text":"Allowed and blocked servers","level":2},{"id":"block-lists","text":"Block lists","level":2},{"id":"announcements","text":"Announcements","level":2},{"id":"server-settings","text":"Server settings","level":2},{"id":"relays","text":"Relays","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"the-administration-page","manual":false,"prev":{"path":"/docs/admin-bluesky","title":"Bluesky"},"next":{"path":"/docs/admin-external-users","title":"External users"},"parent":null},{"slug":"admin-external-users","path":"/docs/admin-external-users","title":"External users","description":"People without an account on this server can register one themselves, when an administrator switches it on. They log in through the normal login page and reach Aloha Social and nothing…","group":"admin","html":"<p>People without an account on this server can register one themselves, when\nan administrator switches it on. They log in through the normal login page\nand reach Aloha Social and nothing else. It is off by default, and the three cards\nare in the <strong>Sign-ups</strong> group of the administration page, for\nadministrators proper only: who may have an account here is not a\nmoderator&#39;s decision.</p>\n<p><strong>Registration.</strong> The switch <em>Let people register</em>, the maximum number of\nexternal accounts (registration closes when that many exist, with a message\nsaying so), the megabytes of media each may upload, and the minimum age a\nperson confirms. <em>Who gets an account</em> is anybody who registers, anybody an\nadministrator approves, or only the holders of an invitation link; an\ninvitation admits its holder in every mode, without approval. With <em>Confirm\nthe email address</em> on, which is the default, the account is made when the\nlink in the confirmation email is followed, so the server needs working\nmail. The form also asks to accept the server rules (the <strong>Server rules</strong> section) and\nlinks the privacy policy and legal notice set in Administration → Theming.\nThe additional registration and privacy information box is plain text shown\non the introduction page and beside the form. It starts with a translated\ntemplate and can be adapted for this instance. <em>Require registrants to accept\nthis notice</em> adds a required checkbox. When enabled, Aloha Social records the text\nversion, the time and the accepted text with the account. The record remains\nfor the lifetime of that account and is removed when the account is deleted.\nPending records transfer the acknowledgement to the account when it is made;\nrejected records are removed, and unconfirmed registrations expire after 24\nhours. These\nsettings provide an audit trail, not legal advice or a guarantee that a notice\nis sufficient for a particular jurisdiction. The operator remains responsible\nfor local policies and any consent required.\n<em>Usernames nobody may register</em> adds to a built-in list (<code>admin</code>, <code>root</code>,\n<code>support</code>, <code>social</code>, <code>postmaster</code> and similar). Email domains on the access\nblock list are refused here as they are for every account.</p>\n<p><em>Require two-factor authentication</em> is Aloha&#39;s own mandatory two-factor\nsetting for the <code>social-external</code> group, the same one as in Administration →\nSecurity; changing it asks for your password. With it on, external users set\nup a second factor when they first log in.</p>\n<p>Where Aloha Social is enabled for some groups only, external users are let in by\nadding <code>social-external</code> to them. Switching registration on does that, and\nthe card warns and offers a button when the restriction leaves them out.</p>\n<p><strong>Waiting and invited.</strong> The registrations waiting for approval, with\n<em>Approve</em>, which makes the account and emails the person, and <em>Reject</em>, which\ndeletes the registration and emails them, with a reason if you give one.\nBelow it, the invitation links: a note to remember who each is for, how many\nregistrations it admits (0 for any number) and how many days it works (0 for\never). <em>Let everybody here send invitation links</em> also gives every user an\n<em>Invite people</em> section in their Aloha Social settings, single-use links that work\nfor a week, at most ten open at a time.</p>\n<p><strong>External accounts.</strong> Every external account with its email and verification\nstatus, enabled or disabled status, registration source, when it registered\nand last logged in, media usage, and the version and time of any accepted\nregistration notice. Search matches the username and display name. Sort by username or registration\ndate, newest or oldest. Filters cover account status, registration source and\ndate, login activity, minimum media usage and notice acceptance. The list is paged and scans at most a\nbounded number of candidates per request.\n<em>Disable</em> and\n<em>Enable</em> are Aloha&#39;s own. <em>Promote</em> makes one an ordinary account of this\nserver with the same username, password, two-factor setup and Aloha Social\naccount; from then on the groups and apps you give them apply, and there is\nno way back. <em>Delete</em> removes the account and its Aloha Social account, the way\ndeleting any Aloha user does. Both ask for your password. External users\nalso appear on the Users page, with <em>Aloha Social</em> as their backend and in the\n<code>social-external</code> group.</p>\n<p><strong>Guests app.</strong> Aloha Social&#39;s self-registered accounts use Aloha Social&#39;s own <code>Social</code>\nuser backend and the <code>social-external</code> group. They are distinct from accounts\ncreated by the <a href=\"https://github.com/nextcloud/guests\">Guests app</a>, which uses\nthe <code>Guests</code> backend and <code>guest_app</code> group. Aloha Social&#39;s account restrictions and\ncollaborator filtering target only its own backend, so they do not classify a\nGuests-app account as an Aloha Social external account. The two apps can be installed\ntogether, but the Guests app controls which Aloha apps its accounts may\nopen: add <code>social</code> to its app whitelist if those accounts should use Aloha Social.\nThis setting does not grant a Guests account the Aloha Social-only restrictions;\nGuests accounts remain governed by the Guests app and Aloha group policy.</p>\n<p>What an external user reaches: Aloha Social, logging in and out, their personal\nsettings for their details, language, security, appearance and\nnotifications, and their notifications. Everything else is refused before it\nruns, including every app installed later, and WebDAV, CalDAV and CardDAV are\nrefused altogether, so Aloha&#39;s desktop and mobile clients and Talk do not\nwork for them; Mastodon apps do. Nobody outside Aloha Social finds them in the\nshare dialog, the contacts menu, the user status list or the system address\nbook. See <a href=\"Architecture.md#external-users\">Architecture.md</a> for how.</p>\n<p><code>occ social:reset</code> refuses to run while external accounts exist: their logins\nare rows of this app.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"external-users","manual":false,"prev":{"path":"/docs/admin-the-administration-page","title":"The administration page"},"next":{"path":"/docs/admin-moderating","title":"Moderating"},"parent":null},{"slug":"admin-moderating","path":"/docs/admin-moderating","title":"Moderating","description":"Reports arrive from two directions: a local user reporting somebody through a client, and a peer instance sending POST /api/v1/reports about one of its own users' complaints. Both land in…","group":"admin","html":"<p>Reports arrive from two directions: a local user reporting somebody through a\nclient, and a peer instance sending <code>POST /api/v1/reports</code> about one of its\nown users&#39; complaints. Both land in the same table, and the administrators (and\nthe delegated group) are notified.</p>\n<p>There are five things a moderator can do to an account, in order of weight:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>What it costs</th>\n<th>Reversible</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Warn</strong></td>\n<td>Nothing. The account is told there is a problem and everything else stays as it is.</td>\n<td>n/a</td>\n</tr>\n<tr>\n<td><strong>Mark everything sensitive</strong></td>\n<td>Every post the account makes from now on is marked sensitive, whatever it said. It stays in the timelines and its followers still see it — behind a click.</td>\n<td>yes, completely</td>\n</tr>\n<tr>\n<td><strong>Silence</strong></td>\n<td>The account leaves the public and global timelines. Whoever deliberately follows it still sees it.</td>\n<td>yes, completely</td>\n</tr>\n<tr>\n<td><strong>Take down</strong></td>\n<td>One post is deleted. A local post is deleted everywhere it reached; a remote one only here.</td>\n<td>no</td>\n</tr>\n<tr>\n<td><strong>Suspend</strong></td>\n<td>Everything the account posted here is deleted, its cached actor is dropped, its follows in both directions go, and everything it sends afterwards is refused. A <strong>local</strong> account&#39;s suspension is federated as a <code>Delete</code>.</td>\n<td>the refusal stops; nothing deleted comes back</td>\n</tr>\n</tbody></table></div>\n<p><em>Resolve</em> marks the complaint handled and changes nothing about the account, so\na report can be closed with any of the four applied, or with none.</p>\n<p><strong>What is recorded.</strong> <code>social_moderation</code> holds what stands <em>now</em> — one row an\naccount, replaced by the next decision and gone when it is lifted.\n<code>social_strikes</code> is the history: a warning, a silence, a suspension, a takedown\nand a lift each write a row naming the moderator, and nothing removes one\nexcept the account itself going. The strike count in the account browser counts\nwhat stands against the account, so a lift is in the history and not in the\ncount.</p>\n<p><strong>The audit log.</strong> Suspending, silencing, lifting, taking a post down and\nblocking or unblocking an instance each emit\n<code>OCP\\Log\\Audit\\CriticalActionPerformedEvent</code>, so with core&#39;s <code>admin_audit</code> app\nenabled they land in the audit log beside &quot;user X was added to group Y&quot;, naming\nthe moderator who acted. Without that app nothing listens and nothing is\nwritten.</p>\n<p><strong>Before anybody sees it.</strong> Two rules hold a post back instead of publishing\nit. The spam rules are on by default; first-post review is off until an\nadministrator turns it on:</p>\n<ul>\n<li><strong>first-post review</strong> (<code>review_first_post</code>) holds the first post of an\naccount that has published nothing here yet. Accounts here are Aloha\nusers, so a spammer has to be given an account by this server before they can\npost at all — and on an instance that hands accounts to strangers, the\ncheapest thing that can be done about it is that the first thing they write\nis seen by a person. <strong>Off by default</strong>: on the ordinary instance, whose\naccounts are colleagues an administrator created, it held every new person&#39;s\nfirst post and made their first five minutes look broken — the composer\nclosed, the post did not appear, and it existed only in a panel nobody had\nopened yet. Turn it on where registration is open.\n<strong>An administrator&#39;s own posts are never held</strong>: somebody who can empty the\nqueue is not somebody to put in it, and the first post on a brand-new\ninstance is the administrator&#39;s — held, it made a fresh install look broken,\nbecause the post did not appear and the only place it existed was a panel\nthey had not opened yet.</li>\n<li><strong>autospam</strong> (<code>autospam</code>) holds a post that trips one of a very short list of\nrules: more than five links in a short post, or more than five mentions from\nan account that nobody follows and that follows nobody. There is no wordlist\nand no score — &quot;seven links&quot; is something a moderator can agree or disagree\nwith in a second, and &quot;0.82&quot; is not.</li>\n</ul>\n<p>A <strong>direct message is never held</strong>, whatever it says: holding one would put\nprivate correspondence in front of a moderator who was not written to, for a\nmachine&#39;s reason. Nor is a post by an account a decision already stands\nagainst — that account is being dealt with by the decision.</p>\n<p>Nothing is published, and nothing is deleted, without somebody pressing\nsomething. A held post is stored as the <em>request</em> the client sent, not as a\npost: it is in no timeline, no profile, no outbox and no search, not even its\nauthor&#39;s, and their own copy of it is in <strong>Settings → Your posts → Waiting for review</strong>,\nwhere they can take it back. Approving replays the request down the path an\nimmediate post takes and dates it now. Refusing deletes it, tells the author,\nand records a takedown strike. One account may have twenty waiting; past that\nits posts are refused outright, because nobody is going to read the fortieth.</p>\n<p><strong>Instances, not accounts.</strong> <em>Allowed and blocked servers</em> is the instance-wide list.\nIn block-list mode (the default, <code>access_type=all_but</code>) everything on it is\nrefused, including every subdomain, and blocking a domain queues a purge of\neverything it ever sent. In allow-list mode (<code>none_but</code>) the list is the only\ninstances this server will talk to at all — and it is matched exactly, so a\nsubdomain of a listed domain is a different instance and is not covered.</p>\n<p>The one thing an entry does cover is <strong>what an allowed instance holds\nelsewhere</strong>. A post&#39;s pictures are fetched from whatever host the post says\nholds them, and that is routinely not the host the post came from: a post on\n<code>mastodon.xyz</code> carries its media on <code>6-28.mastodon.xyz</code>, and object storage or\na CDN is common besides. Those hosts are judged as the instance that named\nthem, because nobody can list the buckets another server keeps its pictures\nin. Judging them on their own refused every picture from every allowed\ninstance, so allow-list mode federated text and nothing else. An instance that is a nuisance\nrather than a menace can be <em>silenced</em> instead with <code>occ social:fediverse silence</code>: its accounts leave the public timelines and stay readable for the\npeople who follow them.</p>\n<hr>\n<h2 id=\"from-a-pixelfed-admin-app\">From a Pixelfed admin app</h2>\n<p>The administration screens of Pixelfed&#39;s official app call Pixelfed&#39;s own\n<code>/api/admin/*</code> routes, and this instance answers them — behind the same gate\nas everything above, and through the same service, so a takedown from the app\nis the same takedown as one from this page. Users, open reports and the\ninstances this server federates with are all there; Pixelfed&#39;s <code>unlisted</code> on\nan instance is the silence tier and its <code>banned</code> the deny list. Its <strong>autospam</strong>\nscreen draws this instance&#39;s own review queue, with <em>not spam</em> publishing a held\npost and <em>delete</em> refusing it. What this instance does not have — per-account\n&quot;unlisted&quot; or &quot;content warning&quot; flags, switches that flip from the app — is\nanswered as absent or refused with a reason, never as a 200 that changed\nnothing. The\nroutes and their answers are in <a href=\"API.md\">API.md</a>.</p>\n","toc":[{"id":"from-a-pixelfed-admin-app","text":"From a Pixelfed admin app","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"moderating","manual":false,"prev":{"path":"/docs/admin-external-users","title":"External users"},"next":{"path":"/docs/admin-configuration","title":"Configuration"},"parent":null},{"slug":"admin-configuration","path":"/docs/admin-configuration","title":"Configuration","description":"Nothing here is reachable through core's app-config API: the settings page writes through its own validated endpoints, and a delegate can write only what the moderation routes accept.","group":"admin","html":"<p>Everything below is app configuration under <code>social</code>, read and written with:</p>\n<pre><code class=\"language-bash\">occ config:app:get social &lt;key&gt;\nocc config:app:set social &lt;key&gt; --value=&lt;value&gt;\n</code></pre>\n<p>Nothing here is reachable through core&#39;s app-config API: the settings page\nwrites through its own validated endpoints, and a delegate can write only what\nthe moderation routes accept.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":[{"path":"/docs/admin-set-by-the-app-not-by-you","title":"Set by the app, not by you","description":"The base address every id is built from, copied from overwrite.cli.url the first time the app is opened. Changing it by hand does not rewrite the ids already issued.","parent":true},{"path":"/docs/admin-server-settings","title":"Server settings","description":"Instance-wide settings. Most of them are on the Server section of the settings page, which validates the ranges given here; every one can be set with occ.","parent":true},{"path":"/docs/admin-moderation-and-federation","title":"Moderation and federation","description":"all_but — federate with everyone except the listed instances (block list). none_but — federate only with the listed ones (allow list).","parent":true},{"path":"/docs/admin-external-users-2","title":"External users","description":"Set from the External users cards; these are the keys they write.","parent":true},{"path":"/docs/admin-system-configuration","title":"System configuration","description":"And one of Aloha's own that matters here: allow_local_remote_servers, which must be on for an instance to federate with anything on a private address. That is a development arrangement.","parent":true}],"anchor":"configuration","manual":false,"prev":{"path":"/docs/admin-moderating","title":"Moderating"},"next":{"path":"/docs/admin-set-by-the-app-not-by-you","title":"Set by the app, not by you"},"parent":null},{"slug":"admin-set-by-the-app-not-by-you","path":"/docs/admin-set-by-the-app-not-by-you","title":"Set by the app, not by you","description":"The base address every id is built from, copied from overwrite.cli.url the first time the app is opened. Changing it by hand does not rewrite the ids already issued.","group":"admin","html":"<h2 id=\"cloud-url\">cloud_url</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>The base address every id is built from, copied from <code>overwrite.cli.url</code> the first time the app is opened. Changing it by hand does not rewrite the ids already issued.</p>\n<h2 id=\"social-url\">social_url</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>The app&#39;s own base URL (<code>…/apps/social/</code>), which every id is minted from and which profile links, WebFinger and NodeInfo use. Derived from <code>cloud_url</code> — never from the request — the first time the app is opened with <code>cloud_url</code> set, and again by <code>occ social:reset</code>.</p>\n<h2 id=\"social-address\">social_address</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>The hostname accounts are federated under, when it is not the host of <code>cloud_url</code>. Only set this if the fediverse address genuinely differs from the Aloha host, and only before the first account exists.</p>\n<h2 id=\"service\">service</h2>\n<p><strong>Default: </strong><code>1</code></p>\n<p>Unused; a leftover of the original installer.</p>\n<h2 id=\"installed-version\">installed_version</h2>\n<p>Written by the upgrade machinery.</p>\n<h2 id=\"media-usage\">media_usage</h2>\n<p><strong>Default: </strong><em>(written by the job)</em></p>\n<p>The last measurement of what is on disk, as JSON with the moment it was taken. Bookkeeping, not a setting: the walk is a <code>stat</code> per stored file and belongs in the cron, so the administration page reads this rather than counting on page load.</p>\n<h2 id=\"directory-known\">directory_known</h2>\n<p><strong>Default: </strong><em>(written by the job)</em></p>\n<p>What <code>Cron\\Cache</code> last found out about the servers the Discover page may ask: the <code>fediverse.info</code> server list and each federated peer&#39;s NodeInfo software, as JSON with when each was read. Bookkeeping, not a setting: the page reads this rather than asking those servers while somebody waits.</p>\n<h2 id=\"polls-swept\">polls_swept</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>How far the closed-poll sweep has got, as a timestamp.</p>\n<h2 id=\"stream-author-hosts-filled\">stream_author_hosts_filled</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Set to <code>1</code> by <code>Cron\\StreamAuthorHosts</code> once every post carries the host of its author in <code>social_stream.author_host</code>. Until then the domain-block and silenced-instance filters also match a post by its actor id, which is slower. Bookkeeping, not a setting.</p>\n<h2 id=\"story-secret\">story_secret</h2>\n<p><strong>Default: </strong><em>(generated)</em></p>\n<p>The secret a 24-hour short&#39;s fetch capability (the bearcap Pixelfed fetches it with) is derived from, made the first time one is published. Changing it invalidates every outstanding capability at once, which is the only revocation it needs: a 24-hour short lives a day. Never set this by hand.</p>\n","toc":[{"id":"cloud-url","text":"cloud_url","level":2},{"id":"social-url","text":"social_url","level":2},{"id":"social-address","text":"social_address","level":2},{"id":"service","text":"service","level":2},{"id":"installed-version","text":"installed_version","level":2},{"id":"media-usage","text":"media_usage","level":2},{"id":"directory-known","text":"directory_known","level":2},{"id":"polls-swept","text":"polls_swept","level":2},{"id":"stream-author-hosts-filled","text":"stream_author_hosts_filled","level":2},{"id":"story-secret","text":"story_secret","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"set-by-the-app-not-by-you","manual":false,"prev":{"path":"/docs/admin-configuration","title":"Configuration"},"next":{"path":"/docs/admin-server-settings","title":"Server settings"},"parent":"admin-configuration"},{"slug":"admin-server-settings","path":"/docs/admin-server-settings","title":"Server settings","description":"Instance-wide settings. Most of them are on the Server section of the settings page, which validates the ranges given here; every one can be set with occ.","group":"admin","html":"<p>Instance-wide settings. Most of them are on the <strong>Server</strong> section of the\nsettings page, which validates the ranges given here; every one can be set with\n<code>occ</code>.</p>\n<h2 id=\"contact-email\">contact_email</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>Who to write to about this instance. Mastodon&#39;s <code>instance.email</code>: every client reads it on its first request and shows it on the server&#39;s about page. Empty until somebody fills it in, which until now most instances never did, because nothing said it existed.</p>\n<h2 id=\"contact-account\">contact_account</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>The local Aloha Social account responsible for this instance. Choose a local account by username under Server settings; remote accounts and team accounts without an Aloha user are refused. Aloha Social stores the owning Aloha user id and resolves the current account when it builds <code>/api/v1/instance</code> and <code>/api/v2/instance</code>, so profile changes are reflected without rewriting the setting. Clearing the field omits the contact account.</p>\n<h2 id=\"extended-description\">extended_description</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>The long form of what this instance is, for <code>/api/v1/instance/extended_description</code>. Up to 10000 characters.</p>\n<h2 id=\"max-size\">max_size</h2>\n<p><strong>Default: </strong><code>10</code></p>\n<p>The largest picture or file an upload may be, in MB. 1–10240.</p>\n<h2 id=\"max-video-size\">max_video_size</h2>\n<p><strong>Default: </strong><code>2048</code></p>\n<p>The largest video, in MB. 1–102400. A peer will refuse a great deal less than the ceiling.</p>\n<h2 id=\"image-max-edge\">image_max_edge</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>The longest edge a <strong>stored</strong> picture may have, in pixels. <code>0</code> stores every upload exactly as it arrived — the default, and the only setting that loses nothing: this app strips metadata losslessly and re-encodes only a picture it has to rotate. Set it (480–16384) on an instance where storage costs money or whose people post from a 48-megapixel phone. A picture already inside the ceiling is not re-encoded, because shrinking nothing and losing a generation anyway is the worst of both.</p>\n<h2 id=\"image-quality\">image_quality</h2>\n<p><strong>Default: </strong><code>85</code></p>\n<p>What a re-encoded picture is stored at, 40–100. Only consulted when <code>image_max_edge</code> is set.</p>\n<h2 id=\"video-transcode\">video_transcode</h2>\n<p><strong>Default: </strong><code>1</code></p>\n<p>Whether videos uploaded here are re-encoded to H.264 in an MP4 by a background job; a video cached from another server is never touched. <strong>On by default, and it does nothing where ffmpeg is not installed</strong> — the <em>Aloha Social: video conversion</em> setup check says which it is. What it converts: <code>.mov</code>, WebM, Matroska and the other formats in <code>VideoTranscodeService::CONVERTIBLE</code>, and an MP4 whose video ffprobe does not report as H.264 (HEVC, which phones write and only Safari plays). An H.264 MP4 is never re-encoded; without ffprobe an MP4 is left as it is. Why: <strong>Pixelfed&#39;s default <code>media_types</code> accepts <code>video/mp4</code> and nothing else</strong>, so every <code>video/quicktime</code> posted from here, which is every video straight off an iPhone, is dropped by its inbox without a word to anybody, and Safari will not play WebM. <strong>The converted file replaces the original, which is deleted</strong> — re-encoding is lossy, so switch it off where the uploaded files must be kept exactly as they are. Never runs during an upload: converting a video is minutes rather than the seconds a poster frame takes, so the upload finishes as it always did. A <strong>new post</strong> carrying such a video is queued but <strong>held back</strong> while the video it carries is converted by a job of its own at the next cron run, and goes out naming the MP4 — for at most ten minutes (<code>VideoDeliveryHold::HOLD_SECONDS</code>), after which it is delivered as it is. Posts without such a video, and every post on a server without ffmpeg or with this off, are not held at all. Older videos are converted by a sweep, one every quarter of an hour, or <code>occ social:media:transcode</code> to work through a backlog now. An instance that never saved this key has it on after upgrading.</p>\n<h2 id=\"video-max-height\">video_max_height</h2>\n<p><strong>Default: </strong><code>1080</code></p>\n<p>The tallest a converted video is written, 240–2160. Only smaller, never larger: a 480p video is left at 480p. Only consulted when <code>video_transcode</code> is on.</p>\n<h2 id=\"video-ladder\">video_ladder</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Whether each stored MP4 is <strong>also</strong> written at a ladder of smaller sizes, as HLS, so a player can pick the one that fits the connection. A different question from <code>video_transcode</code>, which is about a video being playable at all elsewhere; this is about it being watchable on a phone on a train. Off by default, because it is several ffmpeg encodes per video on this server. Each rung is one file — <code>-hls_flags single_file</code> writes the rendition as a fragmented MP4 and the playlist addresses its segments as byte ranges — so a forty-minute video is three files rather than a thousand, which is also the shape PeerTube publishes. The original is kept and is what a player without HLS falls back to. Needs ffmpeg <strong>and</strong> ffprobe. One video every half-hour, or <code>occ social:media:ladder</code> to work through a backlog now. Built from <code>video/mp4</code> only: a <code>.mov</code> goes through the transcoder first.</p>\n<h2 id=\"video-ladder-heights\">video_ladder_heights</h2>\n<p><strong>Default: </strong><code>360,720,1080</code></p>\n<p>Which heights, comma-separated, 144–2160. Heights at or above a video&#39;s own are skipped rather than upscaled, and the video&#39;s own height is always a rung, so the best rung is never worse than the file beside it. A list with nothing usable in it is refused by the admin card rather than silently replaced with the default. Only consulted when <code>video_ladder</code> is on.</p>\n<h2 id=\"search-window-days\">search_window_days</h2>\n<p><strong>Default: </strong><code>365</code></p>\n<p>How far back a content search scans while it cannot use its word index: before <code>Cron\\SearchIndex</code> has indexed the posts stored before the upgrade (until <code>search_index_ready</code> is <code>1</code>), and for a query that is only the beginning of a word. Such a search is a range rather than one indexed word, and unbounded it reads every post the instance has ever stored; a year covers what anybody is looking for. <code>0</code> searches everything, which an instance small enough can afford to say. A search for whole words reads the index and is not bounded by this.</p>\n<h2 id=\"local-actor-cursor\">local_actor_cursor</h2>\n<p><strong>Default: </strong><code>&#39;&#39;</code></p>\n<p>Bookkeeping, not a setting: where the cron&#39;s local-account refresh walk got to. It used to read every local account into memory on every pass; it pages now, and this is what makes the next pass carry on rather than start again.</p>\n<h2 id=\"profile-link-cursor\">profile_link_cursor</h2>\n<p><strong>Default: </strong><code>&#39;&#39;</code></p>\n<p>Bookkeeping, not a setting: where the cron&#39;s walk over the local accounts whose profile fields carry a link got to, so the next pass checks the next ones.</p>\n<h2 id=\"video-quota\">video_quota</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>How many megabytes of video <strong>one account</strong> may keep here; <code>0</code> is no quota, which is what every instance has in effect today. A different question from <code>max_video_size</code>, which is a ceiling on one file: that is about a single request, this about a year of them. Off by default because an instance that has been running without a quota and acquires one on upgrade would start refusing uploads from exactly the accounts that use it most. Checked once, where an upload is written, against the size recorded on each stored file — so a video uploaded before this app recorded sizes counts as nothing until the daily usage job has been past it, which fills the column in as it walks. The <strong>ladders this server builds do not count against it</strong>: they are made because an administrator asked for them, are several times the size of the upload, and would turn a quota somebody was told about into one several times smaller. They are counted in what an administrator is shown, because they are real disk. Who is holding what is under <strong>Administration → Aloha Social → Storage</strong>.</p>\n<h2 id=\"nsfw-policy\">nsfw_policy</h2>\n<p><strong>Default: </strong><code>default</code></p>\n<p>What happens to media somebody marked sensitive, for readers who have not chosen for themselves. PeerTube&#39;s three NSFW policies under Mastodon&#39;s names for the same three states: <code>show_all</code> (PeerTube&#39;s <em>display</em>), <code>default</code> (its <em>blur</em> — covered, the blurhash showing, one press away, and what this app has always done) and <code>hide_all</code> (its <em>hide</em> — not drawn, and no button to draw it). Anybody can override it for themselves under <strong>Settings</strong> in the app, and &quot;follow the instance&quot; stays a state of its own, so changing this moves everybody who is following it and nobody who has chosen. A <strong>content warning is a different thing</strong> and always covers its post, whatever this says.</p>\n<h2 id=\"review-videos\">review_videos</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Whether every post with a video on it waits for a moderator. The third rule of the review queue, beside a new account&#39;s first post and the spam rules, and the one an instance that hosts video wants: a video is minutes of somebody&#39;s attention and a great deal of somebody else&#39;s disk. <strong>Unlike the other two it is not about the account</strong> — a trusted account with a thousand posts behind it is held by it too, every time, because what it is about is the video. A moderator&#39;s own video is not held, and neither is a direct message. Under <strong>Administration → Aloha Social → Posts waiting to be looked at</strong>.</p>\n<h2 id=\"inbox-throttle\">inbox_throttle</h2>\n<p><strong>Default: </strong><code>300</code></p>\n<p>Incoming inbox requests allowed per origin host per minute. <code>0</code> accepts everything, which is what an instance behind its own rate limiter wants.</p>\n<h2 id=\"rate-limit-user\">rate_limit_user</h2>\n<p><strong>Default: </strong><code>900</code></p>\n<p>How many client API requests one <strong>signed-in account</strong> may make per window. The routes that fan out — search, the directories, the follow graph — carry limits of their own and Aloha enforces those; this is the budget for everything else, which was some three hundred routes with no limit at all. Generous on purpose: it exists to stop a scraper reading the whole instance at machine speed, not to pace an app. One budget for the whole API, not one per route. <code>0</code> switches it off, which is what an instance behind its own limiter wants. Federation, the internal queue and the routes that serve bytes (attachments, avatars, emoji, GIFs) are never counted — one public page is forty requests for pictures, and deliveries arrive in bursts from a handful of addresses.</p>\n<h2 id=\"rate-limit-anon\">rate_limit_anon</h2>\n<p><strong>Default: </strong><code>300</code></p>\n<p>The same budget for a caller with <strong>no account</strong>, counted per address.</p>\n<h2 id=\"rate-limit-window\">rate_limit_window</h2>\n<p><strong>Default: </strong><code>300</code></p>\n<p>How long that window is, in seconds.</p>\n<h2 id=\"token-max-days\">token_max_days</h2>\n<p><strong>Default: </strong><code>365</code></p>\n<p>How many days an OAuth token works from the moment it was granted, <strong>however much it is used</strong>. A token idle for a year stops working anyway; this is about one in use, which used to live for ever — every request kept it alive, so a token copied off a phone lived as long as whoever held the copy kept using it. Past it the app is signed out and the person signs in again; there are no refresh tokens. Each person sees when under <strong>Settings → Authorized apps</strong>. <code>0</code> lets a token in use live for ever.</p>\n<h2 id=\"follow-limit\">follow_limit</h2>\n<p><strong>Default: </strong><code>100</code></p>\n<p>How many follows <strong>one account</strong> may send in an hour. A compromised account, or one running a script, can fan out follows to thousands of servers from this instance&#39;s address in a few minutes — every one a signed request this instance is answerable for. An hour rather than a day because what this catches is a burst, and high enough that importing a follow list from another server still goes through. Counted from the rows, so it holds on an instance with no memcache. <code>0</code> is no limit.</p>\n<h2 id=\"domain-media-quota\">domain_media_quota</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>How many megabytes of media <strong>one other server</strong> may keep here. Every picture on a post somebody here follows is fetched and cached, and nothing bounded that by where it came from: one server posting large images at a high rate fills the disk of every instance that follows anybody on it. The server is the host of the file&#39;s own address (its <code>url</code>), which for a Mastodon instance is often a separate media host. Counted from the figure the daily storage walk takes, plus successfully cached bytes from that host since — rejected or unreadable downloads do not spend quota. The figure is up to a day coarse and errs towards refusing early. Off by default, because an instance that has been federating for a year and acquires a quota on upgrade would start refusing the pictures of the servers it talks to most. Who is holding what is under <strong>Administration → Aloha Social → Storage</strong>.</p>\n<h2 id=\"secure-mode\">secure_mode</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Refuse ActivityPub fetches that are not signed. Mastodon&#39;s secure mode. Turning it on makes this instance invisible to every peer that does not sign what it asks for, and to every anonymous reader; it is a decision about who to federate with, not a hardening step to apply by default.</p>\n<h2 id=\"publish-blocks\">publish_blocks</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Publish the deny list on <code>/api/v1/instance/domain_blocks</code>, the way Mastodon does, so somebody choosing a server can see who it will not talk to. Whether <em>this</em> server wants that read by anybody is a disclosure decision.</p>\n<h2 id=\"allow-self-signed\">allow_self_signed</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Accept peers whose certificates do not check out. <strong>Development only</strong>: on a server anybody else uses, this hands every federated request to whoever can answer for the address.</p>\n","toc":[{"id":"contact-email","text":"contact_email","level":2},{"id":"contact-account","text":"contact_account","level":2},{"id":"extended-description","text":"extended_description","level":2},{"id":"max-size","text":"max_size","level":2},{"id":"max-video-size","text":"max_video_size","level":2},{"id":"image-max-edge","text":"image_max_edge","level":2},{"id":"image-quality","text":"image_quality","level":2},{"id":"video-transcode","text":"video_transcode","level":2},{"id":"video-max-height","text":"video_max_height","level":2},{"id":"video-ladder","text":"video_ladder","level":2},{"id":"video-ladder-heights","text":"video_ladder_heights","level":2},{"id":"search-window-days","text":"search_window_days","level":2},{"id":"local-actor-cursor","text":"local_actor_cursor","level":2},{"id":"profile-link-cursor","text":"profile_link_cursor","level":2},{"id":"video-quota","text":"video_quota","level":2},{"id":"nsfw-policy","text":"nsfw_policy","level":2},{"id":"review-videos","text":"review_videos","level":2},{"id":"inbox-throttle","text":"inbox_throttle","level":2},{"id":"rate-limit-user","text":"rate_limit_user","level":2},{"id":"rate-limit-anon","text":"rate_limit_anon","level":2},{"id":"rate-limit-window","text":"rate_limit_window","level":2},{"id":"token-max-days","text":"token_max_days","level":2},{"id":"follow-limit","text":"follow_limit","level":2},{"id":"domain-media-quota","text":"domain_media_quota","level":2},{"id":"secure-mode","text":"secure_mode","level":2},{"id":"publish-blocks","text":"publish_blocks","level":2},{"id":"allow-self-signed","text":"allow_self_signed","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"server-settings","manual":false,"prev":{"path":"/docs/admin-set-by-the-app-not-by-you","title":"Set by the app, not by you"},"next":{"path":"/docs/admin-moderation-and-federation","title":"Moderation and federation"},"parent":"admin-configuration"},{"slug":"admin-moderation-and-federation","path":"/docs/admin-moderation-and-federation","title":"Moderation and federation","description":"all_but — federate with everyone except the listed instances (block list). none_but — federate only with the listed ones (allow list).","group":"admin","html":"<h2 id=\"access-type\">access_type</h2>\n<p><strong>Default: </strong><code>all_but</code></p>\n<p><code>all_but</code> — federate with everyone except the listed instances (block list). <code>none_but</code> — federate only with the listed ones (allow list).</p>\n<h2 id=\"access-list\">access_list</h2>\n<p><strong>Default: </strong><code>[]</code></p>\n<p>The instances on that list, as a JSON array of hostnames. An entry covers every subdomain of itself. Managed from the settings page and by <code>occ social:fediverse</code>.</p>\n<h2 id=\"silenced-list\">silenced_list</h2>\n<p><strong>Default: </strong><code>[]</code></p>\n<p>Instances whose accounts are kept out of the public and global timelines but stay readable for whoever follows them. The middle tier a block does not have.</p>\n<h2 id=\"retention-days\">retention_days</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Remote statuses older than this that no local user interacted with, follows the author of, or replied below are deleted, with their cached attachments. <code>0</code> disables it. Local content is never touched.</p>\n<h2 id=\"notification-retention-days\">notification_retention_days</h2>\n<p><strong>Default: </strong><code>90</code></p>\n<p>In-app notification rows older than this are deleted by the same prune, whether or not <code>retention_days</code> is set. <code>0</code> keeps them for good.</p>\n<h2 id=\"notification-policy-defaults\">notification_policy_defaults</h2>\n<p><strong>Default: </strong><em>(calm)</em></p>\n<p>What the notification policy of a <strong>new</strong> local account starts as, as JSON with the five keys of Mastodon&#39;s policy, each <code>accept</code> or <code>filter</code>. Unset, it is the calm policy: people the account does not follow, accounts younger than 30 days, private mentions it did not ask for and accounts this server limited are <strong>held for review</strong> (no bell, push or mail; they wait in the account&#39;s requests), everyone else gets through. Read once, when the account is created — the first-run screen, <code>occ social:account:create</code>, an external user&#39;s sign-up and every other path go through the same <code>AccountService::createActor()</code> — so changing it <strong>never touches an existing account</strong>; accounts from before this setting existed keep receiving everything until their owner chooses. Written through <code>GET</code>/<code>POST /apps/social/admin/notification-policy</code> (administrators only, not delegates; any value but <code>accept</code> or <code>filter</code> is refused with a 422, because an administrator decides what waits for review, never what is thrown away), whose current value the settings page receives as <code>notificationPolicyDefaults</code>.</p>\n<h2 id=\"federate-blocks\">federate_blocks</h2>\n<p><strong>Default: </strong><code>1</code></p>\n<p>Whether a user&#39;s own blocks are federated to the blocked account&#39;s instance. <code>0</code> keeps them local.</p>\n<h2 id=\"publish-video-objects\">publish_video_objects</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Whether a post that is a video is federated as an ActivityPub <code>Video</code> (PeerTube&#39;s shape) rather than a <code>Note</code> with an attachment. Off by default: Pixelfed&#39;s inbox handles only <code>Note</code>s and silently drops a <code>Video</code>, so with this on no video posted here reaches a Pixelfed follower. Mastodon draws both shapes; PeerTube draws only the <code>Video</code>. Turn it on for an instance whose audience is on PeerTube.</p>\n<h2 id=\"network-stats\">network_stats</h2>\n<p><strong>Default: </strong><code>1</code></p>\n<p>Whether the statistics page may ask <a href=\"https://fedidb.org\">FediDB</a> how big the fediverse is — servers, accounts, accounts that posted in the last month — to show beside the number of servers this one federates with. One request every six hours for the whole instance, carrying no account, no query and nothing about this instance; a survey that does not answer is left alone for half an hour. Set it to <code>0</code> and the section is absent rather than zeroed: an instance that makes no outbound request to draw a page is a legitimate thing to want. The same value governs the <strong>growth</strong> section below it, which asks <a href=\"https://fediverse.observer\">Fediverse Observer</a> for the last two years month by month — FediDB publishes a snapshot and no history, so the shape over time comes from a second survey, once a day. The two do not agree about the totals, because they crawl different servers and count dormant accounts differently, so the page keeps them apart and names each: a page that averaged them would produce a number neither survey would stand behind.</p>\n<h2 id=\"rules\">rules</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>The instance rules shown by <code>/api/v1/instance/rules</code>, one per line.</p>\n<h2 id=\"review-first-post\">review_first_post</h2>\n<p><strong>Default: </strong><code>0</code></p>\n<p>Hold the first post of an account that has published nothing here yet, for a moderator to see before it goes out. Off by default; turn it on where accounts are handed to strangers. An administrator&#39;s own posts are never held — a moderator waiting on themselves is a circle, and on a new instance the first post is theirs.</p>\n<h2 id=\"review-posts\">review_posts</h2>\n<p><strong>Default: </strong><code>1</code></p>\n<p>How many posts an account must have had published before its posts stop being held. <code>1</code> is first-post review as it has always meant. An account graduates by having that many posts approved — a person having looked at it that many times, which is the only measure of trust here that is not a guess. Capped at 20.</p>\n<h2 id=\"autospam\">autospam</h2>\n<p><strong>Default: </strong><code>1</code></p>\n<p>Hold a post that trips one of the spam rules — more than five links in a short post, or more than five mentions from an account nobody follows and that follows nobody. Nothing is ever refused by the rules, only shown to a person.</p>\n<h2 id=\"ai-tags\">ai_tags</h2>\n<p><strong>Default: </strong><em>(empty)</em></p>\n<p>Hashtags that label a post as <strong>made with AI</strong>, comma-separated, added to the built-in list (<code>#ai</code>, <code>#aiart</code>, <code>#aigenerated</code>, <code>#aigeneratedart</code>, <code>#aiimage</code>, <code>#aiphoto</code>, <code>#aivideo</code>, <code>#genai</code>, <code>#generativeai</code>, <code>#madewithai</code>, <code>#midjourney</code>, <code>#stablediffusion</code>, <code>#dalle</code>, <code>#dalle3</code>, <code>#sora</code>, <code>#fluxai</code>, <code>#comfyui</code>). Compared without the <code>#</code> and without regard to case; a built-in tag cannot be removed. A reader who turns on <strong>Hide posts made with AI</strong> under Settings → Blocking is shown no post carrying one of these tags, and no post whose picture states machine-generation provenance in its metadata (IPTC <code>DigitalSourceType</code> of <code>trainedAlgorithmicMedia</code> or <code>compositeWithTrainedAlgorithmicMedia</code>, in XMP or inside a C2PA manifest — read when the picture is stored, before the metadata is stripped). <strong>What this can and cannot do:</strong> it recognises <em>labels</em> — a hashtag the author or their tool added, a provenance mark a generator wrote into the file — and nothing else. A generated post that carries neither is not recognised; a real photograph tagged <code>#ai</code> by its author is. There is no classifier here and there should not be one.</p>\n","toc":[{"id":"access-type","text":"access_type","level":2},{"id":"access-list","text":"access_list","level":2},{"id":"silenced-list","text":"silenced_list","level":2},{"id":"retention-days","text":"retention_days","level":2},{"id":"notification-retention-days","text":"notification_retention_days","level":2},{"id":"notification-policy-defaults","text":"notification_policy_defaults","level":2},{"id":"federate-blocks","text":"federate_blocks","level":2},{"id":"publish-video-objects","text":"publish_video_objects","level":2},{"id":"network-stats","text":"network_stats","level":2},{"id":"rules","text":"rules","level":2},{"id":"review-first-post","text":"review_first_post","level":2},{"id":"review-posts","text":"review_posts","level":2},{"id":"autospam","text":"autospam","level":2},{"id":"ai-tags","text":"ai_tags","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"moderation-and-federation","manual":false,"prev":{"path":"/docs/admin-server-settings","title":"Server settings"},"next":{"path":"/docs/admin-external-users-2","title":"External users"},"parent":"admin-configuration"},{"slug":"admin-external-users-2","path":"/docs/admin-external-users-2","title":"External users","description":"Set from the External users cards; these are the keys they write.","group":"admin","html":"<p>Set from the External users cards; these are the keys they write.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Key</th>\n<th>Default</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>external_enabled</code></td>\n<td><code>0</code></td>\n<td>Whether people without an account may register one for Aloha Social.</td>\n</tr>\n<tr>\n<td><code>external_max</code></td>\n<td><code>100</code></td>\n<td>How many external accounts may exist.</td>\n</tr>\n<tr>\n<td><code>external_media_quota</code></td>\n<td><code>1024</code></td>\n<td>Megabytes of media each external user may upload. <code>0</code> is no quota.</td>\n</tr>\n<tr>\n<td><code>external_signup_mode</code></td>\n<td><code>approval</code></td>\n<td><code>open</code>, <code>approval</code> or <code>invite</code>.</td>\n</tr>\n<tr>\n<td><code>external_verify_email</code></td>\n<td><code>1</code></td>\n<td>Whether the email address is confirmed before the account is made.</td>\n</tr>\n<tr>\n<td><code>external_min_age</code></td>\n<td><code>16</code></td>\n<td>The age a person confirms at registration. <code>0</code> asks nothing.</td>\n</tr>\n<tr>\n<td><code>external_reserved</code></td>\n<td><code>[]</code></td>\n<td>Usernames nobody may register, as a JSON array, on top of the built-in ones.</td>\n</tr>\n<tr>\n<td><code>external_user_invites</code></td>\n<td><code>0</code></td>\n<td>Whether every user may send invitation links.</td>\n</tr>\n</tbody></table></div>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"external-users","manual":false,"prev":{"path":"/docs/admin-moderation-and-federation","title":"Moderation and federation"},"next":{"path":"/docs/admin-system-configuration","title":"System configuration"},"parent":"admin-configuration"},{"slug":"admin-system-configuration","path":"/docs/admin-system-configuration","title":"System configuration","description":"And one of Aloha's own that matters here: allow_local_remote_servers, which must be on for an instance to federate with anything on a private address. That is a development arrangement.","group":"admin","html":"<p>Two <code>config.php</code> values, neither documented anywhere else:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Key</th>\n<th>Default</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>social.checkssl</code></td>\n<td><code>true</code></td>\n<td>Whether the WebFinger setup check verifies the certificate it is offered. Set it to <code>false</code> on an instance using a certificate the server itself does not trust. It affects the probe only — federation still verifies.</td>\n</tr>\n<tr>\n<td><code>social.tests</code></td>\n<td><em>(unset)</em></td>\n<td>Enables <code>GET /apps/social/test/{account}/</code>, a WebFinger self-test. Leave it unset outside development.</td>\n</tr>\n</tbody></table></div>\n<p>And one of Aloha&#39;s own that matters here: <code>allow_local_remote_servers</code>,\nwhich must be on for an instance to federate with anything on a private\naddress. That is a development arrangement.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"system-configuration","manual":false,"prev":{"path":"/docs/admin-external-users-2","title":"External users"},"next":{"path":"/docs/admin-commands-by-task","title":"Commands by task"},"parent":"admin-configuration"},{"slug":"admin-commands-by-task","path":"/docs/admin-commands-by-task","title":"Commands by task","description":"The full reference is OCC-Commands.md; these are the ones an administrator reaches for.","group":"admin","html":"<p>The full reference is <a href=\"/docs/occ\">OCC-Commands.md</a>; these are the ones an\nadministrator reaches for.</p>\n<p><strong>Is it working?</strong></p>\n<pre><code class=\"language-bash\">occ social:check:install            # the setup checks it can run from the console, plus repairs\nocc social:check:install --offline  # the same without the network probe\nocc social:queue:status             # what the outbound queue is doing\nocc social:details &lt;id&gt;             # who can see one post and where it lands\n</code></pre>\n<p>Aloha Social also repairs the recipient and hashtag side indexes automatically in\nbounded five-minute cron passes. Each pass visits at most 500 streams, stores\nits last fully indexed NID, and resumes from there; a failed row is retried on\nthe next passes, and after five failures it is logged as skipped and the walk\nmoves on. Once the walk reaches the newest post the repair is complete\n(app config <code>index_done</code> = <code>1</code>) and the job does nothing more; deleting that\nkey runs it again from the stored cursor. Keep Aloha background jobs\nworking as <code>Cron\\Index</code> relies on them. The manual <code>occ social:check:install --index --force</code> remains a full\nrebuild for administrators; it clears and repopulates both indexes and should\nnot be scheduled as a cron command.</p>\n<p><strong>External users</strong></p>\n<pre><code class=\"language-bash\">occ social:external list                                        # who, and how many of how many\nOC_PASS=... occ social:external add &lt;handle&gt; --email EMAIL --password-from-env\nocc social:external promote &lt;handle&gt;                            # make one an ordinary account\n</code></pre>\n<p><strong>Delivery is behind</strong></p>\n<pre><code class=\"language-bash\">occ social:queue:process            # drain it now instead of waiting for cron\nocc social:queue:retry              # give failing deliveries the full run of retries again\n</code></pre>\n<p><strong>Moderation</strong></p>\n<pre><code class=\"language-bash\">occ social:fediverse list                  # the access list; bare, it prints the mode\nocc social:fediverse add &lt;instance&gt;        # block it (or allow it, in allow-list mode)\nocc social:fediverse remove &lt;instance&gt;\nocc social:fediverse import &lt;csv_file&gt;     # add reviewed CSV domains to a block list\nocc social:fediverse import &lt;csv_file&gt; --dry-run   # print what it would add, change nothing\nocc social:fediverse silence &lt;instance&gt;    # out of the public timelines, still followable\n</code></pre>\n<p><code>import</code> reads the first CSV column, accepts a <code>#domain</code>/<code>domain</code> header or a\nplain one-domain-per-line file, validates the complete file before changing\nanything, and adds the domains to the existing <code>all_but</code> block list. It refuses\nallow-list mode, does not fetch or enable a list on its own, and applies the\nnormal audit and queued domain-purge behavior to every new entry.</p>\n<p>The same import is on the admin page under <strong>Block lists</strong>, with a file picker\nand a preview: it reads the file, says how many servers it would block and how\nmany it would silence, and changes nothing until the button under that number\nis pressed. The page and the command run the same code, so a list imported one\nway cannot turn out to have been read differently the other.</p>\n<p><strong>Following a published list.</strong> The same section offers two sources, both off\nuntil an administrator turns one on:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Source</th>\n<th>What it is</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>mastodon.social</code></td>\n<td>that server&#39;s own moderated-servers list, through Mastodon&#39;s <code>/api/v1/instance/domain_blocks</code></td>\n</tr>\n<tr>\n<td><code>thebad.space</code></td>\n<td>a shared list rather than one server&#39;s, as a CSV export by how many of its participating servers agree. The default is <code>/80</code>: what eighty per cent of them block</td>\n</tr>\n</tbody></table></div>\n<p>A Mastodon server answers <code>/api/v1/instance/domain_blocks</code> only where its\nadministrators turned publishing on, and most have not — which is why one such\nserver is offered rather than a row of them. Point either source at another\nserver&#39;s endpoint to follow that one instead; a server that does not publish\nanswers &quot;that server did not hand over a list&quot; rather than failing.</p>\n<p>A followed source is re-read once a day by <code>OCA\\Social\\Cron\\BlocklistSync</code>.\n<strong>Check now</strong> reads one immediately; for a source that is off it reports what\nfollowing it <em>would</em> do, which is how to read a list before adopting it.</p>\n<p>Turning a source off stops it being re-read. It does not undo what it already\napplied: a block purges what this instance held of that server, and that does\nnot come back.</p>\n<p><strong>Severity is honoured.</strong> A row marked <code>suspend</code> blocks the server; a row\nmarked <code>silence</code> silences it — out of the public, global and hashtag timelines,\nstill followable — and a row marked <code>noop</code> does nothing. Reading the column and\nblocking everything would delete what this instance holds of servers the source\nmerely limits: of mastodon.social&#39;s 276 entries, 30 are silences, and of The\nBad Space&#39;s 200 at the 80% threshold, 2 are. A list with no severity column is\na list of blocks, which is what a bare one-domain-per-line file has always\nmeant here.</p>\n<p>Every entry added queues a domain purge, which deletes what this instance holds\nof that server, so the import asks before it writes — <code>--no-interaction</code> skips\nthe question, and <code>--dry-run</code> prints the domains and changes nothing. A row\nnaming a single label (<code>com</code>, <code>localhost</code>) is refused, because an entry covers\nevery subdomain of itself and one such row would block a whole top-level\ndomain; so is a row naming this instance. That is not a public-suffix check:\n<code>co.uk</code> still passes, which is what <code>--dry-run</code> is for. Files over 8 MB are\nrefused unread. An\nadministrator can download and review a <a href=\"https://tweaking.thebad.space/exports\">The Bad Space CSV export</a>\nbefore importing it; the export source and moderation policy remain the\nadministrator&#39;s choice.</p>\n<p><strong>Housekeeping</strong></p>\n<pre><code class=\"language-bash\">occ social:stream:prune             # apply retention, purge finished queue rows and old notifications\nocc social:cache:refresh            # re-fetch cached remote accounts\nocc social:domain:purge &lt;instance&gt;  # remove what a now-blocked instance sent\n</code></pre>\n<p><strong>Starting over</strong></p>\n<pre><code class=\"language-bash\">occ social:reset                    # empties every Social table; asks twice\nocc social:reset --uninstall        # and drops the tables, jobs and app config\n</code></pre>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"commands-by-task","manual":false,"prev":{"path":"/docs/admin-system-configuration","title":"System configuration"},"next":{"path":"/docs/admin-running-a-large-instance","title":"Running a large instance"},"parent":null},{"slug":"admin-running-a-large-instance","path":"/docs/admin-running-a-large-instance","title":"Running a large instance","description":"Everything below is optional and nothing on a small instance needs any of it. These are the three things that stop working first as an instance grows, and what to do about each.","group":"admin","html":"<p>Everything below is optional and nothing on a small instance needs any of it.\nThese are the three things that stop working first as an instance grows, and\nwhat to do about each.</p>\n<p><strong>Install <code>notify_push</code>.</strong> Without it every open tab asks the server for the\nhome timeline and the unread count <strong>every thirty seconds</strong>; with it the server\ntells the client instead and the poll drops to once every five minutes — a\ntenfold cut in the request volume, for one app install. The polls also answer\n<code>304</code> now when nothing has changed, so even without it most of them cost an\nindex probe and an empty response rather than a rendered page.</p>\n<p><strong>Run delivery workers.</strong> <code>Cron\\Queue</code> delivers twenty servers at a time and\ntakes batch after batch for its 240 seconds: with peers that answer within a\nsecond that is up to 6,000 deliveries a run, some 30,000 an hour, and when every\nbatch runs into a dead peer&#39;s 30-second timeout still about 160 a run. A peer\nthat fails is left alone — from a minute, doubling to an hour — and that is\nkept in the database (<code>social_host_breaker</code>), so it holds without a memcache and\nacross runs: a dead server costs one timeout per wait, not one per row. An\ninstance whose accounts are followed across tens of thousands of servers still\noutgrows that with a popular post, and <code>occ social:worker</code> is the same delivery\nin a loop that does not stop; <strong>several may run at once</strong>, see\n<a href=\"/docs/occ\">OCC-Commands.md</a> for a systemd unit. The worker still delivers\none row at a time, so it is more processes, not wider ones, that add capacity.</p>\n<p><strong>Watch the cron actually finish.</strong> The steps are budgeted at 300 seconds a pass\nand resume where they stopped, so a pass that runs out of time is normal. A pass\nthat <em>never</em> reaches the later steps is not: <code>social:check</code> and the Aloha log\nare where that shows.</p>\n<p><strong>Cached remote accounts</strong> are refreshed by <code>Cron\\Cache</code> for up to 90 seconds\na pass, and their details (counts, pinned posts, verified links) for up to 90\nmore, batch after batch of fifty, the longest-waiting first. A refresh is one\nfetch, so at a third of a second to a second each that is 90 to 300 accounts a\npass, 11,000 to 36,000 a day — enough for the ten-day refresh cycle to hold\nover roughly 110,000 to 360,000 cached accounts, where one batch of fifty a\npass held to about 60,000. A details refresh is three or more fetches, so it\ncovers fewer, 30 to 90 a pass. Past those sizes the cycle stretches and the\nstalest still go first; a key that rotated in between is fetched again the\nfirst time a signature fails to verify.</p>\n<p><strong>Plan the upgrade window on a large instance.</strong> Three upgrade steps rewrite\n<code>social_stream</code> row by row, and they run inside <code>occ upgrade</code>, while the server\nis in maintenance mode — there is no way to defer them:</p>\n<ul>\n<li><code>Version1000Date20260917000001</code> copies each post&#39;s sort key onto every one of\nits recipient rows in <code>social_stream_dest</code>;</li>\n<li><code>Version1000Date20260917000003</code> reads every post&#39;s attachments to record what\nkind of media it carries;</li>\n<li><code>Version1000Date20260917000005</code> reads every post&#39;s content to record whether\nit is a news item.</li>\n</ul>\n<p>Each walks the table 5,000 posts to a statement, after a <code>COUNT(*)</code> over it, and\nprints its progress every 50,000. The time is proportional to the number of\nposts — for the first step to the number of recipient rows, which is several per\npost — and to how fast the database rewrites rows; none of it has been measured\non a large instance, so time it on a copy of the database first. As a rough\nrule of thumb rather than a measurement, expect minutes per million posts for\neach of the three, and so hours of maintenance mode for ten million. The media\nand news steps only touch rows that still carry no value, so an upgrade\ninterrupted during them picks up where it stopped; the first starts again from\nthe beginning.</p>\n<p>Two settings exist for size and are listed above: <code>search_window_days</code> bounds\nwhat a content search scans when it cannot use its word index, and <code>retention_days</code> bounds what cached remote\nmedia costs. Both trade completeness for a bounded cost, and the default of each\nis the one a medium instance wants.</p>\n<p><code>occ social:benchmark</code> seeds a realistic amount of content and times the\ntimeline queries against it, which is the only honest way to find out what any\nof this costs on the hardware in front of you.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"running-a-large-instance","manual":false,"prev":{"path":"/docs/admin-commands-by-task","title":"Commands by task"},"next":{"path":"/docs/admin-what-to-watch","title":"What to watch"},"parent":null},{"slug":"admin-what-to-watch","path":"/docs/admin-what-to-watch","title":"What to watch","description":"Running an Aloha Social server: the checks before you federate, moderation, external users, configuration and scale.","group":"admin","html":"<ul>\n<li><strong>Administration → Overview.</strong> The setup checks above are there precisely so\nthat an administrator who never opens Aloha Social still hears about it.</li>\n<li><strong>The delivery queue.</strong> A rising count of failing deliveries against one host\nis that instance&#39;s problem; a rising count against all of them is this one&#39;s.</li>\n<li><strong><code>social.log</code> / the Aloha log.</strong> Signature verification failures on\ninbound requests, and <code>could not federate</code> warnings on outbound ones.</li>\n<li><strong>Disk.</strong> Cached remote attachments are the largest thing this app stores.\n<code>retention_days</code> is what bounds them; on an instance that federates widely,\nleaving it at <code>0</code> means keeping every picture anybody here ever scrolled\npast.</li>\n<li><strong>The audit log</strong>, if <code>admin_audit</code> is enabled: every moderation decision,\nwith the moderator who took it.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Admin.md","sections":null,"anchor":"what-to-watch","manual":false,"prev":{"path":"/docs/admin-running-a-large-instance","title":"Running a large instance"},"next":null,"parent":null},{"slug":"occ","path":"/docs/occ","title":"Aloha Social — OCC Commands Reference","description":"All commands are invoked via php occ <command> from the Aloha root directory.","group":"occ","html":"<p>All commands are invoked via <code>php occ &lt;command&gt;</code> from the Aloha root directory.</p>\n<p>This page documents the commands the app registers in\n<code>appinfo/info.xml</code>. Every command extends <code>OCA\\Social\\Command\\SocialCommand</code>,\nthe app&#39;s own base class, which extends Symfony&#39;s <code>Command</code> — nothing here\nreaches into the server&#39;s private <code>core/</code>. That base class declares the generic\n<code>--output plain|json|json_pretty</code> option, so the option exists on all of them,\nbut only <code>social:timeline</code> reads it (see below).</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":[{"path":"/docs/occ-account-management","title":"Account Management","description":"Fails with Unknown user if no such Aloha user exists. On success the command prints nothing.","parent":false},{"path":"/docs/occ-post-note-management","title":"Post / Note Management","description":"--to and --hashtag each accept only one value. In addition, PostService::fixRecipientAndHashtags() scans the content for @mentions and #hashtags and adds those too.","parent":false},{"path":"/docs/occ-timeline-and-stream","title":"Timeline & Stream","description":"The three bounds are taken as the decimal strings they are typed as, so a status id wider than a PHP integer is not rounded; one that is not a decimal integer fails with --<option> must be…","parent":false},{"path":"/docs/occ-queue-management","title":"Queue Management","description":"Why it matters: Cron\\Queue runs every twelve minutes with a 240-second budget for deliveries (and 120 seconds of its own for the inbound queue). It delivers twenty servers at a time and…","parent":false},{"path":"/docs/occ-development","title":"Development","description":"Seeds a plausible amount of content and times the queries behind the timelines, because a query's cost cannot be judged on the couple of dozen rows a development instance holds. For…","parent":false},{"path":"/docs/occ-cache","title":"Cache","description":"Steps and their output lines: local accounts deleted, local accounts regenerated, remote accounts created, remote accounts updated, remote accounts details updated, documents cached…","parent":false},{"path":"/docs/occ-federation","title":"Federation","description":"import accepts a first-column #domain/domain header or a plain one-domain-per-line file. It validates the entire file before mutation, skips duplicates, caps an import at 10,000 unique…","parent":false},{"path":"/docs/occ-external-users","title":"External Users","description":"Self-registered external users: list them, add one without the registration form, or promote one to an ordinary local user.","parent":false},{"path":"/docs/occ-installation-and-maintenance","title":"Installation & Maintenance","description":"Check the integrity of the installation, or regenerate the stream index.","parent":false},{"path":"/docs/occ-exit-codes","title":"Exit Codes","description":"Every command the app adds to occ, grouped by the task it performs.","parent":false},{"path":"/docs/occ-background-jobs","title":"Background Jobs","description":"Every 12 minutes, with a 300-second budget. Same steps as social:cache:refresh (deleted actors, local actor cache, remote actors and their details, documents, hashtags), and additionally…","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/occ-account-management","title":"Account Management"},"parent":null},{"slug":"occ-account-management","path":"/docs/occ-account-management","title":"Account Management","description":"Fails with Unknown user if no such Aloha user exists. On success the command prints nothing.","group":"occ","html":"<h2 id=\"social-account-create\"><code>social:account:create</code></h2>\n<p>Create the Aloha Social actor for an existing Aloha user.</p>\n<pre><code>php occ social:account:create [--handle HANDLE] &lt;userId&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha username of the account</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--handle</code></td>\n<td>required</td>\n<td>Aloha Social handle. If omitted, the <code>userId</code> is used as the handle.</td>\n</tr>\n</tbody></table></div>\n<p>Fails with <code>Unknown user</code> if no such Aloha user exists. On success the command\nprints nothing.</p>\n<hr>\n<h2 id=\"social-account-delete\"><code>social:account:delete</code></h2>\n<p>Delete a local Aloha Social account.</p>\n<pre><code>php occ social:account:delete &lt;account&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>account</code></td>\n<td>Yes</td>\n<td>Local Aloha Social account (the handle / preferred username)</td>\n</tr>\n</tbody></table></div>\n<p>Prints nothing on success.</p>\n<hr>\n<h2 id=\"social-account-following\"><code>social:account:following</code></h2>\n<p>Follow or unfollow an account on behalf of a local user.</p>\n<pre><code>php occ social:account:following [--local] [--unfollow] &lt;userId&gt; &lt;account&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha user performing the action</td>\n</tr>\n<tr>\n<td><code>account</code></td>\n<td>Yes</td>\n<td>Account to follow (e.g. <code>user@example.org</code>)</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--local</code></td>\n<td>none</td>\n<td>Resolve <code>account</code> as a <strong>local</strong> account first, and use its canonical account name</td>\n</tr>\n<tr>\n<td><code>--unfollow</code></td>\n<td>none</td>\n<td>Send an <code>Undo</code>/unfollow instead of a follow</td>\n</tr>\n</tbody></table></div>\n<p>Prints progress lines (<code>Following account...</code>, the resolved local actor id and nid,\nthen the result). This is the only command that returns exit code <code>1</code> on a handled\nfailure; the rest let the exception surface.</p>\n<hr>\n<h2 id=\"social-account-alias\"><code>social:account:alias</code></h2>\n<p>Since 0.20.6 an account&#39;s own aliases are also settable by its owner, in <strong>Settings → Migration → Accounts you also answer to</strong> (<code>/api/v1/migration/aliases</code>) — setting one federates nothing. This command stays for an administrator acting on somebody else&#39;s account, and for scripting a migration.</p>\n<p>Manage the <code>alsoKnownAs</code> list of a local account: the actor ids it also answers\nto. Setting one is the first step of moving an account <strong>to</strong> this server — a\nMastodon (or other) server refuses to start a Move towards an account that does\nnot list the moving one here.</p>\n<pre><code>php occ social:account:alias [--add URL] [--remove URL] [--list] &lt;userId&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha user whose actor is aliased</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--add</code></td>\n<td>required</td>\n<td>The old account, as its <code>alice@mastodon.example</code> handle (resolved through WebFinger) or its <code>https://mastodon.example/users/alice</code> actor id; the id is what is stored. Adding one that is already listed changes nothing.</td>\n</tr>\n<tr>\n<td><code>--remove</code></td>\n<td>required</td>\n<td>Actor id to remove. Removing one that is not listed changes nothing.</td>\n</tr>\n<tr>\n<td><code>--list</code></td>\n<td>none</td>\n<td>Print the current list. This is also what happens with no option at all.</td>\n</tr>\n</tbody></table></div>\n<p><code>--add</code> and <code>--remove</code> cannot be combined in one run. Every change refreshes the\nactor cache, so the new list is on the actor document at once; the remote server\nreads it when the Move is started there.</p>\n<p>Prints <code>added &lt;url&gt;</code> / <code>removed &lt;url&gt;</code> followed by the list, or <code>no alias set.</code>.\nExit code <code>1</code> when <code>userId</code> has no actor or the value is not an <code>http(s)://</code> URL.</p>\n<hr>\n<h2 id=\"social-account-move\"><code>social:account:move</code></h2>\n<p>Move a local account to one on another server, the way Mastodon&#39;s account\nmigration works: the new account has to list this one in its <code>alsoKnownAs</code>, every\nfollower is sent a <code>Move</code>, and the account here is marked as moved.</p>\n<p>Since 0.26.113 a person can do this themselves, in <strong>Settings → Migration → Move\nyour account away</strong> (<code>POST /api/v1/migration/move</code>), behind their password, their\nown handle typed back and a thirty-day cooldown between moves. This command stays\nfor an administrator acting on somebody else&#39;s account, and it <strong>skips the\ncooldown</strong>. Undoing a move (clearing <code>movedTo</code>) is on the same page.</p>\n<pre><code>php occ social:account:move [-f|--force] &lt;userId&gt; &lt;target&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha user whose actor moves away</td>\n</tr>\n<tr>\n<td><code>target</code></td>\n<td>Yes</td>\n<td>The new account, as <code>@you@new.example</code> or its <code>https://…</code> actor id</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Do not ask for confirmation (required with <code>--no-interaction</code>)</td>\n</tr>\n</tbody></table></div>\n<p>What happens, in order:</p>\n<ol>\n<li>The target is fetched fresh from its server (not read from the cache) and\nmust list this account&#39;s actor id in <code>alsoKnownAs</code> — the same check\n<code>MoveInterface</code> applies to an incoming Move. Without it the command stops\nwith exit code <code>1</code> and nothing changes; add the alias on the new account\nfirst (in Mastodon: <em>Preferences → Account → Moving from a different\naccount</em>).</li>\n<li>A <code>Move{actor, object: this actor, target}</code> is signed and queued through the\nordinary delivery queue to every follower&#39;s inbox and to the new account&#39;s\ninbox. Servers that support migration re-follow the target for their users\nand drop the follow of the old account.</li>\n<li><code>movedTo</code> is recorded on the actor: it appears on the actor document and as\n<code>moved</code> on the account entity, so clients show the &quot;has moved&quot; banner.</li>\n<li>Followers <strong>on this server</strong> never receive the Move (deliveries to ourselves\nare dropped), so the command follows the new account on their behalf through\nthe ordinary follow path. One follower that cannot be re-followed is logged\nand does not stop the others.</li>\n</ol>\n<p>The command asks for confirmation first; under <code>--no-interaction</code> it refuses\nunless <code>--force</code> is given, rather than moving an account because nobody was\nthere to say no. Posts stay where they are — like Mastodon, a move carries the\nfollowers, not the content.</p>\n<hr>\n<h2 id=\"social-account-import-posts\"><code>social:account:import-posts</code></h2>\n<p>Bring an account&#39;s own posts over from the server it wrote them on, with their\npictures: the same importer the Migration page uses, for the archives a browser\ncannot upload.</p>\n<pre><code>php occ social:account:import-posts [--no-media] [--limit LIMIT] &lt;userId&gt; &lt;archive&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha user whose account the posts are written as</td>\n</tr>\n<tr>\n<td><code>archive</code></td>\n<td>Yes</td>\n<td>Path to the export: a zip with an <code>outbox.json</code> (this app&#39;s, under <code>social/</code>; Mastodon&#39;s and GoToSocial&#39;s, at the root), an <strong>Instagram</strong> archive (the JSON one — <code>content/posts_*.json</code> and the reels beside them, with the pictures under <code>media/</code>), or a JSON export on its own — an <code>outbox.json</code>, or Pixelfed&#39;s <code>pixelfed-statuses.json</code></td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--no-media</code></td>\n<td>none</td>\n<td>Do not fetch the pictures an export names only by their address. The ones inside the archive are still restored</td>\n</tr>\n<tr>\n<td><code>--limit</code></td>\n<td>number</td>\n<td>How many posts to write at most (default and ceiling 2000). The command says when it stopped there; run it again to carry on</td>\n</tr>\n</tbody></table></div>\n<p>Each post is written as a <strong>new local post</strong> of that account, dated when it was\nwritten. <strong>Nothing is federated</strong> — not one delivery is queued — because\nre-publishing somebody&#39;s years of posts would put them into the timeline of\nevery person who follows them, on every server, at once. The original id is\nremembered in <code>social_import_post</code>, so running the command twice over the same\narchive writes nothing the second time, and a reply keeps its parent where the\narchive holds both. Deleting an imported post forgets it as well, so a later\nrun of the same archive brings that post over again.</p>\n<p>What is left alone: boosts (somebody else&#39;s post), direct messages (addressed\nto accounts on the old server, so a copy here would be addressed to nobody),\nand items with neither words nor pictures. Every file goes through the same\nupload path a post&#39;s own attachment does, so an imported picture is stripped of\nits metadata and held to the sizes and types this instance accepts.</p>\n<p>A picture named only by an address is fetched from the server it is still on,\nwhich means that server learns the import is happening and that it has to be\nrunning. <code>--no-media</code> is the way to import the words without either.</p>\n<h2 id=\"social-account-import-follows\"><code>social:account:import-follows</code></h2>\n<p>Follow every account of a follows export — Mastodon&#39;s <code>following_accounts.csv</code>\nor Pixelfed&#39;s <code>pixelfed-following.json</code> — from a local account: the other half\nof moving an account <strong>to</strong> this server.</p>\n<pre><code>php occ social:account:import-follows &lt;userId&gt; &lt;csv&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha user whose actor follows the accounts</td>\n</tr>\n<tr>\n<td><code>csv</code></td>\n<td>Yes</td>\n<td>Path to the export. The current Mastodon format with the header <code>Account address,Show boosts,Notify on new posts,Languages</code> is read by its <code>Account address</code> column wherever it is; the older format — one handle per line, no header — works too. A file that parses as JSON is read as Pixelfed&#39;s export: an array of actor URLs (or handles, or objects naming one), each URL fetched and followed as the actor it resolves to.</td>\n</tr>\n</tbody></table></div>\n<p>Each entry goes through the same path as <code>social:account:following</code>: the\naccount is resolved (WebFinger for a handle, an actor fetch for a URL), a\n<code>Follow</code> is queued, and an account already followed is left alone. A leading\n<code>@</code> is dropped, repeats are followed once, and an entry that is neither a\n<code>user@host</code> handle nor an actor URL is ignored. The other columns (boosts,\nnotifications, languages) are not imported.</p>\n<p>One handle that fails — an unreachable instance, an account that no longer\nexists — is reported and does not stop the rest. The command prints how many\nwere followed, how many were skipped (the importing account&#39;s own handle) and\nhow many failed, each with its reason. Exit code <code>1</code> when the file cannot be\nread, or when something was asked for and none of it could be followed.</p>\n<hr>\n","toc":[{"id":"social-account-create","text":"social:account:create","level":2},{"id":"social-account-delete","text":"social:account:delete","level":2},{"id":"social-account-following","text":"social:account:following","level":2},{"id":"social-account-alias","text":"social:account:alias","level":2},{"id":"social-account-move","text":"social:account:move","level":2},{"id":"social-account-import-posts","text":"social:account:import-posts","level":2},{"id":"social-account-import-follows","text":"social:account:import-follows","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"account-management","manual":false,"prev":{"path":"/docs/occ","title":"Aloha Social — OCC Commands Reference"},"next":{"path":"/docs/occ-post-note-management","title":"Post / Note Management"},"parent":null},{"slug":"occ-post-note-management","path":"/docs/occ-post-note-management","title":"Post / Note Management","description":"--to and --hashtag each accept only one value. In addition, PostService::fixRecipientAndHashtags() scans the content for @mentions and #hashtags and adds those too.","group":"occ","html":"<h2 id=\"social-note-create\"><code>social:note:create</code></h2>\n<p>Create a note (post) as a given user and federate it.</p>\n<pre><code>php occ social:note:create [-r|--replyTo REPLYTO] [-t|--to TO] [-y|--type TYPE] [-g|--hashtag HASHTAG] &lt;user_id&gt; &lt;content&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>user_id</code></td>\n<td>Yes</td>\n<td>Aloha user ID of the author</td>\n</tr>\n<tr>\n<td><code>content</code></td>\n<td>Yes</td>\n<td>Content of the post</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-r</code>, <code>--replyTo</code></td>\n<td>optional</td>\n<td>Id of the post this one replies to</td>\n</tr>\n<tr>\n<td><code>-t</code>, <code>--to</code></td>\n<td>optional</td>\n<td>A single mentioned account</td>\n</tr>\n<tr>\n<td><code>-y</code>, <code>--type</code></td>\n<td>optional</td>\n<td>Visibility: <code>public</code>, <code>unlisted</code>, <code>followers</code> (Mastodon&#39;s <code>private</code> is accepted as a synonym) or <code>direct</code>. Anything else — including omitting the option — becomes <strong><code>direct</code></strong>, the most restrictive option, because <code>Post::setType()</code> maps a value it does not know through <code>Stream::visibilityFromClient()</code>. Note the option&#39;s own <code>--help</code> text still says &quot;public (default)&quot;, which is not what happens.</td>\n</tr>\n<tr>\n<td><code>-g</code>, <code>--hashtag</code></td>\n<td>optional</td>\n<td>A single hashtag, without the leading <code>#</code></td>\n</tr>\n</tbody></table></div>\n<p><code>--to</code> and <code>--hashtag</code> each accept only one value. In addition,\n<code>PostService::fixRecipientAndHashtags()</code> scans the\ncontent for <code>@mentions</code> and <code>#hashtags</code> and adds those too.</p>\n<p>Prints the resulting activity as pretty JSON followed by <code>token: &lt;request token&gt;</code>\n(written with <code>echo</code>, so <code>--output json</code> does not change it).</p>\n<hr>\n<h2 id=\"social-note-boost\"><code>social:note:boost</code></h2>\n<p>Boost (<code>Announce</code>) a note, or undo a boost.</p>\n<pre><code>php occ social:note:boost [--unboost] &lt;user_id&gt; &lt;note_id&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>user_id</code></td>\n<td>Yes</td>\n<td>Aloha user ID boosting the note</td>\n</tr>\n<tr>\n<td><code>note_id</code></td>\n<td>Yes</td>\n<td>Id of the note</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--unboost</code></td>\n<td>none</td>\n<td>Undo the boost instead of creating one</td>\n</tr>\n</tbody></table></div>\n<p>Prints the activity as pretty JSON plus <code>token: &lt;request token&gt;</code>.</p>\n<hr>\n<h2 id=\"social-note-like\"><code>social:note:like</code></h2>\n<p>Like a note, or undo a like.</p>\n<pre><code>php occ social:note:like [--unlike] &lt;user_id&gt; &lt;note_id&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>user_id</code></td>\n<td>Yes</td>\n<td>Aloha user ID liking the note</td>\n</tr>\n<tr>\n<td><code>note_id</code></td>\n<td>Yes</td>\n<td>Id of the note</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--unlike</code></td>\n<td>none</td>\n<td>Undo the like instead of creating one</td>\n</tr>\n</tbody></table></div>\n<p>Prints the activity as pretty JSON plus <code>token: &lt;request token&gt;</code>.</p>\n<hr>\n","toc":[{"id":"social-note-create","text":"social:note:create","level":2},{"id":"social-note-boost","text":"social:note:boost","level":2},{"id":"social-note-like","text":"social:note:like","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"post-note-management","manual":false,"prev":{"path":"/docs/occ-account-management","title":"Account Management"},"next":{"path":"/docs/occ-timeline-and-stream","title":"Timeline & Stream"},"parent":null},{"slug":"occ-timeline-and-stream","path":"/docs/occ-timeline-and-stream","title":"Timeline & Stream","description":"The three bounds are taken as the decimal strings they are typed as, so a status id wider than a PHP integer is not rounded; one that is not a decimal integer fails with --<option> must be…","group":"occ","html":"<h2 id=\"social-timeline\"><code>social:timeline</code></h2>\n<p>Print a timeline as seen by a given local viewer.</p>\n<pre><code>php occ social:timeline [--local] [--min_id MIN] [--max_id MAX] [--since SINCE] [--limit N] [--account ACCOUNT] [--crop N] &lt;userId&gt; &lt;timeline&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>userId</code></td>\n<td>Yes</td>\n<td>Aloha user whose view is used. Fails with <code>Unknown user</code> if unknown.</td>\n</tr>\n<tr>\n<td><code>timeline</code></td>\n<td>Yes</td>\n<td>See the table of supported values below</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Default</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--local</code></td>\n<td>none</td>\n<td>off</td>\n<td>Restrict to local content</td>\n</tr>\n<tr>\n<td><code>--min_id</code></td>\n<td>required</td>\n<td><code>0</code></td>\n<td>Pagination bound: a status id (<code>nid</code>); rows newer than it</td>\n</tr>\n<tr>\n<td><code>--max_id</code></td>\n<td>required</td>\n<td><code>0</code></td>\n<td>Pagination bound: a status id (<code>nid</code>); rows older than it</td>\n</tr>\n<tr>\n<td><code>--since</code></td>\n<td>required</td>\n<td><code>0</code></td>\n<td>Pagination bound: a status id (<code>nid</code>); rows newer than it</td>\n</tr>\n<tr>\n<td><code>--limit</code></td>\n<td>required</td>\n<td><code>5</code></td>\n<td>Number of items</td>\n</tr>\n<tr>\n<td><code>--account</code></td>\n<td>required</td>\n<td><code>&#39;&#39;</code></td>\n<td>A <strong>local</strong> account, resolved with <code>CacheActorService::getFromLocalAccount()</code>; used as the account filter</td>\n</tr>\n<tr>\n<td><code>--crop</code></td>\n<td>required</td>\n<td><code>0</code></td>\n<td>Truncate the printed content to N characters (<code>0</code> = no cropping)</td>\n</tr>\n</tbody></table></div>\n<p>The three bounds are taken as the decimal strings they are typed as, so a status id wider than a PHP integer is not rounded; one that is not a decimal integer fails with <code>--&lt;option&gt; must be a status id</code>.</p>\n<p>Supported <code>timeline</code> values (the <code>switch</code> in <code>StreamRequest::getTimeline()</code>):</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Value</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>home</code></td>\n<td>Own posts plus posts of followed accounts</td>\n</tr>\n<tr>\n<td><code>public</code></td>\n<td>Public timeline</td>\n</tr>\n<tr>\n<td><code>direct</code></td>\n<td>Direct messages</td>\n</tr>\n<tr>\n<td><code>account</code></td>\n<td>Posts of one account (combine with <code>--account</code>)</td>\n</tr>\n<tr>\n<td><code>favourites</code></td>\n<td>Liked posts</td>\n</tr>\n<tr>\n<td><code>bookmarks</code></td>\n<td>Posts the viewer bookmarked</td>\n</tr>\n<tr>\n<td><code>notifications</code></td>\n<td>Notifications (rendered in the notification format)</td>\n</tr>\n<tr>\n<td><code>#&lt;tag&gt;</code></td>\n<td>A leading <code>#</code> selects the hashtag timeline for <code>&lt;tag&gt;</code></td>\n</tr>\n</tbody></table></div>\n<p>Matching is case-insensitive. <code>ProbeOptions</code> also defines <code>followers</code> and\n<code>following</code>, but <code>getTimeline()</code> has no case for them and silently returns an\nempty list. Any other value behaves the same way.</p>\n<p>Output is a table (<code>Nid</code>, <code>Id</code>, <code>Source</code>, <code>Type</code>, <code>Author</code>, <code>Content</code>).\n<code>--output json</code> switches this command to a JSON dump of the streams.</p>\n<hr>\n<h2 id=\"social-details\"><code>social:details</code></h2>\n<p>Print who can see one stream item and which timelines it lands on.</p>\n<pre><code>php occ social:details [--json] &lt;streamId&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>streamId</code></td>\n<td>Yes</td>\n<td>Id of the stream item. Fails with <code>Unknown item</code> if it does not exist.</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--json</code></td>\n<td>none</td>\n<td>Dump the details object as pretty JSON</td>\n</tr>\n</tbody></table></div>\n<p>Without <code>--json</code> it prints the item id, author and type, then <code>Affected Timelines</code>\nwith the <code>Home</code> viewers, the <code>Direct</code> viewers, and the <code>Public</code> / <code>Federated</code> flags.\nThis command uses its own <code>--json</code> flag; the inherited <code>--output</code> option is ignored.</p>\n<p>Note the command name is <code>social:details</code>, not <code>social:stream:details</code>, even though\nthe class is <code>OCA\\Social\\Command\\StreamDetails</code>.</p>\n<hr>\n<h2 id=\"social-stream-prune\"><code>social:stream:prune</code></h2>\n<p>Deletes remote statuses older than the retention period, together with their\nrecipient/action/tag rows and cached attachments.</p>\n<pre><code class=\"language-bash\">php occ social:stream:prune [-d|--days DAYS] [--dry-run]\n</code></pre>\n<ul>\n<li>Without <code>--days</code>, the <code>retention_days</code> app setting decides the period; <code>0</code>\n(the default) disables status retention and no status is touched.</li>\n<li>Two sweeps run on every call whatever <code>retention_days</code> says: the queue rows\nnothing will act on again (exhausted deliveries, finished cache items) are\npurged, and in-app notification rows older than <code>notification_retention_days</code>\n(default 90; <code>0</code> keeps them) are deleted. The notification count is printed\non its own line.</li>\n<li><code>--dry-run</code> only counts what would be deleted, including the notifications.</li>\n<li>A status is kept when a local user liked, boosted, replied to or bookmarked\nit, when a local user follows its author, when a local status replies to it\nor boosts it, or when it is a direct message. Local content is never touched.</li>\n<li>The same pruning runs from the <code>Cron\\Cache</code> background job (bounded to 5000\nstatuses per run) whenever <code>retention_days</code> is greater than 0; the admin can\nchange the period in the Aloha Social section of the administration settings.</li>\n</ul>\n<hr>\n","toc":[{"id":"social-timeline","text":"social:timeline","level":2},{"id":"social-details","text":"social:details","level":2},{"id":"social-stream-prune","text":"social:stream:prune","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"timeline-and-stream","manual":false,"prev":{"path":"/docs/occ-post-note-management","title":"Post / Note Management"},"next":{"path":"/docs/occ-queue-management","title":"Queue Management"},"parent":null},{"slug":"occ-queue-management","path":"/docs/occ-queue-management","title":"Queue Management","description":"Why it matters: Cron\\Queue runs every twelve minutes with a 240-second budget for deliveries (and 120 seconds of its own for the inbound queue). It delivers twenty servers at a time and…","group":"occ","html":"<h2 id=\"social-worker\"><code>social:worker</code></h2>\n<p>Drain the queues continuously, instead of once every twelve minutes.</p>\n<pre><code>php occ social:worker [--once] [--max-seconds SECONDS] [--quiet-log]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--once</code></td>\n<td>none</td>\n<td>Drain what is queued now and return, instead of waiting for more — what a cron entry wants</td>\n</tr>\n<tr>\n<td><code>--max-seconds</code></td>\n<td>int (0)</td>\n<td>Stop after this long, so a supervisor can restart it; <code>0</code> runs until stopped</td>\n</tr>\n<tr>\n<td><code>--quiet-log</code></td>\n<td>none</td>\n<td>Do not print a line per batch</td>\n</tr>\n</tbody></table></div>\n<p><strong>Why it matters:</strong> <code>Cron\\Queue</code> runs every twelve minutes with a 240-second\nbudget for deliveries (and 120 seconds of its own for the inbound queue). It\ndelivers twenty servers at a time and takes batch after batch of 200 while time\nis left — up to 6,000 deliveries a run when peers answer within a second, and\nabout 160 when every batch runs into a dead peer&#39;s 30-second timeout — and Aloha runs one <code>cron.php</code> at a time, so that is its ceiling.\nAn instance whose accounts are followed across tens of thousands of servers\nreaches it with one popular post.</p>\n<p>This is the same delivery in a loop that does not stop, one row at a time. A healthy peer answers in\na fraction of a second, so one worker moves thousands of rows an hour rather than\na thousand a day — and because claiming a row is already atomic (an\n<code>UPDATE … WHERE status = standby</code> that throws when it loses the race),\n<strong>several workers may run at once</strong> and will not collide. Run as many as the\ninstance needs, under systemd:</p>\n<pre><code class=\"language-ini\">[Unit]\nDescription=Aloha Social delivery worker %i\nAfter=network.target\n\n[Service]\nUser=www-data\nExecStart=/usr/bin/php /var/www/html/occ social:worker --max-seconds=3600 --quiet-log\nRestart=always\nRestartSec=5\n\n[Install]\nWantedBy=multi-user.target\n</code></pre>\n<p><code>systemctl enable --now social-worker@{1..4}</code> for four of them. It finishes the\nrow in hand on <code>SIGTERM</code> rather than abandoning a delivery the receiving server\nmay already have taken, sleeps (with a growing wait) when there is nothing to do,\nand hands rows back to standby when an attempt fails outside the delivery\nservice&#39;s own error handling — without that a killed worker leaves a row\n<code>running</code>, which nothing retries until the stale reaper an hour later.</p>\n<p><strong>The cron job is unchanged.</strong> An instance that will not run a daemon keeps\nexactly the behaviour it has; one that will gets the throughput.</p>\n<hr>\n<h2 id=\"social-atproto-serve\"><code>social:atproto:serve</code></h2>\n<p>Serve the Bluesky firehose: the WebSocket a relay subscribes to.</p>\n<pre><code>php occ social:atproto:serve [--bind ADDRESS:PORT] [--max-seconds SECONDS] [--once]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--bind</code></td>\n<td>string (127.0.0.1:8787)</td>\n<td>Where to listen; the web server proxies <code>/xrpc/com.atproto.sync.subscribeRepos</code> here with the WebSocket upgrade</td>\n</tr>\n<tr>\n<td><code>--max-seconds</code></td>\n<td>int (0)</td>\n<td>Stop after this long, so a supervisor can restart it; <code>0</code> runs until stopped</td>\n</tr>\n<tr>\n<td><code>--once</code></td>\n<td>none</td>\n<td>Serve what is queued now to whoever is connected and return — what a test wants</td>\n</tr>\n</tbody></table></div>\n<p><strong>Why it matters:</strong> a PDS is only a PDS while something serves its event stream. The\nweb requests append frames to <code>social_atproto_event</code>; this process reads them in\norder and hands each to every connected relay, replaying from the cursor a relay\nreconnects with out of the 72-hour window the table keeps. Run it under systemd\n(see <a href=\"/docs/admin-bluesky#bluesky\">Admin.md</a>); the setup checks say when it is not running.</p>\n<h2 id=\"social-atproto-identities\"><code>social:atproto:identities</code></h2>\n<p>Give every local account its Bluesky identity now, rather than on first need.</p>\n<pre><code>php occ social:atproto:identities [--user USER] [--list]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--user</code></td>\n<td>string</td>\n<td>Only this Aloha user</td>\n</tr>\n<tr>\n<td><code>--list</code></td>\n<td>none</td>\n<td>List the identities there are instead of making any</td>\n</tr>\n</tbody></table></div>\n<p>An identity is a <code>did:plc</code> registered with the PLC directory, a handle\n<code>alice.&lt;host&gt;</code> and a signing key, and the profile record is written with it. An\naccount that already has one is left alone, so the command is safe to run\nagain; a registration the directory refused is logged and resent by the\nmaintenance job and by <code>social:atproto:plc --repair</code>.</p>\n<h2 id=\"social-atproto-plc\"><code>social:atproto:plc</code></h2>\n<p>This app&#39;s log of PLC directory operations beside what the directory holds, or\nthe resend of what never got through.</p>\n<pre><code>php occ social:atproto:plc [DID] [--repair]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>did</code></td>\n<td>No</td>\n<td>The DID or handle to show; none with <code>--repair</code></td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--repair</code></td>\n<td>none</td>\n<td>Send every operation the directory never confirmed again</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"social-atproto-resolve\"><code>social:atproto:resolve</code></h2>\n<p>What a handle or DID is: the local identity, and the DID document the directory\nserves.</p>\n<pre><code>php occ social:atproto:resolve IDENTIFIER\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>identifier</code></td>\n<td>Yes</td>\n<td>A handle (<code>alice.social.example.com</code>) or a <code>did:plc</code></td>\n</tr>\n</tbody></table></div>\n<p>Exits 1 when neither this instance nor the directory knows it.</p>\n<h2 id=\"social-atproto-repo\"><code>social:atproto:repo</code></h2>\n<p>A user&#39;s Bluesky repository: its head commit, what it holds, and whether it\nchecks out.</p>\n<pre><code>php occ social:atproto:repo USER [--verify]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>user</code></td>\n<td>Yes</td>\n<td>The Aloha user id, the handle or the DID</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--verify</code></td>\n<td>none</td>\n<td>Recompute the Merkle search tree from the records and check the head&#39;s signature; exits 1 when either differs</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"social-atproto-block\"><code>social:atproto:block</code></h2>\n<p>The administrator&#39;s Bluesky block list: an account by its DID, or a PDS host\nand every account on it.</p>\n<pre><code>php occ social:atproto:block [&lt;target&gt;] [--unblock] [--reason=REASON] [--list]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>target</code></td>\n<td>No</td>\n<td>A DID (<code>did:plc:…</code>), or a PDS host (<code>pds.example.com</code>); none lists the blocks</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--unblock</code></td>\n<td>none</td>\n<td>Take the target off the list</td>\n</tr>\n<tr>\n<td><code>--reason</code></td>\n<td>string</td>\n<td>Why, shown in the list</td>\n</tr>\n<tr>\n<td><code>--list</code></td>\n<td>none</td>\n<td>List the blocks (also what no target does)</td>\n</tr>\n</tbody></table></div>\n<p>A blocked account is not resolved, its posts are not read, its follows, likes\nand replies are dropped on arrival, and it does not appear in search. Blocking\none that is followed here purges it as a domain block purges a Fediverse\naccount: its posts, the follows, and the watch. A host blocks every account\nwhose PDS it is, and the hosts under it. The list is never published.</p>\n<h2 id=\"social-atproto-crawl\"><code>social:atproto:crawl</code></h2>\n<p>Ask the configured relays to subscribe to this instance&#39;s firehose now.</p>\n<pre><code>php occ social:atproto:crawl\n</code></pre>\n<p>Sends <code>com.atproto.sync.requestCrawl</code> to every relay in <code>atproto_relays</code>. A relay\nkeeps the subscription from then on; this is for the first time, and for after\nthe daemon was down longer than the replay window.</p>\n<h2 id=\"social-atproto-rotate-key\"><code>social:atproto:rotate-key</code></h2>\n<p>A new instance rotation key, and a PLC update for every identity so the new key\nis the one in charge.</p>\n<pre><code>php occ social:atproto:rotate-key [--force]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--force</code></td>\n<td>none</td>\n<td>Do it without asking</td>\n</tr>\n</tbody></table></div>\n<p>The old key is kept, retired, for the PLC&#39;s 72-hour recovery window and dropped\nby the maintenance job after it. Each identity gets one directory operation,\npaced so the directory&#39;s limits are respected; one the directory does not\nconfirm is resent by the maintenance job.</p>\n<h2 id=\"social-queue-process\"><code>social:queue:process</code></h2>\n<p>Process both queues once: the outbound request queue (federation delivery) and the\nstream queue (caching of not-yet-resolved incoming objects).</p>\n<pre><code>php occ social:queue:process\n</code></pre>\n<p>No arguments or options. Prints how many items are in each queue, how many are\nprocessable right now, and a <code>.</code> per processed item.</p>\n<hr>\n<h2 id=\"social-queue-status\"><code>social:queue:status</code></h2>\n<p>Report the state of the outbound delivery queue, or dump the rows belonging to\none request token.</p>\n<pre><code>php occ social:queue:status [-t|--token TOKEN]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-t</code>, <code>--token</code></td>\n<td>optional</td>\n<td>Token of the request; without it, the whole queue is summarised</td>\n</tr>\n</tbody></table></div>\n<p>With a token, each matching row is printed as one line of JSON.</p>\n<p>Without one, the command prints how many deliveries are waiting and how many are\nbeing sent, how many have already failed at least once and how many are close to\nbeing abandoned (a delivery is dropped after 16 attempts), followed by the worst\ninstances — how many deliveries are stacked up for each, the highest attempt\ncount so far and when it was last tried. The same figures appear in the\nDeliveries section of the administration settings.</p>\n<p>Then the half that matters most: what this instance has <strong>given up on</strong>. An\nabandoned delivery used to appear nowhere — it left the failing count the moment\nit was abandoned, so the queue looked healthiest exactly when a peer had been\nlost for good. The count covers the last seven days, which is how long a\nfinished row is kept, and is followed by the same per-instance table under\n&quot;given up&quot;. <code>occ social:queue:retry --instance HOST</code> puts those deliveries back\nin the queue once the reason they failed has been dealt with.</p>\n<hr>\n<h2 id=\"social-queue-retry\"><code>social:queue:retry</code></h2>\n<p>Put queued deliveries back on standby, or drop them.</p>\n<pre><code>php occ social:queue:retry [-t|--token TOKEN] [--min-tries N] [-i|--instance HOST]\n                           [--limit N] [--stream] [--flush] [-f|--force]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-t</code>, <code>--token</code></td>\n<td>optional</td>\n<td>Act on one delivery only, by the token <code>social:queue:status</code> prints</td>\n</tr>\n<tr>\n<td><code>--min-tries</code></td>\n<td>int (1)</td>\n<td>Without a token, act on the rows that have already failed at least this many times</td>\n</tr>\n<tr>\n<td><code>-i</code>, <code>--instance</code></td>\n<td>hostname</td>\n<td>Act on the deliveries for one host only, including the ones already given up on. Cannot be combined with <code>--stream</code>, which holds what came in rather than what was going out</td>\n</tr>\n<tr>\n<td><code>--limit</code></td>\n<td>int (500)</td>\n<td>How many rows one run touches at most; run it again to work through the rest</td>\n</tr>\n<tr>\n<td><code>--stream</code></td>\n<td>none</td>\n<td>Act on the inbound stream queue (<code>social_stream_queue</code>) instead of the outbound delivery queue</td>\n</tr>\n<tr>\n<td><code>--flush</code></td>\n<td>none</td>\n<td>Delete the matching rows instead of queueing them again</td>\n</tr>\n<tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Do not ask for confirmation (required with <code>--no-interaction</code>)</td>\n</tr>\n</tbody></table></div>\n<p>Retrying clears the attempt count and sets the row back to standby, so it gets the\nfull run of retries again on the next queue cron (or <code>occ social:queue:process</code>)\nrather than being abandoned on its next failure. <code>--flush</code> deletes the rows: those\nactivities are never delivered, which is what you want for a delivery that will\nnever succeed — a peer that is gone, or an activity it refuses.</p>\n<p>Rows that already succeeded are never touched, so a retry cannot send an activity\ntwice. Rows that were <em>abandoned</em> are: they are exactly what this command is for,\nand they are still in the table for seven days after the drain gave up on them.\n<code>--instance</code> is the form that answers <code>social:queue:status</code>, which names the\nhosts this instance has stopped delivering to:</p>\n<pre><code>php occ social:queue:retry --instance gone.example\n</code></pre>\n<p>The host is matched in PHP — it lives inside the JSON <code>instance</code> column — so the\ntable is read in pages of 1000 rows until <code>--limit</code> matching rows are found.</p>\n<p>The command prints how many rows matched, across how many delivery tokens\nand with what spread of attempt counts, and asks before it changes anything.</p>\n<hr>\n","toc":[{"id":"social-worker","text":"social:worker","level":2},{"id":"social-atproto-serve","text":"social:atproto:serve","level":2},{"id":"social-atproto-identities","text":"social:atproto:identities","level":2},{"id":"social-atproto-plc","text":"social:atproto:plc","level":2},{"id":"social-atproto-resolve","text":"social:atproto:resolve","level":2},{"id":"social-atproto-repo","text":"social:atproto:repo","level":2},{"id":"social-atproto-block","text":"social:atproto:block","level":2},{"id":"social-atproto-crawl","text":"social:atproto:crawl","level":2},{"id":"social-atproto-rotate-key","text":"social:atproto:rotate-key","level":2},{"id":"social-queue-process","text":"social:queue:process","level":2},{"id":"social-queue-status","text":"social:queue:status","level":2},{"id":"social-queue-retry","text":"social:queue:retry","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"queue-management","manual":false,"prev":{"path":"/docs/occ-timeline-and-stream","title":"Timeline & Stream"},"next":{"path":"/docs/occ-development","title":"Development"},"parent":null},{"slug":"occ-development","path":"/docs/occ-development","title":"Development","description":"Seeds a plausible amount of content and times the queries behind the timelines, because a query's cost cannot be judged on the couple of dozen rows a development instance holds. For…","group":"occ","html":"<h2 id=\"social-benchmark\"><code>social:benchmark</code></h2>\n<p>Seeds a plausible amount of content and times the queries behind the timelines, because a query&#39;s cost cannot be judged on the couple of dozen rows a development instance holds. <strong>For development instances only</strong> — it writes thousands of rows.</p>\n<pre><code>php occ social:benchmark [--actors=200] [--notes=5000] [--follows=150] [--viewer=USER]\n                         [--seed-only] [--time-only] [--clean] [-f|--force]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--actors</code></td>\n<td>int (200)</td>\n<td>Remote actors to seed</td>\n</tr>\n<tr>\n<td><code>--notes</code></td>\n<td>int (5000)</td>\n<td>Public notes to seed, spread over the preceding weeks</td>\n</tr>\n<tr>\n<td><code>--follows</code></td>\n<td>int (150)</td>\n<td>How many of those actors the viewer follows, which is what the home timeline joins through</td>\n</tr>\n<tr>\n<td><code>--followers</code></td>\n<td>int (0)</td>\n<td>How many of those actors follow the viewer <strong>back</strong>, which is what delivery reads: one queue row per distinct inbox when the viewer posts. An instance seeded without it measures reads and says nothing about writes</td>\n</tr>\n<tr>\n<td><code>--viewer</code></td>\n<td>username</td>\n<td>The local account the timelines are read as; the first local actor by default</td>\n</tr>\n<tr>\n<td><code>--seed-only</code></td>\n<td>none</td>\n<td>Write the rows without timing anything</td>\n</tr>\n<tr>\n<td><code>--time-only</code></td>\n<td>none</td>\n<td>Time what is already seeded</td>\n</tr>\n<tr>\n<td><code>--clean</code></td>\n<td>none</td>\n<td>Delete everything the command wrote and nothing else</td>\n</tr>\n</tbody></table></div>\n<p>Seeding writes <strong>multi-row <code>INSERT</code>s directly</strong>, not through the model layer: a\n<code>Note</code> built and saved one at a time is three statements and a transaction per\nrow, about 400 rows a second, which makes ten million posts a seven-hour wait —\nso nobody ever seeded enough to find out what the queries cost. The rows are\nstill <em>shaped</em> like real ones (the prim hashes, the recipient rows, the follower\ncollections), because a query plan is only worth measuring against rows the\nplanner sees the way it sees real data. The cost is that a column added to\n<code>social_stream</code> later is one this command forgets to write; that is the right\ntrade for a development-only command and would be the wrong one anywhere else.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Job</th>\n<th>Class</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Seed without asking (required with <code>--no-interaction</code>)</td>\n</tr>\n</tbody></table></div>\n<p>Seeding says how many rows it is about to write and asks before writing any of\nthem; under <code>--no-interaction</code> it refuses unless <code>--force</code> is given, rather than\nseeding a production database because nobody was there to say no. <code>--clean</code> and\n<code>--time-only</code> write nothing and do not ask.</p>\n<p>Every row it writes carries <code>benchmark.invalid</code> in its id, which is what <code>--clean</code> matches on. The reported time is the second run of each query, so it measures a served request rather than a cold cache.</p>\n<hr>\n","toc":[{"id":"social-benchmark","text":"social:benchmark","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"development","manual":false,"prev":{"path":"/docs/occ-queue-management","title":"Queue Management"},"next":{"path":"/docs/occ-cache","title":"Cache"},"parent":null},{"slug":"occ-cache","path":"/docs/occ-cache","title":"Cache","description":"Steps and their output lines: local accounts deleted, local accounts regenerated, remote accounts created, remote accounts updated, remote accounts details updated, documents cached…","group":"occ","html":"<h2 id=\"social-cache-refresh\"><code>social:cache:refresh</code></h2>\n<p>Run the cache maintenance steps once, printing a counter per step.</p>\n<pre><code>php occ social:cache:refresh [-f|--force] [--rotate-keys]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Refresh cached remote actors even if they are not due — including the ones whose refresh has been given up on after ten consecutive failures, so this is also how an instance that has come back is asked again straight away. Every attempt is recorded either way, and one that works clears the failure count</td>\n</tr>\n<tr>\n<td><code>--rotate-keys</code></td>\n<td>none</td>\n<td>Renew the RSA key pair of local actors older than <code>AccountService::KEY_PAIR_LIFESPAN</code> (60) days. Blind rotation: no <code>Update</code> is federated, remote servers pick the new key up when they next fetch the actor (most do so after a failed signature check), so expect a short delivery hiccup. Deliberately opt-in and never run by the cron</td>\n</tr>\n</tbody></table></div>\n<p>Steps and their output lines: local accounts deleted, local accounts regenerated,\nremote accounts created, remote accounts updated, remote accounts details updated,\ndocuments cached, hashtags updated. With <code>--rotate-keys</code>, <code>N key pairs refreshed</code>\nis printed first.</p>\n<p>Rotation is the only step that is opt-in, and it is the only way to rotate a key\npair: nothing else calls <code>AccountService::blindKeyRotation()</code>, and the cron never\ndoes.</p>\n<h2 id=\"social-counts-refresh\"><code>social:counts:refresh</code></h2>\n<p>Ask each remote server what the counts of the posts it owns are right now, and\nstore what it says.</p>\n<pre><code>php occ social:counts:refresh [-f|--force] [-l|--limit LIMIT]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Ask about every remote post rather than only those not asked about in the last <code>RemoteCountService::TTL</code> (7200) seconds</td>\n</tr>\n<tr>\n<td><code>-l</code>, <code>--limit</code></td>\n<td>required</td>\n<td>Stop after this many posts. <code>0</code>, the default, means all that are due, which is what a backfill wants</td>\n</tr>\n</tbody></table></div>\n<p>A post&#39;s counts were a snapshot of the moment it was imported and nothing ever\nlooked again, so a status sitting at two likes an hour ago still reads as two.\nThis asks each post&#39;s origin server for the <code>likes</code> and <code>shares</code> totals of its\nown document and replaces the stored figure with what comes back — the answer\nis only taken if the document&#39;s <code>id</code> is the one that was asked for, and a post\nthat answers with nothing keeps the count it had and is asked about again at\nthe next window rather than every pass.</p>\n<p>The stated total is split as <code>stated - local</code> before it is stored, so what is\ndisplayed stays the origin&#39;s number while the likes, boosts and replies made\nhere keep counting on top of it. Without <code>--force</code> only the posts past the\nwindow are asked about; with it the whole timeline is, which is the backfill\nafter a version that never refreshed counts at all.</p>\n<p>Reply counts are the limit of this: ActivityPub documents publish\n<code>replies.totalItems</code> on almost no server, so the reply figure is what this\ninstance holds and not a number the origin supplies.</p>\n<p>The cron (<code>OCA\\Social\\Cron\\Cache</code>) runs the same work on its own schedule for\nat most a minute per pass, <code>RemoteCountService::BATCH</code> posts at a time, so this\ncommand is for the other moments. It prints <code>N post(s) asked, M answered with a count</code>.</p>\n<h2 id=\"social-media-retry\"><code>social:media:retry</code></h2>\n<p>Retry one remote attachment which was previously rejected by the media cache.\nThis is useful after an administrator raises a size limit or the remote origin\nrecovers from a temporary access problem.</p>\n<pre><code>php occ social:media:retry &lt;remote_url&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>remote_url</code></td>\n<td>Yes</td>\n<td>Exact HTTP(S) URL shown in the attachment&#39;s <code>remote_url</code> field</td>\n</tr>\n</tbody></table></div>\n<p>The argument must be the exact HTTP(S) <code>remote_url</code> exposed by Aloha Social. The\ncommand finds the cache row by that media URL and only resets a row with a\nstored media error and no local copy; it does not touch healthy cached files or\nretry every failed attachment at once. It clears the old error and caching\ntimestamp, then fetches that one document immediately through the usual MIME,\nsize, quota, blocklist, and image-decode checks. Exit code 0 means the copy was\nstored. If it is still refused, the command reports failure and the new\nrejection remains recorded for diagnosis.</p>\n<h2 id=\"social-media-recover\"><code>social:media:recover</code></h2>\n<p>Restore missing pictures on remote posts whose saved ActivityPub original still\ncontains attachments. It does not rewrite post text, audience or date.</p>\n<pre><code>php occ social:media:recover [--dry-run] [--limit LIMIT]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--dry-run</code></td>\n<td>none</td>\n<td>List affected posts without downloading or changing anything</td>\n</tr>\n<tr>\n<td><code>--limit</code></td>\n<td>required</td>\n<td>Examine at most this many candidate posts; <code>0</code> (default) examines all</td>\n</tr>\n</tbody></table></div>\n<p>Only remote posts with an empty stored attachment list are candidates. For\neach original attachment, the normal federated media importer validates the\nURL and caches the file, then the command updates the post&#39;s attachment list\nand Photos/Videos index. Posts without usable media remain unchanged and are\nreported; run the command again after fixing a remote or local cache error.</p>\n<h2 id=\"social-media-posters\"><code>social:media:posters</code></h2>\n<p>Make the poster frames of videos that have none, so a client shows a still\ninstead of a black rectangle before anybody presses play.</p>\n<pre><code>php occ social:media:posters [--dry-run] [--limit LIMIT]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--dry-run</code></td>\n<td>none</td>\n<td>Print the videos that have no poster and change nothing</td>\n</tr>\n<tr>\n<td><code>--limit</code></td>\n<td>required</td>\n<td>Stop after this many videos. <code>0</code>, the default, means all of them</td>\n</tr>\n</tbody></table></div>\n<p>A video uploaded here is given a still on its way in. Videos stored before that\nexisted, or while the server had no ffmpeg, have none and would never get one:\nthe frame is taken from the bytes as they are written and they are only written\nonce. This reads them back and takes it now — the same frame, the same JPEG and\nthe same <code>resized_copy</code> an upload gets, with the duration and the dimensions\nwritten into the document&#39;s <code>meta</code> alongside it. <strong>The video itself is not\ntouched</strong>: nothing is transcoded, re-encoded or re-written.</p>\n<p>Exits 1 without doing anything if ffmpeg is not on the server. A video ffmpeg\ncannot read is counted, reported and left alone, so the run finishes and the\nvideo can be tried again after whatever was wrong with it is fixed.</p>\n<p>It is a command rather than a background job on purpose: it is a one-off after\nan upgrade, it spends a subprocess and a temporary copy of each video, and an\ninstance with a large media library should choose when that happens.</p>\n<h2 id=\"social-team\"><code>social:team</code></h2>\n<p>Give an Aloha group an account to post from.</p>\n<pre><code>php occ social:team &lt;group&gt; &lt;username&gt;\nphp occ social:team --list\nphp occ social:team --remove &lt;username&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>group</code></td>\n<td>No</td>\n<td>The Aloha group. Required unless <code>--list</code> or <code>--remove</code> is used</td>\n</tr>\n<tr>\n<td><code>username</code></td>\n<td>No</td>\n<td>The handle the team posts under. Required unless <code>--list</code> or <code>--remove</code> is used</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--list</code></td>\n<td>none</td>\n<td>Show the team accounts there are, group by group</td>\n</tr>\n<tr>\n<td><code>--remove</code></td>\n<td>required</td>\n<td>Stop a handle being a team account. The account itself stays; delete it with <code>social:account:delete</code> if that is what you want</td>\n</tr>\n</tbody></table></div>\n<p><strong>What it is.</strong> Pixelfed&#39;s answer to &quot;several people, one voice&quot; is its\n<code>Group*</code> family: twenty models, still in beta, and a second social graph beside\nthe one it already has. Aloha&#39;s answer is the one it has had all along — a\ngroup of people who already work together — and this gives that group an\naccount. It is the one thing in this comparison Aloha can do and Pixelfed\ncannot, because Pixelfed has no idea who works with whom.</p>\n<p>A team account is <strong>an actor like any other</strong>: a key pair, a followers\ncollection, an inbox and an outbox, followable from Mastodon and Pixelfed,\nmoderatable and suspendable. What is new is only who may speak as it — and that\nis whoever is in the group, asked live every time rather than copied into a list\nthat would drift.</p>\n<p><strong>A command rather than a route, deliberately.</strong> Creating an actor makes an\naddress other servers will follow, cache and keep, which is an administrator&#39;s\ndecision. Posting as one afterwards needs no administrator at all: everybody in\nthe group finds it in the composer.</p>\n<p>Who wrote each post from a team account is recorded and shown to the team and to\nmoderators, and to nobody else — outside the team, one voice is the point of\nhaving a team account; inside it, and in a report, the trail is.</p>\n<p>A group that does not exist, and one that already has an account, are each\nrefused by name.</p>\n<h2 id=\"social-media-transcode\"><code>social:media:transcode</code></h2>\n<p>Convert stored videos to H.264 in an MP4, which is the one format the rest of\nthe network plays.</p>\n<pre><code>php occ social:media:transcode [--limit LIMIT]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--limit</code></td>\n<td>required</td>\n<td>Stop after this many videos. 25 by default</td>\n</tr>\n</tbody></table></div>\n<p><strong>Why it matters:</strong> Pixelfed&#39;s default <code>media_types</code> accepts <code>video/mp4</code> and\nnothing else, so every <code>video/quicktime</code> posted from here — which is every video\nstraight off an iPhone — is dropped by its inbox without a word to anybody.\nSafari will not play WebM either, and only Safari plays the HEVC that phones\nwrite into an <code>.mp4</code>, so an MP4 whose video ffprobe does not report as H.264 is\nconverted too. An H.264 MP4 is never re-encoded; without ffprobe an MP4 is left\nas it is.</p>\n<p>On by default, and nothing happens on a server without ffmpeg. An administrator\ncan switch it off — re-encoding is lossy, and <strong>the converted file replaces the\noriginal</strong> — under <strong>Administration → Aloha Social → Server → Convert videos to MP4\nin the background</strong>, or with <code>occ config:app:set social video_transcode --value=0</code>. The command exits 1 and changes nothing when it is off, or when the\nserver has no ffmpeg.</p>\n<p>A new post does not wait for this command or the sweep: the video it carries is\nconverted by a job of its own at the next cron run, and the post&#39;s delivery is\nheld until then (at most ten minutes). The same work also runs by itself in the\nbackground for everything else, one video every quarter of an hour, which is\nabout a hundred a day — fast enough that a backlog clears and slow enough that a\nserver converting one is never the reason its cron is late. An MP4 found to be\nH.264 costs a copy and a probe rather than a conversion, and a run reads up to\nfive of those. This command is for an administrator who has just installed\nffmpeg and would rather not wait a week. Posts that went out before their video\nwas converted are not sent again.</p>\n<h2 id=\"social-media-ladder\"><code>social:media:ladder</code></h2>\n<p>Write stored videos at a ladder of smaller sizes, as HLS, so a player can pick\nthe one that fits the connection.</p>\n<pre><code>php occ social:media:ladder [--limit LIMIT]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--limit</code></td>\n<td>required</td>\n<td>Stop after this many videos. 10 by default</td>\n</tr>\n</tbody></table></div>\n<p><strong>Why it matters:</strong> a stored video is one file at whatever height it was\nuploaded at, and a reader on a phone on a train downloads the 1080p of it or\nnothing. A ladder is the same video written two or three more times, smaller,\nplus a playlist that lets the player move between them as the connection\nchanges. It is also the shape PeerTube publishes, so a laddered video reaches a\nPeerTube reader the way a native one does.</p>\n<p>Each rung is <strong>one file</strong>: <code>-hls_flags single_file</code> writes the whole rendition\nas a fragmented MP4 and the playlist addresses each segment as a byte range into\nit, so a forty-minute video is three files rather than a thousand. Rungs at or\nabove a video&#39;s own height are skipped rather than upscaled.</p>\n<p>Off unless an administrator turned it on: <strong>Administration → Aloha Social → Server →\nBuild a ladder of video sizes</strong>, or <code>occ config:app:set social video_ladder --value=1</code>. Which heights, with <code>occ config:app:set social video_ladder_heights --value=360,720,1080</code>. The command exits 1 and changes nothing when it is off,\nor when the server has no ffmpeg and ffprobe.</p>\n<p>Slower per video than <code>social:media:transcode</code> by however many rungs the ladder\nhas — worth knowing before starting it on a library of ten thousand. The\nbackground job does one video every half-hour.</p>\n<p>The converted file is written before the row is pointed at it and the original is\ndeleted last, so a failure anywhere leaves a document pointing at a file that\nexists, and the posts carrying the video are pointed at the new file before the\noriginal goes. A video ffmpeg cannot read is recorded as tried and left alone\nrather than retried for ever, and one that is already an H.264 MP4 is passed\nover without being re-encoded into a second generation of loss.</p>\n<h2 id=\"social-media-usage\"><code>social:media:usage</code></h2>\n<p>Report what the app&#39;s media occupies on disk, split into what was uploaded here\nand what was cached off other servers.</p>\n<pre><code>php occ social:media:usage\n</code></pre>\n<p>No options of its own. <code>--output=json</code> (or <code>json_pretty</code>) prints the same\nfigures as a structure, for a monitoring script.</p>\n<p>The two halves are very different things: an upload is the only copy there is,\nand a cached remote file is a copy that can be thrown away and fetched again.\nEach half is broken down into attachments and the avatars and headers of\naccounts. Every row of <code>social_cache_doc</code> is walked and the size of each stored\ncopy — the original and the resized one — is read from appdata, file by file,\nrather than taken from anything the row claims:</p>\n<pre><code>12043 document row(s) in social_cache_doc\n\nUploaded here                   842 files     2.1 GiB\n  attachments                   808 files     2.0 GiB\n  avatars and headers            34 files    41.3 MiB\nCached from other servers     19664 files     8.7 GiB\n  attachments                 15912 files     8.4 GiB\n  avatars and headers          3752 files   311.0 MiB\n\nTotal on disk                 20506 files    10.8 GiB\n</code></pre>\n<p>Three counts are printed after the total when they are not zero: copies that are\n<em>streamed</em> (a pointer at a file on the server that holds it, so no bytes here),\ncopies served from Aloha&#39;s own avatar store rather than by this app, and\ncopies a row names that are <strong>not in appdata</strong> — reported rather than counted as\nzero bytes, because a cached remote one is simply fetched again when it is next\nasked for.</p>\n<p>No quota accounting: this is what is on disk, not what anybody is allowed. It\nalso does not walk appdata looking for files no row names — the path of a copy\nis derived from its own name, so finding an orphan means listing a four-level\ntree with a directory per file, and there is no safe way to delete a file this\napp cannot name.</p>\n<p>The number to read it against is <code>cache_actor_days</code> (default 180), which is how\nlong a cached remote account nobody here refers to survives before the cache\ncron evicts it with its avatar; <code>occ config:app:set social cache_actor_days --value 0</code> turns that sweep off.</p>\n<hr>\n","toc":[{"id":"social-cache-refresh","text":"social:cache:refresh","level":2},{"id":"social-counts-refresh","text":"social:counts:refresh","level":2},{"id":"social-media-retry","text":"social:media:retry","level":2},{"id":"social-media-recover","text":"social:media:recover","level":2},{"id":"social-media-posters","text":"social:media:posters","level":2},{"id":"social-team","text":"social:team","level":2},{"id":"social-media-transcode","text":"social:media:transcode","level":2},{"id":"social-media-ladder","text":"social:media:ladder","level":2},{"id":"social-media-usage","text":"social:media:usage","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"cache","manual":false,"prev":{"path":"/docs/occ-development","title":"Development"},"next":{"path":"/docs/occ-federation","title":"Federation"},"parent":null},{"slug":"occ-federation","path":"/docs/occ-federation","title":"Federation","description":"import accepts a first-column #domain/domain header or a plain one-domain-per-line file. It validates the entire file before mutation, skips duplicates, caps an import at 10,000 unique…","group":"occ","html":"<h2 id=\"social-fediverse\"><code>social:fediverse</code></h2>\n<p>Inspect and change the Fediverse access list.</p>\n<pre><code>php occ social:fediverse [-t|--type TYPE] [--dry-run] [-f|--force] [&lt;action&gt;] [&lt;address&gt;]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Default</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>action</code></td>\n<td>No</td>\n<td><code>&#39;&#39;</code></td>\n<td>One of <code>list</code>, <code>add</code>, <code>remove</code>, <code>import</code>, <code>test</code>, <code>reset</code>, <code>silence</code>, <code>unsilence</code>, <code>silenced</code>, or empty</td>\n</tr>\n<tr>\n<td><code>address</code></td>\n<td>No</td>\n<td><code>&#39;&#39;</code></td>\n<td>Host for single-address actions, or a readable CSV path for <code>import</code></td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-t</code>, <code>--type</code></td>\n<td>required</td>\n<td>Set the access type. Only <code>all_but</code> (deny-list, the default) and <code>none_but</code> (allow-list) are accepted; anything else throws <code>invalid type</code> (<code>FediverseService::setAccessType()</code>).</td>\n</tr>\n<tr>\n<td><code>--dry-run</code></td>\n<td>none</td>\n<td>For <code>import</code>: read and validate the CSV, print the domains it would add, and change nothing.</td>\n</tr>\n<tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>For <code>import</code>: skip the confirmation prompt. Required with <code>--no-interaction</code>; without it a non-interactive run prints <code>Refusing to run non-interactively without --force</code> and returns 1.</td>\n</tr>\n</tbody></table></div>\n<p>Passing <code>--type</code> <strong>sets the type and exits</strong> — the <code>action</code> argument is not executed\nin the same invocation (<code>Fediverse::typeAccess()</code> returns true and the command\nreturns). Without <code>--type</code>, the\ncommand first prints the current access type and then runs the action:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><em>(empty)</em></td>\n<td>Print the access list under <code>- List:</code></td>\n</tr>\n<tr>\n<td><code>list</code></td>\n<td>Print <code>- Known address:</code> followed by the access list</td>\n</tr>\n<tr>\n<td><code>add &lt;address&gt;</code></td>\n<td>Add the address to the list</td>\n</tr>\n<tr>\n<td><code>remove &lt;address&gt;</code></td>\n<td>Remove the address from the list</td>\n</tr>\n<tr>\n<td><code>import &lt;csv_file&gt;</code></td>\n<td>Read domains from the CSV&#39;s first column and add them to the existing <code>all_but</code> block list, after asking</td>\n</tr>\n<tr>\n<td><code>test &lt;address&gt;</code></td>\n<td>Print <code>Authorized</code> or <code>Unauthorized</code> for that address</td>\n</tr>\n<tr>\n<td><code>reset</code></td>\n<td>Empty the list</td>\n</tr>\n<tr>\n<td><code>silence &lt;address&gt;</code></td>\n<td>Silence the instance: keep it out of the public, global and hashtag timelines</td>\n</tr>\n<tr>\n<td><code>unsilence &lt;address&gt;</code></td>\n<td>Lift the silence</td>\n</tr>\n<tr>\n<td><code>silenced</code></td>\n<td>Print the silenced instances under <code>- Silenced:</code></td>\n</tr>\n</tbody></table></div>\n<p><code>import</code> accepts a first-column <code>#domain</code>/<code>domain</code> header or a plain\none-domain-per-line file. It validates the entire file before mutation, skips\nduplicates, caps an import at 10,000 unique domains and the file at 8 MB, and\nrefuses allow-list mode. Each new domain receives the same audit entry and\nqueued purge as an individual block — which is why it asks before writing, and\nwhy <code>--dry-run</code> exists. A row naming a single label (<code>com</code>, <code>localhost</code>) is\nrefused: an entry covers every subdomain of itself, so one such row would block\na whole top-level domain. So is a row naming this instance. Neither is a\npublic-suffix check — <code>co.uk</code> still passes — so read a file with <code>--dry-run</code>\nbefore applying it. It does not fetch remote sources; review an export before\nrunning it. An unknown action throws\n<code>specify action: add, remove, import, list, reset, silence, unsilence, silenced</code>.\n<code>silence</code> and <code>unsilence</code> without an address throw <code>specify an address to silence</code> / <code>... to unsilence</code>.</p>\n<p><strong>Silencing, the tier between a block and nothing.</strong> A block cuts the instance\noff in both directions and <code>social:domain:purge</code> deletes what it already sent,\nwhich also cuts off the local users who deliberately follow somebody there — so\nthe tool was too blunt to reach for and the nuisance stayed. A silence stores\nthe host in a second list (<code>silenced_list</code>) and changes one thing: posts whose\nauthor is on that instance are left out of the <strong>public</strong>, <strong>global</strong>,\n<strong>hashtag</strong> and <strong>followed-tag</strong> timelines (<code>StreamRequest::filterSilencedInstances()</code>).\nDelivery, fetching, webfinger, search by address, following, and the home\ntimeline of somebody who follows the account are all untouched — a silence is\nnot enforced in <code>authorized()</code>. Nothing is deleted, so <code>unsilence</code> brings the\nposts back.</p>\n<p>The match is on the author&#39;s actor id, so it covers the domain <strong>and everything\nunder it</strong> the way a deny-list entry does: silencing <code>noisy.test</code> also silences\n<code>sub.noisy.test</code>, and not <code>notnoisy.test</code>. The two lists are independent — an\ninstance can be silenced, blocked, both or neither.</p>\n<p><strong>What is actually enforced.</strong> There is a single list (<code>access_list</code>) whose meaning\ndepends on <code>access_type</code>: with <code>all_but</code> every address that is <em>not</em> listed is\nallowed; with <code>none_but</code> only listed addresses and the local host are allowed.\n<code>FediverseService::authorized()</code> is enforced on both inbox routes in\n<code>ActivityPubController</code> and on every outgoing HTTP request in <code>CurlService</code>, so the\nlist does take effect for inbox delivery and for fetching remote data. A refused\ninbox delivery is answered <strong>403</strong>, not 500, so the peer stops redelivering it —\nsee the rejection table in <code>docs/Architecture.md</code>.</p>\n<p><strong>How an address is matched.</strong> Case-insensitively, and without the trailing dot of\nthe absolute form. The two modes then read the list differently, on purpose:</p>\n<ul>\n<li>With <code>all_but</code>, a listed domain covers the domain itself <strong>and everything under\nit</strong> (<code>isListed()</code>). Blocking <code>evil.test</code> while <code>www.evil.test</code> walks straight\nback in is not a block.</li>\n<li>With <code>none_but</code>, an entry matches <strong>exactly</strong> (<code>isExactlyListed()</code>). A subdomain\nof an allowed domain is a different instance, and whoever runs the parent domain\nwas never asked before it appeared.</li>\n</ul>\n<p>There is no wildcard syntax; <code>add</code> stores what you type, and <code>remove</code> takes it away\nby the same exact comparison.</p>\n<p><strong>Known limitations:</strong></p>\n<ul>\n<li><code>list</code> always prints an empty <code>Known address:</code> section, because\n<code>FediverseService::getKnownAddresses()</code> returns an empty array.</li>\n<li>The older two-list implementation (<code>blockAddress()</code>, <code>allowAddress()</code>,\n<code>isBlocked()</code>, <code>isAllowed()</code>, and the separate blacklist/whitelist config keys) is\ncommented out at the end of <code>lib/Service/FediverseService.php</code>. Only the single\n<code>access_list</code> above exists; there is no separate block list.</li>\n<li>Webfinger lookups are not filtered per address; <code>WebfingerHandler</code> only calls\n<code>jailed()</code>, which refuses service when the instance is in <code>none_but</code> mode with an\nempty list.</li>\n</ul>\n<h2 id=\"social-emoji\"><code>social:emoji</code></h2>\n<p>The custom emoji this instance publishes.</p>\n<pre><code>php occ social:emoji [-c|--category CATEGORY] [--hidden] [&lt;action&gt;] [&lt;shortcode&gt;] [&lt;file&gt;]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Default</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>action</code></td>\n<td>No</td>\n<td><code>list</code></td>\n<td>One of <code>list</code>, <code>add</code>, <code>remove</code></td>\n</tr>\n<tr>\n<td><code>shortcode</code></td>\n<td>No</td>\n<td><code>&#39;&#39;</code></td>\n<td>Required by <code>add</code> and <code>remove</code>. The name between the colons: 2–64 characters of <code>a-z</code>, <code>0-9</code> and <code>_</code>. Read lowercase and trimmed, so <code>BlobCat</code> and <code>blobcat</code> are the same emoji</td>\n</tr>\n<tr>\n<td><code>file</code></td>\n<td>No</td>\n<td><code>&#39;&#39;</code></td>\n<td>Required by <code>add</code>. A readable path to the picture</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-c</code>, <code>--category</code></td>\n<td>required</td>\n<td>Group it under this in a client&#39;s picker</td>\n</tr>\n<tr>\n<td><code>--hidden</code></td>\n<td>none</td>\n<td>Store it usable by name but not offered in a picker (Mastodon&#39;s <code>visible_in_picker: false</code>)</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>list</code> <em>(the default)</em></td>\n<td>Print every emoji with its category, whether a picker offers it, and the URL it is served from</td>\n</tr>\n<tr>\n<td><code>add &lt;shortcode&gt; &lt;file&gt;</code></td>\n<td>Publish the picture under that shortcode</td>\n</tr>\n<tr>\n<td><code>remove &lt;shortcode&gt;</code></td>\n<td>Stop publishing it</td>\n</tr>\n</tbody></table></div>\n<p>An unknown action throws <code>specify action: list, add, remove</code>; removing one that\nis not there throws <code>no emoji is published as :&lt;shortcode&gt;:</code>.</p>\n<p><strong>What is accepted.</strong> A PNG, GIF, WebP or JPEG of at most <strong>256 KiB</strong> — the\nbytes decide, not the extension, because this is served to every reader of\nevery post that uses it. Anything else is refused with a reason.</p>\n<p><strong>What <code>add</code> does to a shortcode already in use.</strong> Replaces the picture. A\nshortcode names one emoji, and an admin re-uploading under a name in use means\nto replace it rather than to be told it exists.</p>\n<p><strong>What a post carries.</strong> The shortcode stays in the content as text, and an\n<code>Emoji</code> tag beside it says where the picture is — which is how every fediverse\nserver does it, and why an instance that has never heard of <code>:blobcat:</code> still\nrenders the post. A shortcode this instance has no picture for is left as the\ntext it already was. Editing a post rebuilds its tags, so a shortcode added by\nan edit renders and one removed by an edit takes its tag with it.</p>\n<p><strong>What <code>remove</code> does to posts that used it.</strong> Nothing. What they carry is the\ntag they were federated with; this instance no longer offering the picture does\nnot rewrite what was already said. Locally, the picture stops being served, so\nthe shortcode shows as text again.</p>\n<h2 id=\"social-gif\"><code>social:gif</code></h2>\n<p>The shared pictures the composer offers in its GIF picker, on top of the 881\nanimated emoji every instance has (<code>gif_pack</code>, on by default — see\n<a href=\"Architecture.md\">Architecture</a>). These are the ones that are <em>this</em> instance&#39;s:\nthe in-joke, the team&#39;s own, the thing nowhere else has. They are offered first,\nabove the emoji.</p>\n<pre><code>php occ social:gif [-t|--title TITLE] [&lt;action&gt;] [&lt;slug&gt;] [&lt;file&gt;]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Default</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>action</code></td>\n<td>No</td>\n<td><code>list</code></td>\n<td>One of <code>list</code>, <code>add</code>, <code>remove</code></td>\n</tr>\n<tr>\n<td><code>slug</code></td>\n<td>No</td>\n<td><code>&#39;&#39;</code></td>\n<td>Required by <code>add</code> and <code>remove</code>. What the picture is served and searched under: 2–64 characters of <code>a-z</code>, <code>0-9</code>, <code>-</code> and <code>_</code>. Read lowercase and trimmed</td>\n</tr>\n<tr>\n<td><code>file</code></td>\n<td>No</td>\n<td><code>&#39;&#39;</code></td>\n<td>Required by <code>add</code>. A readable path to the picture</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-t</code>, <code>--title</code></td>\n<td>required</td>\n<td>What the picker searches on — &quot;the one with the cat&quot; is how anybody actually looks for one of these</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Action</th>\n<th>Effect</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>list</code> <em>(the default)</em></td>\n<td>Print every picture in the library with its title and the URL it is served from</td>\n</tr>\n<tr>\n<td><code>add &lt;slug&gt; &lt;file&gt;</code></td>\n<td>Put the picture in the library under that slug</td>\n</tr>\n<tr>\n<td><code>remove &lt;slug&gt;</code></td>\n<td>Take it out</td>\n</tr>\n</tbody></table></div>\n<p>An unknown action throws <code>specify action: list, add, remove</code>; removing one that\nis not there throws <code>there is no library picture called &lt;slug&gt;</code>.</p>\n<p><strong>What is accepted.</strong> A GIF, an animated WebP or an MP4 of at most <strong>8 MiB</strong> —\nthe bytes decide, not the extension. Animated formats only: a library of stills\nis what the Files picker beside it is already for. The metadata is stripped the\nway every other upload&#39;s is, because these end up attached to posts that leave\nthis instance.</p>\n<p><strong>Why there is no upload form.</strong> This is a small set curated for a whole\ninstance rather than something every reader adds to, and the files an\nadministrator wants in it are already on a machine they have a shell on.</p>\n<p><strong>Why there is no Giphy or Tenor.</strong> Both would mean every composer on the\ninstance talking to a third party: the search terms people type go there, and\nevery thumbnail is a request from a reader&#39;s browser to a host the instance does\nnot control. That is not a decision this app should make on an administrator&#39;s\nbehalf, and a setting to turn it on would still be a setting that quietly sends\nwhat people are looking for to somebody else&#39;s server.</p>\n<p><strong>What <code>add</code> does to a slug already in use.</strong> Replaces the picture, for the\nreason <code>social:emoji add</code> does.</p>\n<p><strong>What <code>remove</code> does to posts that used it.</strong> Nothing. An attachment is a copy\ntaken when the post was written, so a post keeps the picture it was published\nwith.</p>\n<h2 id=\"social-domain-purge\"><code>social:domain:purge</code></h2>\n<p>Delete everything an instance already sent this one. Blocking the domain\n(<code>social:fediverse add</code>) is what stops it coming back; this removes what arrived\nbefore the block.</p>\n<pre><code>php occ social:domain:purge [-b|--batches BATCHES] [--check] &lt;domain&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>domain</code></td>\n<td>Yes</td>\n<td>The instance to purge, e.g. <code>spam.example</code>. Accepts what a user would type — <code>https://spam.example/@someone</code>, <code>@someone@spam.example</code>, <code>Spam.Example:8443</code> — and reduces it to the host</td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>-b</code>, <code>--batches</code></td>\n<td>required</td>\n<td>Stop after this many batches of 50 accounts instead of running to the end. Without it the command runs until nothing of the domain is left</td>\n</tr>\n<tr>\n<td><code>--check</code></td>\n<td>none</td>\n<td>Only report whether anything of the domain is still stored; deletes nothing</td>\n</tr>\n</tbody></table></div>\n<p><strong>What goes.</strong> For every account of that instance still known here: its cached\nactor, its posts (with their recipient, tag, action, card, revision and cached\nattachment rows), the notifications they caused, the follows in <strong>both</strong>\ndirections, the per-user blocks, mutes and notes about it, and the deliveries\nstill queued towards it. Leaving the follows behind kept the instance in the\ndelivery fan-out of every local post.</p>\n<p><strong>This cannot be undone.</strong> Unblocking the domain lets it reach the instance\nagain; it does not restore anything deleted here. The command says so before it\nexits.</p>\n<p><strong>Safe to interrupt and safe to repeat.</strong> Each pass asks what of the domain is\nstill stored rather than counting off a position, so a run that is killed half\nway is resumed by running it again, and a run against an already-purged domain\ndoes nothing. Accounts are found from three places — the actor cache, the\nauthors of stored posts, and the follow rows — because a post can outlive the\nactor it was cached from and a follow can name an account this instance never\ncached.</p>\n<p><strong>The exact host, not subdomains.</strong> A deny-list entry covers everything under\nthe domain (<code>isListed()</code>), but the purge does not: refusing traffic from one\ninstance too many is undone by editing the list, and deleting one is not. Purge\neach subdomain you mean to include.</p>\n<p><strong>This normally runs on its own.</strong> Adding a domain to the deny list queues\n<code>OCA\\Social\\Cron\\DomainPurge</code>, which does 10 batches per cron run and re-queues\nitself until the instance is gone. Use this command for a domain blocked before\nthe purge existed, for a job that failed part way, or to finish without waiting\nfor cron.</p>\n<hr>\n","toc":[{"id":"social-fediverse","text":"social:fediverse","level":2},{"id":"social-emoji","text":"social:emoji","level":2},{"id":"social-gif","text":"social:gif","level":2},{"id":"social-domain-purge","text":"social:domain:purge","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"federation","manual":false,"prev":{"path":"/docs/occ-cache","title":"Cache"},"next":{"path":"/docs/occ-external-users","title":"External Users"},"parent":null},{"slug":"occ-external-users","path":"/docs/occ-external-users","title":"External Users","description":"Self-registered external users: list them, add one without the registration form, or promote one to an ordinary local user.","group":"occ","html":"<h2 id=\"social-external\"><code>social:external</code></h2>\n<p>Self-registered external users: list them, add one without the registration\nform, or promote one to an ordinary local user.</p>\n<pre><code>php occ social:external list\nOC_PASS=... php occ social:external add &lt;handle&gt; --email EMAIL --password-from-env\nphp occ social:external promote &lt;handle&gt;\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Argument</th>\n<th>Required</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>action</code></td>\n<td>Yes</td>\n<td><code>list</code>, <code>add</code> or <code>promote</code></td>\n</tr>\n<tr>\n<td><code>handle</code></td>\n<td>No</td>\n<td>The user id, which is also the Aloha Social handle; needed by <code>add</code> and <code>promote</code></td>\n</tr>\n</tbody></table></div>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--email</code></td>\n<td>required</td>\n<td>The email address of a new external user, for <code>add</code></td>\n</tr>\n<tr>\n<td><code>--password-from-env</code></td>\n<td>none</td>\n<td>Read the password of a new external user from the <code>OC_PASS</code> environment variable, for <code>add</code></td>\n</tr>\n</tbody></table></div>\n<p><code>add</code> checks the handle, the email address and the room left under the\nmaximum the same way the registration page does, and needs external users to\nbe switched on. It skips email confirmation and approval. <code>promote</code> moves the\nuser to Aloha&#39;s database backend with the same user id and password hash;\nfrom then on the normal app and group rules apply to them. A refusal prints\nthe reason and exits with 1.</p>\n<hr>\n","toc":[{"id":"social-external","text":"social:external","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"external-users","manual":false,"prev":{"path":"/docs/occ-federation","title":"Federation"},"next":{"path":"/docs/occ-installation-and-maintenance","title":"Installation & Maintenance"},"parent":null},{"slug":"occ-installation-and-maintenance","path":"/docs/occ-installation-and-maintenance","title":"Installation & Maintenance","description":"Check the integrity of the installation, or regenerate the stream index.","group":"occ","html":"<h2 id=\"social-check-install\"><code>social:check:install</code></h2>\n<p>Check the integrity of the installation, or regenerate the stream index.</p>\n<pre><code>php occ social:check:install [--index] [--offline] [-f|--force]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--index</code></td>\n<td>none</td>\n<td>Regenerate the stream index instead of running the checks</td>\n</tr>\n<tr>\n<td><code>--offline</code></td>\n<td>none</td>\n<td>Leave out the WebFinger probe, the one check that goes out on the network</td>\n</tr>\n<tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Skip the confirmation of <code>--index</code> (required with <code>--no-interaction</code>)</td>\n</tr>\n</tbody></table></div>\n<p>Without <code>--index</code>:</p>\n<ul>\n<li>runs <code>CheckService::checkInstallationStatus()</code>,</li>\n<li>prints how many invalid followers and invalid notes were removed,</li>\n<li>runs the four checks that Administration → Overview shows (<code>lib/SetupChecks/</code>) and prints each with its severity: whether <code>.well-known/webfinger</code> answers for an account of this instance, whether the address Aloha Social builds ids from still matches the one the server reports, whether the delivery job has run lately, and whether anything in the outbound queue is stuck. A check that fails links to <a href=\"/docs/admin\">Admin.md</a>,</li>\n<li>prints a verdict line — <code>all N checks passed</code>, or <code>M of N checks reported an error</code> — and <strong>exits 1</strong> when any check reported an error, so the command can stand in a deployment script</li>\n<li>prints the current app configuration as pretty JSON.</li>\n</ul>\n<p>The command exits <code>1</code> when any of those four reports an error, so a deployment\nscript can run it. <code>--offline</code> leaves out the WebFinger probe for a machine with\nno route out; the other three read only the database and the configuration.</p>\n<p>With <code>--index</code> the checks are skipped entirely. The command warns that the operation\ntakes a while, asks <code>Do you confirm this operation? (y/N)</code>, and on confirmation\nempties <code>stream_dest</code> and <code>stream_tags</code> and rebuilds both from <code>social_stream</code>, a\nfew hundred rows at a time, with a progress bar. Answering anything but <code>y</code> exits\nwithout changes; under <code>--no-interaction</code> it refuses unless <code>--force</code> is given\n(exit code <code>1</code>), because the index tables are truncated before the rebuild starts\nand a run that stops there leaves every timeline empty.</p>\n<p>Rows it cannot parse are reported at the end (the first ten in full, then a count)\nand make the command exit <code>1</code>; the rest of the index is still rebuilt.</p>\n<hr>\n<h2 id=\"social-reset\"><code>social:reset</code></h2>\n<p>Delete all Aloha Social data, or uninstall the app&#39;s database footprint.</p>\n<pre><code>php occ social:reset [--uninstall] [--uri ADDRESS] [-f|--force]\n</code></pre>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Option</th>\n<th>Value</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>--uninstall</code></td>\n<td>none</td>\n<td>Full removal instead of a data flush</td>\n</tr>\n<tr>\n<td><code>--uri</code></td>\n<td>address</td>\n<td>The cloud base address to rebuild every id from, instead of being asked for it. This is the option <code>social:check:install</code> names when the configured address no longer matches the server. After the flush <code>social_url</code>, the base ids are minted from, is derived from the cloud address again, with or without this option</td>\n</tr>\n<tr>\n<td><code>-f</code>, <code>--force</code></td>\n<td>none</td>\n<td>Skip both confirmations (required with <code>--no-interaction</code>)</td>\n</tr>\n</tbody></table></div>\n<p>The command asks <strong>two</strong> confirmations before doing anything:</p>\n<ol>\n<li><code>Do you confirm this operation? (y/N)</code></li>\n<li><code>Operation is destructive. Are you sure about this? (y/N)</code></li>\n</ol>\n<p>Answering anything but <code>y</code> to either question aborts with exit code <code>0</code> and changes\nnothing. Under <code>--no-interaction</code> the command refuses with exit code <code>1</code> unless\n<code>--force</code> is given: a confirmation prompt answers itself with its default when\nnobody is there, so without this the command would exit <code>0</code> having done nothing.</p>\n<p>It refuses with exit code <code>1</code>, before asking anything, while self-registered\nexternal users exist: their logins are rows of this app, and flushing them\nwould leave Aloha users nobody can log in as. Delete them, or promote them\nwith <code>social:external promote</code>, first.</p>\n<p>Without <code>--uninstall</code>:</p>\n<ul>\n<li>empties every Aloha Social table (<code>CoreRequestBuilder::emptyAll()</code>),</li>\n<li>re-runs <code>checkInstallationStatus(true)</code>,</li>\n<li>sets the cloud base address to <code>--uri</code>, or, with somebody at the keyboard and no\n<code>--uri</code>, offers to change it, pre-filled with the current one; entering the same\nvalue leaves it unchanged. Non-interactively and without <code>--uri</code> the address is\nleft as it was.</li>\n</ul>\n<p>With <code>--uninstall</code>:</p>\n<ul>\n<li>drops the Aloha Social tables,</li>\n<li>removes the app&#39;s rows from the migrations table,</li>\n<li>removes the app&#39;s background jobs,</li>\n<li>unsets the app configuration.</li>\n</ul>\n<p>The app files themselves are not removed, and the app is not disabled.</p>\n<hr>\n","toc":[{"id":"social-check-install","text":"social:check:install","level":2},{"id":"social-reset","text":"social:reset","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"installation-and-maintenance","manual":false,"prev":{"path":"/docs/occ-external-users","title":"External Users"},"next":{"path":"/docs/occ-exit-codes","title":"Exit Codes"},"parent":null},{"slug":"occ-exit-codes","path":"/docs/occ-exit-codes","title":"Exit Codes","description":"Every command the app adds to occ, grouped by the task it performs.","group":"occ","html":"<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Code</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>0</td>\n<td>Success, and also a confirmation prompt answered with &quot;no&quot;</td>\n</tr>\n<tr>\n<td>1</td>\n<td>A refusal to act non-interactively without <code>--force</code> (<code>social:reset</code>, <code>social:check:install --index</code>, <code>social:benchmark</code>, <code>social:queue:retry</code>), a failed flush or uninstall in <code>social:reset</code>, <code>social:reset</code> while external users exist, streams <code>social:check:install --index</code> could not parse, a setup check that <code>social:check:install</code> reports as an error, <code>social:account:following</code> handled failure, or an uncaught exception in any command</td>\n</tr>\n</tbody></table></div>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"exit-codes","manual":false,"prev":{"path":"/docs/occ-installation-and-maintenance","title":"Installation & Maintenance"},"next":{"path":"/docs/occ-background-jobs","title":"Background Jobs"},"parent":null},{"slug":"occ-background-jobs","path":"/docs/occ-background-jobs","title":"Background Jobs","description":"Every 12 minutes, with a 300-second budget. Same steps as social:cache:refresh (deleted actors, local actor cache, remote actors and their details, documents, hashtags), and additionally…","group":"occ","html":"<p>The <code>TimedJob</code>s below are among those registered in <code>&lt;background-jobs&gt;</code> in\n<code>appinfo/info.xml</code> (that list is the complete one), run by Aloha&#39;s cron;\nthe last four are queued on demand instead:</p>\n<h2 id=\"cache-maintenance\">Cache maintenance</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\Cache</code></p>\n<p>Every 12 minutes, with a 300-second budget. Same steps as <code>social:cache:refresh</code> (deleted actors, local actor cache, remote actors and their details, documents, hashtags), and additionally closes polls, prunes remote statuses past retention, evicts cached remote accounts nobody here refers to, syncs the timelines of the cached remote actors somebody here follows, verifies profile links, reconciles group lists, finds out which servers the Discover page may ask and deletes the expired rows of the durable cache. A run that spends its budget logs which steps it skipped, and the next run starts with the first of them, so the steps at the end of the list are not the ones that never run. No key rotation is performed.</p>\n<h2 id=\"queue-processing\">Queue processing</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\Queue</code></p>\n<p>Every 12 minutes. Processes the outbound request queue <strong>and</strong> the stream queue, like <code>social:queue:process</code>.</p>\n<h2 id=\"expired-stories\">Expired stories</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\ExpiredStories</code></p>\n<p>Hourly. Deletes the stories whose day is up, at most 500 per run. The second of the two guards on a story&#39;s expiry: every read already filters on <code>expires_at</code>, so an instance whose cron has stopped shows nothing it should not — but without this the rows and their pictures would pile up for ever, and &quot;it disappears after a day&quot; would be true of what people can see and false of what is stored.</p>\n<h2 id=\"scheduled-posts\">Scheduled posts</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\ScheduledPosts</code></p>\n<p>Every 5 minutes. Publishes the posts whose <code>scheduled_at</code> has passed, at most 50 per run. Shorter than the other two on purpose: a scheduled post may be published up to one cron period late, and a longer period would promise a precision the five-minute minimum on <code>scheduled_at</code> implies but the app could not keep.</p>\n<h2 id=\"block-lists\">Block lists</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\BlocklistSync</code></p>\n<p>Daily. Re-reads the block lists an administrator follows and applies what they say; does nothing while no source is on.</p>\n<h2 id=\"external-registrations\">External registrations</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\ExternalSignups</code></p>\n<p>Hourly. Forgets registrations of external users whose email was not confirmed within a day, and invitations that expired or were used up. A registration waiting for an administrator is kept until somebody decides on it.</p>\n<h2 id=\"bluesky-sync\">Bluesky sync</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\AtprotoSync</code></p>\n<p>Every 2 minutes, only while Bluesky is on. Reads the feeds of the Bluesky authors somebody here follows — the newest page of each due watch from the public AppView, what is new stored, the next read soon after a page with posts and doubling up to six hours after empty ones — then the AppView&#39;s notifications of each due local account, asked for as that account; both passes stop at the instance&#39;s request ceiling (<code>atproto_sync_ceiling</code>).</p>\n<h2 id=\"bluesky-maintenance\">Bluesky maintenance</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\AtprotoMaintenance</code></p>\n<p>Every 5 minutes, only while Bluesky is on. Reconciles the last day&#39;s public posts with their Bluesky records — a post the listener missed is published, an edit within the grace period replaced, a deleted post&#39;s record removed — resends directory operations the PLC refused, prunes the firehose past its replay window, drops retired instance keys, and checks a page of 25 Bluesky posts read here in the last week against the AppView, deleting the ones it no longer has.</p>\n<h2 id=\"bluesky-video\">Bluesky video</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\AtprotoVideo</code></p>\n<p>Every minute, only while Bluesky is on and <code>atproto_video_service</code> is set. Sends up to three queued videos of posts published here to Bluesky&#39;s video service, asks after the jobs it is making, and publishes each post whose video has ended: with the video when the service stored it here, otherwise as text and a link to the post here.</p>\n<h2 id=\"domain-purge\">Domain purge</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\DomainPurge</code></p>\n<p>Queued with a domain when one is added to the deny list — not registered in <code>appinfo/info.xml</code>, because a job listed there is added once at install time with no argument. Does 10 batches of 50 accounts per run and re-queues itself while anything of the domain is left.</p>\n<h2 id=\"external-promotion\">External promotion</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\ExternalPromoted</code></p>\n<p>Queued with a user id when an external user is promoted to a local one — not in <code>appinfo/info.xml</code>, for the same reason as the domain purge. Writes the user&#39;s system address book card, which external users do not have, in a request that sees them on their new backend.</p>\n<h2 id=\"bluesky-publish\">Bluesky publish</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\AtprotoPublish</code></p>\n<p>Queued by the post listener with a post id and an action (publish, edit, delete) or by the account service for a profile — not in <code>appinfo/info.xml</code>, for the same reason. Does the work off the request that made the post; the maintenance job catches what a job that failed or was never queued left behind.</p>\n<h2 id=\"bluesky-move\">Bluesky move</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\AtprotoMove</code></p>\n<p>Queued when a person starts moving their Bluesky account away — not in <code>appinfo/info.xml</code>, for the same reason. Copies the repository, the blobs and the preferences to the other PDS, points the DID there, activates the account there and switches it off here; stops at a step that fails, which the person can start again.</p>\n<h2 id=\"actor-cleanup\">Actor cleanup</h2>\n<p><strong>Class: </strong><code>OCA\\Social\\Cron\\ActorCleanup</code></p>\n<p>Queued with an actor id when a deleted account is addressed by more posts than one inbox request should rewrite — not in <code>appinfo/info.xml</code>, for the same reason as the domain purge. Rewrites 2000 posts per run and re-queues itself while any remain. Without it, the rewrite ran inline in the request a peer was waiting on for its <code>Delete</code>, so the peer timed out, re-sent, and the work started over.</p>\n","toc":[{"id":"cache-maintenance","text":"Cache maintenance","level":2},{"id":"queue-processing","text":"Queue processing","level":2},{"id":"expired-stories","text":"Expired stories","level":2},{"id":"scheduled-posts","text":"Scheduled posts","level":2},{"id":"block-lists","text":"Block lists","level":2},{"id":"external-registrations","text":"External registrations","level":2},{"id":"bluesky-sync","text":"Bluesky sync","level":2},{"id":"bluesky-maintenance","text":"Bluesky maintenance","level":2},{"id":"bluesky-video","text":"Bluesky video","level":2},{"id":"domain-purge","text":"Domain purge","level":2},{"id":"external-promotion","text":"External promotion","level":2},{"id":"bluesky-publish","text":"Bluesky publish","level":2},{"id":"bluesky-move","text":"Bluesky move","level":2},{"id":"actor-cleanup","text":"Actor cleanup","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/OCC-Commands.md","sections":null,"anchor":"background-jobs","manual":false,"prev":{"path":"/docs/occ-exit-codes","title":"Exit Codes"},"next":null,"parent":null},{"slug":"mastodon","path":"/docs/mastodon","title":"Mastodon compatibility","description":"How close this app is to Mastodon, in the three senses that phrase can have: whether Mastodon's clients work against it, whether other fediverse servers can tell the difference, and…","group":"mastodon","html":"<p>How close this app is to Mastodon, in the three senses that phrase can have:\nwhether Mastodon&#39;s clients work against it, whether other fediverse servers can\ntell the difference, and whether an existing Mastodon instance could move onto\nit. Written for whoever has to decide what to build next.</p>\n<p><strong>Verified against:</strong> app version 0.19.95, <code>master</code>, 2026-09-15 — every status\nre-checked against the code, and the client-facing claims re-checked against a\nrunning instance rather than against the unit tests — and 0.26.60, 2026-09-25,\nagainst the code only, for the domain-root sections (§1, §2, §3.1, §9 item 1\nand <em>Where to start</em>), the post import (§5.3, item 28) and the list of what\nMastodon has no equivalent for; the rest has not been re-checked since.</p>\n<p><strong>What changed in this revision</strong>, for a reader who knew the document before:\na walk of Mastodon&#39;s documented client routes found 23 genuinely unserved (the\nraw diff said 45; 22 of those were false positives — <code>statuses/{nid}/{act}</code>,\n<code>timelines/{timeline}</code> and the <code>accounts/{id}</code> route in <code>appinfo/routes.php</code>\nare catch-alls a path-by-path comparison cannot see). Of the 23, <strong>everything\nthat is not Web Push, streaming or a sign-up this app does not own is now\nserved</strong>: translation, grouped notifications, the notification policy and its\nrequests inbox, per-status filters, <code>profile/avatar|header</code>,\n<code>suggestions/{id}</code>, <code>instance/privacy_policy|terms_of_service|translation_languages</code>\nand <code>oembed</code>. <code>translate</code> no longer returns the post unchanged, and\n<code>showing_reblogs</code> is no longer hardcoded. The web client gained the three\nthings a Mastodon user meets on day one and could not do here: filters,\ndelete-and-redraft, and the per-account bell and hide-boosts switches.</p>\n<p>This document supersedes the parity reviews written against 0.11.51 and 0.11.63,\nand the &quot;what can be improved&quot; assessment written against 0.11.49: every item in\nthose was checked, and what survives is here, in\n<a href=\"/docs/performance\">Performance.md</a> or in <a href=\"/docs/debt\">Technical-Debt.md</a>.\nThe rest is fixed.</p>\n<p>Like those two, nothing in <code>tests/DocumentationTest.php</code> checks the <em>claims</em>\nhere, so they go stale silently. Re-check rather than trust after the next wave\nof work.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":[{"path":"/docs/mastodon-the-answer-in-one-paragraph","title":"The answer in one paragraph","description":"Aloha Social 0.19.95 is a capable, standards-correct ActivityPub server with a broad and largely genuine Mastodon client API. A walk of Mastodon's 145 documented client routes against the…","parent":false},{"path":"/docs/mastodon-what-drop-in-has-to-mean","title":"What \"drop-in\" has to mean","description":"The phrase hides three different tests, with three different difficulties. A report that does not separate them will either sound alarming or sound smug.","parent":false},{"path":"/docs/mastodon-the-client-test","title":"The client test","description":"Every route is registered under the app prefix (a #[FrontpageRoute] on the controller method), served at https://host/index.php/apps/social/api/v1/.... The only things the app registers at…","parent":false},{"path":"/docs/mastodon-the-peer-test","title":"The peer test","description":"This is where the app is strongest, and it deserves saying plainly. A remote server talking to an Aloha Social instance on its own domain would find very little to complain about.","parent":false},{"path":"/docs/mastodon-the-takeover-test","title":"The takeover test","description":"This is the part that makes \"drop-in replacement\" a much larger question than feature parity, and it is where the honest answer is no.","parent":false},{"path":"/docs/mastodon-feature-gaps-a-migrating-admin-would-hit-on-day-one","title":"Feature gaps a migrating admin would hit on day one","description":"No longer on this list, each verified against the code rather than assumed: conversation mute; all four of the notification types that were missing — poll, status, moderation_warning and…","parent":false},{"path":"/docs/mastodon-deliberate-differences-that-are-not-gaps","title":"Deliberate differences that are not gaps","description":"Worth stating so they are not mistaken for work. Authentication, 2FA and sessions come from Aloha. Accounts are Aloha users, so accountEnable is a deliberate no-op and there is no…","parent":false},{"path":"/docs/mastodon-what-landed-since-the-last-review","title":"What landed since the last review","description":"Credit where it is due. Of the nine defects listed at 0.11.63, seven are fully fixed and two partially: local poll voting, scheduled_at, the character limit, poll expiry, the single-choice…","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/mastodon-the-answer-in-one-paragraph","title":"The answer in one paragraph"},"parent":null},{"slug":"mastodon-the-answer-in-one-paragraph","path":"/docs/mastodon-the-answer-in-one-paragraph","title":"The answer in one paragraph","description":"Aloha Social 0.19.95 is a capable, standards-correct ActivityPub server with a broad and largely genuine Mastodon client API. A walk of Mastodon's 145 documented client routes against the…","group":"mastodon","html":"<p>Aloha Social 0.19.95 is a capable, standards-correct ActivityPub server with a broad\nand largely genuine Mastodon client API. A walk of Mastodon&#39;s 145 documented\nclient routes against the route table found 23 genuinely unserved — the raw\npath diff said 45, and 22 of those were catch-alls a textual comparison cannot\nsee. Of the 23, <strong>three</strong> are left: <code>push/subscription</code> and <code>streaming</code>, the\ntwo known weeks-long items, both announced as absent so a client stops asking\nrather than hanging, and <code>emails/confirmations</code>, which belongs to a sign-up\nthis app does not own. Everything else exists, and §3.3 says which of them is a\nstub.</p>\n<p>It is <strong>not</strong> a drop-in replacement for Mastodon, and two things stood between\nit and that goal. One was small and mechanical: the API is not served at the\ndomain root by the app itself, and the web-server rules that put it there now\nship with the app (§3.1). (The other of that pair — an OAuth app row holding\nexactly one token — is fixed: authorizations are their own table, so two people\ncan use the same client.) The second is architectural: <strong>an actor&#39;s identity is\nrecomputed from configuration on every read rather than stored</strong>, and every URI\nthe app mints lives under <code>/apps/social/</code>. That single decision is what makes\ntaking over an existing Mastodon domain impossible rather than merely\nunimplemented.</p>\n<p>The good news is that nothing here is impossible in principle. The storage layer\nwould accept Mastodon-shaped ids and imported keys today; there is simply no code\npath that writes them.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"the-answer-in-one-paragraph","manual":false,"prev":{"path":"/docs/mastodon","title":"Mastodon compatibility"},"next":{"path":"/docs/mastodon-what-drop-in-has-to-mean","title":"What \"drop-in\" has to mean"},"parent":null},{"slug":"mastodon-what-drop-in-has-to-mean","path":"/docs/mastodon-what-drop-in-has-to-mean","title":"What \"drop-in\" has to mean","description":"The phrase hides three different tests, with three different difficulties. A report that does not separate them will either sound alarming or sound smug.","group":"mastodon","html":"<p>The phrase hides three different tests, with three different difficulties. A\nreport that does not separate them will either sound alarming or sound smug.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Test</th>\n<th>Question</th>\n<th>Verdict</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>The client test</strong></td>\n<td>Do existing Mastodon apps work against it, unmodified?</td>\n<td><strong>Only once the shipped web-server rules are installed</strong> (§3.1), and then without push or streaming (§3.3); without the rules, no</td>\n</tr>\n<tr>\n<td><strong>The peer test</strong></td>\n<td>Would other fediverse servers notice the difference?</td>\n<td><strong>Almost no</strong> — federation quality is genuinely good, with one live defect (§4)</td>\n</tr>\n<tr>\n<td><strong>The takeover test</strong></td>\n<td>Can an existing Mastodon instance move onto it, same domain, same users, without the network noticing?</td>\n<td><strong>No</strong> — and this is weeks to months of work</td>\n</tr>\n</tbody></table></div>\n<p>Most of the value is in the first test. Most of the difficulty is in the third.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"what-drop-in-has-to-mean","manual":false,"prev":{"path":"/docs/mastodon-the-answer-in-one-paragraph","title":"The answer in one paragraph"},"next":{"path":"/docs/mastodon-the-client-test","title":"The client test"},"parent":null},{"slug":"mastodon-the-client-test","path":"/docs/mastodon-the-client-test","title":"The client test","description":"Every route is registered under the app prefix (a #[FrontpageRoute] on the controller method), served at https://host/index.php/apps/social/api/v1/.... The only things the app registers at…","group":"mastodon","html":"<h2 id=\"3-1-the-api-at-the-domain-root\">3.1 The API at the domain root</h2>\n<p>Every route is registered under the app prefix (a <code>#[FrontpageRoute]</code> on the\ncontroller method), served at\n<code>https://host/index.php/apps/social/api/v1/...</code>. The only things the app\nregisters at the server root are the WebFinger, NodeInfo and host-meta well-known\nhandlers (<code>AppInfo\\Application</code>).</p>\n<p>Ivory, Tusky, Mona, Elk, Ice Cubes and Phanpy all build request URLs as\n<code>https://&lt;domain&gt;/api/v1/...</code> from the domain the user types. The Mastodon client\nprotocol has <strong>no mechanism for a non-root API base</strong>, so out of the box none of\nthem can reach any endpoint.</p>\n<p>The way in is a web-server change, not an app setting: the app ships the rules\nthat map <code>/api</code> and <code>/oauth</code> at the domain root onto itself, for Apache and\nnginx, in <code>contrib/webserver/</code>, with the explanation in\n<a href=\"/docs/admin-mastodon-apps-cannot-connect#mastodon-apps-cannot-connect\">Admin.md</a>. The <code>ClientApiAtRoot</code> setup\ncheck (and <code>ProxyForwardsTheScheme</code> beside it) says in Administration →\nOverview whether they are in place, and an administrator opening the app sees\nthe same warning with the rules to paste until they are. Where they are not,\nnothing else in this section is reachable by a stock client.</p>\n<h2 id=\"3-1a-fixed-account-pictures\">3.1a Fixed — account pictures</h2>\n<p>Fixed in #2468: a local account that had never set a picture was sent with\n<code>avatar: &quot;&quot;</code> and its Aloha avatar in <code>header</code>, because the model&#39;s header\nfell back to the avatar and the cached copy of the actor handed that fallback\nback as if it were a banner; clients drew the face as the banner over an empty\ncircle. The Account entity now always carries a URL in all four picture fields:\nthe avatar is the account&#39;s own or, for a local account, Aloha&#39;s generated\none; the header is the banner or a plain placeholder picture\n(<code>img/header-missing.png</code>), a PNG as Mastodon&#39;s <code>missing.png</code> so that clients\nwhich decode only raster images draw it too, never the avatar.</p>\n<p>Fixed in #2487: the avatars the old fallback had already stored as the header\nof cached local actors are removed by the <code>ClearAvatarHeaders</code> repair step, and\nread as no header until it has run. <code>GET /api/v1/accounts/{id}</code> read the actor\nwithout its cached icon and answered the placeholder avatar where\n<code>verify_credentials</code> answered the uploaded picture; it joins the icon in like\nevery other lookup. Every Account entity also carries <code>avatar_default</code> and\n<code>header_default</code>, <code>true</code> when the picture is a placeholder, so a client can\ntell one from a picture the account set without matching URLs — something\nMastodon itself has no flag for.</p>\n<h2 id=\"3-2-fixed-one-access-token-per-registered-app\">3.2 Fixed — one access token per registered app</h2>\n<p><code>social_client</code> used to hold a single <code>token</code>, <code>auth_user_id</code>, <code>auth_account</code>\nand <code>auth_scopes</code> per row, and the whole OAuth flow keyed on <code>client_id</code>.\n<code>authClient()</code> blanked the token on every authorization — with a comment\nexplaining that leaving it would let the previous user&#39;s token act as the new\none — so a second authorization against the same <code>client_id</code> silently revoked\nthe first. Elk and Phanpy register one app per instance and serve several\nusers from it, so user B signing in logged user A out, and a single user adding\nthe same account twice did the same thing.</p>\n<p>Mastodon&#39;s model is one application, many tokens, and that is now the model\nhere: <code>social_client_auth</code> holds one authorization per (app, account) — the\ncode, the token, the scopes granted and the account they were granted to. The\napp registration stays where it was, and every read joins it, so the rest of\nthe app still sees one <code>SocialClient</code> carrying both halves.</p>\n<p>Three things went with it. Revoking a token took the app row&#39;s only token, so\nrevoking on one device signed out everybody who had authorized that client; it\nnow takes one authorization. The expiry sweep deleted the whole <code>social_client</code>\nrow, so an idle token took the app&#39;s registration with it and the client had to\nregister again; it now deletes authorizations. And a code is spent in the same\nstatement that writes the token, so two requests arriving together cannot both\nexchange it.</p>\n<h2 id=\"3-3-the-endpoint-surface-is-now-broad-and-mostly-real\">3.3 The endpoint surface is now broad and mostly real</h2>\n<p>I opened the controller method behind each route rather than trusting the route\ntable. <strong>One true stub remains in the entire Mastodon surface:</strong></p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Endpoint</th>\n<th>State</th>\n<th>Evidence</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>/api/saved_searches/list.json</code></td>\n<td>initialises the viewer, returns <code>[]</code></td>\n<td><code>ApiController::savedSearches()</code></td>\n</tr>\n</tbody></table></div>\n<p>It is also not Mastodon&#39;s — it is a Twitter route an early client brought with\nit, which is why §9 files it as a decision rather than a task.</p>\n<p>Everything else that exists as a route does real work, including subsystems the\n2026-09-11 review listed as absent: lists, v2 filters (applied server-side),\nconversations, markers, edit history, trends for tags and statuses and links,\nsuggestions, the directory, featured tags, endorsements, per-user domain blocks,\nannouncements with an admin UI, account notes, scheduled statuses with a cron,\nand a real admin API. Since that was written, so do conversation mute, the\nthree standalone <code>instance</code> sub-routes, <code>/api/v1/timelines/link</code> and\n<code>/api/v1/statuses/{id}/card</code>, and the four notification types §6 used to list.</p>\n<h2 id=\"3-4-genuinely-missing-endpoints\">3.4 Genuinely missing endpoints</h2>\n<p>Three, and only three:</p>\n<ul>\n<li><strong>Web Push (<code>/api/v1/push/*</code>)</strong> — absent. <code>lib/Service/PushService.php</code> is\nunrelated; it pokes the <code>notify_push</code> app so the <em>web</em> client refreshes.\nThird-party mobile apps get no push from this server.</li>\n<li><strong>Streaming</strong> — absent, and deliberately so. <code>InstanceService</code> returns an empty\n<code>urls</code> object so clients fall back to polling immediately rather than after a\ntimeout.</li>\n<li><strong><code>/api/v1/emails/confirmations</code></strong> — part of a sign-up this app does not own;\nsee §9 item 16. <code>/api/v1/admin/canonical_email_blocks</code> is absent for the same\nreason, though it belongs to the admin API rather than to this count.</li>\n</ul>\n<p>What used to be on this list and is not any more: <code>POST /statuses/{id}/translate</code>\n(a real translation through Aloha&#39;s own provider, answering a Translation\nentity, with <code>instance/translation_languages</code> beside it and a 503 where the\nserver has no provider); the Mastodon 4.3 notification routes\n(<code>/api/v2/notifications</code> and its four, <code>/api/v1/notifications/policy</code>, and\n<code>/api/v1/notifications/requests</code> with its accept and dismiss, single and bulk);\nthe status half of v2 filters (<code>/api/v2/filters/{id}/statuses</code> and\n<code>/api/v2/filters/statuses/{id}</code>); <code>DELETE /api/v1/profile/avatar</code> and <code>/header</code>;\n<code>DELETE /api/v1/suggestions/{id}</code>; <code>/api/v1/instance/privacy_policy</code> and\n<code>/terms_of_service</code>, from Aloha&#39;s own Theming settings; and <code>/api/oembed</code>,\nanswered as <code>type: link</code> because there is no embed page here and framing the\nwhole app would publish something nobody meant to.</p>\n<p>Everything else that was on this list is answered now. Conversation mute is\nhandled (<code>ActionService::muteConversation()</code>); <code>/api/v1/timelines/link</code>,\n<code>/api/v1/statuses/{id}/card</code> and the three standalone <code>instance</code> sub-routes are\nregistered; <code>/api/v1/preferences</code>, <code>familiar_followers</code>, <code>instance/peers</code>,\n<code>instance/activity</code> and the v1 filter routes arrived with #2134;\n<code>/api/v1/custom_emojis</code> answers with the instance&#39;s own emoji rather than <code>[]</code>;\nand <code>/api/v1/accounts/search</code>, <code>favourited_by</code> and <code>reblogged_by</code> came with\n#2126 — the first is what a composer calls to complete a <code>@handle</code> and no\nclient substitutes <code>/api/v2/search</code> for it, and the other two make a tap on a\nfavourite or boost count something other than a dead end. Both reaction lists\nresolve the status through the visibility filter first: who liked a post is as\nprivate as the post.</p>\n<h2 id=\"3-5-the-version-string\">3.5 The version string</h2>\n<p><code>Instance::COMPAT_VERSION = &#39;4.3.0&#39;</code>. It said <code>3.5.0</code> until #2126 and <code>4.2.0</code> until\nthe 4.3 surface was whole, which is what it announces now — with <code>api_versions</code>\n(<code>{&quot;mastodon&quot;: 3, &quot;aloha_social&quot;: 1}</code>) beside it, which is what a 4.3 client\nreads <em>instead of</em> parsing a string that, on a fork, says nothing about which\nMastodon API is implemented. <code>aloha_social</code> is this app&#39;s own generation, for\nbehaviour a client cannot infer from <code>mastodon</code> because older versions of the\napp reported the same number without it; a client gates on <code>&gt;=</code>. Generation 1\n(#2481): <code>/api/v2/search</code> honours <code>account_id</code>, narrowing <code>statuses</code> to that\naccount&#39;s posts the viewer may see while <code>accounts</code> and <code>hashtags</code> stay as they\nare, as in Mastodon; an account this instance does not know finds no posts\nrather than an error. <code>offset</code> pages the posts up to 400 deep, and <code>max_id</code> /\n<code>min_id</code> bound them by status id without changing the newest-first order.\nThis was\nright when it was written and had stopped being: clients gate features on this\nstring, so they were hiding edit and history, calling the v1 filter routes that\n404 instead of v2, and never asking for <code>/api/v2/instance</code> or\n<code>/notifications/unread_count</code> — all of which are implemented.</p>\n<p>The 4.x features still missing are announced rather than left to fail. <code>urls</code>\nis an empty object, which is how a client learns there is no streaming\nendpoint, and <code>vapid_key</code> is an empty string, so a client decides against\noffering Web Push before it asks for it — which is what it does against any\nserver with no VAPID key. <code>configuration.translation.enabled</code> is no longer\nalways <code>false</code>: it is <code>true</code> where this Aloha has a translation provider,\nand the languages that provider offers are at\n<code>/api/v1/instance/translation_languages</code>.</p>\n<h2 id=\"3-6-entity-shapes\">3.6 Entity shapes</h2>\n<p>Good overall. Two of the four issues this section used to list are fixed in\n#2126:</p>\n<ul>\n<li><strong><code>source</code> was emitted on every Account</strong>, including other people&#39;s and to\nanonymous callers, leaking <code>source.follow_requests_count</code> — how many people\nare waiting on an account&#39;s approval. It is now built by the two credentials\nroutes, which are the two that know they are answering the account itself, and\nthe model no longer has it to leak.</li>\n<li><strong><code>poll</code> was absent rather than <code>null</code></strong> on non-poll statuses, against the\napp&#39;s own rule that a client should never have to test for a missing key.</li>\n</ul>\n<p><code>POST /api/v1/apps</code> was the third: it omitted <code>redirect_uri</code>, which Mastodon&#39;s\nApplication entity always carries. It now answers with the first registered URI\nand an empty <code>vapid_key</code>, because there is no Web Push here to have a key for.</p>\n<p>Two remain:</p>\n<ul>\n<li>An Account can still carry <code>&quot;avatar&quot;: &quot;&quot;</code> — verified against a running\ninstance, where one account out of a search page came back with an empty\nstring — because <code>Person::exportAsLocal()</code> falls through to <code>getAvatar()</code>\nwhen the actor has no cached icon, and that is the stored value, which may be\nempty. Mastodon declares the field a URL, and a client that decodes it as one\nfails on the whole account.\nOne deliberate extension to note: a <code>Status</code> carries <code>delivery: &quot;held&quot;</code> on\nthe author&#39;s own copy while its deliveries wait for a video to be converted\n(§ <em>Held for a video</em> in Architecture.md), and the key is absent otherwise. A\nMastodon client ignores an unknown key; the app&#39;s own web client draws the\n&quot;still converting&quot; hint from it rather than guessing from the attachment type.</li>\n</ul>\n<p>Another: every <code>Status</code> and every <code>MediaAttachment</code> carries <code>ai_generated</code>\n(bool, always present) — whether the post <em>says</em> it was made with AI, by one\nof a set of hashtags (<code>#aigenerated</code>, <code>#midjourney</code>, … plus the administrator&#39;s\n<code>ai_tags</code>) or by a picture whose metadata stated IPTC <code>DigitalSourceType</code>\nprovenance when it was stored. A label the post carries, never a judgement\nabout its content. The reader&#39;s switch for it is <code>GET</code>/<code>PATCH /api/v1/social/ai_content</code> under the filter scopes, echoed by\n<code>/api/v1/preferences</code> as <code>reading:hide:ai</code>; turned on, such posts are dropped\nserver-side in <code>FilterService::apply()</code> — every timeline, thread, profile and\nnotification page, lists included — so a Mastodon client that knows nothing\nof the switch still shows what the reader chose. One that reads the key can\ndraw a quiet mark for readers who left the switch off.</p>\n<p>A second extension lives beside the notifications: <code>GET</code>/<code>PATCH /api/v1/social/notification_delivery</code>, and the <code>notifications:delivery</code> key\n<code>/api/v1/preferences</code> echoes. Mastodon has nothing to compare it with — its\nnotifications <em>are</em> the list, and a client&#39;s push is the client&#39;s business —\nwhereas here the list has a second half, the Aloha bell, and this is the\nsetting for when that half rings: at once, or as a digest at times of the\nreader&#39;s choosing, with direct messages and mentions from followed accounts\npassing through and optional quiet hours. A Mastodon client never sees the\ndifference: <code>/api/v1/notifications</code> and the markers read the stored rows, and\nthe setting only decides when the bell is told about them.</p>\n<p>The notification policy goes further than Mastodon&#39;s in one respect and\nstarts differently in another. <strong>A held notification raises nothing</strong>: the\nAloha notification is the only push there is here (the bell, the mobile\napps, mail), and <code>NotificationService::emit()</code> asks the policy — the same\nrules <code>/api/v1/notifications</code> applies to the list — before raising it, so a\nheld sender does not reach a phone app either. The same goes for a post in a\nconversation the reader muted (<code>POST /api/v1/statuses/{id}/mute</code>, recorded\nagainst the thread&#39;s root). Accepting a request releases what was held into\nthe list without raising it; it counts as unread. And <strong>a new account starts\ncalm</strong>: an account created here gets a stored policy that holds people it does\nnot follow, new accounts, unsolicited private mentions and limited accounts\n(the administrator may choose otherwise for new accounts), while every account\nthat existed before keeps Mastodon&#39;s all-<code>accept</code> until its owner chooses. A\nclient reading <code>GET /api/v2/notifications/policy</code> sees the stored values, not\na default. <code>drop</code> is accepted from Mastodon apps and behaves as <code>filter</code>; the\nweb app never writes it. Three additions sit beside the Mastodon routes:\n<code>GET /api/v1/social/notifications/allowed</code> and <code>DELETE …/allowed/{account_id}</code>\n(the senders accepted from requests, which Mastodon keeps no list of), and\n<code>POST /api/v1/social/notifications/policy/notice/dismiss</code> for the <code>notice</code>\nflag the policy entity carries.</p>\n<p>A status&#39;s <code>muted</code> is real for the viewer, where it used to be a constant\n<code>false</code>; a client can show and toggle the conversation mute from it.</p>\n<p><code>showing_reblogs</code> is no longer among them either: <code>POST /accounts/{id}/follow</code>\ntakes <code>reblogs</code> as well as <code>notify</code>, a &quot;no&quot; is stored as a row in\n<code>social_actor_relation</code>, and the home and list timelines drop that account&#39;s\nboosts as a predicate of the query rather than by filtering a page after it was\nread.</p>\n<h2 id=\"3-7-profile-editing\">3.7 Profile editing</h2>\n<p>Fixed in #2126. <code>update_credentials</code> used to accept <code>header</code> and\n<code>source[privacy]</code> and ignore <code>avatar</code>, <code>display_name</code> and <code>bot</code> while returning\n200 — and a client&#39;s profile editor sends all of them in one PATCH, so somebody\nchanging their name, picture and bio together got a success and only the bio.</p>\n<p>All three are written now. The name and the picture belong to the Aloha\naccount rather than to the actor, so they are written there and the actor cache\nis refreshed; <code>bot</code> needed a column of its own and sets the actor&#39;s <em>type</em> with\nit, because an account marked automated that went on publishing <code>Person</code> would\ntell a client and a peer different things. A backend that owns the name or the\npicture (LDAP, SAML, anything provisioned elsewhere) makes the request a <strong>422</strong>\nrather than a silent success — which is what this section asked for, applied to\nthe fields that cannot be honoured rather than to the whole request.</p>\n<p>Fixed in #2437: clients send this route as a multipart <strong>PATCH</strong> whenever a\npicture is in it, and PHP parses a multipart body by itself for a POST only.\nThe body reached the controller unread, so no client could set an avatar or a\nheader, and a text-only multipart save changed nothing, all under a 200. The\nbody is now read with <code>request_parse_body()</code> on PHP 8.4 and later and by the\napp&#39;s own parser on PHP 8.3. A body that cannot be read, and a picture that was\nsent and did not arrive, are a <strong>422</strong> with nothing written.</p>\n<p>Fixed in #2439: the alt text and focal point of a published post&#39;s media are\nedited the way Mastodon edits them, with <code>media_attributes</code> on\n<code>PUT /api/v1/statuses/:id</code>. Nothing read that field, and <code>PUT /api/v1/media/:id</code>\nchanged only the upload while the post kept its own copy, so a description\ncould only be fixed by deleting the post. That route now refuses an upload a\npost carries, as Mastodon&#39;s does.</p>\n<p>Fixed in #2486: <code>GET /api/v1/statuses/:id/history</code> carries each version&#39;s\n<code>media_attachments</code>, descriptions and focal points included, as Mastodon&#39;s\n<code>StatusEdit</code> does. Every version used to have <code>[]</code>, so an edit that only\nchanged a description looked like no change at all. Versions recorded before\nthis keep <code>[]</code>.</p>\n<hr>\n","toc":[{"id":"3-1-the-api-at-the-domain-root","text":"3.1 The API at the domain root","level":2},{"id":"3-1a-fixed-account-pictures","text":"3.1a Fixed — account pictures","level":2},{"id":"3-2-fixed-one-access-token-per-registered-app","text":"3.2 Fixed — one access token per registered app","level":2},{"id":"3-3-the-endpoint-surface-is-now-broad-and-mostly-real","text":"3.3 The endpoint surface is now broad and mostly real","level":2},{"id":"3-4-genuinely-missing-endpoints","text":"3.4 Genuinely missing endpoints","level":2},{"id":"3-5-the-version-string","text":"3.5 The version string","level":2},{"id":"3-6-entity-shapes","text":"3.6 Entity shapes","level":2},{"id":"3-7-profile-editing","text":"3.7 Profile editing","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"the-client-test","manual":false,"prev":{"path":"/docs/mastodon-what-drop-in-has-to-mean","title":"What \"drop-in\" has to mean"},"next":{"path":"/docs/mastodon-the-peer-test","title":"The peer test"},"parent":null},{"slug":"mastodon-the-peer-test","path":"/docs/mastodon-the-peer-test","title":"The peer test","description":"This is where the app is strongest, and it deserves saying plainly. A remote server talking to an Aloha Social instance on its own domain would find very little to complain about.","group":"mastodon","html":"<p>This is where the app is strongest, and it deserves saying plainly. A remote\nserver talking to an Aloha Social instance on its own domain would find very little to\ncomplain about.</p>\n<p><strong>Working and correct:</strong> signed delivery and verification including RFC 9421, a\ndedicated instance actor with its own key pair for signed GETs\n(<code>lib/Service/InstanceActorService.php</code>), paged outbox, followers, following and\nfeatured collections, a real <code>replies</code> collection, Mastodon-shaped HTML content\nwhose <code>u-url mention</code> and <code>hashtag</code> anchors agree with the <code>tag</code> array\n(<code>lib/Service/LinkifyService.php</code>), <code>contentMap</code> and language, correct visibility\naddressing that fails closed on unknown, <code>updated</code> on edits, inbox forwarding per\nActivityPub 7.1.2 with the LD signature preserved (and, receiving one without an LD\nsignature, the object fetched from its origin rather than refused), per-inbox delivery\ndeduplication, and a retry window of 16 attempts on Sidekiq&#39;s <code>tries⁴+15</code>\nbackoff — about 49 hours, deliberately matching Mastodon.</p>\n<p>Two findings from the 0.11.63 review are fixed: outbound content is no longer\nescaped plain text, and delivery no longer sends one copy per mentioned user on\nthe same host. Three more have gone since: <code>Add</code> and <code>Remove</code> federate a pin,\n<code>Move</code> is built by <code>occ social:account:move</code> with an <code>alsoKnownAs</code>\nback-reference check, and the WebFinger profile-page link points at an Aloha Social\nprofile rather than at <code>/index.php/u/alice</code>.</p>\n<p><strong>What a peer would still notice — one thing, and it is live today:</strong></p>\n<p><strong>Attachments are served in Mastodon&#39;s client shape rather than as ActivityPub\ndocuments.</strong> Fetch any status of this instance with\n<code>Accept: application/activity+json</code> and <code>attachment</code> comes back as</p>\n<pre><code class=\"language-json\">[{&quot;id&quot;: &quot;707&quot;, &quot;type&quot;: &quot;video&quot;, &quot;url&quot;: &quot;…/media/02f8b930….mp4&quot;,\n  &quot;preview_url&quot;: &quot;…&quot;, &quot;remote_url&quot;: null, &quot;meta&quot;: {…}, &quot;description&quot;: &quot;…&quot;}]\n</code></pre>\n<p>where the wire calls for <code>{&quot;type&quot;: &quot;Document&quot;, &quot;mediaType&quot;: &quot;video/mp4&quot;, &quot;url&quot;: …, &quot;name&quot;: &quot;…&quot;}</code>. There is no <code>mediaType</code> at all, <code>type</code> is the client\nentity&#39;s half-word, and <code>description</code> is not the property a peer reads alt text\nfrom.</p>\n<p>The pieces are all present and correctly written — <code>MediaAttachment::asDocument()</code>\nemits exactly the right object, and <code>StatusApiController::statusNew()</code> sets\n<code>ACore::FORMAT_ACTIVITYPUB</code> on the attachments of a post as it is created, so\nthe original <code>Create</code> that goes out over the wire is right. What is wrong is\neverything <em>after</em> that: <code>StreamRequest::save()</code> deliberately stores\n<code>$item-&gt;asLocal()</code>, hydration leaves the rebuilt objects in the local format,\nand <code>Stream::jsonSerialize()</code> then hands those objects straight to the\nserialiser under <code>attachment</code>. So a single status, the outbox, <code>featured</code>,\n<code>replies</code>, an <code>Update</code> after an edit, and any re-fetch by a peer resolving a\nboost all carry the client shape.</p>\n<p>This is the same defect the Pixelfed compatibility review found in September and\nwas believed fixed. It was not caught because the test that pins it —\n<code>WireCompatibilityTest::testWhatGoesBackToPixelfedStatesItsMediaType()</code> — calls\n<code>asDocument()</code> directly rather than serialising a stored status the way the\ncontroller does, so it passes against a wire format nothing produces. It is §9\nitem 39, it is hours of work, and it is the highest-value item on that list\nafter the tier-1 blocker.</p>\n<p>Authorized fetch inbound is <strong>no longer</strong> among them: a signed GET is verified\nand resolved to the account behind it (<code>AuthorizedFetchService</code>), so a\nfollowers-only object is served to a remote reader who follows it, and secure\nmode — refusing an unsigned ActivityPub GET outright — is available behind the\n<code>secure_mode</code> app value. Custom <code>Emoji</code> tags are emitted and reactions to an\nannouncement are stored and served; emoji reactions to a <em>status</em> are a\nMisskey and Pleroma extension that Mastodon itself does not handle, and are\nnot implemented here either.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"the-peer-test","manual":false,"prev":{"path":"/docs/mastodon-the-client-test","title":"The client test"},"next":{"path":"/docs/mastodon-the-takeover-test","title":"The takeover test"},"parent":null},{"slug":"mastodon-the-takeover-test","path":"/docs/mastodon-the-takeover-test","title":"The takeover test","description":"This is the part that makes \"drop-in replacement\" a much larger question than feature parity, and it is where the honest answer is no.","group":"mastodon","html":"<p>This is the part that makes &quot;drop-in replacement&quot; a much larger question than\nfeature parity, and it is where the honest answer is no.</p>\n<h2 id=\"5-1-the-urls-do-not-match-and-cannot-be-made-to\">5.1 The URLs do not match, and cannot be made to</h2>\n<p>Every id is built from <code>ConfigService::getSocialUrl()</code>, which is the app&#39;s route\nroot.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Object</th>\n<th>Aloha Social</th>\n<th>Mastodon</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>actor</td>\n<td><code>https://host/apps/social/@alice</code></td>\n<td><code>https://host/users/alice</code></td>\n</tr>\n<tr>\n<td>status</td>\n<td><code>https://host/apps/social/@alice/17578…</code></td>\n<td><code>https://host/users/alice/statuses/&lt;id&gt;</code></td>\n</tr>\n<tr>\n<td>inbox</td>\n<td><code>https://host/apps/social/@alice/inbox</code></td>\n<td><code>https://host/users/alice/inbox</code></td>\n</tr>\n<tr>\n<td>shared inbox</td>\n<td><code>https://host/apps/social/inbox</code></td>\n<td><code>https://host/inbox</code></td>\n</tr>\n<tr>\n<td>instance actor</td>\n<td><code>https://host/apps/social/actor</code></td>\n<td><code>https://host/actor</code></td>\n</tr>\n</tbody></table></div>\n<p>After a domain swap, every remote server still holds the old Mastodon URIs as\nprimary keys. Actors 404, so peers mark the accounts gone and the follower\nrelationships die on their side. Status URIs 404, so boosts, favourites, replies\nand quotes across the network dangle. Old inbox URIs 404, so queued deliveries\nfail permanently. There is no redirect, no <code>Tombstone</code> and no <code>Move</code>, so nothing\nmigrates. And the signing key changes while the old <code>keyId</code> becomes unresolvable,\nso signature verification fails on the far side.</p>\n<h2 id=\"5-2-the-root-cause-is-that-identity-is-derived-not-stored\">5.2 The root cause is that identity is derived, not stored</h2>\n<p><code>ActorsRequestBuilder::parseActorsSelectSql()</code> <strong>overwrites</strong> the actor&#39;s id on\nevery read:</p>\n<pre><code class=\"language-php\">$actor-&gt;setId($root . &#39;@&#39; . $actor-&gt;getPreferredUsername());\n</code></pre>\n<p>(<code>ActorsRequestBuilder::parseActorsSelectSql()</code>, with inbox, outbox, followers,\nfollowing, featured and sharedInbox all derived from it on the lines below.) Writing a\nMastodon-shaped id into the column achieves nothing, because hydration discards\nit. Status ids are minted the same way in <code>StreamService::assignItem()</code>, and the\nserving routes <strong>reconstruct</strong> the id from the URL path rather than looking it up\n(<code>ActivityPubController::displayPost()</code>), so a post stored under a foreign\nid has no URL that serves it.</p>\n<p>Keys are always freshly generated (<code>AccountService::createActor()</code>), and\nthere is no setter reachable from outside. <code>SocialMigrator</code> refuses to carry a\nprivate key deliberately and explains why at length\n(<code>SocialMigrator</code>). The cipher itself\n(<code>PrivateKeyCipher</code>) would seal any PEM handed to it, so this\nis unimplemented rather than impossible.</p>\n<h2 id=\"5-3-what-exists-today-is-the-lossy-move-path\">5.3 What exists today is the lossy Move path</h2>\n<p><code>occ social:account:move</code> builds a proper <code>Move</code> with an <code>alsoKnownAs</code>\nback-reference check, and the inbound side handles it. <code>docs/OCC-Commands.md:145</code>\nstates the consequence: a move carries the followers, not the archive. And it\nrequires the old instance to still be running to send the Move, which contradicts\nkeeping the same domain.</p>\n<p>The archive half has moved since this was written, in one direction. An account\ncan now take its data out and put it back: <code>SocialMigrator</code> — driven by\n<code>occ user:export</code>, by Aloha&#39;s account migration, and by the Migration page&#39;s\ntwo buttons — writes the profile, the follows and followers as CSV, the\nbookmarks and favourites as URLs, the account&#39;s <strong>own posts as an ActivityPub\n<code>OrderedCollection</code></strong>, and <strong>the files of those posts</strong>, under\n<code>media_attachments/</code> in the layout Mastodon&#39;s own archive uses, with each\nattachment&#39;s <code>url</code> rewritten to point into the archive. What comes back on import\nis the profile, the follows, the relations, the marks, the banner and the files\nof the posts this server still has. That import counts the posts and does not\nwrite them, and the key pair is deliberately never carried. Posts are brought\nover separately: <strong>Settings → Migration → Bring your posts with you</strong> and\n<code>occ social:account:import-posts</code> (<code>PostImportService</code>) read another server&#39;s\narchive and write the account&#39;s own posts as new local posts, dated when they\nwere written, with their pictures, under ids of this server and with nothing\nfederated.</p>\n<p>The follows <em>file</em> is read whichever network wrote it: Mastodon&#39;s CSV, or\nPixelfed&#39;s <code>pixelfed-following.json</code> — a JSON array of actor URLs, which the\nimporter used to read as a CSV with no handle in it and follow nobody.</p>\n<p>Follower import is still the other half, and it is still impossible without\nidentity continuity: the relationship&#39;s other half lives on the follower&#39;s\nserver pointing at the old id. With identity continuity it becomes easy,\nbecause nothing has to be federated at all — it is a local row insert.</p>\n<h2 id=\"5-4-what-would-have-to-be-written\">5.4 What would have to be written</h2>\n<p>In order. The first three are the irreducible core; without them the fediverse\nnotices on the first signature check.</p>\n<ol>\n<li><strong>Make actor identity stored rather than derived.</strong> Stop overwriting <code>id</code> on\nread and on create; use the column when set, mint only when empty. Same for\nthe derived collection URLs.</li>\n<li><strong>Serve the Mastodon URL space and look up by stored id.</strong> Add\n<code>/users/{name}</code>, <code>/users/{name}/statuses/{id}</code>, root <code>/inbox</code>, <code>/outbox</code>,\n<code>/followers</code>, <code>/following</code>, and change the serving controllers to resolve the\nrequested URI instead of rebuilding it. Document the root rewrites.</li>\n<li><strong>Add a key-pair import</strong>, root-only and loudly warned, validating that the\npublic key matches the private one.</li>\n<li><strong>Add a handle and id rename path.</strong> This is the step most likely to be\nunderestimated: the <code>*_prim</code> md5 columns mean an id change is a fan-out\nrewrite across roughly a dozen tables.</li>\n<li><strong>Write the status importer</strong> — original id, published time, <code>inReplyTo</code>,\nconversation, addressing, language — rejecting any id whose host is not ours.\nThe export side of this exists (<code>SocialMigrator</code> writes the outbox); nothing\nreads it back.</li>\n<li><strong>Write the media importer.</strong> Half of it exists: the export carries every\nfile, and the import stores one back through the upload path\n(<code>DocumentService::storeLocalAttachment()</code>) and hangs it on the post it\nbelongs to — but only where this server already has that post, because\nnothing mints the posts. It becomes whole with 5.</li>\n<li><strong>Write the follower-graph importer</strong>, inserting rows directly rather than\ncalling the follow service, which would re-send a <code>Follow</code> to everyone.</li>\n<li><strong>Import the remaining per-actor state</strong> with the same write-the-row,\nfederate-nothing discipline <code>SocialMigrator::importRelations()</code> already models.</li>\n<li><strong>Reconcile counters and threading</strong> so like, boost and reply totals survive.</li>\n<li><strong>Add a cutover verification command</strong> that fetches our own actor and a\nsample of statuses over HTTPS as a remote server would, and checks that the\nserved id matches the stored one, that <code>publicKey.id</code> and the PEM agree, and\nthat a signature made with the imported key verifies.</li>\n<li><strong>Write the operational runbook</strong>: freeze, drain the delivery queue, dump,\nimport, flip, keep the old inbox reachable while DNS settles.</li>\n</ol>\n<hr>\n","toc":[{"id":"5-1-the-urls-do-not-match-and-cannot-be-made-to","text":"5.1 The URLs do not match, and cannot be made to","level":2},{"id":"5-2-the-root-cause-is-that-identity-is-derived-not-stored","text":"5.2 The root cause is that identity is derived, not stored","level":2},{"id":"5-3-what-exists-today-is-the-lossy-move-path","text":"5.3 What exists today is the lossy Move path","level":2},{"id":"5-4-what-would-have-to-be-written","text":"5.4 What would have to be written","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"the-takeover-test","manual":false,"prev":{"path":"/docs/mastodon-the-peer-test","title":"The peer test"},"next":{"path":"/docs/mastodon-feature-gaps-a-migrating-admin-would-hit-on-day-one","title":"Feature gaps a migrating admin would hit on day one"},"parent":null},{"slug":"mastodon-feature-gaps-a-migrating-admin-would-hit-on-day-one","path":"/docs/mastodon-feature-gaps-a-migrating-admin-would-hit-on-day-one","title":"Feature gaps a migrating admin would hit on day one","description":"No longer on this list, each verified against the code rather than assumed: conversation mute; all four of the notification types that were missing — poll, status, moderation_warning and…","group":"mastodon","html":"<p>Genuinely absent, in rough order of how much they would be missed:</p>\n<ol>\n<li>Web Push and streaming — every client polls, and both are announced as\nabsent rather than left to time out.</li>\n<li>Registration management: sign-up, approval queue, invites, email\nconfirmation. Accounts are Aloha users, so provisioning lives in the\nserver, and an approval queue and invite links have no equivalent anywhere.\nThis one is not going to be built here; what changed is that\n<code>POST /api/v1/accounts</code> answers <strong>403</strong> with the server&#39;s registration\naddress instead of a 404.</li>\n<li><strong>Graded domain blocks, through a Mastodon admin client.</strong> The app has a\nsilence tier — <code>FediverseService::silenceAddress()</code>, reachable from the\nadmin settings and <code>occ social:fediverse</code> — but the admin API does not\nexpose it: <code>AdminApiService::assertSeverity()</code> refuses any severity but\n<code>suspend</code>, <code>AdminDomainBlock</code> reports every entry as <code>suspend</code>, and silenced\ndomains are not in that list at all. An admin moving from Mastodon finds the\nfeature present in the web UI and absent from their tooling.</li>\n<li>Search is by word, not by substring. <code>StreamRequest::searchContent()</code> looks\nevery word of the query up in <code>social_search_term</code> and matches the last one\nas a word beginning; a fragment from the middle of a word finds nothing, as\non Mastodon. Script written without spaces between words is indexed in runs\nof up to 32 characters and found from the beginning of a run only.</li>\n<li><code>tootctl</code> equivalents for <code>preview_cards remove</code> and media-only sweeps.\n<code>accounts cull</code> and <code>accounts prune</code> no longer belong on this list: the cache\ncron gives up on an unreachable remote actor after ten failed refreshes\n(<code>CacheActorService</code>, the cull) and evicts the cached remote accounts nobody\nhere refers to after <code>cache_actor_days</code> (<code>CacheActorSweepService</code>, the\nprune), both of them continuous rather than a command an administrator has\nto remember. <code>occ social:media:usage</code> reports what the media costs but\ndeletes nothing.</li>\n<li>Canonical email blocks, which belong with registration.</li>\n</ol>\n<p><strong>No longer on this list</strong>, each verified against the code rather than assumed:\nconversation mute; all four of the notification types that were missing —\n<code>poll</code>, <code>status</code>, <code>moderation_warning</code> and <code>severed_relationships</code>; the three\nstandalone <code>instance</code> sub-routes; warnings and strikes; an account browser and a\npost-takedown button; custom emoji; admin metrics; IP and email-domain blocks;\nand a moderator role distinct from Aloha admin.</p>\n<p>The moderation gap that was a correctness bug rather than a missing feature —\n<strong>suspending a local account purged its posts here and federated nothing</strong>, so\nevery remote instance kept its copies and the takedown stopped at this\ninstance&#39;s own edge — is fixed in #2126: a suspension now sends the same\n<code>Delete</code> the account&#39;s own deletion sends. Only for a local account, because a\n<code>Delete</code> this instance signed for somebody else&#39;s actor is not one any peer\nwould act on.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"feature-gaps-a-migrating-admin-would-hit-on-day-one","manual":false,"prev":{"path":"/docs/mastodon-the-takeover-test","title":"The takeover test"},"next":{"path":"/docs/mastodon-deliberate-differences-that-are-not-gaps","title":"Deliberate differences that are not gaps"},"parent":null},{"slug":"mastodon-deliberate-differences-that-are-not-gaps","path":"/docs/mastodon-deliberate-differences-that-are-not-gaps","title":"Deliberate differences that are not gaps","description":"Worth stating so they are not mistaken for work. Authentication, 2FA and sessions come from Aloha. Accounts are Aloha users, so accountEnable is a deliberate no-op and there is no…","group":"mastodon","html":"<p>Worth stating so they are not mistaken for work. Authentication, 2FA and sessions\ncome from Aloha. Accounts are Aloha users, so <code>accountEnable</code> is a\ndeliberate no-op and there is no per-actor login to disable. Notifications go\nthrough the Aloha notification system — bell, mobile app, mail digest —\nrather than Web Push, and they are emitted for mention, favourite,\nreblog, follow, follow request and update from the single write path\n(<code>NotificationService</code>). There is no materialised home feed\nto rebuild, because timelines are queried live. Rules and retention are app\nvalues and occ commands. Moderation lives in Aloha admin settings.</p>\n<p><code>POST /api/v1/media</code> accepts more than Mastodon does, on purpose. Beside the\npictures, video and audio, a post here may carry a <strong>document</strong> — a PDF, a\nspreadsheet, a text file — which is what people on an Aloha actually have to\nshare, and Mastodon would answer one of those <code>422 File content type is invalid</code>. The answer here is <code>200</code> with <code>type: &quot;unknown&quot;</code>, which is exactly what\nMastodon&#39;s own entity says about an attachment it cannot draw, so a Mastodon\nclient renders it as a link and a reader on another Aloha gets a file card.\nNothing a browser would execute is accepted: HTML and SVG are refused <code>422</code>, and\neverything served carries <code>X-Content-Type-Options: nosniff</code>.</p>\n<p>And in the other direction, Mastodon has no equivalent for: dashboard\nwidgets, profile-page integration, posting a picture straight from Aloha\nFiles, Aloha Social data in <code>occ user:export</code>, and occ commands as an admin\nsurface.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"deliberate-differences-that-are-not-gaps","manual":false,"prev":{"path":"/docs/mastodon-feature-gaps-a-migrating-admin-would-hit-on-day-one","title":"Feature gaps a migrating admin would hit on day one"},"next":{"path":"/docs/mastodon-what-landed-since-the-last-review","title":"What landed since the last review"},"parent":null},{"slug":"mastodon-what-landed-since-the-last-review","path":"/docs/mastodon-what-landed-since-the-last-review","title":"What landed since the last review","description":"Credit where it is due. Of the nine defects listed at 0.11.63, seven are fully fixed and two partially: local poll voting, scheduled_at, the character limit, poll expiry, the single-choice…","group":"mastodon","html":"<p>Credit where it is due. Of the nine defects listed at 0.11.63, seven are fully\nfixed and two partially: local poll voting, <code>scheduled_at</code>, the character limit,\npoll expiry, the single-choice duplicate vote, <code>?remote=true</code>, and notification\ndismiss and clear are all correct now. Of the four moderation findings, all four\nare fixed — takedowns federate a <code>Delete</code>, domain blocks purge stored content\nthrough a background job, reports are forwarded outbound signed by the instance\nactor, and a suspension of a local account federates its <code>Delete</code> (#2126).\nNotifications, called the largest functional gap in that review, now reach the\nAloha bell.</p>\n<p>Since that paragraph was written, four more waves landed. <strong>#2134</strong> filled the\nsmall client gaps — the v1 filter routes, <code>instance/peers</code> and <code>instance/activity</code>,\n<code>preferences</code>, <code>familiar_followers</code>. <strong>#2135</strong> went after what a peer would\nnotice — <code>Add</code> and <code>Remove</code> federate a pin, the WebFinger profile link points at\nan Aloha Social profile, and <code>mediaType</code>, which §4 has now reopened because the fix\nnever reached the object a peer is served. <strong>#2136</strong> is the admin and\nmoderation tier almost entire: instance silencing, a moderator role that is\nAloha&#39;s own settings delegation, an account browser and a takedown button,\nwarnings and strikes, IP and email-domain blocks, admin metrics, the instance&#39;s\nown custom emoji, announcement reactions, and authorized fetch with secure mode.\nAnd the whole of tier 2b followed it: conversation mute, the <code>poll</code>, <code>status</code>,\n<code>moderation_warning</code> and <code>severed_relationships</code> notifications, the three\n<code>instance</code> sub-routes, the link timeline and the standalone card.</p>\n<p>Three fields this server has long accepted have also stopped being reachable\nonly from somebody else&#39;s client: the web composer sends <code>language</code> with every\npost, schedules one with <code>scheduled_at</code> and lists what is waiting through\n<code>/api/v1/scheduled_statuses</code>, and writes a <code>focus</code> onto an attachment. Nothing\nchanged on the API for any of them; what changed is who can set them.</p>\n<p>Of the tier-1 pair, one has moved: per-user OAuth tokens are done. The root\npath has not.</p>\n<p>Since then, 0.20.2 went after what a <strong>Pixelfed</strong> user and their app would\nmeet. Two silent failures on the wire: every video posted here went out as an\nActivityPub <code>Video</code>, which Pixelfed&#39;s inbox drops without a word, so it is a\n<code>Note</code> by default now; and Pixelfed&#39;s follows export is a JSON array of actor\nURLs that the importer read as an empty CSV, so it reads JSON. The official\napp was read against the route table — forty endpoints of Pixelfed&#39;s own, ten\nanswered — and thirty-four are answered now, through one façade that reshapes\ndata this app already serves: the <code>v1.2</code> story carousel, <code>collections/self</code>,\n<code>accounts/username</code> and <code>mutuals</code>, <code>v1.1/report</code>, <code>compose/settings</code>, the\ndirect-message thread routes, <code>tags/{tag}/related</code>, <code>push/*</code> told the truth\n(off, no token), and Pixelfed&#39;s <code>/api/admin/*</code> screens behind the same gate as\nMastodon&#39;s admin API. The silence tier reached the Mastodon admin API on the\nway (item 19). And the three Pixelfed-native features that were API-only —\nstories, collections, places — have pages in the web app. In the API and on\nthe wire a story stays Pixelfed&#39;s <code>Story</code> (bearcap fetch, <code>View</code>,\n<code>Story:Reaction</code>, <code>Story:Reply</code>); the web client presents it as a 24-hour\nshort, beside the kept shorts that are ordinary video posts, all under Shorts.</p>\n<p>And of this document&#39;s own list, five items were done in #2126 — the <code>source</code>\nleak, the suspension, the three dropped profile fields, the version string and\nthe three missing endpoints — with authorized fetch joining them in #2136 and\n<code>redirect_uri</code> on the Application entity since. What is left of that list is\nwhat it was always going to be: the root path, push, the attachment shape, and\nthe takeover.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Mastodon-Compatibility.md","sections":null,"anchor":"what-landed-since-the-last-review","manual":false,"prev":{"path":"/docs/mastodon-deliberate-differences-that-are-not-gaps","title":"Deliberate differences that are not gaps"},"next":null,"parent":null},{"slug":"atproto","path":"/docs/atproto","title":"Bluesky and AT Protocol compatibility","description":"Status: phases 1, 2 and 3 (§18) and phase 4 — custom handles (4a), moving away (4b), moving here (4c), Bridgy twins with any migration tool (4d) and a moved account's posts in its timeline…","group":"atproto","html":"<p><strong>Status: phases 1, 2 and 3 (§18) and phase 4 — custom handles (4a), moving away (4b), moving here (4c), Bridgy twins with any migration tool (4d) and a moved account&#39;s posts in its timeline (4e) — are implemented.</strong>\nThis document is the contract for a multi-PR project: the decisions were\ntaken by the product owner in two interviews (2026-09-25 and 2026-10-06)\nand are not to be re-derived; the technical facts were checked against the\nAT Protocol specifications and the Bluesky reference implementation on the\ndates given in §20, and the ones marked <em>verify</em> have to be checked again\nbefore the code that depends on them is written. What phase 1 built, and\nwhere it departs from the letter of this document, is in §18.</p>\n<p><strong>Verified against:</strong> Aloha Social master <code>2eb7b99a9</code> (0.26.121),\nAT Protocol specifications as of 2026-10-06, Bluesky PDS reference\nimplementation (<code>@atproto/pds</code>) 0.4.x, PLC directory API as served by\n<code>plc.directory</code>.</p>\n<p><strong>Relation to PR #2482 (&quot;AT-Proto/Bluesky integration&quot;).</strong> That pull\nrequest is a different product: a Social user <em>links an existing Bluesky\naccount</em> with an app password, and Social mirrors into it and acts from it.\nThe owner decided on 2026-10-06 to keep the two tracks separate. This\nspecification describes <strong>native</strong> identity — Aloha Social <em>is</em> the user&#39;s\nBluesky host — and shares nothing with the linked-account track beyond the\nprotocol library pieces (§4, §5) that both would use. Where the two meet in\nthe user interface (a profile that is both), §11 says which one wins.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":[{"path":"/docs/atproto-the-answer-in-one-paragraph","title":"The answer in one paragraph","description":"Every Aloha Social account becomes a Bluesky account as well, hosted by this Aloha: a did:plc identity whose handle is alice.<instance host>, a signed repository of records that a Bluesky…","parent":false},{"path":"/docs/atproto-decisions","title":"Decisions","description":"Taken by the product owner; the date is the interview. Do not re-ask.","parent":false},{"path":"/docs/atproto-the-protocol-as-far-as-this-app-needs-it","title":"The protocol, as far as this app needs it","description":"Enough of AT Protocol to read the rest; the specifications are at atproto.com and are the authority.","parent":false},{"path":"/docs/atproto-identity","title":"Identity","description":"The DID document the PLC publishes names the handle (§4.2), the signing key under #atproto, and the PDS service #atproto_pds with endpoint https://<instance host> — the Aloha host itself…","parent":false},{"path":"/docs/atproto-the-repository","title":"The repository","description":"Records are built by RecordMapper from the Social model (§8) and validated against the lexicon shapes this app ships as JSON (the lexicon files are vendored under lib/Atproto/lexicons/…","parent":false},{"path":"/docs/atproto-the-xrpc-surface","title":"The XRPC surface","description":"https://<instance host>/xrpc/<nsid> — the DID document's PDS endpoint is the bare host, so the /xrpc/ path has to be at the root. The existing root rules in…","parent":false},{"path":"/docs/atproto-the-firehose","title":"The firehose","description":"One long-running process (D6), a WebSocket server (ratchet/rfc6455 + react/socket, both on Packagist and PHP ≥ 8.1) bound to a local port that the web server proxies at…","parent":false},{"path":"/docs/atproto-outbound-what-a-post-becomes-on-bluesky","title":"Outbound: what a post becomes on Bluesky","description":"Decided shape (D8, D9, D10, D11); the mapping lives in RecordMapper and is pinned by tests against the lexicon validator.","parent":false},{"path":"/docs/atproto-inbound-reading-bluesky","title":"Inbound: reading Bluesky","description":"A handle typed anywhere a handle is accepted — search, the follow box, the alias field — that is not an ActivityPub account is tried as a Bluesky handle: com.atproto.identity.resolveHandle…","parent":false},{"path":"/docs/atproto-being-followed-liked-and-answered-from-bluesky","title":"Being followed, liked and answered from Bluesky","description":"The notification policy (NotificationPolicyService) sees a Bluesky sender like any other: for_not_following holds a like from a Bluesky account the person does not follow, for_new_accounts…","parent":false},{"path":"/docs/atproto-what-the-person-sees","title":"What the person sees","description":"How every Aloha account is also a Bluesky account — identity, repositories, the firehose, moderation and operations.","parent":false},{"path":"/docs/atproto-moderation","title":"Moderation","description":"A labeler's label value definitions (app.bsky.labeler.service record, policies.labelValueDefinitions) are read once per labeler and cached, so a custom label is shown with the labeler's…","parent":false},{"path":"/docs/atproto-moving-a-bluesky-account-here","title":"Moving a Bluesky account here","description":"Its own phase (D19). The AT Protocol account-migration flow, driven from the Migration page as a third card, Bring your Bluesky account here, beside the Fediverse move-in.","parent":false},{"path":"/docs/atproto-operations","title":"Operations","description":"HTTPS on the instance host; a wildcard DNS record *.<host> to the same server and a wildcard certificate (Let's Encrypt DNS-01), for the handle hosts; the root web-server rules (§6.1)…","parent":false},{"path":"/docs/atproto-data-model","title":"Data model","description":"one per local actor: actor_id(_prim), did, handle, custom_handle with custom_handle_checked/_failures (§4.2, phase 4), signing_key (sealed), signing_public, recovery_public, state…","parent":false},{"path":"/docs/atproto-security","title":"Security","description":"Signing and rotation private keys are sealed with the instance secret through PrivateKeyCipher, the same primitive as app passwords; decrypted for one signature and discarded; never…","parent":false},{"path":"/docs/atproto-testing","title":"Testing","description":"A workflow like interop.yml: the official @atproto/dev-env TestNetwork (PLC, PDS, AppView, bsync, Ozone) plus an indigo relay (the dev-env starts none), this app behind the Caddy of the…","parent":false},{"path":"/docs/atproto-phases","title":"Phases","description":"One PR each, each green on its own, each shrinking this document into Architecture/API/OCC-Commands/Admin/User-Guide as it lands (docs stay current).","parent":false},{"path":"/docs/atproto-phase-1-as-built","title":"Phase 1 as built","description":"Everything in the phase 1 row, in lib/Atproto/ (Protocol, Crypto, Lexicon, Identity, Repository, Firehose, Publisher, Xrpc, Service), with these departures from the letter of the sections…","parent":true},{"path":"/docs/atproto-phase-2-as-built","title":"Phase 2 as built","description":"Everything in the phase 2 row, in lib/Atproto/Reader/ (BlueskyActorService, ActorMapper, PostMapper, FacetRenderer, PostStore, FeedPoller, NotificationPoller, BlueskyGraphService…","parent":true},{"path":"/docs/atproto-phase-3-as-it-lands","title":"Phase 3 as it lands","description":"Phase 3 is five concerns, so it lands as five pull requests in this order: 3a interaction (threads, quotes, link cards, deletes both ways, quote rules), 3b moderation (§12.2–12.4), 3c…","parent":true},{"path":"/docs/atproto-phase-4-as-it-lands","title":"Phase 4 as it lands","description":"Five parts, five pull requests: 4a custom handles (§4.2), 4b moving away (§13.2), 4c moving a Bluesky account here (§13.1), 4d Bridgy Fed twins (§13.3), 4e the moved posts in the timeline…","parent":true},{"path":"/docs/atproto-open-questions","title":"Open questions","description":"For the owner, not blocking phase 1:","parent":false},{"path":"/docs/atproto-facts-and-when-they-were-checked","title":"Facts, and when they were checked","description":"Checked 2026-09-25 unless marked; verify means re-check before the code that depends on it is written, because the number or the API has moved before.","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/atproto-the-answer-in-one-paragraph","title":"The answer in one paragraph"},"parent":null},{"slug":"atproto-the-answer-in-one-paragraph","path":"/docs/atproto-the-answer-in-one-paragraph","title":"The answer in one paragraph","description":"Every Aloha Social account becomes a Bluesky account as well, hosted by this Aloha: a did:plc identity whose handle is alice.<instance host>, a signed repository of records that a Bluesky…","group":"atproto","html":"<p>Every Aloha Social account becomes a Bluesky account as well, hosted by this\nAloha: a <code>did:plc</code> identity whose handle is <code>alice.&lt;instance host&gt;</code>, a\nsigned repository of records that a Bluesky relay crawls, and a firehose the\nrelay subscribes to. A Bluesky user finds <code>alice.social.example.com</code> in the\nBluesky app, sees the profile and the public posts, follows, likes, replies\nand quotes — and Alice sees all of that here, in Activities and in her\nthreads, under the same notification policy as everything else. Alice\nfollows Bluesky accounts from here and reads them in her home feed, badged\nbut otherwise ordinary posts. Nothing is required of the person: no Bluesky\naccount, no app password, no switch — the administrator turns Bluesky on for\nthe instance once, with a wildcard DNS record and certificate for the handle\nhost. Direct, followers-only and unlisted posts never leave ActivityPub;\nblocks and mutes are never published; direct messages stay out of scope. An\nexisting Bluesky user can later move their account here, keeping their DID\nand their followers.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"the-answer-in-one-paragraph","manual":false,"prev":{"path":"/docs/atproto","title":"Bluesky and AT Protocol compatibility"},"next":{"path":"/docs/atproto-decisions","title":"Decisions"},"parent":null},{"slug":"atproto-decisions","path":"/docs/atproto-decisions","title":"Decisions","description":"Taken by the product owner; the date is the interview. Do not re-ask.","group":"atproto","html":"<p>Taken by the product owner; the date is the interview. <strong>Do not re-ask.</strong></p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Decision</th>\n<th>Date</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>D1</td>\n<td><strong>Native identity</strong>: Aloha Social is the PDS. No Bluesky account is needed or used. (The linked-account approach of PR #2482 is a separate track.)</td>\n<td>09-25, confirmed 10-06</td>\n</tr>\n<tr>\n<td>D2</td>\n<td><strong>Both directions</strong>: Social → Bluesky and Bluesky → Social.</td>\n<td>09-25</td>\n</tr>\n<tr>\n<td>D3</td>\n<td><strong>Every account, automatically</strong>: each Social account is reachable from Bluesky; the administrator can disable Bluesky instance-wide. No per-user opt-in.</td>\n<td>10-06 (supersedes 09-25&#39;s opt-in)</td>\n</tr>\n<tr>\n<td>D4</td>\n<td>Handles are <strong><code>alice.&lt;instance host&gt;</code></strong> via wildcard DNS and a wildcard certificate; bring-your-own-domain handles are a later phase.</td>\n<td>09-25, fixed 10-06</td>\n</tr>\n<tr>\n<td>D5</td>\n<td><strong><code>did:plc</code> only</strong>, registered at <code>plc.directory</code>.</td>\n<td>09-25</td>\n</tr>\n<tr>\n<td>D6</td>\n<td>The firehose is served by a daemon, <strong><code>occ social:atproto:serve</code></strong>, run under systemd.</td>\n<td>09-25</td>\n</tr>\n<tr>\n<td>D7</td>\n<td><code>/xrpc/</code> reaches the app through the existing root web-server rules (<code>contrib/webserver/*-social-root.conf</code>), like <code>/api/</code> and <code>/oauth/</code>.</td>\n<td>09-25</td>\n</tr>\n<tr>\n<td>D8</td>\n<td><strong>Every public post goes to Bluesky automatically.</strong> Unlisted, followers-only and direct posts never do. No per-post switch.</td>\n<td>10-06</td>\n</tr>\n<tr>\n<td>D9</td>\n<td>A post that does not fit Bluesky is <strong>truncated with a link</strong> to the full post; <strong>first four pictures</strong>; a poll becomes <strong>the question plus a link</strong>; a content warning becomes a <strong>self-label plus a text prefix</strong>. No threads.</td>\n<td>09-25, fixed 10-06</td>\n</tr>\n<tr>\n<td>D10</td>\n<td><strong>Edits</strong>: within a grace period of five minutes the Bluesky record is deleted and recreated; after that the Bluesky copy keeps its text and its likes, and its link leads to the current version here.</td>\n<td>10-06</td>\n</tr>\n<tr>\n<td>D11</td>\n<td><strong>Pictures</strong> go with the first posting phase; <strong>video</strong> through Bluesky&#39;s video service is a later phase, and until then a video post links here.</td>\n<td>10-06</td>\n</tr>\n<tr>\n<td>D12</td>\n<td><strong>Inbound</strong> reads by <strong>polling</strong> the public AppView per followed author, with a cap and backoff; <strong>Jetstream</strong> is an optional daemon an administrator may run for instant delivery on a large instance.</td>\n<td>09-25 polling, 10-06 the optional daemon</td>\n</tr>\n<tr>\n<td>D13</td>\n<td>Bluesky posts appear <strong>in the same timelines</strong>, their authors addressed as bare <code>@alice.bsky.social</code> with a <strong>badge</strong>.</td>\n<td>09-25, confirmed 10-06</td>\n</tr>\n<tr>\n<td>D14</td>\n<td><strong>All Bluesky interactions</strong> (like, repost, follow, reply, mention, quote) show in Activities like their ActivityPub counterparts, under the same <strong>notification policy</strong> and requests inbox.</td>\n<td>10-06</td>\n</tr>\n<tr>\n<td>D15</td>\n<td><strong>Direct messages</strong> are out of scope (Bluesky chat is a separate service).</td>\n<td>10-06</td>\n</tr>\n<tr>\n<td>D16</td>\n<td><strong>Blocks and mutes are never published</strong>; in scope: honour Bluesky&#39;s moderation labels, let users subscribe to labelers, file reports with Bluesky&#39;s moderation service, instance-level blocks of PDS hosts and DIDs.</td>\n<td>09-25, extended 10-06</td>\n</tr>\n<tr>\n<td>D17</td>\n<td>The client API is a PDS: Bluesky apps may log in here, with <code>app.bsky.*</code> proxied to the AppView; no AppView of our own.</td>\n<td>09-25</td>\n</tr>\n<tr>\n<td>D18</td>\n<td>Bridgy Fed twins of local accounts are folded into the native identity (§13.3).</td>\n<td>09-25</td>\n</tr>\n<tr>\n<td>D19</td>\n<td><strong>Moving an existing Bluesky account here</strong> is its own phase.</td>\n<td>10-06</td>\n</tr>\n<tr>\n<td>D20</td>\n<td><strong>Phase 1 makes a Social account visible on Bluesky</strong> (identity, repository, firehose); reading Bluesky from here is phase 2. Four phases, one PR each.</td>\n<td>09-25, order fixed 10-06</td>\n</tr>\n<tr>\n<td>D21</td>\n<td>CI and devel use a self-hosted PLC, <code>@atproto/dev-env</code> and an <code>indigo</code> relay; the real network is exercised by hand only.</td>\n<td>09-25</td>\n</tr>\n</tbody></table></div>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"decisions","manual":false,"prev":{"path":"/docs/atproto-the-answer-in-one-paragraph","title":"The answer in one paragraph"},"next":{"path":"/docs/atproto-the-protocol-as-far-as-this-app-needs-it","title":"The protocol, as far as this app needs it"},"parent":null},{"slug":"atproto-the-protocol-as-far-as-this-app-needs-it","path":"/docs/atproto-the-protocol-as-far-as-this-app-needs-it","title":"The protocol, as far as this app needs it","description":"Enough of AT Protocol to read the rest; the specifications are at atproto.com and are the authority.","group":"atproto","html":"<p>Enough of AT Protocol to read the rest; the specifications are at\natproto.com and are the authority.</p>\n<ul>\n<li><strong>DID</strong>: the permanent identifier of an account, <code>did:plc:…</code> (24\nbase32 characters after the prefix). Resolves, through the PLC directory,\nto a <em>DID document</em> naming the account&#39;s <strong>handle</strong>, its <strong>signing key</strong>,\nits <strong>rotation keys</strong> and its <strong>PDS</strong> service endpoint.</li>\n<li><strong>Handle</strong>: a domain name that <em>points at</em> a DID: either a DNS TXT record\n<code>_atproto.&lt;handle&gt;</code> holding <code>did=did:plc:…</code>, or\n<code>https://&lt;handle&gt;/.well-known/atproto-did</code> answering the DID as text.\nHandles are display and lookup; every reference between records is by\nDID.</li>\n<li><strong>PDS</strong> (personal data server): the host that stores an account&#39;s\n<strong>repository</strong> and accepts its writes. This app is one.</li>\n<li><strong>Repository</strong>: a Merkle search tree (MST) of <strong>records</strong>, keyed by\n<code>&lt;collection&gt;/&lt;rkey&gt;</code>, with a signed <strong>commit</strong> at the root. Every change\nis a new commit; the relay verifies the signature against the DID\ndocument&#39;s signing key.</li>\n<li><strong>Record</strong>: a DAG-CBOR object of a <strong>lexicon</strong> type (<code>$type</code>), e.g.\n<code>app.bsky.feed.post</code>, <code>app.bsky.feed.like</code>, <code>app.bsky.graph.follow</code>,\n<code>app.bsky.actor.profile</code>. Addressed by an <strong>AT URI</strong>\n<code>at://&lt;did&gt;/&lt;collection&gt;/&lt;rkey&gt;</code> and, for the exact version, by its <strong>CID</strong>.\nThe <code>rkey</code> of most records is a <strong>TID</strong> (timestamp id, 13 characters of\nbase32-sortable).</li>\n<li><strong>Blob</strong>: a binary (picture, video) referenced from a record by CID,\nstored by the PDS, fetched through <code>com.atproto.sync.getBlob</code>.</li>\n<li><strong>Relay</strong> (Bluesky&#39;s <code>bsky.network</code>): subscribes to every PDS&#39;s\n<strong>firehose</strong> (<code>com.atproto.sync.subscribeRepos</code>, a WebSocket of commits),\nverifies and republishes them.</li>\n<li><strong>AppView</strong> (<code>api.bsky.app</code>, public read-only mirror <code>public.api.bsky.app</code>):\nindexes the relay&#39;s stream into the views an app asks for — profiles,\nauthor feeds, threads, followers, notifications, search. A PDS proxies\n<code>app.bsky.*</code> client calls to it with a <strong>service auth</strong> token signed by the\nuser&#39;s signing key.</li>\n<li><strong>Jetstream</strong>: Bluesky&#39;s JSON firehose (<code>jetstream*.bsky.network</code>), filterable\nby collection and by author DID (up to 10,000 DIDs per connection), with a\ncursor in microseconds for catching up after a disconnect. <em>verify limits</em></li>\n<li><strong>Labels</strong>: moderation metadata (<code>com.atproto.label.defs#label</code>) emitted by\na <strong>labeler</strong> service; Bluesky&#39;s own moderation service is one, and a user\nmay subscribe to others. A post may also <strong>self-label</strong> (<code>!warn</code>,\n<code>porn</code>, <code>nudity</code>, <code>sexual</code>, <code>graphic-media</code>).</li>\n<li><strong>PLC directory</strong> (<code>plc.directory</code>): the registry of <code>did:plc</code> documents,\nupdated by <strong>operations</strong> signed by a rotation key. The last 72 hours of\noperations can be undone by a higher-priority rotation key.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"the-protocol-as-far-as-this-app-needs-it","manual":false,"prev":{"path":"/docs/atproto-decisions","title":"Decisions"},"next":{"path":"/docs/atproto-identity","title":"Identity"},"parent":null},{"slug":"atproto-identity","path":"/docs/atproto-identity","title":"Identity","description":"The DID document the PLC publishes names the handle (§4.2), the signing key under #atproto, and the PDS service #atproto_pds with endpoint https://<instance host> — the Aloha host itself…","group":"atproto","html":"<h2 id=\"4-1-one-did-per-account\">4.1 One DID per account</h2>\n<p>When Bluesky is enabled for the instance, every local Social actor gets an\nAT Protocol identity, created lazily on first need (the first public post,\nthe first follow of a Bluesky account, the first resolution of its handle)\nand eagerly for every existing account by <code>occ social:atproto:identities</code>.\nThe identity is three things stored in <code>social_atproto_identity</code> (§15):</p>\n<ul>\n<li>the <strong>DID</strong> (<code>did:plc:…</code>), computed by the PLC rules from the genesis\noperation (the DID <em>is</em> a hash of the first operation);</li>\n<li>the <strong>signing key</strong>, secp256k1 (<code>k256</code>), private half sealed with the\ninstance secret the way app passwords are (<code>PrivateKeyCipher</code>), public\nhalf as <code>did:key:z…</code> (multibase, multicodec <code>0xe7</code>);</li>\n<li>two <strong>rotation keys</strong>: the instance&#39;s rotation key (one per instance,\nrotated by the administrator, §16.3) first, and a per-account recovery\nkey whose private half is shown to the person once (§4.4) and otherwise\nnot stored. Order is priority: the instance key wins a dispute.</li>\n</ul>\n<p>The DID document the PLC publishes names the handle (§4.2), the signing\nkey under <code>#atproto</code>, and the PDS service <code>#atproto_pds</code> with endpoint\n<code>https://&lt;instance host&gt;</code> — the Aloha host itself, where <code>/xrpc/</code> is\nserved (§6.1).</p>\n<h2 id=\"4-2-handles\">4.2 Handles</h2>\n<p><code>alice.&lt;instance host&gt;</code>, where the instance host is the hostname of\n<code>social_url</code> (what <code>ConfigService::getSocialAddress()</code> answers) and <code>alice</code>\nis the actor&#39;s <code>preferredUsername</code>. A username that is not a valid DNS\nlabel (Social allows characters a hostname does not: dots, underscores,\nuppercase) is mapped deterministically — lowercase, <code>_</code> and <code>.</code> to <code>-</code>,\ncollapse runs, trim — and the mapping is <strong>stored</strong>, not recomputed, so a\nlater change of the rule cannot rename anybody. Collisions after mapping\nare resolved by a numeric suffix, stored too.</p>\n<p>Resolution is served both ways: <code>https://alice.&lt;host&gt;/.well-known/atproto-did</code>\n(the wildcard certificate and a web-server rule that routes every\n<code>*.&lt;host&gt;/.well-known/atproto-did</code> to the app — a <code>contrib/webserver</code> rule\nbeside the root rules) <strong>and</strong> the DNS TXT record <code>_atproto.alice.&lt;host&gt;</code>\nwhere the administrator runs a DNS server that this app can write to; the\nHTTPS way is the required one, the TXT way is an optimisation the setup\ncheck reports as &quot;available&quot; or not. The app answers the well-known from\nthe stored mapping and nothing else: no lookup by handle pattern, so a\nhandle that was never issued is a 404.</p>\n<p>A later phase lets a person set a <strong>custom handle</strong> on a domain they own\n(they place the TXT record or the well-known file; the app verifies and\nupdates the DID document). The <code>alice.&lt;host&gt;</code> handle keeps resolving to the\nsame DID forever, as an alias the DID document does not list.</p>\n<h2 id=\"4-3-service-identity\">4.3 Service identity</h2>\n<p>The instance itself has a <code>did:web:&lt;instance host&gt;</code> document at\n<code>https://&lt;host&gt;/.well-known/did.json</code> naming the PDS service and its own\nsigning key, which is what service-auth tokens for the relay and the\n<code>requestCrawl</code> call are signed with. One key pair per instance, sealed like\nthe account keys.</p>\n<h2 id=\"4-4-what-the-person-sees-of-their-identity\">4.4 What the person sees of their identity</h2>\n<p>Nothing, unless they look: <strong>Settings → Apps and account → Bluesky</strong> shows the Bluesky\nhandle and DID under the Fediverse handle, with a <em>Copy</em> button and a\nsentence that says the Bluesky account exists because this server offers\none. The recovery key is shown there <strong>once</strong>, on first view, as a\ntwelve-word phrase to write down (BIP-39 encoding of the 32-byte private\nkey), with a &quot;Show again&quot; that requires password confirmation and\nregenerates (and re-registers, §4.5) rather than reveals.</p>\n<h2 id=\"4-5-plc-operations-this-app-sends\">4.5 PLC operations this app sends</h2>\n<ul>\n<li><strong>create</strong>: on first need (§4.1), signed with the instance rotation key.</li>\n<li><strong>update handle</strong>: when the username changes (it does not, in Social, but\nthe custom-handle phase needs it) and when the instance host changes.</li>\n<li><strong>rotate keys</strong>: when the administrator rotates the instance rotation key\n(§16.3) or the person regenerates their recovery key.</li>\n<li><strong>update PDS endpoint</strong>: on a host change, and when an account moves\naway (§13.4).</li>\n<li><strong>tombstone</strong>: when a Social account is deleted. <code>AccountService::deleteActor()</code>\ngains this step; the DID is dead afterwards, as the person asked.</li>\n</ul>\n<p>Every operation goes through one <code>PlcClient</code> with retries and is recorded\nin <code>social_atproto_plc_log</code> before it is sent (so a crash between the two\nleaves a row to reconcile from), and <code>occ social:atproto:plc</code> lists the log\nand the directory&#39;s view side by side.</p>\n","toc":[{"id":"4-1-one-did-per-account","text":"4.1 One DID per account","level":2},{"id":"4-2-handles","text":"4.2 Handles","level":2},{"id":"4-3-service-identity","text":"4.3 Service identity","level":2},{"id":"4-4-what-the-person-sees-of-their-identity","text":"4.4 What the person sees of their identity","level":2},{"id":"4-5-plc-operations-this-app-sends","text":"4.5 PLC operations this app sends","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"identity","manual":false,"prev":{"path":"/docs/atproto-the-protocol-as-far-as-this-app-needs-it","title":"The protocol, as far as this app needs it"},"next":{"path":"/docs/atproto-the-repository","title":"The repository"},"parent":null},{"slug":"atproto-the-repository","path":"/docs/atproto-the-repository","title":"The repository","description":"Records are built by RecordMapper from the Social model (§8) and validated against the lexicon shapes this app ships as JSON (the lexicon files are vendored under lib/Atproto/lexicons/…","group":"atproto","html":"<h2 id=\"5-1-records-this-app-writes\">5.1 Records this app writes</h2>\n<p>Collection → written when:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Collection</th>\n<th>Written</th>\n<th>Content</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>app.bsky.actor.profile</code> (rkey <code>self</code>)</td>\n<td>account created or profile edited</td>\n<td><code>displayName</code>, <code>description</code> (plain text, bio), <code>avatar</code> and <code>banner</code> blobs, <code>createdAt</code></td>\n</tr>\n<tr>\n<td><code>app.bsky.feed.post</code></td>\n<td>public post created (D8)</td>\n<td>§8</td>\n</tr>\n<tr>\n<td><code>app.bsky.feed.like</code></td>\n<td>a local actor likes a post that <strong>exists on Bluesky</strong> (a Bluesky post, or a local post that was published, §8.6)</td>\n<td><code>subject</code> {uri, cid}</td>\n</tr>\n<tr>\n<td><code>app.bsky.feed.repost</code></td>\n<td>a local actor boosts such a post</td>\n<td><code>subject</code> {uri, cid}</td>\n</tr>\n<tr>\n<td><code>app.bsky.graph.follow</code></td>\n<td>a local actor follows a Bluesky account (§9.2)</td>\n<td><code>subject</code> DID</td>\n</tr>\n<tr>\n<td><code>app.bsky.feed.threadgate</code></td>\n<td><em>optional, later</em>: a post&#39;s reply policy maps to one</td>\n<td>who may reply</td>\n</tr>\n<tr>\n<td><code>app.bsky.graph.block</code></td>\n<td><strong>never</strong> (D16)</td>\n<td>—</td>\n</tr>\n<tr>\n<td><code>app.bsky.graph.list*</code>, <code>app.bsky.feed.generator</code>, <code>chat.*</code></td>\n<td>never</td>\n<td>—</td>\n</tr>\n</tbody></table></div>\n<p>Records are built by <code>RecordMapper</code> from the Social model (§8) and\nvalidated against the lexicon shapes this app ships as JSON (the lexicon\nfiles are vendored under <code>lib/Atproto/lexicons/</code>, read at runtime by a\nsmall validator; no code generation).</p>\n<h2 id=\"5-2-storage\">5.2 Storage</h2>\n<p>Two tables (§15): <code>social_atproto_record</code> — one row per live record with\nits collection, rkey, CID, DAG-CBOR bytes, and the Social id it came from\n(<code>local_id</code>, so a post maps to its record in O(1) in both directions) — and\n<code>social_atproto_block</code> — the content-addressed blocks of the MST and the\ncommits, keyed by CID, because the sync endpoints and the firehose serve\nblocks, not rows. The MST is <strong>recomputed in memory from the record table</strong>\nwhen a commit is made, then its new or changed nodes are written to the\nblock table and the unreferenced ones of the previous commit deleted — the\nsimplest correct implementation, and a repository of ten thousand records\nrebuilds in well under a second in PHP; if a measurement says otherwise the\n<code>MST</code> class gets an incremental path, behind the same interface. The MST\nrules (fanout 4, key depth from the leading zero bits of the SHA-256 of the\nkey, two hash bits per level, 32-byte CID v1 <code>dag-cbor</code> SHA-256) are pinned\nby the interop test vectors (§17.1).</p>\n<h2 id=\"5-3-commits\">5.3 Commits</h2>\n<p><code>version: 3</code>, <code>did</code>, <code>data</code> (root MST CID), <code>rev</code> (a TID, strictly\nincreasing per repository), <code>prev: null</code>, <code>sig</code> (64-byte low-S secp256k1\nover the DAG-CBOR of the unsigned commit). One commit per write, written in\nthe same database transaction as the record and the blocks, and one\nfirehose event per commit (§7). A write that fails half-way leaves the\nprevious commit as the repository&#39;s head: the <code>social_atproto_repo</code> row\n(§15) holds the head CID and <code>rev</code>, and it is updated last.</p>\n<h2 id=\"5-4-blobs\">5.4 Blobs</h2>\n<p>A picture or video that a record references is a <strong>blob</strong>: uploaded (§8.4)\nor imported (§13), it is the app&#39;s own stored file (<code>social_cache_doc</code>,\nthrough <code>DocumentService</code>) with a <code>social_atproto_blob</code> row giving its CID\n(SHA-256 of the bytes, <code>raw</code> multicodec), MIME type and size. <code>getBlob</code>\nstreams it; <code>listBlobs</code> lists them per repository; a blob no record refers\nto is deleted by the ordinary document retention. Limits are Bluesky&#39;s:\npictures ≤ 2,000,000 bytes (re-encoded to fit, §8.4), at most four per\npost; a video is one mp4 ≤ 100,000,000 bytes and three minutes, made into\na stream by Bluesky&#39;s video service (D11, built in 3d).</p>\n","toc":[{"id":"5-1-records-this-app-writes","text":"5.1 Records this app writes","level":2},{"id":"5-2-storage","text":"5.2 Storage","level":2},{"id":"5-3-commits","text":"5.3 Commits","level":2},{"id":"5-4-blobs","text":"5.4 Blobs","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"the-repository","manual":false,"prev":{"path":"/docs/atproto-identity","title":"Identity"},"next":{"path":"/docs/atproto-the-xrpc-surface","title":"The XRPC surface"},"parent":null},{"slug":"atproto-the-xrpc-surface","path":"/docs/atproto-the-xrpc-surface","title":"The XRPC surface","description":"https://<instance host>/xrpc/<nsid> — the DID document's PDS endpoint is the bare host, so the /xrpc/ path has to be at the root. The existing root rules in…","group":"atproto","html":"<h2 id=\"6-1-where-it-is-served\">6.1 Where it is served</h2>\n<p><code>https://&lt;instance host&gt;/xrpc/&lt;nsid&gt;</code> — the DID document&#39;s PDS endpoint is\nthe bare host, so the <code>/xrpc/</code> path has to be at the root. The existing\nroot rules in <code>contrib/webserver/apache-social-root.conf</code> and\n<code>nginx-social-root.conf</code> gain one block each, exactly as <code>/api/</code> and\n<code>/oauth/</code> have, rewriting <code>/xrpc/(.*)</code> to <code>/index.php/apps/social/xrpc/$1</code>,\nplus <code>/.well-known/did.json</code> (§4.3) and the wildcard-host\n<code>/.well-known/atproto-did</code> (§4.2). The setup check that pins the rule files\n(see <code>DocumentationTest</code>) is extended; the admin page&#39;s &quot;rules to paste&quot;\nwarning shows the new blocks. <strong>Without the root rules, the instance is not\na PDS</strong>, and the admin page says so in the same words it uses for Mastodon\napps today.</p>\n<h2 id=\"6-2-endpoints\">6.2 Endpoints</h2>\n<p><strong>Served (this app implements them)</strong> — the sync and identity surface a\nrelay and other PDSes need, and the account surface a Bluesky app logging\nin here needs:</p>\n<p><code>com.atproto.sync.getRepo</code>, <code>getLatestCommit</code>, <code>getRecord</code>, <code>getBlob</code>,\n<code>listBlobs</code>, <code>listRepos</code>, <code>getRepoStatus</code>, <code>subscribeRepos</code> (§7);\n<code>com.atproto.identity.resolveHandle</code>, <code>updateHandle</code> (custom handles, later),\n<code>getRecommendedDidCredentials</code>, <code>signPlcOperation</code>, <code>submitPlcOperation</code>,\n<code>requestPlcOperationSignature</code> (§13); <code>com.atproto.server.describeServer</code>,\n<code>createSession</code>, <code>refreshSession</code>, <code>deleteSession</code>, <code>getSession</code>,\n<code>getServiceAuth</code>, <code>checkAccountStatus</code>, <code>activateAccount</code>,\n<code>deactivateAccount</code>, <code>createAccount</code> (migration in only, §13; open\nregistration is <strong>never</strong> offered — a Bluesky account here is an Aloha\naccount); <code>com.atproto.repo.createRecord</code>, <code>putRecord</code>, <code>deleteRecord</code>,\n<code>getRecord</code>, <code>listRecords</code>, <code>describeRepo</code>, <code>uploadBlob</code>, <code>applyWrites</code>,\n<code>importRepo</code>, <code>listMissingBlobs</code>; <code>com.atproto.moderation.createReport</code>\n(proxied, §12.3); <code>com.atproto.label.queryLabels</code> (answers the self-labels\nof local records only); <code>_health</code>.</p>\n<p><strong>Proxied to the AppView</strong> with a service-auth token for the calling user\n(<code>Authorization: Bearer &lt;JWT signed by the user&#39;s signing key, aud did:web:api.bsky.app&gt;</code>): everything under <code>app.bsky.*</code>, and\n<code>chat.bsky.*</code> is refused (D15). The proxy is <code>AppViewClient</code>, the same\nguarded HTTP client as every outbound request (<code>CurlService</code>), with the\nresponse passed through unchanged.</p>\n<p><strong>Not served</strong>: <code>com.atproto.admin.*</code>, <code>com.atproto.temp.*</code>,\n<code>tools.ozone.*</code>, <code>com.atproto.server.createInviteCode*</code>, <code>requestAccountDelete</code>\n(an account is deleted in Aloha), <code>com.atproto.server.requestPasswordReset</code>\n(Aloha&#39;s password is Aloha&#39;s).</p>\n<h2 id=\"6-3-authentication-for-bluesky-apps-d17\">6.3 Authentication for Bluesky apps (D17)</h2>\n<p>Phase 1 serves <code>createSession</code> with <strong>app passwords</strong>: an Aloha app\npassword (Settings → Security) is what a Bluesky app is given as the\npassword, checked through <code>IProvider</code>/<code>IUserManager::checkPassword</code>, which\nis how Aloha&#39;s own clients log in. The session is a pair of JWTs\n(access 2 h, refresh 90 d) signed with the instance service key, carried in\n<code>Authorization: Bearer</code>, with <code>did</code> and <code>handle</code> in the response as Bluesky\napps expect. <strong>OAuth for Bluesky apps</strong> (PAR, DPoP, PKCE S256, client\nmetadata URL — what the official app uses since 2025) is phase 3; until\nthen the official app&#39;s &quot;custom PDS&quot; sign-in works with the app password,\nwhich is what every self-hosted PDS offered before OAuth. The existing\nMastodon OAuth server (<code>OAuthController</code>) is not reused for this: its\ntokens are Social&#39;s client API&#39;s, and the two token worlds stay apart.</p>\n<p>Rate limits: Bluesky&#39;s PDS limits are the model — 3,000 points per hour per\nDID for writes (create 3, update 2, delete 1), 300/5 min per IP on\n<code>createSession</code>; implemented with <code>AnonRateLimit</code>/<code>UserRateLimit</code> and a\n<code>RateLimit-*</code> header answer the way <code>@atproto/pds</code> does. <em>verify current\nnumbers</em></p>\n","toc":[{"id":"6-1-where-it-is-served","text":"6.1 Where it is served","level":2},{"id":"6-2-endpoints","text":"6.2 Endpoints","level":2},{"id":"6-3-authentication-for-bluesky-apps-d17","text":"6.3 Authentication for Bluesky apps (D17)","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"the-xrpc-surface","manual":false,"prev":{"path":"/docs/atproto-the-repository","title":"The repository"},"next":{"path":"/docs/atproto-the-firehose","title":"The firehose"},"parent":null},{"slug":"atproto-the-firehose","path":"/docs/atproto-the-firehose","title":"The firehose","description":"One long-running process (D6), a WebSocket server (ratchet/rfc6455 + react/socket, both on Packagist and PHP ≥ 8.1) bound to a local port that the web server proxies at…","group":"atproto","html":"<h2 id=\"7-1-occ-social-atproto-serve\">7.1 <code>occ social:atproto:serve</code></h2>\n<p>One long-running process (D6), a WebSocket server (<code>ratchet/rfc6455</code> +\n<code>react/socket</code>, both on Packagist and PHP ≥ 8.1) bound to a local port that\nthe web server proxies at <code>/xrpc/com.atproto.sync.subscribeRepos</code>\n(upgrade requests only; the <code>contrib/webserver</code> rules carry the <code>proxy_pass</code>\n/ <code>ProxyPass</code> for that one path). It serves the <strong>sequenced event stream</strong>:\nevery commit (§5.3) is a <code>#commit</code> frame — <code>seq</code>, <code>did</code>, <code>rev</code>, <code>commit</code>\nCID, <code>ops</code> (<code>create</code>/<code>update</code>/<code>delete</code> with path and CID), <code>blocks</code> (the CAR\nof the commit, the changed MST nodes and the records), <code>time</code> — plus\n<code>#identity</code> (handle change), <code>#account</code> (deactivated/deleted) and <code>#info</code>\nframes, each with a <code>seq</code> from one monotonic counter per instance. A client\nthat connects with <code>?cursor=N</code> is replayed from <code>N+1</code> out of\n<code>social_atproto_event</code> (§15), which keeps 72 hours of frames (the relay&#39;s\nreplay window; <em>verify</em>), then followed live.</p>\n<p>The daemon reads new events by polling the event table (every 250 ms when\nidle, immediately after a write it was told about through a Redis/APCu\nnotice where available) — the web request writes the row, the daemon\nserves it; no shared memory, no second code path. <code>--once</code> drains and exits\nfor tests; <code>--max-seconds</code> as <code>social:worker</code> has. systemd unit and the\nDocker variant are documented in Admin.md; the setup check &quot;firehose\nreachable&quot; connects to the public URL and reads an <code>#info</code> frame.</p>\n<h2 id=\"7-2-telling-the-relay\">7.2 Telling the relay</h2>\n<p><code>com.atproto.sync.requestCrawl</code> is sent to the relay (<code>bsky.network</code> by\ndefault, configurable, several allowed) when Bluesky is enabled and after\nthe daemon has been unreachable for more than the replay window. The relay\nthen subscribes, backfills with <code>getRepo</code> per DID, and stays connected. The\nadmin page shows the relay&#39;s last connection and the lag between the head\n<code>seq</code> and what was served.</p>\n<h2 id=\"7-3-backfill-and-consistency\">7.3 Backfill and consistency</h2>\n<p>A record the relay missed (daemon down longer than the window) is\nrecovered by the relay&#39;s own <code>getRepo</code> on reconnect — the sync endpoints are\nthe source of truth, the firehose a notification. The daemon never has to\nbe correct about history; the repository is.</p>\n","toc":[{"id":"7-1-occ-social-atproto-serve","text":"7.1 occ social:atproto:serve","level":2},{"id":"7-2-telling-the-relay","text":"7.2 Telling the relay","level":2},{"id":"7-3-backfill-and-consistency","text":"7.3 Backfill and consistency","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"the-firehose","manual":false,"prev":{"path":"/docs/atproto-the-xrpc-surface","title":"The XRPC surface"},"next":{"path":"/docs/atproto-outbound-what-a-post-becomes-on-bluesky","title":"Outbound: what a post becomes on Bluesky"},"parent":null},{"slug":"atproto-outbound-what-a-post-becomes-on-bluesky","path":"/docs/atproto-outbound-what-a-post-becomes-on-bluesky","title":"Outbound: what a post becomes on Bluesky","description":"Decided shape (D8, D9, D10, D11); the mapping lives in RecordMapper and is pinned by tests against the lexicon validator.","group":"atproto","html":"<p>Decided shape (D8, D9, D10, D11); the mapping lives in <code>RecordMapper</code> and\nis pinned by tests against the lexicon validator.</p>\n<h2 id=\"8-1-which-posts\">8.1 Which posts</h2>\n<p>A local <strong>public</strong> post, at creation, by the same listener that queues\nActivityPub delivery (<code>PostService::createPost()</code> → a <code>PublishToAtproto</code>\nqueued job, so Bluesky never delays the Fediverse). Not: unlisted,\nfollowers-only, direct, a post held for review, a post from a moved account\n(refused by <code>ModerationService::assertNotMoved()</code> before anything), an\narchived post. A team account (§Architecture, teams) publishes like a\nperson.</p>\n<h2 id=\"8-2-text\">8.2 Text</h2>\n<p>Social posts are HTML; Bluesky posts are plain text with <strong>facets</strong>. The\nHTML is converted with the existing <code>plainText</code> helper rules — paragraphs\nto blank lines, <code>&lt;br&gt;</code> to newlines, links kept as their href when the text\nis the href and as <code>text (href)</code> otherwise, mentions and hashtags as their\ntext — then facets are computed on the UTF-8 <strong>byte</strong> offsets of the result:\n<code>#link</code> for every URL, <code>#tag</code> for every <code>#hashtag</code>, <code>#mention</code> for a mention\nof a Bluesky account (resolved to its DID) or of a local account (its own\nDID). A mention of an ActivityPub account that has no Bluesky identity\nbecomes a <code>#link</code> facet to its profile URL.</p>\n<p>The limit is <strong>300 graphemes</strong> and 3,000 bytes. A post over it is cut at\nthe last word boundary before 280 graphemes, <code>…</code> appended, and the link to\nthe post here (<code>$post-&gt;getUrl()</code>) added on its own line with a <code>#link</code>\nfacet — always, so the truncated post is never the whole of what somebody\nsees. The counter in the composer is unchanged (Social&#39;s own limit), but a\nhint under it says &quot;Bluesky shows the first 280 characters and a link&quot;\nwhen crossed.</p>\n<h2 id=\"8-3-warnings-polls-quotes-replies\">8.3 Warnings, polls, quotes, replies</h2>\n<ul>\n<li><strong>Content warning</strong> (<code>spoiler_text</code>): self-label <code>!warn</code> plus the warning\nas the first line, <code>CW: &lt;warning&gt;</code> then a blank line, counted against the<ol start=\"300\">\n<li>A Social post marked sensitive also gets <code>graphic-media</code> on its\npictures as a self-label when it carries pictures. <em>verify label set</em></li>\n</ol>\n</li>\n<li><strong>Poll</strong>: the question and options as text (<code>Poll: … — A / B / C</code>), then\nthe link; results are not synchronised.</li>\n<li><strong>Quote</strong> of a Bluesky post, or of a local post that was published:\n<code>embed</code> <code>app.bsky.embed.record</code> with the quoted {uri, cid}; of anything\nelse: the quoted post&#39;s URL as a <code>#link</code> and an <code>app.bsky.embed.external</code>\ncard built from Social&#39;s own link preview (<code>StreamCard</code>).</li>\n<li><strong>Reply</strong> to a Bluesky post, or to a local post that was published:\n<code>reply: {root: {uri,cid}, parent: {uri,cid}}</code> with the root found by\nwalking <code>in_reply_to</code> through <code>social_atproto_record</code> and the Bluesky\nthread (the AppView&#39;s <code>getPostThread</code> when the parent is remote). A reply\nto a post that is not on Bluesky is published as a top-level post with\nthe parent&#39;s URL as a <code>#link</code> — the thread cannot be joined, and saying\nnothing would hide the post.</li>\n<li><strong>Language</strong>: <code>langs: [&lt;post language&gt;]</code> when known.</li>\n<li><strong>Link card</strong>: when the post has a <code>StreamCard</code> and no pictures,\n<code>app.bsky.embed.external</code> with title, description and the preview image\nas a blob (fetched through the cache, resized to ≤ 2 MB).</li>\n</ul>\n<h2 id=\"8-4-pictures\">8.4 Pictures</h2>\n<p>Up to four <code>media_attachments</code> of image type, in order; more are dropped\nand the text gains a line &quot;+N more pictures&quot; before the link. Each is\nre-encoded to fit <strong>2,000,000 bytes</strong> — JPEG at descending quality, then\ndownscaled — through <code>gumlet/php-image-resize</code> which the app already\ndepends on, uploaded as a blob (§5.4), and placed in\n<code>app.bsky.embed.images</code> with its <code>alt</code> (the Social description) and\n<code>aspectRatio</code>. A post with pictures and a link card keeps the pictures.</p>\n<h2 id=\"8-5-edits-and-deletes\">8.5 Edits and deletes</h2>\n<p><strong>Delete</strong>: <code>deleteRecord</code> of the post, and of the likes and reposts local\nactors made of it, in the same job that sends the ActivityPub <code>Delete</code>.</p>\n<p><strong>Edit</strong> (D10): if the post is less than five minutes old (<code>created_at</code>),\nthe record is deleted and a new one created with the new content — a new\nrkey, so the AT URI changes; replies that already referenced the old URI\non Bluesky dangle, which is why the grace period is short. Later than five\nminutes the Bluesky record is left as it is; the link in it keeps pointing\nat the post here, which shows the current text. The post menu&#39;s <em>Delivery\nstatus</em> dialog says which of the two happened.</p>\n<h2 id=\"8-6-likes-boosts-follows\">8.6 Likes, boosts, follows</h2>\n<p>A local like of a post that exists on Bluesky writes <code>app.bsky.feed.like</code>\n(unlike deletes it); a boost, <code>app.bsky.feed.repost</code>; a follow of a Bluesky\naccount, <code>app.bsky.graph.follow</code> (unfollow deletes it). &quot;Exists on\nBluesky&quot; means the post is either a Bluesky post (its stream row carries an\n<code>at://</code> id, §9.3) or a local post with a <code>social_atproto_record</code> row. A like\nof an ActivityPub-only post writes nothing. These go through the same\nqueued publisher and are reflected in the viewer flags the status entity\nalready carries (<code>favourited</code>, <code>reblogged</code>) — one action, two networks.</p>\n","toc":[{"id":"8-1-which-posts","text":"8.1 Which posts","level":2},{"id":"8-2-text","text":"8.2 Text","level":2},{"id":"8-3-warnings-polls-quotes-replies","text":"8.3 Warnings, polls, quotes, replies","level":2},{"id":"8-4-pictures","text":"8.4 Pictures","level":2},{"id":"8-5-edits-and-deletes","text":"8.5 Edits and deletes","level":2},{"id":"8-6-likes-boosts-follows","text":"8.6 Likes, boosts, follows","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"outbound-what-a-post-becomes-on-bluesky","manual":false,"prev":{"path":"/docs/atproto-the-firehose","title":"The firehose"},"next":{"path":"/docs/atproto-inbound-reading-bluesky","title":"Inbound: reading Bluesky"},"parent":null},{"slug":"atproto-inbound-reading-bluesky","path":"/docs/atproto-inbound-reading-bluesky","title":"Inbound: reading Bluesky","description":"A handle typed anywhere a handle is accepted — search, the follow box, the alias field — that is not an ActivityPub account is tried as a Bluesky handle: com.atproto.identity.resolveHandle…","group":"atproto","html":"<h2 id=\"9-1-resolving-a-bluesky-account\">9.1 Resolving a Bluesky account</h2>\n<p>A handle typed anywhere a handle is accepted — search, the follow box, the\nalias field — that is not an ActivityPub account is tried as a Bluesky\nhandle: <code>com.atproto.identity.resolveHandle</code> (through the public AppView,\nthen DNS/HTTPS directly as a fallback), the DID document from\n<code>plc.directory</code> (or <code>did:web</code>), then <code>app.bsky.actor.getProfile</code>. The\nresult is a <strong>cached actor</strong> (<code>social_cache_actor</code>) with id <code>at://&lt;did&gt;</code>,\naccount <code>alice.bsky.social</code> (the handle, no <code>@…@</code> form), type <code>Person</code>,\n<code>host</code> the handle&#39;s host, the profile fields mapped (<code>displayName</code> →\nname, <code>description</code> → summary as plain text, avatar and banner as cached\ndocuments, <code>followersCount</code>/<code>followsCount</code>/<code>postsCount</code> into the counts),\nand a <code>details.atproto</code> block with the DID, the PDS endpoint and the\nlabels. The cache refresh cron (<code>manageCacheRemoteActors</code>) refreshes it\nthrough <code>getProfile</code> the way it refreshes an ActivityPub actor through its\nactor document, same bookkeeping columns. <code>CacheActorService::getFromAccount()</code>\nis the one entry point and learns the <code>at://</code> scheme; everything that\nalready displays a cached actor displays this one (D13).</p>\n<p>The <strong>search</strong> and <strong>directory</strong> code paths (<code>FediverseDirectoryService</code>)\ngain a <code>bluesky</code> source: <code>app.bsky.actor.searchActorsTypeahead</code> on the\npublic AppView, unauthenticated, marked in the results like the other\nsources.</p>\n<h2 id=\"9-2-following\">9.2 Following</h2>\n<p>A follow of a Bluesky account writes <code>app.bsky.graph.follow</code> in the local\nactor&#39;s repository (§8.6) and a <code>social_follows</code> row as for any follow —\naccepted immediately, since Bluesky has no follow requests — and a\n<strong>watch</strong> row (<code>social_atproto_watch</code>: DID, cursor, timing, failures). The\nfollower count on the Bluesky side is the AppView&#39;s business and appears\nthere within minutes of the relay indexing the commit.</p>\n<h2 id=\"9-3-polling-d12\">9.3 Polling (D12)</h2>\n<p><code>Cron\\AtprotoSync</code> (a <code>TimedJob</code>, every two minutes) takes the watches due\n(<code>next_sync &lt;= now</code>), at most <code>SYNC_BATCH</code> per pass and at most the\ninstance-wide <code>atproto_sync_ceiling</code> (default 200 requests per pass; the\nadmin page shows how far behind the slowest watch is), and asks the public\nAppView <code>app.bsky.feed.getAuthorFeed</code> for each (<code>filter=posts_with_replies</code>,\n<code>limit=50</code>, the stored cursor): new posts are stored, the cursor advanced,\n<code>next_sync</code> set by backoff — one interval after a page with posts, doubling\nup to six hours after empty pages, reset by the next post. Reposts in the\nfeed become boosts (<code>Announce</code>) by the Bluesky author; replies are stored\nwith their <code>in_reply_to</code> and the parent fetched through <code>getPostThread</code>\nwhen it is not here (bounded, one hop per pass). Only the public AppView is\nread, unauthenticated, which is why nothing a Bluesky user kept to\nthemselves can arrive.</p>\n<p>A Bluesky post is a stream row of type <code>Note</code> with id <code>at://…/app.bsky.feed.post/…</code>\n(<code>id_prim</code> as for any id), <code>url</code> the <code>https://bsky.app/profile/&lt;handle&gt;/post/&lt;rkey&gt;</code>\nlink, <code>attributed_to</code> the cached actor, <code>content</code> rebuilt from text and\nfacets (links and mentions as anchors, hashtags as hashtag links), pictures\nas <code>social_cache_doc</code> rows pointing at the AppView&#39;s CDN URL with the\nblob&#39;s CID and alt text, a quote as <code>quoted_id</code>, a reply as <code>in_reply_to</code>,\nlabels as <code>summary</code> (content warning) or <code>sensitive</code> per §12.1, <code>published</code>\nfrom <code>indexedAt</code>, <code>local</code> false, and <code>details.atproto</code> with the CID and\nthe like/repost/reply counts the AppView reported. It goes through\n<code>ImportService::parseIncomingRequest()</code> as a synthetic <code>Create</code>, so every\nside effect of an arriving post — recipients, <code>social_stream_dest</code>,\nnotifications, filters, interests — happens the way it happens for\nActivityPub; nothing downstream knows a Bluesky post from any other.</p>\n<h2 id=\"9-4-jetstream-optional\">9.4 Jetstream (optional)</h2>\n<p><code>occ social:atproto:listen</code>: one WebSocket to a Jetstream instance,\n<code>wantedCollections=app.bsky.feed.post,app.bsky.feed.repost,app.bsky.feed.like,app.bsky.graph.follow</code>,\n<code>wantedDids</code> the watched DIDs <strong>and the local DIDs</strong> (§10), re-sent as a\n<code>#options_update</code> when a watch is added, cursor persisted every second.\nEach event is handed to the same storer the poller uses; the poller keeps\nrunning, backing off watches the listener keeps current, so the daemon\nbeing down costs latency and nothing else. Over 10,000 DIDs the listener\nopens a second connection. <em>verify the per-connection limit</em></p>\n<h2 id=\"9-5-deletes-and-edits-from-bluesky\">9.5 Deletes and edits from Bluesky</h2>\n<p>A <code>delete</code> op from Jetstream, or a post gone from the author feed on the\nnext poll (the AppView answers 404 for <code>getPosts</code> of it — checked for the\nlast page&#39;s ids once a day, bounded), becomes a <code>Delete</code> through the same\nimport path, as a remote <code>Delete</code> would. Bluesky has no edits.</p>\n","toc":[{"id":"9-1-resolving-a-bluesky-account","text":"9.1 Resolving a Bluesky account","level":2},{"id":"9-2-following","text":"9.2 Following","level":2},{"id":"9-3-polling-d12","text":"9.3 Polling (D12)","level":2},{"id":"9-4-jetstream-optional","text":"9.4 Jetstream (optional)","level":2},{"id":"9-5-deletes-and-edits-from-bluesky","text":"9.5 Deletes and edits from Bluesky","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"inbound-reading-bluesky","manual":false,"prev":{"path":"/docs/atproto-outbound-what-a-post-becomes-on-bluesky","title":"Outbound: what a post becomes on Bluesky"},"next":{"path":"/docs/atproto-being-followed-liked-and-answered-from-bluesky","title":"Being followed, liked and answered from Bluesky"},"parent":null},{"slug":"atproto-being-followed-liked-and-answered-from-bluesky","path":"/docs/atproto-being-followed-liked-and-answered-from-bluesky","title":"Being followed, liked and answered from Bluesky","description":"The notification policy (NotificationPolicyService) sees a Bluesky sender like any other: for_not_following holds a like from a Bluesky account the person does not follow, for_new_accounts…","group":"atproto","html":"<p>As a PDS this app is <strong>not told</strong> when somebody on Bluesky follows, likes,\nreposts or replies to a local account: those are records in <em>their</em>\nrepositories, indexed by the AppView. Two sources, both used:</p>\n<ul>\n<li><strong>Jetstream</strong> (when the listener runs, §9.4) with the local DIDs in\n<code>wantedDids</code> sees follows, likes and reposts <em>by</em> those DIDs — which is\nthe local side — not <em>of</em> them. It does see a reply or quote <em>by a\nwatched author</em>. So Jetstream alone is not enough.</li>\n<li><strong>The AppView&#39;s notifications</strong>: <code>app.bsky.notification.listNotifications</code>,\ncalled <em>as the local user</em> with a service-auth token (§6.2), lists\nfollows, likes, reposts, replies, mentions and quotes of that user&#39;s\nrecords, with a cursor. <code>Cron\\AtprotoNotifications</code> polls it for every\nlocal account that has a Bluesky identity, with the same backoff as the\nwatches (an account nobody on Bluesky interacts with is asked twice a\nday), and the ceiling shared with §9.3.</li>\n</ul>\n<p>Each notification becomes the corresponding Social event by the import\npath, so <strong>D14</strong> holds without a second notification system:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Bluesky</th>\n<th>Here</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>follow</code></td>\n<td>a <code>Follow</code> from the cached actor, accepted (Bluesky follows need no acceptance); the follower appears in the followers list and count; <strong>their posts are not fetched</strong> by this alone — only if a local actor follows them back</td>\n</tr>\n<tr>\n<td><code>like</code></td>\n<td>a <code>Like</code> → favourite notification, count on the post</td>\n</tr>\n<tr>\n<td><code>repost</code></td>\n<td>an <code>Announce</code> → boost notification, count</td>\n</tr>\n<tr>\n<td><code>reply</code></td>\n<td>the reply post is fetched (<code>getPostThread</code>), stored with <code>in_reply_to</code>, a mention/reply notification follows</td>\n</tr>\n<tr>\n<td><code>mention</code></td>\n<td>the post is fetched and stored; a mention notification</td>\n</tr>\n<tr>\n<td><code>quote</code></td>\n<td>the quoting post is fetched; a quote notification (Social has quote notifications already)</td>\n</tr>\n<tr>\n<td><code>starterpack-joined</code>, <code>verified</code>, <code>unverified</code></td>\n<td>ignored</td>\n</tr>\n</tbody></table></div>\n<p>The <strong>notification policy</strong> (<code>NotificationPolicyService</code>) sees a Bluesky\nsender like any other: <code>for_not_following</code> holds a like from a Bluesky\naccount the person does not follow, <code>for_new_accounts</code> reads the DID\ndocument&#39;s creation time (the first PLC operation&#39;s <code>createdAt</code>) as the\naccount age, and the requests inbox shows the sender with the badge.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"being-followed-liked-and-answered-from-bluesky","manual":false,"prev":{"path":"/docs/atproto-inbound-reading-bluesky","title":"Inbound: reading Bluesky"},"next":{"path":"/docs/atproto-what-the-person-sees","title":"What the person sees"},"parent":null},{"slug":"atproto-what-the-person-sees","path":"/docs/atproto-what-the-person-sees","title":"What the person sees","description":"How every Aloha account is also a Bluesky account — identity, repositories, the firehose, moderation and operations.","group":"atproto","html":"<ul>\n<li><strong>Profiles</strong>: a Bluesky account&#39;s profile is the ordinary profile page at\n<code>/@alice.bsky.social</code> (the handle has no second <code>@</code>, which is how the\nrouter tells it apart), the follow button, the counts, the posts from\nthe author feed (fetched live and paged by the AppView cursor when the\naccount is not watched), and a <strong>Bluesky badge</strong> next to the name — the\nbutterfly glyph with <code>title=&quot;On Bluesky&quot;</code>, the same place the verified\ntick sits. The badge appears on every card the author appears in: post\nheader, notification, follower list, search result.</li>\n<li><strong>Addressing</strong>: <code>@alice.bsky.social</code> in a post mentions the Bluesky\naccount; the composer&#39;s mention picker completes Bluesky handles from the\nAppView typeahead when the typed text has a dot and no second <code>@</code>.</li>\n<li><strong>The person&#39;s own profile</strong> shows both handles under the name, each\nwith <em>Copy</em>; the Bluesky one links to <code>https://bsky.app/profile/&lt;handle&gt;</code>.\nNo switch between &quot;Fediverse&quot; and &quot;Bluesky&quot; views: one account, one\nprofile, one feed (D1, D13). PR #2482&#39;s network switch belongs to its\nown product and is not part of this one.</li>\n<li><strong>Composer</strong>: the counter hint of §8.2; nothing else. There is no target\npicker (D8).</li>\n<li><strong>Post</strong>: a Bluesky post&#39;s permalink menu entry <em>Open on Bluesky</em>; the\nlike/boost/reply/quote buttons do what they do, writing the records of\n§8.6. Reply to a Bluesky post from here → published as a reply (§8.3).</li>\n<li><strong>Activities</strong>: Bluesky events with the badge on the actor; the filter\nswitcher gains no entry (D14 chose &quot;mixed&quot;, not &quot;separate&quot;).</li>\n<li><strong>Settings → Apps and account → Bluesky</strong>: the Bluesky handle/DID block and the\nrecovery phrase (§4.4). <strong>Settings → Blocking</strong>: labelers (§12.2).</li>\n<li><strong>Admin settings</strong>: the Bluesky section (§14.2).</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"what-the-person-sees","manual":false,"prev":{"path":"/docs/atproto-being-followed-liked-and-answered-from-bluesky","title":"Being followed, liked and answered from Bluesky"},"next":{"path":"/docs/atproto-moderation","title":"Moderation"},"parent":null},{"slug":"atproto-moderation","path":"/docs/atproto-moderation","title":"Moderation","description":"A labeler's label value definitions (app.bsky.labeler.service record, policies.labelValueDefinitions) are read once per labeler and cached, so a custom label is shown with the labeler's…","group":"atproto","html":"<h2 id=\"12-1-labels-on-what-arrives-d16\">12.1 Labels on what arrives (D16)</h2>\n<p>Bluesky&#39;s moderation service (<code>did:plc:ar7c4by46qjdydhdevvrndac</code>) labels\nposts and accounts; the AppView attaches the labels to what it answers.\nMapping, applied when a Bluesky post is stored (§9.3) and when a cached\nactor is refreshed:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Label</th>\n<th>Here</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>porn</code>, <code>sexual</code>, <code>nudity</code>, <code>graphic-media</code></td>\n<td><code>sensitive: true</code> on the post&#39;s pictures, and a content warning naming the label when the post had none</td>\n</tr>\n<tr>\n<td><code>!warn</code> (self or service)</td>\n<td>content warning (the post&#39;s own text prefix is kept)</td>\n</tr>\n<tr>\n<td><code>!hide</code> (service)</td>\n<td>the post is not stored; the account&#39;s posts are not fetched while the label stands</td>\n</tr>\n<tr>\n<td><code>spam</code>, <code>impersonation</code>, <code>scam</code>, <code>misleading</code>, other service labels</td>\n<td>a content warning naming the label; the account&#39;s profile shows it</td>\n</tr>\n<tr>\n<td>account-level <code>!hide</code> / takedown</td>\n<td>the cached actor is marked limited: no posts fetched, interactions not announced</td>\n</tr>\n</tbody></table></div>\n<p>A labeler&#39;s label value definitions (<code>app.bsky.labeler.service</code> record,\n<code>policies.labelValueDefinitions</code>) are read once per labeler and cached, so\na custom label is shown with the labeler&#39;s own name and severity.</p>\n<h2 id=\"12-2-subscribing-to-labelers\">12.2 Subscribing to labelers</h2>\n<p><strong>Settings → Blocking → Labelers</strong>: the list of labelers the person\nsubscribes to (Bluesky&#39;s moderation service is always there and cannot be\nremoved, as on Bluesky), add by handle or DID, with each label value&#39;s\nsetting <em>ignore / warn / hide</em> as the labeler defines its defaults. Stored\nper user (<code>social_atproto_labeler</code>), applied in <code>FilterService</code> as a filter\nsource — which is where hiding already happens for words and for posts\nmade with AI — and sent along as <code>atproto-accept-labelers</code> on the AppView\ncalls made for that user, so the AppView&#39;s own answers (threads, search)\ncome labelled the way the person asked.</p>\n<h2 id=\"12-3-reporting\">12.3 Reporting</h2>\n<p><em>Report</em> on a Bluesky post or account files the local report as today and,\nwhen the person ticks &quot;also report to Bluesky&#39;s moderation service&quot; (on by\ndefault for Bluesky content), a <code>com.atproto.moderation.createReport</code>\nproxied to the labeler (<code>atproto-proxy: &lt;labeler did&gt;#atproto_labeler</code>)\nwith the reason mapped (<code>spam</code> → <code>com.atproto.moderation.defs#reasonSpam</code>,\netc.) and the report&#39;s reference. The report row records the Bluesky\nreport id.</p>\n<h2 id=\"12-4-blocks-mutes-instance-blocks\">12.4 Blocks, mutes, instance blocks</h2>\n<p>Local blocks and mutes of Bluesky accounts work as they do for anybody —\nstored in <code>social_actor_relation</code>, applied on read — and are <strong>never\nwritten as <code>app.bsky.graph.block</code></strong> (D16); a blocked Bluesky account&#39;s\ninteractions are dropped on arrival. A Bluesky user&#39;s public block <em>of</em> a\nlocal account is read from their repository when it is encountered (the\nAppView says <code>viewer.blockedBy</code>) and honoured: no replies, no quotes of\ntheir posts are published by the blocked local account.</p>\n<p>The administrator&#39;s federation blocklist gains Bluesky: a blocked <strong>PDS\nhost</strong> or <strong>DID</strong> (<code>social_atproto_blocklist</code>, managed on the admin page and\nby <code>occ social:atproto:block</code>) is refused on resolution, its posts not\nfetched, its interactions dropped. The whole network is switched off by\nthe instance switch (§14.2), which keeps the repositories but stops the\ndaemon, the crons and the publisher.</p>\n","toc":[{"id":"12-1-labels-on-what-arrives-d16","text":"12.1 Labels on what arrives (D16)","level":2},{"id":"12-2-subscribing-to-labelers","text":"12.2 Subscribing to labelers","level":2},{"id":"12-3-reporting","text":"12.3 Reporting","level":2},{"id":"12-4-blocks-mutes-instance-blocks","text":"12.4 Blocks, mutes, instance blocks","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"moderation","manual":false,"prev":{"path":"/docs/atproto-what-the-person-sees","title":"What the person sees"},"next":{"path":"/docs/atproto-moving-a-bluesky-account-here","title":"Moving a Bluesky account here"},"parent":null},{"slug":"atproto-moving-a-bluesky-account-here","path":"/docs/atproto-moving-a-bluesky-account-here","title":"Moving a Bluesky account here","description":"Its own phase (D19). The AT Protocol account-migration flow, driven from the Migration page as a third card, Bring your Bluesky account here, beside the Fediverse move-in.","group":"atproto","html":"<p>Its own phase (D19). The AT Protocol account-migration flow, driven from\nthe Migration page as a third card, <strong>Bring your Bluesky account here</strong>,\nbeside the Fediverse move-in.</p>\n<h2 id=\"13-1-the-flow\">13.1 The flow</h2>\n<ol>\n<li>The person types their Bluesky handle and app password (never stored\nbeyond the run; Bluesky OAuth later). The old PDS is resolved from the\nDID document.</li>\n<li><strong>Create the account here with the existing DID</strong>:\n<code>com.atproto.server.getServiceAuth</code> on the old PDS (aud this instance&#39;s\nservice DID, lxm <code>com.atproto.server.createAccount</code>), then\n<code>createAccount</code> here with that token and the DID — the account exists\nhere <em>deactivated</em>. The DID is bound to the Aloha user; the local\nactor&#39;s own <code>did:plc</code> is <strong>not</strong> created, the moved DID is its identity.</li>\n<li><strong>Repository</strong>: <code>com.atproto.sync.getRepo</code> from the old PDS, imported\nwith <code>importRepo</code> into this one; <code>listMissingBlobs</code> here, each fetched\nwith <code>getBlob</code> from the old PDS and <code>uploadBlob</code> here; preferences via\n<code>app.bsky.actor.getPreferences</code>/<code>putPreferences</code>. Runs as a queued import\n(<code>ImportQueueService</code>, kind <code>bluesky_move</code>), progress on the page.</li>\n<li><strong>Identity</strong>: <code>getRecommendedDidCredentials</code> here (our signing key, our\nrotation key, the new handle <code>alice.&lt;host&gt;</code>, our PDS endpoint);\n<code>requestPlcOperationSignature</code> on the old PDS (Bluesky e-mails the\nperson a code), the person enters the code, <code>signPlcOperation</code> on the\nold PDS, <code>submitPlcOperation</code> here.</li>\n<li><strong>Activate</strong>: <code>activateAccount</code> here, <code>deactivateAccount</code> on the old\nPDS. The followers follow the DID and need do nothing; the handle\nchanges to <code>alice.&lt;host&gt;</code> unless the person owns a domain and sets a\ncustom handle (later phase).</li>\n<li>The imported posts become local stream rows (§9.3&#39;s mapping, attributed\nto the local actor), the follows become watches and <code>social_follows</code>\nrows, the likes and reposts become actions — through the import path,\nnothing re-published.</li>\n</ol>\n<h2 id=\"13-2-moving-away\">13.2 Moving away</h2>\n<p>The mirror image, so a person is not locked in: <code>Settings → Migration → Move your Bluesky account away</code> performs steps 2–5 from the other side\n(this instance is the <em>old</em> PDS: it serves <code>getServiceAuth</code>,\n<code>requestPlcOperationSignature</code> by Aloha e-mail, <code>signPlcOperation</code>,\n<code>deactivateAccount</code>). The Fediverse account is untouched; after the move\nthe local actor has no Bluesky identity until §4.1 creates a fresh one —\nwhich it does not do automatically for a moved-away account (flag on the\nidentity row), so the person is not silently given a second Bluesky\naccount.</p>\n<h2 id=\"13-3-bridgy-fed-twins-d18\">13.3 Bridgy Fed twins (D18)</h2>\n<p>An account that was bridged to Bluesky by Bridgy Fed has a Bluesky\nidentity <code>alice.social.example.com.ap.brid.gy</code> with its own <code>did:plc</code> and\nfollowers. Folding it in is the move-in of §13.1 with Bridgy as the old\nPDS — Bridgy Fed supports account migration out — so the followers come\nalong; the page offers it when the handle resolves to a <code>*.ap.brid.gy</code>\nDID, and tells the person to turn the bridge off afterwards.</p>\n","toc":[{"id":"13-1-the-flow","text":"13.1 The flow","level":2},{"id":"13-2-moving-away","text":"13.2 Moving away","level":2},{"id":"13-3-bridgy-fed-twins-d18","text":"13.3 Bridgy Fed twins (D18)","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"moving-a-bluesky-account-here","manual":false,"prev":{"path":"/docs/atproto-moderation","title":"Moderation"},"next":{"path":"/docs/atproto-operations","title":"Operations"},"parent":null},{"slug":"atproto-operations","path":"/docs/atproto-operations","title":"Operations","description":"HTTPS on the instance host; a wildcard DNS record *.<host> to the same server and a wildcard certificate (Let's Encrypt DNS-01), for the handle hosts; the root web-server rules (§6.1)…","group":"atproto","html":"<h2 id=\"14-1-requirements\">14.1 Requirements</h2>\n<p>HTTPS on the instance host; a <strong>wildcard DNS record</strong> <code>*.&lt;host&gt;</code> to the\nsame server and a <strong>wildcard certificate</strong> (Let&#39;s Encrypt DNS-01), for the\nhandle hosts; the <strong>root web-server rules</strong> (§6.1) including the WebSocket\nproxy for the firehose; the <strong>daemon</strong> <code>occ social:atproto:serve</code> under\nsystemd (or the container&#39;s supervisor); <code>cron</code> background jobs (already\nrequired); PHP <code>gmp</code> (for <code>paragonie/ecc</code>) and <code>sodium</code>. Each is a <strong>setup\ncheck</strong> on the admin page and in <code>occ social:check:install</code>, with the fix\nspelled out, and Bluesky cannot be switched on while one fails.</p>\n<h2 id=\"14-2-admin-page\">14.2 Admin page</h2>\n<p>A <strong>Bluesky</strong> section: the instance switch (D3), the handle host (read\nfrom <code>social_url</code>, with the wildcard checks beside it), the relay(s), the\nJetstream endpoint and whether the listener is running, the service DID,\nthe instance rotation key&#39;s age and a <em>Rotate</em> button (§16.3), the sync\nceiling and the current lag, counts (identities, records, blobs, watches,\nevents in the window), the PDS/DID blocklist (§12.4), and the state of\neach daemon (last frame served, last event seen, pid, uptime). The same\nnumbers on the Statistics page&#39;s agency view, labelled.</p>\n<h2 id=\"14-3-commands\">14.3 Commands</h2>\n<p><code>social:atproto:serve</code> (§7.1), <code>social:atproto:listen</code> (§9.4),\n<code>social:atproto:identities</code> (create missing identities; <code>--user</code>),\n<code>social:atproto:plc</code> (log and directory view, <code>--repair</code>),\n<code>social:atproto:resolve &lt;handle|did&gt;</code>, <code>social:atproto:repo &lt;user&gt;</code>\n(head, record counts, <code>--verify</code> recomputes the MST and compares),\n<code>social:atproto:block &lt;host|did&gt;</code> / <code>--unblock</code>, <code>social:atproto:crawl</code>\n(<code>requestCrawl</code> now), <code>social:atproto:rotate-key</code>. Each documented in\nOCC-Commands.md with the usual shape.</p>\n<h2 id=\"14-4-configuration\">14.4 Configuration</h2>\n<p>App values: <code>atproto_enabled</code>, <code>atproto_relays</code> (JSON list),\n<code>atproto_jetstream</code>, <code>atproto_sync_ceiling</code>, <code>atproto_plc_directory</code>\n(default <code>https://plc.directory</code>, the dev-env&#39;s in CI), <code>atproto_appview</code>\n(default <code>https://public.api.bsky.app</code> for reads, <code>https://api.bsky.app</code>\nfor the proxy), <code>atproto_video_service</code> and <code>atproto_video_service_did</code>\n(default <code>https://video.bsky.app</code>, <code>did:web:video.bsky.app</code>; an empty\naddress publishes a video post as a link). Secrets (keys) in their\ntables, sealed; never in app values.</p>\n<h2 id=\"14-5-backups\">14.5 Backups</h2>\n<p>The instance rotation key and the account signing keys are <strong>the\nidentities</strong>: losing them loses the ability to update the DIDs (the\nrecovery phrase, §4.4, is the person&#39;s way back; the PLC&#39;s 72-hour window\nis the administrator&#39;s). Admin.md gets a section: back up the database\n<em>and</em> the instance secret, and what to do after a restore from an older\nbackup (the firehose <code>seq</code> goes backwards → <code>requestCrawl</code> and the relay\nre-syncs from <code>getRepo</code>).</p>\n","toc":[{"id":"14-1-requirements","text":"14.1 Requirements","level":2},{"id":"14-2-admin-page","text":"14.2 Admin page","level":2},{"id":"14-3-commands","text":"14.3 Commands","level":2},{"id":"14-4-configuration","text":"14.4 Configuration","level":2},{"id":"14-5-backups","text":"14.5 Backups","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"operations","manual":false,"prev":{"path":"/docs/atproto-moving-a-bluesky-account-here","title":"Moving a Bluesky account here"},"next":{"path":"/docs/atproto-data-model","title":"Data model"},"parent":null},{"slug":"atproto-data-model","path":"/docs/atproto-data-model","title":"Data model","description":"one per local actor: actor_id(_prim), did, handle, custom_handle with custom_handle_checked/_failures (§4.2, phase 4), signing_key (sealed), signing_public, recovery_public, state…","group":"atproto","html":"<p>New tables, each in a <strong>new migration step</strong> (never the squash), with the\n<code>CoreRequestBuilder::$tables</code> entry, the Architecture.md schema row and the\nregenerated schema check that <code>SchemaConventionsTest</code> expects:</p>\n<h2 id=\"social-atproto-identity\">social_atproto_identity</h2>\n<p>one per local actor: <code>actor_id(_prim)</code>, <code>did</code>, <code>handle</code>, <code>custom_handle</code> with <code>custom_handle_checked</code>/<code>_failures</code> (§4.2, phase 4), <code>signing_key</code> (sealed), <code>signing_public</code>, <code>recovery_public</code>, <code>state</code> (<code>active</code>/<code>deactivated</code>/<code>moved_away</code>/<code>tombstoned</code>), <code>moved_from_pds</code>, timestamps. Unique on actor and on DID</p>\n<h2 id=\"social-atproto-instance-key\">social_atproto_instance_key</h2>\n<p>the instance&#39;s rotation and service keys, sealed, with <code>kind</code> and <code>created</code> (rotation keeps the previous one for the PLC window)</p>\n<h2 id=\"social-atproto-repo\">social_atproto_repo</h2>\n<p>one per DID: head <code>commit_cid</code>, <code>rev</code>, <code>record_count</code>, <code>blob_bytes</code>, <code>updated</code></p>\n<h2 id=\"social-atproto-record\">social_atproto_record</h2>\n<p><code>did</code>, <code>collection</code>, <code>rkey</code>, <code>cid</code>, <code>bytes</code> (DAG-CBOR), <code>local_id(_prim)</code> (the Social object), <code>created</code>. Unique on (did, collection, rkey); index on <code>local_id_prim</code></p>\n<h2 id=\"social-atproto-block\">social_atproto_block</h2>\n<p><code>cid</code>, <code>did</code>, <code>bytes</code>, <code>kind</code> (<code>mst</code>/<code>commit</code>/<code>record</code>); unique on (did, cid)</p>\n<h2 id=\"social-atproto-blob\">social_atproto_blob</h2>\n<p><code>did</code>, <code>cid</code>, <code>document_id</code> (the <code>social_cache_doc</code> row), <code>mime</code>, <code>size</code>; unique on (did, cid)</p>\n<h2 id=\"social-atproto-event\">social_atproto_event</h2>\n<p>the firehose frames: <code>seq</code> (primary), <code>did</code>, <code>kind</code>, <code>bytes</code> (the frame), <code>time</code>; pruned past the window</p>\n<h2 id=\"social-atproto-plc-log\">social_atproto_plc_log</h2>\n<p><code>did</code>, <code>cid</code> (operation), <code>operation</code> (JSON), <code>sent</code>, <code>confirmed</code></p>\n<h2 id=\"social-atproto-watch\">social_atproto_watch</h2>\n<p>followed Bluesky authors: <code>did</code>, <code>handle</code>, <code>cursor</code>, <code>last_sync</code>, <code>next_sync</code>, <code>failures</code>, <code>last_error</code>; one per DID, however many local followers</p>\n<h2 id=\"social-atproto-notify-cursor\">social_atproto_notify_cursor</h2>\n<p>per local DID: the AppView notifications cursor, <code>last_sync</code>, <code>next_sync</code>, <code>failures</code></p>\n<h2 id=\"social-atproto-labeler\">social_atproto_labeler</h2>\n<p>per user: labeler DID, the per-label settings (JSON), <code>added</code></p>\n<h2 id=\"social-atproto-blocklist\">social_atproto_blocklist</h2>\n<p>admin blocks: <code>kind</code> (<code>host</code>/<code>did</code>), <code>value</code>, <code>reason</code>, <code>created</code></p>\n<h2 id=\"social-atproto-session\">social_atproto_session</h2>\n<p>app-password sessions for Bluesky apps (§6.3): <code>did</code>, <code>jti</code>, refresh token hash, <code>expires</code>, <code>created</code>; OAuth later adds its own</p>\n<p>Existing tables gain nothing except: <code>social_stream.id</code> may be an <code>at://</code>\nURI (no schema change; <code>id_prim</code> handles it), <code>social_cache_actor.id</code>\nlikewise, and <code>details</code> JSON on both carries <code>atproto</code> blocks.</p>\n","toc":[{"id":"social-atproto-identity","text":"social_atproto_identity","level":2},{"id":"social-atproto-instance-key","text":"social_atproto_instance_key","level":2},{"id":"social-atproto-repo","text":"social_atproto_repo","level":2},{"id":"social-atproto-record","text":"social_atproto_record","level":2},{"id":"social-atproto-block","text":"social_atproto_block","level":2},{"id":"social-atproto-blob","text":"social_atproto_blob","level":2},{"id":"social-atproto-event","text":"social_atproto_event","level":2},{"id":"social-atproto-plc-log","text":"social_atproto_plc_log","level":2},{"id":"social-atproto-watch","text":"social_atproto_watch","level":2},{"id":"social-atproto-notify-cursor","text":"social_atproto_notify_cursor","level":2},{"id":"social-atproto-labeler","text":"social_atproto_labeler","level":2},{"id":"social-atproto-blocklist","text":"social_atproto_blocklist","level":2},{"id":"social-atproto-session","text":"social_atproto_session","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"data-model","manual":false,"prev":{"path":"/docs/atproto-operations","title":"Operations"},"next":{"path":"/docs/atproto-security","title":"Security"},"parent":null},{"slug":"atproto-security","path":"/docs/atproto-security","title":"Security","description":"Signing and rotation private keys are sealed with the instance secret through PrivateKeyCipher, the same primitive as app passwords; decrypted for one signature and discarded; never…","group":"atproto","html":"<h2 id=\"16-1-keys\">16.1 Keys</h2>\n<p>Signing and rotation private keys are sealed with the instance secret\nthrough <code>PrivateKeyCipher</code>, the same primitive as app passwords; decrypted\nfor one signature and discarded; never logged, never exported (the account\nexport carries the DID and the handle, not the keys — a moved repository\nis re-signed by the new PDS&#39;s key, which is how the protocol works).\n<code>paragonie/ecc</code> (secp256k1, deterministic RFC 6979 signatures, low-S\nnormalisation) with <code>gmp</code>; interop vectors pin the signature format.</p>\n<h2 id=\"16-2-service-auth-and-the-proxy\">16.2 Service auth and the proxy</h2>\n<p>Service-auth JWTs are short-lived (60 s), bound to <code>lxm</code> (the method) and\n<code>aud</code>, signed per request; the AppView proxy forwards only <code>app.bsky.*</code>,\nstrips <code>Authorization</code> from the client and adds its own, passes\n<code>atproto-accept-labelers</code> and <code>atproto-proxy</code> through, and limits the body.\nA proxied call is counted against the user&#39;s rate limit.</p>\n<h2 id=\"16-3-rotation\">16.3 Rotation</h2>\n<p>The instance rotation key is rotated by the administrator (<code>occ social:atproto:rotate-key</code>, admin page): a PLC operation per identity\n(queued, rate-limited by the PLC&#39;s limits — <em>verify</em>), the old key kept\nfor the 72-hour window and then deleted. An account&#39;s signing key is\nrotated when its sealing secret changes (Aloha&#39;s <code>secret</code> rotation) —\nthe setup check notices the seal no longer opens and the repair re-signs\nthe repository with a fresh key and a PLC update.</p>\n<h2 id=\"16-4-input\">16.4 Input</h2>\n<p>Records from Bluesky are untrusted input: the lexicon validator rejects\nwhat does not fit, facets are clamped to the text&#39;s byte length, every URL\ngoes through the same guarded fetch as ActivityPub documents (no local\naddresses, the federation blocklist, size ceilings), blobs are fetched\nonly from the AppView CDN or the author&#39;s PDS endpoint and only as the MIME\ntypes the record declares, and text is escaped on render as every remote\npost is. The firehose daemon accepts connections but reads nothing from\nthem beyond the <code>cursor</code> query; a slow consumer is dropped after a bounded\nbuffer, as the reference relay does to a slow PDS.</p>\n<h2 id=\"16-5-what-is-published\">16.5 What is published</h2>\n<p>Only what D8 and D16 allow: public posts, their pictures, profile fields\nthat are already public on the Fediverse, follows of Bluesky accounts,\nlikes and reposts of Bluesky-visible posts. Nothing else is ever written\nto a repository, and <code>RecordMapper</code> is the one place that could, so one\ntest class (§17) is the whole of that guarantee.</p>\n","toc":[{"id":"16-1-keys","text":"16.1 Keys","level":2},{"id":"16-2-service-auth-and-the-proxy","text":"16.2 Service auth and the proxy","level":2},{"id":"16-3-rotation","text":"16.3 Rotation","level":2},{"id":"16-4-input","text":"16.4 Input","level":2},{"id":"16-5-what-is-published","text":"16.5 What is published","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"security","manual":false,"prev":{"path":"/docs/atproto-data-model","title":"Data model"},"next":{"path":"/docs/atproto-testing","title":"Testing"},"parent":null},{"slug":"atproto-testing","path":"/docs/atproto-testing","title":"Testing","description":"A workflow like interop.yml: the official @atproto/dev-env TestNetwork (PLC, PDS, AppView, bsync, Ozone) plus an indigo relay (the dev-env starts none), this app behind the Caddy of the…","group":"atproto","html":"<h2 id=\"17-1-unit\">17.1 Unit</h2>\n<ul>\n<li>Protocol primitives against <strong>bluesky-social/atproto-interop-tests</strong>:\nDAG-CBOR encoding, CID computation, TIDs, MST construction and diff\n(the published trees and their expected CIDs), commit signing (low-S),\nhandle and DID syntax, AT URI parsing, lexicon validation of the records\nthis app writes. Vendored as fixtures.</li>\n<li><code>RecordMapper</code> both ways: every rule of §8 and §9.3, including the\ntruncation at 280 graphemes with combining characters and emoji, facet\nbyte offsets on multi-byte text, the four-picture cap, the CW prefix.</li>\n<li>Services with mocked HTTP: identity creation and PLC operations, the\npoller&#39;s backoff and ceiling, the notifications mapping of §10, the\nlabel mapping of §12.1, the migration steps of §13 in order.</li>\n</ul>\n<h2 id=\"17-2-integration-and-interop-d21\">17.2 Integration and interop (D21)</h2>\n<p>A workflow like <code>interop.yml</code>: the official <code>@atproto/dev-env</code> TestNetwork\n(PLC, PDS, AppView, bsync, Ozone) plus an <code>indigo</code> relay (the dev-env\nstarts none), this app behind the Caddy of the interop job with the root\nrules and the firehose proxy, the daemon started. Tests: a Bluesky user on\nthe dev PDS follows <code>alice.nextcloud.test</code>, sees her post in the AppView&#39;s\nauthor feed and timeline, likes it and replies — asserted here through\nActivities; alice follows the dev user and his post appears in her home\nfeed; a picture round-trips; a label from the dev Ozone hides a post; an\naccount migrates from the dev PDS to here and its follower still follows.\nThe real network (<code>plc.directory</code>, <code>bsky.network</code>) is touched by hand on a\npublic https host only — devel is http and cannot be a PDS; the admin page\nsays so when it detects http.</p>\n","toc":[{"id":"17-1-unit","text":"17.1 Unit","level":2},{"id":"17-2-integration-and-interop-d21","text":"17.2 Integration and interop (D21)","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"testing","manual":false,"prev":{"path":"/docs/atproto-security","title":"Security"},"next":{"path":"/docs/atproto-phases","title":"Phases"},"parent":null},{"slug":"atproto-phases","path":"/docs/atproto-phases","title":"Phases","description":"One PR each, each green on its own, each shrinking this document into Architecture/API/OCC-Commands/Admin/User-Guide as it lands (docs stay current).","group":"atproto","html":"<p>One PR each, each green on its own, each shrinking this document into\nArchitecture/API/OCC-Commands/Admin/User-Guide as it lands\n(<a href=\"Architecture.md#keeping-this-document-in-sync\">docs stay current</a>).</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Phase</th>\n<th>Delivers</th>\n<th>Demonstrable as</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>1 — Visible on Bluesky</strong> (D20)</td>\n<td>§4 identity and PLC, §5 repository with profile and post records (text, links, pictures, CW, polls-as-text, quotes-as-link), §6.1–6.2 sync + identity endpoints and root rules, §7 firehose daemon and <code>requestCrawl</code>, §8.1–8.5 publisher (edits/deletes), §14 requirements, admin section, setup checks, <code>occ</code> basics, §15 tables 1–8, §16, §17.1 + the interop job&#39;s first tests</td>\n<td>A Bluesky user searches <code>alice.&lt;host&gt;</code>, sees profile and posts, follows</td>\n</tr>\n<tr>\n<td><strong>2 — Reading Bluesky</strong></td>\n<td>§9 resolution, following, the poller, the storer, deletes; §10 notifications poll and the mapping; §8.6 likes/reposts/follows; §11 badges, profiles, addressing, mention picker; §12.1 labels honoured; §9.4 optional Jetstream</td>\n<td>alice follows <code>bob.bsky.social</code>, reads him in her feed, likes his post, sees his like and reply in Activities</td>\n</tr>\n<tr>\n<td><strong>3 — Complete interaction and apps</strong></td>\n<td>§8.3 replies and quotes to Bluesky posts both ways, link cards, §12.2 labelers, §12.3 reporting, §12.4 instance blocks, §6.3 app passwords then OAuth for Bluesky apps, threadgates, video (D11) through the video service</td>\n<td>the official Bluesky app logs in to Aloha Social as its PDS; a thread spans both networks</td>\n</tr>\n<tr>\n<td><strong>4 — Moving</strong> (D19)</td>\n<td>§13 move in, move away, Bridgy twins; §4.2 custom handles</td>\n<td>a Bluesky account moves here with its followers; a person sets <code>alice.example.org</code> as their handle</td>\n</tr>\n</tbody></table></div>\n<p>Each phase has its version bump, its tests per commit, its docs in the\nsame change, and its interop job extended before the PR is opened.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":[{"path":"/docs/atproto-phase-1-as-built","title":"Phase 1 as built","description":"Everything in the phase 1 row, in lib/Atproto/ (Protocol, Crypto, Lexicon, Identity, Repository, Firehose, Publisher, Xrpc, Service), with these departures from the letter of the sections…","parent":true},{"path":"/docs/atproto-phase-2-as-built","title":"Phase 2 as built","description":"Everything in the phase 2 row, in lib/Atproto/Reader/ (BlueskyActorService, ActorMapper, PostMapper, FacetRenderer, PostStore, FeedPoller, NotificationPoller, BlueskyGraphService…","parent":true},{"path":"/docs/atproto-phase-3-as-it-lands","title":"Phase 3 as it lands","description":"Phase 3 is five concerns, so it lands as five pull requests in this order: 3a interaction (threads, quotes, link cards, deletes both ways, quote rules), 3b moderation (§12.2–12.4), 3c…","parent":true},{"path":"/docs/atproto-phase-4-as-it-lands","title":"Phase 4 as it lands","description":"Five parts, five pull requests: 4a custom handles (§4.2), 4b moving away (§13.2), 4c moving a Bluesky account here (§13.1), 4d Bridgy Fed twins (§13.3), 4e the moved posts in the timeline…","parent":true}],"anchor":"phases","manual":false,"prev":{"path":"/docs/atproto-testing","title":"Testing"},"next":{"path":"/docs/atproto-phase-1-as-built","title":"Phase 1 as built"},"parent":null},{"slug":"atproto-phase-1-as-built","path":"/docs/atproto-phase-1-as-built","title":"Phase 1 as built","description":"Everything in the phase 1 row, in lib/Atproto/ (Protocol, Crypto, Lexicon, Identity, Repository, Firehose, Publisher, Xrpc, Service), with these departures from the letter of the sections…","group":"atproto","html":"<p>Everything in the phase 1 row, in <code>lib/Atproto/</code> (<code>Protocol</code>, <code>Crypto</code>,\n<code>Lexicon</code>, <code>Identity</code>, <code>Repository</code>, <code>Firehose</code>, <code>Publisher</code>, <code>Xrpc</code>,\n<code>Service</code>), with these departures from the letter of the sections above,\neach for a reason:</p>\n<ul>\n<li><strong>No <code>paragonie/ecc</code>, no gmp.</strong> Signing and verification use OpenSSL&#39;s\nsecp256k1 and P-256 (<code>Crypto\\PrivateKey</code>, <code>Crypto\\PublicKey</code>), which every\nAloha host has; the little arithmetic OpenSSL does not expose\n(low-S, point decompression) is a hundred lines of pure PHP\n(<code>Crypto\\BigNum</code>). A gmp requirement would have kept Bluesky off hosts\nthat have never needed it.</li>\n<li><strong>No <code>ratchet</code>/<code>react</code>.</strong> The firehose daemon is plain PHP sockets\n(<code>Firehose\\WebSocketServer</code>): what a firehose needs of RFC 6455 is a page,\nand the library would have brought a PSR-7 implementation into the app&#39;s\nbundle beside the server&#39;s own.</li>\n<li><strong>The recovery key is issued on request</strong>, from Settings → Apps and account → Bluesky,\nnot at identity creation: an identity made in a background job has nobody\nthere to show the phrase to. The phrase is twelve BIP-39 words (128 bits);\nthe key is derived from them.</li>\n<li><strong>Pictures</strong> are the stored original when it fits Bluesky&#39;s 2,000,000\nbytes and is a type Bluesky shows, re-encoded as JPEG otherwise and stored\nas a document of their own. Link cards (§8.3) are not yet built: a post\nwith a link and no pictures carries the link as a facet only.</li>\n<li><strong>Replies</strong> to a post that is on Bluesky — a local post that was published\n— are replies there (§8.3); to anything else they are a post with the\nparent linked. Quotes are a link. Both as the section says; the AppView\nthread walk for remote parents is phase 2.</li>\n<li><strong>Edits, deletes, profiles</strong> as §8.5 and §5.1; a profile change is\nrepublished when the profile is saved (<code>AccountService::changingProfile</code>)\nand when the identity is first viewed.</li>\n<li><strong>Handles</strong> are checked for syntax by <code>Protocol\\Syntax::isHandle()</code> and,\nbefore anything is resolved, for a top-level domain that can exist by\n<code>isResolvableHandle()</code> — <code>.test</code> kept, for the interop job.</li>\n<li><strong>The interop job</strong> (<code>interop-atproto.yml</code>) uses <code>@atproto/dev-env</code> with a\nsecond AppView subscription to this app&#39;s firehose rather than routing the\ndev PDS through the relay: the stock relay will not crawl a loopback or\nprivate address, so the relay in the job crawls this app alone (on a\nrouted address the runner answers on its loopback) and the test treats it\nas evidence when it is there.</li>\n<li><strong>Suspension</strong> leaves the identity alone (it can be lifted, and nothing is\ntold); deletion tombstones the DID.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"phase-1-as-built","manual":false,"prev":{"path":"/docs/atproto-phases","title":"Phases"},"next":{"path":"/docs/atproto-phase-2-as-built","title":"Phase 2 as built"},"parent":"atproto-phases"},{"slug":"atproto-phase-2-as-built","path":"/docs/atproto-phase-2-as-built","title":"Phase 2 as built","description":"Everything in the phase 2 row, in lib/Atproto/Reader/ (BlueskyActorService, ActorMapper, PostMapper, FacetRenderer, PostStore, FeedPoller, NotificationPoller, BlueskyGraphService…","group":"atproto","html":"<p>Everything in the phase 2 row, in <code>lib/Atproto/Reader/</code> (<code>BlueskyActorService</code>,\n<code>ActorMapper</code>, <code>PostMapper</code>, <code>FacetRenderer</code>, <code>PostStore</code>, <code>FeedPoller</code>,\n<code>NotificationPoller</code>, <code>BlueskyGraphService</code>, <code>BlueskySearch</code>,\n<code>LocalRecordResolver</code>), <code>lib/Atproto/AppView/</code> (<code>AppViewClient</code>,\n<code>ServiceAuth</code>), <code>lib/Atproto/Publisher/InteractionPublisher</code>, and\n<code>Cron\\AtprotoSync</code>, with these departures from the sections above:</p>\n<ul>\n<li><strong>Ids are https URLs on bsky.app, not <code>at://</code> URIs.</strong> Every id this app\nstores must be an https URL: <code>id_prim</code> is empty for anything else, the\nimport validation drops it, and the origin checks compare hosts. A\nBluesky account is <code>https://bsky.app/profile/&lt;did&gt;</code>, a post\n<code>https://bsky.app/profile/&lt;did&gt;/post/&lt;rkey&gt;</code> — by DID, so a handle change\nmoves nothing — and the <code>at://</code> URI, the CID and the AppView&#39;s counts ride\nin <code>details.atproto</code>. The page link (<code>details.page_url</code>) is by handle.</li>\n<li><strong>The cursor is the newest index time seen</strong>, not the AppView&#39;s paging\ncursor: <code>getAuthorFeed</code> pages backwards, so each read takes the newest\npage and stops at the first item at or before the last read. Reposts are\nordered by the repost&#39;s own time, as the feed is.</li>\n<li><strong>Replies to a local post carry a mention of its author.</strong> Bluesky names\nnobody in a reply; the mention tag is what makes the notification here,\nas it does for a Mastodon reply.</li>\n<li><strong>A reply&#39;s parent is resolved only through the record table</strong>: a Bluesky\nreply to <code>at://&lt;local did&gt;/…</code> lands under the local post; a reply to a\nBluesky post that is not here is stored with its bsky.app parent id and\nthe ordinary unknown-parent fetch is not run for it (one hop through\n<code>getPostThread</code> is phase 3).</li>\n<li><strong>Deletes from Bluesky are not yet noticed</strong> (§9.5): a post gone from the\nauthor feed stays until phase 3 adds the daily <code>getPosts</code> check or the\nJetstream listener. Nor is the optional Jetstream listener (§9.4) built.</li>\n<li><strong>No quote notification</strong>: Social has none (the spec was wrong there); a\nquote of a local post is stored as the post it is in and shows in the\nfeed of anybody who follows the quoting account.</li>\n<li><strong>Search</strong> (§9.1) asks the typeahead only for text that is the start of a\nhandle — a dot in it, no <code>@</code> — so a plain username never leaves the\ninstance; what it finds is not stored until somebody follows or\nmentions it.</li>\n<li><strong>The admin&#39;s federation block list applies to a handle&#39;s domain</strong> (the\npart after the first dot) in the directory; the per-DID/PDS-host block\nlist of §12.4 is phase 3, as are labelers (§12.2) and reporting (§12.3).\nOf §12.1, posts and accounts labelled <code>!hide</code>/<code>!takedown</code> are not stored\nor read, the adult labels make the pictures sensitive with a warning\nnaming the label, and other service labels become a warning; labelers&#39;\nown definitions are not read yet.</li>\n<li><strong>Per-user opt-out</strong> (§19.1, taken as recommended): Settings → Your\naccount has a switch; off, the account is announced inactive on the\nfirehose and by <code>getRepoStatus</code>, nothing more is published for it and its\nnotifications are not read; the DID and repository stay.</li>\n<li>Likes and reposts are written by the queued publish job, like posts, so\nthe request that made them never waits for a repository commit; a like\nof a Fediverse-only post writes nothing.</li>\n<li>The authenticated AppView (<code>atproto_appview_auth</code>, default\n<code>https://api.bsky.app</code>) and its DID (<code>atproto_appview_did</code>, default\n<code>did:web:api.bsky.app</code>) are configuration of their own beside the public\none, because the public AppView refuses authenticated requests; the\ninterop job points both at the dev AppView.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"phase-2-as-built","manual":false,"prev":{"path":"/docs/atproto-phase-1-as-built","title":"Phase 1 as built"},"next":{"path":"/docs/atproto-phase-3-as-it-lands","title":"Phase 3 as it lands"},"parent":"atproto-phases"},{"slug":"atproto-phase-3-as-it-lands","path":"/docs/atproto-phase-3-as-it-lands","title":"Phase 3 as it lands","description":"Phase 3 is five concerns, so it lands as five pull requests in this order: 3a interaction (threads, quotes, link cards, deletes both ways, quote rules), 3b moderation (§12.2–12.4), 3c…","group":"atproto","html":"<p>Phase 3 is five concerns, so it lands as five pull requests in this order:\n<strong>3a</strong> interaction (threads, quotes, link cards, deletes both ways, quote\nrules), <strong>3b</strong> moderation (§12.2–12.4), <strong>3c</strong> Bluesky apps logging in with\napp passwords (§6.3), <strong>3d</strong> video (D11), <strong>3e</strong> OAuth for Bluesky apps\n(§6.3).</p>\n<h2 id=\"3a-as-built\">3a as built</h2>\n<p><code>Publisher\\PostRefs</code> (the strong reference of a local\npost that was published or of a Bluesky post read here, and a reply&#39;s\nthread root), <code>RecordMapper</code> (reply, quote and card embeds, the postgate),\n<code>InteractionPublisher::removeAllOf()</code>, <code>Reader\\DeletionSweep</code>, and\n<code>PostStore::storeByUri()</code>/<code>deleteGone()</code>:</p>\n<h2 id=\"replies\">Replies</h2>\n<p> to a Bluesky post read here are replies in its thread there:\nthe parent is the post&#39;s stored URI and CID; the root is what was stored\nwith the parent when it was read (<code>details.atproto.reply_root</code>, new), or\nwhat the AppView says of it, or the parent itself. A Bluesky reply whose\nparent is not here fetches the parent one hop up (<code>getPosts</code>), never\nfurther.</p>\n<h2 id=\"quotes\">Quotes</h2>\n<p> of a post that is on Bluesky are <code>app.bsky.embed.record</code>\n(<code>recordWithMedia</code> with pictures); of anything else, the link as before.\nA quote of a Bluesky post stands at once: Bluesky asks nobody&#39;s\npermission, so no FEP-044f <code>QuoteRequest</code> waits for an answer.</p>\n<ul>\n<li><strong>Link cards</strong>: the post&#39;s link preview as <code>app.bsky.embed.external</code>\nwhen it has a title and the post has no pictures and quotes nothing —\n<strong>without a thumbnail</strong>: the preview&#39;s picture is a remote URL, and a\nblob here is a stored document; storing card pictures idempotently\nacross reconcile passes is left for later. A card that appears after the\npost was published is picked up by the reconcile pass within the edit\ngrace period, as an edit would be.</li>\n<li><strong>Quote rules</strong>: a post whose quote policy is followers-only or nobody\ngets an <code>app.bsky.feed.postgate</code> under its rkey with <code>disableRule</code>.\nBluesky cannot say &quot;followers only&quot;, so the stricter rule is published\nrather than an open one. Reply approval has no Bluesky equivalent and\nwrites no threadgate: Bluesky replies arrive and are held here like any.</li>\n<li><strong>Deletes</strong>: a local post&#39;s delete removes its postgate with it and the\nlike and repost records local accounts made of it (§8.5); a post deleted\non Bluesky is noticed by the maintenance job, which asks the AppView\nabout a page of 25 stored Bluesky posts of the last week per run and\ndeletes what it no longer has (§9.5), the local likes&#39; records too. An\nAppView that does not answer proves nothing and nothing is deleted.</li>\n<li>References are validated before they are written: a CID that is not a\nCID makes the post &quot;not on Bluesky&quot; (linked), never a refused commit.</li>\n</ul>\n<p><strong>3b as built</strong> — <code>Moderation\\Blocklist</code> (the checks) and\n<code>Moderation\\BlocklistManager</code> (blocking, unblocking, purging),\n<code>Moderation\\BlueskyReporter</code>, <code>Moderation\\LabelerService</code>, tables\n<code>social_atproto_blocklist</code> and <code>social_atproto_labeler</code>:</p>\n<h2 id=\"instance-blocks\">Instance blocks</h2>\n<p> (§12.4) by DID or PDS host — a host blocks the hosts\nunder it too. Checked wherever Bluesky comes in: resolution, the feed\nread (a blocked author&#39;s watch is dropped unread), notifications, stored\nposts, search. Blocking purges the blocked accounts that are followed\nhere with the primitive a domain block uses (<code>ModerationService::purgeActor()</code>);\na blocked host purges the followed accounts it hosts and refuses the rest\nas they come. <code>occ social:atproto:block</code>, and the admin card.</p>\n<h2 id=\"reporting\">Reporting</h2>\n<p> (§12.3) is the <code>forward</code> of a Mastodon report: for a\nBluesky account, <code>ReportForwardService</code> hands it to <code>BlueskyReporter</code>,\nwhich sends <code>com.atproto.moderation.createReport</code> to Bluesky&#39;s moderation\nservice (<code>atproto_moderation_did</code>), the first reported post that is on\nBluesky as the subject, else the account. <strong>Made by this server, not the\nreporter</strong>: the token is signed by the instance&#39;s <code>did:web</code> with its\nservice key, which its DID document publishes — the same reason the\nFediverse forward is signed as the instance. The report row records that\nit was forwarded; the Bluesky report id is logged, not stored.</p>\n<h2 id=\"labelers\">Labelers</h2>\n<p> (§12.2): Bluesky&#39;s moderation service always applies, at read\ntime, as §12.1 says; others are subscribed per person (by handle or DID,\nchecked to be a labeler), each label value set to ignore, warn or hide,\nthe labeler&#39;s own default until changed. Because one read of an author&#39;s\nfeed serves everybody here who follows them, the read asks for every\nlabeler anybody subscribes to (<code>atproto-accept-labelers</code>, at most 20),\neach post keeps its labels with their labeler (<code>label_sources</code>), and the\nchoices apply when a person reads, in <code>FilterService</code>: a warn is a filter\nresult naming the label, a hide leaves the post out. The status entity\ncarries <code>bluesky: {uri, url, labels}</code> for this. Labeler definitions are\nread from the AppView once a day.</p>\n<ul>\n<li>Not done: reading a Bluesky user&#39;s public block of a local account\n(<code>viewer.blockedBy</code> is per viewer, and the reads here are anonymous).</li>\n</ul>\n<p><strong>3c as built</strong> — <code>Atproto\\Client\\</code> (<code>AppPasswordService</code>, <code>SessionService</code>,\n<code>AppViewProxy</code>, <code>Preferences</code>, <code>WriteService</code>, <code>ClientXrpc</code>), tables\n<code>social_atproto_app_password</code> and <code>social_atproto_session</code>:</p>\n<h2 id=\"app-passwords-are-this-apps-not-alohas\">App passwords are this app&#39;s, not Aloha&#39;s</h2>\n<p> §6.3 said an Aloha\napp password; that would hand a Bluesky app the whole of Aloha —\nfiles, WebDAV — and can only be checked through the server&#39;s private API.\nSettings → Apps and account → Bluesky makes Bluesky-style app passwords instead (four\ngroups of four, shown once, stored as a password hash, at most 25),\ngood for this app&#39;s Bluesky surface only. Revoking one ends every session\nit opened. A wrong password counts against the caller&#39;s address in\nAloha&#39;s brute-force protection, and the answer for an unknown account\nand a wrong password is the same.</p>\n<h2 id=\"sessions\">Sessions</h2>\n<p> are JWTs this server signs with its service key: an access\ntoken of two hours naming its session, a refresh token of ninety days\nwhose id is the session (<code>createSession</code>, <code>refreshSession</code>,\n<code>getSession</code>, <code>deleteSession</code>). A suspended account&#39;s apps are turned\naway; an account that moved away cannot sign in.</p>\n<h2 id=\"the-appview-proxy\">The AppView proxy</h2>\n<p> (<code>app.bsky.*</code>) goes to the configured AppView only —\n<code>atproto-proxy</code> cannot point the account&#39;s signature elsewhere — with a\ntoken the account&#39;s own key signs for the one method; the answer passes\nthrough with its status. <code>chat.bsky.*</code> is refused (D15).\n<code>app.bsky.actor.getPreferences</code>/<code>putPreferences</code> are kept here, per person,\nwithin the <code>app.bsky</code> namespace and 256 KB.</p>\n<h2 id=\"writes-are-social-actions\">Writes are Social actions</h2>\n<p> (§16.5): <code>createRecord</code> of a post is a\nSocial post (public; reply, quote, pictures, language; a link the app\nshortened is its whole address again), a like a like, a repost a boost,\na follow a follow — the record the publisher writes for it is the answer,\nso the app sees what Social published, which may differ (a long post cut\nwith a link). <code>putRecord</code> of the profile sets the display name and bio.\n<code>deleteRecord</code> undoes the action. <code>applyWrites</code> does the same one by one,\nnot in one commit. Blocks are refused (D16), as are lists, feeds and\ngates. <code>uploadBlob</code> stores a picture as any upload is, named by its CID,\nfor the post that uses it. A report an app files is a report here, passed\non in this server&#39;s name (3b).</p>\n<ul>\n<li>Not yet: the account&#39;s avatar and banner from the app&#39;s profile editor.\n<code>getServiceAuth</code> came with 3d.</li>\n<li>A mention of a Bluesky account in a post published from here — the\ncomposer&#39;s <code>@alice.bsky.social</code> — is now a mention facet with the DID,\nwhere it was a link.</li>\n</ul>\n<p><strong>3d as built</strong> — <code>Publisher\\VideoBlobService</code>, <code>Publisher\\VideoUploadService</code>,\n<code>Client\\ServiceAuthGrant</code>, <code>Cron\\AtprotoVideo</code>, table <code>social_atproto_video</code>:</p>\n<h2 id=\"a-video-posted-here-becomes-a-bluesky-video\">A video posted here becomes a Bluesky video</h2>\n<p> Bluesky&#39;s apps play the\nstream its video service makes, not a blob, so the publisher does what the\nBluesky app does: it asks the service&#39;s daily limit, sends the video in\nthe account&#39;s name (<code>app.bsky.video.uploadVideo</code>) with a token the account\nsigns for <code>com.atproto.repo.uploadBlob</code> here, and the service stores the\nresult in the account&#39;s repository with that token. The post waits in\n<code>social_atproto_video</code> meanwhile; <code>Cron\\AtprotoVideo</code> sends a few videos a\nminute and asks after the jobs, and publishes each post once its job has\nended, naming the stored blob as <code>app.bsky.embed.video</code> with the alt text\nand size of the video posted here. Beside a quote it is the media of\n<code>recordWithMedia</code>; pictures beside a video are left to the link.</p>\n<h2 id=\"when-it-stays-a-link\">When it stays a link</h2>\n<p> A video Bluesky does not take (not MP4, WebM,\nQuickTime or MPEG; over 100,000,000 bytes; over three minutes), an\naccount over its daily limit, a refusal, three failed tries, a job not\ndone in thirty minutes, or a job whose result was not stored here: the\npost goes out as before, its text and a link to the post here, and the\nreason is logged. <code>atproto_video_service</code> empty turns the service off.</p>\n<h2 id=\"apps-upload-video-as-the-bluesky-app-does\">Apps upload video as the Bluesky app does</h2>\n<p> <code>getServiceAuth</code> hands an\napp a token signed with the account&#39;s key, for two kinds of use only:\nBluesky&#39;s video service (<code>getUploadLimits</code>, <code>uploadVideo</code>,\n<code>getJobStatus</code>) and this server&#39;s <code>uploadBlob</code>, for at most thirty\nminutes. Any other service or method is refused: it would be the\naccount&#39;s signature somewhere this server knows nothing of. <code>uploadBlob</code>\naccepts such a token, checked against the account&#39;s key, as well as a\nsession; the body is written to disk as it arrives, never held in\nmemory, and a video may weigh up to 100,000,000 bytes. A post with an\n<code>app.bsky.embed.video</code> is a Social video post. A video blob is stored as\nit came, hashed as it is read, and <code>getBlob</code> streams it.</p>\n<h2 id=\"a-bluesky-video-plays-here\">A Bluesky video plays here</h2>\n<p> A post whose embed has a playlist is read\nas a federated <code>Video</code>: the HLS playlist is a streamed document, never\ncopied, played through this server&#39;s playlist proxy (hls.js, as for\nPeerTube); the still is mirrored as its poster. A video the service has\nnot finished is a link to the post until it is read again.</p>\n<h2 id=\"fixed-on-the-way\">Fixed on the way</h2>\n<p> a streamed HLS video was handed to the player as\nthe byte route, so its segments 404&#39;d; it now gets the playlist route,\nand stored links of older posts are rebuilt the same way when read.</p>\n<ul>\n<li><strong><code>getSession</code> reports the Aloha account&#39;s e-mail address</strong>, and as\nconfirmed when it is set: the Bluesky app offers video only to an account\nwith a confirmed address, and the account is one an administrator or the\nperson manages.</li>\n</ul>\n<h2 id=\"departure\">Departure</h2>\n<p> a token handed to the video service is not single-use;\nit is scoped to <code>uploadBlob</code> here and expires within thirty minutes, as\nBluesky&#39;s own PDS does it.</p>\n<p><strong>3e as built</strong> — <code>Atproto\\OAuth\\</code> (<code>AuthorizationServer</code>, <code>ClientMetadataService</code>,\n<code>ClientAuthenticator</code>, <code>DpopVerifier</code>, <code>DpopNonce</code>, <code>Jwk</code>, <code>Jose</code>),\n<code>AtprotoOAuthController</code>, tables <code>social_atproto_oauth_request</code>,\n<code>social_atproto_oauth_session</code>, <code>social_atproto_oauth_replay</code>:</p>\n<ul>\n<li><strong>Bluesky sign-in is AT Protocol&#39;s OAuth profile</strong>: pushed authorization\nrequests only, PKCE S256, DPoP with this server&#39;s nonces on every token and\nevery PDS request, client IDs that are the address of the app&#39;s metadata\n(and the profile&#39;s <code>http://localhost</code> development exception), public and\nconfidential (<code>private_key_jwt</code>) clients, the <code>atproto</code> scope with\n<code>transition:generic</code> and <code>transition:email</code>. <code>transition:chat.bsky</code> is\nlisted and never granted (D15).</li>\n</ul>\n<h2 id=\"one-issuer-with-the-mastodon-oauth-server\">One issuer with the Mastodon OAuth server</h2>\n<p> AT Protocol requires the\nissuer to be the bare origin, and an origin has one\n<code>/.well-known/oauth-authorization-server</code>. With Bluesky on (and the root\nrules in place) that document is both servers&#39;: Mastodon&#39;s fields with AT\nProtocol&#39;s added, the issuer without a trailing slash, as RFC 8414 has it.\n<code>/oauth/authorize</code>, <code>/oauth/token</code> and <code>/oauth/revoke</code> are shared and tell\nthe two apart by what only AT Protocol sends — a pushed <code>request_uri</code>, a\n<code>DPoP</code> proof, a URL as <code>client_id</code>; <code>/oauth/par</code> and\n<code>/.well-known/oauth-protected-resource</code> are AT Protocol&#39;s alone. The\ntokens, sessions and tables stay apart: a Mastodon token is not good on\n<code>/xrpc/</code>, an OAuth token for Bluesky not on <code>/api/</code>.</p>\n<ul>\n<li><strong>The consent page is the Mastodon apps&#39; one</strong>, told it is a Bluesky app:\nit names the app by the host of its client ID and shows the whole\naddress, because an app&#39;s own name and logo are what it says of itself\nand are not shown. A <code>login_hint</code> naming another account than the one\nsigned in is refused.</li>\n<li><strong>Tokens</strong>: access tokens of fifteen minutes, bound to the DPoP key and\nchecked against their session on every request, so signing an app out\nstops it at once; refresh tokens used once and rotated, and a replaced\none presented again ends the session; a code exchanged twice ends the\nsession the first exchange started. A public app&#39;s session ends after two\nweeks; a confidential one&#39;s refresh tokens last 180 days and must be\npresented with the key that started it, still published.</li>\n</ul>\n<h2 id=\"settings-apps-and-account-bluesky\">Settings → Apps and account → Bluesky</h2>\n<p> lists the apps signed in this way,\nwith their client ID, what they may do and when they were last used, and\nsigns one out. An OAuth app without <code>transition:generic</code> may only ask who\nit is (<code>getSession</code>); <code>getSession</code> shows the e-mail address only with\n<code>transition:email</code>.</p>\n<ul>\n<li><strong>Not built</strong>: the granular permission scopes (<code>repo:</code>, <code>rpc:</code>,\n<code>include:</code>) — an app asking only for those gets <code>atproto</code> alone — and a\nlist of trusted apps whose names and logos would be shown.</li>\n</ul>\n","toc":[{"id":"3a-as-built","text":"3a as built","level":2},{"id":"replies","text":"Replies","level":2},{"id":"quotes","text":"Quotes","level":2},{"id":"instance-blocks","text":"Instance blocks","level":2},{"id":"reporting","text":"Reporting","level":2},{"id":"labelers","text":"Labelers","level":2},{"id":"app-passwords-are-this-apps-not-alohas","text":"App passwords are this app's, not Aloha's","level":2},{"id":"sessions","text":"Sessions","level":2},{"id":"the-appview-proxy","text":"The AppView proxy","level":2},{"id":"writes-are-social-actions","text":"Writes are Social actions","level":2},{"id":"a-video-posted-here-becomes-a-bluesky-video","text":"A video posted here becomes a Bluesky video","level":2},{"id":"when-it-stays-a-link","text":"When it stays a link","level":2},{"id":"apps-upload-video-as-the-bluesky-app-does","text":"Apps upload video as the Bluesky app does","level":2},{"id":"a-bluesky-video-plays-here","text":"A Bluesky video plays here","level":2},{"id":"fixed-on-the-way","text":"Fixed on the way","level":2},{"id":"departure","text":"Departure","level":2},{"id":"one-issuer-with-the-mastodon-oauth-server","text":"One issuer with the Mastodon OAuth server","level":2},{"id":"settings-apps-and-account-bluesky","text":"Settings → Apps and account → Bluesky","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"phase-3-as-it-lands","manual":false,"prev":{"path":"/docs/atproto-phase-2-as-built","title":"Phase 2 as built"},"next":{"path":"/docs/atproto-phase-4-as-it-lands","title":"Phase 4 as it lands"},"parent":"atproto-phases"},{"slug":"atproto-phase-4-as-it-lands","path":"/docs/atproto-phase-4-as-it-lands","title":"Phase 4 as it lands","description":"Five parts, five pull requests: 4a custom handles (§4.2), 4b moving away (§13.2), 4c moving a Bluesky account here (§13.1), 4d Bridgy Fed twins (§13.3), 4e the moved posts in the timeline…","group":"atproto","html":"<p>Five parts, five pull requests: <strong>4a</strong> custom handles (§4.2), <strong>4b</strong> moving\naway (§13.2), <strong>4c</strong> moving a Bluesky account here (§13.1), <strong>4d</strong> Bridgy\nFed twins (§13.3), <strong>4e</strong> the moved posts in the timeline (§13.1, step 6).</p>\n<p><strong>4a as built</strong> — <code>Identity\\HandleVerifier</code>, <code>Identity\\CustomHandleService</code>,\n<code>Identity\\DnsLookup</code>, columns <code>custom_handle</code>, <code>custom_handle_checked</code>,\n<code>custom_handle_failures</code> on <code>social_atproto_identity</code>:</p>\n<ul>\n<li><strong>Settings → Apps and account → Bluesky</strong> takes a domain, shows the DNS TXT\nrecord (<code>_atproto.&lt;domain&gt;</code> = <code>did=&lt;DID&gt;</code>) and the file\n(<code>https://&lt;domain&gt;/.well-known/atproto-did</code> = the DID) that make it the\naccount&#39;s, and checks them: either is enough, as for the AppView. Setting\nit asks for the Aloha password.</li>\n<li><strong>Then</strong> the DID document names the domain (a PLC update with the same\nkeys and endpoint) and the firehose sends <code>#identity</code>, so relays and\nAppViews resolve the handle again. The assigned <code>alice.&lt;host&gt;</code> keeps\nresolving here — <code>resolveHandle</code>, the well-known, sign-in by handle — as\nan alias the document does not list; going back to it is one button.</li>\n<li><strong>Refused</strong>: a name that is not a resolvable domain, anything under this\nserver&#39;s handle host (those are the ones it gives out), another\naccount&#39;s handle here.</li>\n<li><strong>Checked daily</strong> by the maintenance job, twenty at a time: a domain that\nfailed two checks in a row is shown as broken in the settings, as\nBluesky shows the handle as invalid. Nothing is changed for the person:\nthe record may only be gone for a while.</li>\n</ul>\n<p><strong>4b as built</strong> — <code>Move\\MoveAwayService</code>, <code>Move\\PdsClient</code>,\n<code>IdentityService::handOver()</code>/<code>markMovedAway()</code>, <code>Cron\\AtprotoMove</code>, table\n<code>social_atproto_move</code>:</p>\n<h2 id=\"driven-from-here-not-from-the-other-side\">Driven from here, not from the other side</h2>\n<p> §13.2 had this server\nserve <code>requestPlcOperationSignature</code> and <code>signPlcOperation</code> to a\nmigration tool. A tool would need a session with account-management\nrights, which neither app passwords nor <code>transition:generic</code> give, and\nthis server holds both the signing key and a rotation key of the DID.\nSo Settings → Migration → <em>Move your Bluesky account away</em> does what the\ntool would: the person names the other PDS, a handle there, an e-mail\naddress and a password (and an invite code if it wants one), confirms\nwith their Aloha password, and this server makes the account there\nwith a token the account signs (<code>createAccount</code> with the DID). What the\nother server refuses is said at once.</p>\n<ul>\n<li><strong>Then a background job</strong>: <code>importRepo</code> with this repository&#39;s CAR, every\nblob <code>listMissingBlobs</code> names, the preferences, then\n<code>getRecommendedDidCredentials</code> there and a PLC operation signed with this\nserver&#39;s rotation key that hands the DID over — the person&#39;s recovery key\nfirst among the rotation keys, so the DID stays theirs; this server&#39;s key\nis no longer listed — then <code>activateAccount</code> there. Here the identity is\n<code>moved_away</code>, announced inactive on the firehose, and nothing more is\npublished; no new identity is made for the account.</li>\n<li><strong>A step that fails stops the move</strong>, and <em>Try again</em> starts it from that\nstep. The DID moves only once the repository and the blobs are there, and\na hand-over the directory refused is not left for the PLC repair pass:\nthe move is finished by the person, never behind their back. The session\non the other PDS is kept sealed while the move runs and dropped after.</li>\n</ul>\n<h2 id=\"the-fediverse-account-is-untouched\">The Fediverse account is untouched</h2>\n<p> Posts written while the move\nruns, after the repository was copied, stay here only.</p>\n<p><strong>4c as built</strong> — <code>Move\\MoveInService</code>, <code>Move\\RepoArchive</code>,\n<code>Protocol\\MstReader</code>, <code>RepositoryService::import()</code>,\n<code>IdentityService::adopt()</code>, <code>FollowService::adoptBlueskyFollow()</code>,\n<code>DocumentService::storeAsIs()</code>:</p>\n<h2 id=\"driven-from-here-as-moving-away-is\">Driven from here, as moving away is</h2>\n<p> Settings → Migration → <em>Bring\nyour Bluesky account here</em>: the person names their Bluesky account and\ntypes its <strong>password</strong> — the account&#39;s own, not an app password, because\na PDS signs a change of the DID only for a full session (§13.1 said app\npassword, which cannot work). It is used to sign in and not kept; the\nsession is, sealed, while the move runs. A sign-in the old PDS wants\nconfirmed by an e-mailed code takes that code as well.</p>\n<h2 id=\"the-repository\">The repository</h2>\n<p> is fetched with <code>getRepo</code>, checked — every block\nagainst its CID, the commit against the signing key the DID document\nnames — and written here <strong>byte for byte</strong>, every record of every\napplication, under one commit signed with a key made for the account\nhere. Records keep their CIDs, so every reference to them stays good.\n<strong>Blobs</strong> are fetched with <code>listBlobs</code>/<code>getBlob</code> and stored as they came,\neach checked against its CID; nothing is re-encoded. <strong>Preferences</strong> come\nalong. <strong>Follows</strong> become follows here, each tied to the record it came\nwith, so nothing is written twice.</p>\n<h2 id=\"then-the-old-pds-e-mails-a-code\">Then the old PDS e-mails a code</h2>\n<p> (<code>requestPlcOperationSignature</code>); the\nmove waits. With the code it signs the operation that names this PDS,\nthis server&#39;s rotation key and the account&#39;s handle here — checked\nbefore it is taken — the directory takes it, and the account <strong>takes the\nDID</strong>: the account&#39;s identity row keeps its handle (and custom handle)\nand gets the moved DID and its new key, and the DID this server had made\nfor the account is <strong>retired</strong>, tombstoned with its repository. The page\nsays so before the move starts. Last, <code>deactivateAccount</code> on the old PDS.</p>\n<h2 id=\"then-the-posts\">Then the posts</h2>\n<p> become posts in the timeline here (4e). A wrong code\nstops the move, and <em>Try again</em> asks the old PDS for a new one.</p>\n<p><strong>4d as built</strong> — <code>Move\\InboundMoveService</code>, <code>Move\\BridgyTwin</code>,\n<code>ServiceAuth::verify()</code>, <code>IdentityService::receive()</code>/<code>submit()</code>; moves of\ndirection <code>inbound</code> in <code>social_atproto_move</code>:</p>\n<h2 id=\"this-server-as-the-new-pds-of-the-protocols-own-migration\">This server as the new PDS of the protocol&#39;s own migration</h2>\n<p> §13.3\nassumed the 4c flow with Bridgy as the old PDS; but a bridged account has\nno password — Bridgy holds its keys — and Bridgy moves an account out\nitself, with the DM command <code>migrate-to &lt;pds&gt; &lt;email&gt; &lt;handle&gt; &lt;password&gt; [invite]</code>, doing what a migration tool does against the new PDS. So 4d\nserves that side, and every standard tool (<code>goat account migrate</code>, say)\ncan move an account here the same way.</p>\n<h2 id=\"invited-first\">Invited first</h2>\n<p> Settings → Migration → <em>Bring your bridged Bluesky\naccount here</em> finds the twin (the handle Bridgy gives the Fediverse\naddress, resolving to a DID whose PDS is <code>atproto.brid.gy</code>); a person can\nalso name any other account. Inviting, after the Aloha password, makes\na one-time code, kept only as a hash, good for a day. A twin&#39;s move is\nthen asked for by a direct message from the account to Bridgy&#39;s bot with\nthe command; for anything else the page shows the server, the handle,\nthe e-mail address and the code, once.</p>\n<h2 id=\"createaccount\">createAccount</h2>\n<p> takes only an invited DID, with the code (as password\nor invite code) and a service-auth token the DID signs for this server&#39;s\n<code>did:web</code>, checked against the key the directory names; the handle asked\nfor is ignored — the account goes by its handle here. What it gets is a\nsession that can only move the account: <code>importRepo</code> (checked as in 4c,\nreplacing what came before, up to 64 MB), <code>listMissingBlobs</code>, <code>uploadBlob</code>\n(kept byte for byte, also after activation, as Bridgy sends blobs last),\n<code>getRecommendedDidCredentials</code> (this server&#39;s rotation key, the handle\nhere, a key made for the account here, this PDS), <code>submitPlcOperation</code>\nfor a tool that leaves the directory to the new PDS, <code>checkAccountStatus</code>,\npreferences, <code>refreshSession</code>. Seven days, then it ends.</p>\n<h2 id=\"activateaccount\">activateAccount</h2>\n<p> checks the directory names this PDS, the\nrecommended key and this server&#39;s rotation key; then the account takes\nthe DID as in 4c (<code>receive()</code>, the auto-made DID retired) and a job turns\nits follows into follows here. Bridgy stops bridging the account to\nBluesky itself.</p>\n<h2 id=\"not-built\">Not built</h2>\n<p> a twin&#39;s handle Bridgy derived from a custom domain is not\nfound by the page; it can be named by hand.</p>\n<p><strong>4e as built</strong> — <code>Move\\PostHistory</code>, <code>PostImportService::importParsed()</code>,\n<code>ImportedPostsRequest::isImported()</code>; a last step <code>posts</code> of both moves here:</p>\n<ul>\n<li><strong>The moved posts become the account&#39;s posts here</strong>, through the import\npath every archive import takes, so nothing is federated: dated when they\nwere written, the whole link where the app shortened it, the hashtags the\nfacets name, the language, a warning where the post carried a label for\none, a reply under its parent when that is one of the account&#39;s own\nposts too, the pictures or the video from the blobs held here.</li>\n<li><strong>Each is tied to the record it came from</strong>, so a like, a repost or a reply\non Bluesky reaches it here, and nothing is published again: the publisher\nleaves an imported post alone — neither rewrites its record when it is\nyounger than the edit grace, nor publishes an archive import dated in the\nlast day as new, which it did before.</li>\n<li><strong>The account has moved by then</strong>: a post that cannot be imported is\nlogged, and the move is done regardless. Running it again picks up only\nwhat is left.</li>\n<li><strong>Not built</strong>: the account&#39;s likes and reposts are on Bluesky, as records\nof the repository, but are not actions in this app; a reply to somebody\nelse&#39;s post stands alone here, the thread being on Bluesky.</li>\n</ul>\n","toc":[{"id":"driven-from-here-not-from-the-other-side","text":"Driven from here, not from the other side","level":2},{"id":"the-fediverse-account-is-untouched","text":"The Fediverse account is untouched","level":2},{"id":"driven-from-here-as-moving-away-is","text":"Driven from here, as moving away is","level":2},{"id":"the-repository","text":"The repository","level":2},{"id":"then-the-old-pds-e-mails-a-code","text":"Then the old PDS e-mails a code","level":2},{"id":"then-the-posts","text":"Then the posts","level":2},{"id":"this-server-as-the-new-pds-of-the-protocols-own-migration","text":"This server as the new PDS of the protocol's own migration","level":2},{"id":"invited-first","text":"Invited first","level":2},{"id":"createaccount","text":"createAccount","level":2},{"id":"activateaccount","text":"activateAccount","level":2},{"id":"not-built","text":"Not built","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"phase-4-as-it-lands","manual":false,"prev":{"path":"/docs/atproto-phase-3-as-it-lands","title":"Phase 3 as it lands"},"next":{"path":"/docs/atproto-open-questions","title":"Open questions"},"parent":"atproto-phases"},{"slug":"atproto-open-questions","path":"/docs/atproto-open-questions","title":"Open questions","description":"For the owner, not blocking phase 1:","group":"atproto","html":"<p>For the owner, not blocking phase 1:</p>\n<ol>\n<li><strong>Per-user opt-out.</strong> D3 says every account, automatically. Should a\nperson be able to switch <em>their</em> Bluesky identity off (deactivate the\nrepository; the DID stays theirs) — an Aloha user who wants no\npresence on Bluesky at all? Recommended: yes, in phase 2, as\n<code>deactivateAccount</code> on their own identity with a plain explanation.</li>\n<li><strong>Bluesky-only replies.</strong> A Bluesky user replies to alice&#39;s post; alice\nanswers from here; her answer goes to Bluesky (§8.3) — and to the\nFediverse, where the parent does not exist. Publish it as an ordinary\npublic post there (the parent linked), or keep a reply-to-Bluesky off\nthe Fediverse? Recommended: publish, parent linked — one post, two\naddresses, as D8 says.</li>\n<li><strong>Who pays for pictures.</strong> A re-encoded picture is a second stored file\nper picture per post. Count it against the user&#39;s quota (it is their\npost) or the app&#39;s? Recommended: the user&#39;s, like the original.</li>\n<li><strong>Relay choice.</strong> <code>bsky.network</code> only, or also announce to independent\nrelays by default? Recommended: <code>bsky.network</code> default, list editable.</li>\n</ol>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"open-questions","manual":false,"prev":{"path":"/docs/atproto-phase-4-as-it-lands","title":"Phase 4 as it lands"},"next":{"path":"/docs/atproto-facts-and-when-they-were-checked","title":"Facts, and when they were checked"},"parent":null},{"slug":"atproto-facts-and-when-they-were-checked","path":"/docs/atproto-facts-and-when-they-were-checked","title":"Facts, and when they were checked","description":"Checked 2026-09-25 unless marked; verify means re-check before the code that depends on it is written, because the number or the API has moved before.","group":"atproto","html":"<p>Checked 2026-09-25 unless marked; <strong>verify</strong> means re-check before the code\nthat depends on it is written, because the number or the API has moved\nbefore.</p>\n<ul>\n<li>Post: 300 graphemes / 3,000 bytes; 4 images ≤ 2,000,000 bytes each;\none video per post, mp4 ≤ 100 MB and three minutes, through the video\nservice; 25 videos or 10 GB a day per account (checked 2026-10-08). The\nflow: <code>getServiceAuth</code> (aud the PDS&#39;s <code>did:web</code>, lxm\n<code>com.atproto.repo.uploadBlob</code>, up to 30 minutes) →\n<code>POST https://video.bsky.app/xrpc/app.bsky.video.uploadVideo?did=&amp;name=</code>\nwith that token → <code>getJobStatus?jobId=</code> (no token) until\n<code>JOB_STATE_COMPLETED</code> with the blob, which the service stored on the PDS;\n<code>getUploadLimits</code> takes a token for <code>did:web:video.bsky.app</code>. A video\nview&#39;s playlist is <code>https://video.bsky.app/watch/&lt;did&gt;/&lt;cid&gt;/playlist.m3u8</code>,\nits segments relative to it.</li>\n<li>Commit <code>version: 3</code>, <code>prev: null</code>, 64-byte low-S secp256k1 signature;\nMST fanout 4, 2 bits per level; CID v1 dag-cbor sha-256.</li>\n<li>PLC: <code>POST /:did</code> operations, <code>GET /:did</code> document, <code>/:did/log/audit</code>,\n72-hour recovery window; <code>did:plc</code> is 24 base32 chars of the genesis\noperation&#39;s hash.</li>\n<li>Handle resolution: DNS TXT <code>_atproto.&lt;handle&gt;</code> or\n<code>https://&lt;handle&gt;/.well-known/atproto-did</code>.</li>\n<li>Account migration endpoints (checked 2026-10-06 against atproto.com):\n<code>com.atproto.server.describeServer</code>, <code>getServiceAuth</code>, <code>createAccount</code>,\n<code>checkAccountStatus</code>, <code>activateAccount</code>, <code>deactivateAccount</code>;\n<code>com.atproto.repo.importRepo</code>, <code>listMissingBlobs</code>; <code>com.atproto.sync.getRepo</code>,\n<code>listBlobs</code>; <code>com.atproto.identity.getRecommendedDidCredentials</code>,\n<code>requestPlcOperationSignature</code>, <code>signPlcOperation</code>, <code>submitPlcOperation</code>.</li>\n<li>Bluesky OAuth for apps needs PAR, DPoP, PKCE S256 and a client-metadata\nURL (phase 3).</li>\n<li><code>@atproto/dev-env</code> TestNetwork starts PLC, bsync, AppView, PDS and Ozone\nand <strong>no relay</strong> — <code>indigo</code> <code>cmd/relay</code> for CI.</li>\n<li>Jetstream: <code>wantedCollections</code>, <code>wantedDids</code> (<em>verify</em> the 10,000 limit\nand the <code>#options_update</code> frame), <code>cursor</code> in microseconds, public\ninstances <code>jetstream1/2.us-east.bsky.network</code>, <code>jetstream1/2.us-west…</code>.</li>\n<li>Bluesky moderation service DID <code>did:plc:ar7c4by46qjdydhdevvrndac</code>;\nreports via <code>com.atproto.moderation.createReport</code> with\n<code>atproto-proxy: &lt;did&gt;#atproto_labeler</code>. <em>verify</em> label value names.</li>\n<li>PDS rate limits (3,000 points/hour/DID for writes; per-IP on\n<code>createSession</code>): <em>verify</em>.</li>\n<li>Packagist: <code>spomky-labs/cbor-php</code> 3.4.2, <code>paragonie/ecc</code> 2.6.0 (gmp),\n<code>ratchet/rfc6455</code> 0.4.1, <code>react/socket</code> 1.17.0 — usable on PHP 8.3.\n<code>aazsamir/libphpsky</code> and <code>karanshukla/php-atproto-identity</code> need PHP ≥ 8.4\n(floor is 8.3); <code>socialweb/atproto</code> is a 2023 alpha — not used. Verify\neach against Packagist before adding to <code>composer.json</code>.</li>\n<li>Interop vectors: github.com/bluesky-social/atproto-interop-tests.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Atproto-Compatibility.md","sections":null,"anchor":"facts-and-when-they-were-checked","manual":false,"prev":{"path":"/docs/atproto-open-questions","title":"Open questions"},"next":null,"parent":null},{"slug":"performance","path":"/docs/performance","title":"Performance and scalability","description":"A survey of the query and scalability behaviour of this app, and of what the browser has to download before any of it is on screen: what costs what, what is bounded, and what is still…","group":"performance","html":"<p>A survey of the query and scalability behaviour of this app, and of what the\nbrowser has to download before any of it is on screen: what costs what, what is\nbounded, and what is still known to be wrong. Every claim below was checked\nagainst the code rather than carried over from a previous survey.</p>\n<p><strong>Verified against:</strong> app version 0.19.14, <code>master</code>, 2026-09-13 — the queries\nre-measured end to end on a seeded instance (22,642 posts, 65,014 recipient\nrows, 916 follows, 435 cached actors) after the read-path wave below, and the\nbundle sizes measured from <code>npm run build</code> on this version.</p>\n<p>This file is <strong>not</strong> enforced by <code>tests/DocumentationTest.php</code> — its claims are\nabout behaviour rather than about routes or schema rows, and a test that tried\nto check them would either be brittle or would be the fix. It therefore goes\nstale silently. Re-verify before trusting a line of it, and update it in the\nsame change as any work on a read path.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":[{"path":"/docs/performance-what-a-page-costs","title":"What a page costs","description":"Measured with occ social:benchmark --time-only, which times StreamRequest::getTimeline() itself — the query builders and the hydration, not just the SQL. Two datasets: a demo instance of…","parent":false},{"path":"/docs/performance-what-is-still-open","title":"What is still open","description":"Nothing is unbounded any more. What is left is bounded work that could still be cheaper, and the schema items at the end.","parent":false},{"path":"/docs/performance-the-frontend-bundle","title":"The frontend bundle","description":"Every byte here is downloaded before the first post is on screen, so this is the part of the app's speed that a fast database cannot help with. Sizes are gzipped, which is what the wire…","parent":false},{"path":"/docs/performance-what-was-fixed-and-what-fixed-it","title":"What was fixed, and what fixed it","description":"The previous survey (2026-09-10, against 0.11.49) is largely answered. Kept here so a reader who finds that report knows why the code no longer matches it.","parent":false},{"path":"/docs/performance-the-home-timeline-and-one-thing-that-did-not-work","title":"The home timeline, and one thing that did not work","description":"Home is now the slowest page and the reason is structural: it asks for \"the newest posts addressed to anyone I follow\", where the selection lives in social_stream_dest and the order in…","parent":false},{"path":"/docs/performance-what-to-do-next","title":"What to do next","description":"Aloha Social documentation.","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/performance-what-a-page-costs","title":"What a page costs"},"parent":null},{"slug":"performance-what-a-page-costs","path":"/docs/performance-what-a-page-costs","title":"What a page costs","description":"Measured with occ social:benchmark --time-only, which times StreamRequest::getTimeline() itself — the query builders and the hydration, not just the SQL. Two datasets: a demo instance of…","group":"performance","html":"<p>Measured with <code>occ social:benchmark --time-only</code>, which times\n<code>StreamRequest::getTimeline()</code> itself — the query builders and the hydration,\nnot just the SQL. Two datasets: a demo instance of 650 posts, and the same\ninstance with <code>--actors=400 --notes=20000 --follows=300</code> seeded on top.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>timeline</th>\n<th>22k posts, before</th>\n<th>22k posts, now</th>\n<th>650 posts, now</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>home (My Feed)</td>\n<td>114.7 ms</td>\n<td><strong>49.6 ms</strong></td>\n<td>16.6 ms</td>\n</tr>\n<tr>\n<td>public (Local/Global)</td>\n<td>52.6 ms</td>\n<td><strong>3.6 ms</strong></td>\n<td>4.6 ms</td>\n</tr>\n<tr>\n<td>notifications</td>\n<td>29.6 ms</td>\n<td><strong>7.4 ms</strong></td>\n<td>7.0 ms</td>\n</tr>\n<tr>\n<td>direct</td>\n<td>1.3 ms</td>\n<td>1.3 ms</td>\n<td>1.2 ms</td>\n</tr>\n</tbody></table></div>\n<p>Three changes did that, and all three are about what a <em>page-selection</em> query\nasks for rather than about indexes:</p>\n<ol>\n<li><strong>The page queries stopped projecting columns nobody reads.</strong>\n<code>linkToCacheActors()</code> appends twenty select aliases — <code>source</code>, <code>details</code>,\n<code>summary</code>, <code>public_key</code> among them — plus eleven for the cached document,\nand the home timeline&#39;s <code>SELECT DISTINCT</code> had to deduplicate over all of\nthem. <code>joinCacheActors()</code> is the same join without the select list; the\nhome query went from 94.5 ms to 56.2 ms on nothing else.</li>\n<li><strong><code>SELECT DISTINCT</code> is asked for only where a page can actually\nduplicate.</strong> <code>social_stream_dest</code> is unique on <code>(stream_id, actor_id, type)</code>, so a query that fixes the actor <em>and</em> the type — public,\nnotifications, direct, the marked timelines — cannot match a post twice.\nThose now select without it: the public page query went from <strong>37.4 ms to\n0.21 ms</strong>, for the same twenty rows, with no duplicates among them. The\nhome timeline keeps it, because a post addressed to three accounts you\nfollow really does match three rows. <code>getNidsFromRequest()</code> deduplicates the\ntwenty integers in PHP as well, which covers the one case SQL uniqueness\ndoes not: the left join on expired mutes can match twice for a viewer who\ntimed-muted both a booster and the account they boosted.</li>\n<li><strong>Notifications moved onto the two-query pattern</strong> the home and public\ntimelines already used — choose a page of ids, then hydrate them. It was\ncarrying two full stream column sets, two cached-actor sets and two\ncached-document sets through a <code>DISTINCT</code> to pick twenty rows, and every\nclient polls it on a timer.</li>\n</ol>\n<p>And one that is not about reads at all: <strong>a viewer&#39;s domain blocks are no\nlonger joined per row.</strong> The filter was a <code>LEFT JOIN</code> whose <code>ON</code> clause held\nfour <code>LIKE</code>s against <code>LOWER(attributed_to)</code> — an unindexed text column —\nevaluated for every candidate row of every timeline, for every account,\nincluding the overwhelming majority who have blocked nothing. The list is read\nonce per request and compared as constants; an account that has blocked nothing\nnow adds no clause at all. Measured at 56.2 ms → 41.5 ms on the home timeline\nof an instance with a single block row.</p>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":null,"anchor":"what-a-page-costs","manual":false,"prev":{"path":"/docs/performance","title":"Performance and scalability"},"next":{"path":"/docs/performance-what-is-still-open","title":"What is still open"},"parent":null},{"slug":"performance-what-is-still-open","path":"/docs/performance-what-is-still-open","title":"What is still open","description":"Nothing is unbounded any more. What is left is bounded work that could still be cheaper, and the schema items at the end.","group":"performance","html":"<h2 id=\"unbounded-work\">Unbounded work</h2>\n<p>Nothing is unbounded any more. What is left is bounded work that\ncould still be cheaper, and the schema items at the end.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Where</th>\n<th>What it costs now</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>StreamRequest::getDescendants()</code></td>\n<td>A thread is walked a level at a time, each level one query, bounded by depth and by page size. Fine for a conversation; a thread thousands deep is still thousands of levels.</td>\n</tr>\n<tr>\n<td><code>CacheActorService::getFromId()</code></td>\n<td>An uncached actor is fetched over HTTP inside the request that asked for it. Bounded by the access list and a timeout, but it is network in a read path.</td>\n</tr>\n<tr>\n<td><code>StreamPruneService</code></td>\n<td>The retention pass is <code>NOT EXISTS</code> over the largest table, which is a sequential scan by design. It runs from cron and from <code>occ</code>, never from a request.</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"transactions\">Transactions</h2>\n<p><code>StreamRequest::save()</code> is now one transaction: the post, its recipient rows\nand its tags go in together or not at all, and <code>StreamDestRequest::createRecipients()</code>\nraises instead of logging a failure and carrying on. It was the one place where\na partial write was both permanent and silent — the recipient rows are what put\na post in a timeline, so the post existed and was in nobody&#39;s.</p>\n<p>Inside a transaction, a <em>tolerated</em> failure is not free either. Recipients and\nhashtags repeat in ordinary posts — <code>getToAll()</code> returns <code>to</code> alongside\n<code>toArray</code>, the unique index on the recipient rows does not include the subtype\nso the same actor in <code>to</code> and <code>cc</code> collides too — and both inserts used to\ncatch the violation and carry on. PostgreSQL aborts the whole transaction on\nany refused statement, so that caught violation took the commit with it and the\npost was lost. Both now ask the database to skip the duplicate row, nothing\nfails, and the raise is left to mean what it says. The recipient rows go in as\none statement per post (<code>CoreRequestBuilder::insertIgnoringConflicts()</code>: the\nmulti-row <code>INSERT IGNORE</code> / <code>ON CONFLICT DO NOTHING</code> / <code>INSERT OR IGNORE</code> that\n<code>insertIgnoreConflict()</code> issues for one row), not one round trip per recipient\nwith the post&#39;s locks held.</p>\n<p>The two places this section used to name are settled: <code>StreamActionsRequest::save()</code>\ninserts first and updates on the unique violation (<code>StreamActionsFlagsTest</code> pins\nthe race), and <code>ModerationRequest::save()</code> does the same rather than delete-then-\ninsert, so a decision is replaced or kept, never lost.</p>\n<h2 id=\"wide-select-distinct\">Wide <code>SELECT DISTINCT</code></h2>\n<p><code>getStreamNidsSelectSql()</code> exists precisely to avoid deduplicating over every\ncolumn — it selects nids, then hydrates. <strong>Every branch of <code>getTimeline()</code> now\ngoes through it</strong>: home (both halves), public, direct, account, hashtag,\nfavourites and bookmarks, notifications, and the list timeline in <code>ListsRequest</code>\n— each a <code>*TimelineNids()</code> method that decides the page over one indexed\ncolumn, then <code>streamsByNids()</code> for exactly those rows\n(<code>tests/Db/TwoQueryTimelinesTest.php</code> pins the shape for the three moved last).\nWhat still pairs <code>selectDistinct(&#39;s.id&#39;)</code> with the full stream column set is\nthe single-row lookups (<code>getStreamById()</code> and friends, which return one row and\nhave nothing to deduplicate), <code>searchContent()</code> (which hydrates only the nids\nthe word index picked, but still through the wide select), <code>getDescendants()</code> /\n<code>getRepliesTo()</code>, <code>getAnnouncesAndRepliesTo()</code>, and the <code>*_dep()</code> methods behind\nthe uncalled Custom Local API routes. Of those, the thread walk is the one worth\nmoving next; the <code>_dep</code> ones go with their routes.</p>\n<h2 id=\"lookups-that-cannot-use-an-index\">Lookups that cannot use an index</h2>\n<p><code>DomainBlocksRequestBuilder::filterDomainBlocked()</code> is no longer one of them:\nthe blocked domains are read once per request, skipped entirely for an account\nthat has blocked nothing, and compared as one <code>NOT IN</code> against\n<code>social_stream.author_host</code>, the author&#39;s host in its own indexed column. The\nsilenced-instance filter next door uses the same column. Both still carry the\nold <code>LIKE</code>s on <code>attributed_to</code> for rows whose host is NULL, until\n<code>Cron\\StreamAuthorHosts</code> has filled in every row stored before the column and\nset <code>stream_author_hosts_filled</code>.</p>\n<p>The <code>*_prim</code> columns (md5 of the lower-cased id) exist so a lookup can be an\nindexed equality. The hot paths now use them, but <code>ActorsRequest</code>&#39;s\n<code>preferred_username</code> lookups still compare <code>LOWER(column)</code> against\n<code>LOWER(?)</code> on an unindexed column — the public ActivityPub actor endpoint and\nwebfinger both land there.</p>\n<h2 id=\"paging-by-offset\">Paging by offset</h2>\n<p>An offset page reads and throws away every row before it, so page <em>n</em> costs\n<em>n</em> pages. Everything this app walks for itself pages on a keyset: the\ntimelines on the nid, the follower and following lists on (<code>creation</code>,\n<code>id_prim</code>) through <code>FollowsRequest::cursorAfter()</code> — which is also how the\nexport of both lists and the re-follow after a Move walk them. The offsets\nthat are left are ones a contract outside this app asks for:</p>\n<ul>\n<li>the numbered <code>?page=N</code> of the ActivityPub outbox, followers, following and\nreplies collections (<code>getPublicByAuthor()</code>, <code>getFollowersByActorId()</code>,\n<code>getFollowingByActorId()</code>, <code>getPublicRepliesTo()</code>), because those are the\naddresses peers already hold. Every <code>next</code> link those pages hand out is a\ncursor, so a peer that follows them never reads by offset past the first;</li>\n<li>Mastodon&#39;s <code>offset</code> on <code>/api/v1/trends/*</code> (<code>TrendsRequest</code>), where the rows\nare a ranking over a window and the grouping, not the offset, is the cost;</li>\n<li>Mastodon&#39;s <code>offset</code> on <code>/api/v2/search</code>, capped at\n<code>StreamRequest::SEARCH_MAX_OFFSET</code>, with <code>max_id</code> the way further back.</li>\n</ul>\n<p><code>favourited_by</code> and <code>reblogged_by</code> answer one page of up to 80 accounts and do\nnot page at all.</p>\n<h2 id=\"schema-shape\">Schema shape</h2>\n<ul>\n<li><del><code>social_follow</code>&#39;s unique indexes lead with the <code>accepted</code> boolean</del> —\nfixed by <code>Version1000Date20260913000001</code>, which drops both, adds\n<code>social_f_oa_u</code> unique on <code>(object_id_prim, actor_id_prim)</code> and\n<code>social_f_foa</code> on the three id columns, and removes the duplicate rows that\nthe old shape allowed before adding them. That migration also drops\n<code>social_stream_dest.ts (type, subtype)</code>: three values against three across\nthe second-largest table, never the best index for any query the app makes,\nand pure write cost — 27.7 MB of index over 8 MB of data on a 65,000-row\ntable.</li>\n<li>Several indexes from the 2022 migration are unnamed, so Doctrine names them\nper install and a later <code>hasIndex()</code>/<code>dropIndex()</code> cannot refer to them. Index\nnames from that era are also not app-prefixed (<code>sa</code>, <code>ts</code>, <code>aoa</code>, …) and live\nin PostgreSQL&#39;s schema-global namespace, where another app can collide with\nthem. Migrations from 2026 use <code>social_*</code>.</li>\n<li>Every <code>NOT NULL</code> column these migrations add carries an explicit default,\nincluding <code>social_cache_doc.account</code>. PostgreSQL refuses a <code>NOT NULL</code> column\non a table that already has rows unless there is one (&quot;column contains null\nvalues&quot;) where MySQL quietly invents the empty string, so the default is what\nmakes such a column safe to add at all. <code>CoreSchemaTest</code> holds the four\ncolumns on that table to it.</li>\n<li><del>The queue drain&#39;s sort had no index behind it</del> — <code>getStandby()</code> selects on\n<code>status</code> and orders <code>priority DESC, tries ASC, last ASC, id ASC</code> to take 200\nrows, and the only index on the table was <code>social_rq_si (status, id)</code>: every\ndrain, every twelve minutes, sorted the whole standby set to pick its window.\n<code>Version1000Date20260914000003</code> adds <code>social_rq_sptl (status, priority, tries, last)</code>, which is the select and the first three sort keys in order, so the\nwindow is read off the index. <code>id</code> is left out on purpose — it only breaks\nties between rows that agree on the other three, and a fifth column would be\nwrite cost on the hottest-written table in the app for nothing.</li>\n<li>The same migration adds <code>social_cache_actor.sync_attempt</code>/<code>sync_failures</code> and\n<code>social_ca_lsa (local, sync_attempt)</code>. Both are integers rather than\ndatetimes so that &quot;never&quot; is 0 and sorts identically on every database, where\na NULL datetime does not.</li>\n<li><code>social_stream_act.bookmarked</code> is <code>SMALLINT</code> while its three sibling flags are\n<code>BOOLEAN</code>.</li>\n<li><code>social_stream</code> carries nine JSON-in-TEXT columns — <code>to_array</code>, <code>cc</code>, <code>bcc</code>,\n<code>hashtags</code>, <code>tags</code>, <code>details</code>, <code>instances</code>, <code>attachments</code> and <code>cache</code> — plus\n<code>source</code>, the whole ActivityPub wire object. None of them can be filtered,\nindexed or sorted on by any database this app supports, so anything that has\nto be queried needs a column or a side table of its own, and every insert\nwrites both copies: <code>hashtags</code> duplicates <code>social_stream_tag</code>, and\n<code>to_array</code>/<code>cc</code>/<code>bcc</code> duplicate <code>social_stream_dest</code>. That is the cost of the\narrangement, and it is paid knowingly — the side tables exist <em>because</em> the\nJSON is unqueryable.</li>\n<li>Five post fields used to be readable only by <code>json_decode</code>ing <code>source</code> once\nper timeline row: <code>tag</code>, <code>language</code>, <code>updated</code>, <code>quote</code> and\n<code>quoteAuthorization</code>. <code>Version1000Date20260912000007</code> gave each a column, so\n<code>language</code> is now an indexed equality (<code>social_s_lang</code>) and the other four are\nread without parsing. <code>tags</code> stayed JSON, because the one facet of the <code>tag</code>\narray worth querying — the hashtags — is already <code>social_stream_tag</code>, and a\nsecond side table would be a second source of truth for it. <code>quote</code> and\n<code>quote_authorization</code> have no <code>_prim</code> companions: no query filters on either,\nand an md5 column plus index on the largest table in the app costs every\ninsert for a read nobody makes. Rows written before that step still fall back\nto <code>source</code> until <code>BackfillStreamPostFields</code> reaches them.</li>\n<li>The four <code>NOT EXISTS</code> clauses in <code>StreamPruneService</code> are assembled by calling\n<code>getSQL()</code> on separate query builders and concatenating the strings. The\nsub-builders have their own parameter namespaces, so a\n<code>createNamedParameter()</code> added inside one later would silently vanish from the\nouter query.</li>\n</ul>\n","toc":[{"id":"unbounded-work","text":"Unbounded work","level":2},{"id":"transactions","text":"Transactions","level":2},{"id":"wide-select-distinct","text":"Wide SELECT DISTINCT","level":2},{"id":"lookups-that-cannot-use-an-index","text":"Lookups that cannot use an index","level":2},{"id":"paging-by-offset","text":"Paging by offset","level":2},{"id":"schema-shape","text":"Schema shape","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":null,"anchor":"what-is-still-open","manual":false,"prev":{"path":"/docs/performance-what-a-page-costs","title":"What a page costs"},"next":{"path":"/docs/performance-the-frontend-bundle","title":"The frontend bundle"},"parent":null},{"slug":"performance-the-frontend-bundle","path":"/docs/performance-the-frontend-bundle","title":"The frontend bundle","description":"Every byte here is downloaded before the first post is on screen, so this is the part of the app's speed that a fast database cannot help with. Sizes are gzipped, which is what the wire…","group":"performance","html":"<p>Every byte here is downloaded before the first post is on screen, so this is\nthe part of the app&#39;s speed that a fast database cannot help with. Sizes are\ngzipped, which is what the wire actually carries.</p>\n<p>Since 0.19.13 the third-party code that more than one entry needs lives in one\nshared <code>social-framework</code> chunk rather than being built into each entry, so the\nhonest figure for a page is that chunk <strong>plus</strong> the entry — which is what this\ntable gives.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Page</th>\n<th align=\"right\">0.19.13</th>\n<th align=\"right\">0.19.14</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>the app (<code>framework</code> + <code>social</code>)</td>\n<td align=\"right\">357.5 KB</td>\n<td align=\"right\">265.1 KB</td>\n</tr>\n<tr>\n<td>a public profile (<code>framework</code> + <code>profilePage</code>)</td>\n<td align=\"right\">356.5 KB</td>\n<td align=\"right\">269.2 KB</td>\n</tr>\n<tr>\n<td>the remote-follow page (<code>framework</code> + <code>ostatus</code>)</td>\n<td align=\"right\">313.2 KB</td>\n<td align=\"right\">223.5 KB</td>\n</tr>\n<tr>\n<td>the dashboard widget (<code>framework</code> + <code>dashboard</code>)</td>\n<td align=\"right\">309.7 KB</td>\n<td align=\"right\">220.0 KB</td>\n</tr>\n<tr>\n<td>the consent screen (<code>framework</code> + <code>oauth</code>)</td>\n<td align=\"right\">305.2 KB</td>\n<td align=\"right\">215.4 KB</td>\n</tr>\n</tbody></table></div>\n<p>Almost all of it is the shared chunk, which went from 294.8 KB to 204.8 KB —\na saving every page gets once, and every page after the first gets for free.\nThree changes account for it:</p>\n<ul>\n<li><strong>Toasts are fetched when one is shown</strong> (<code>src/services/toast.js</code>).\n<code>@nextcloud/dialogs</code> re-exports the file picker, the conflict picker and the\ndialog builder from the same module as <code>showError</code>, so importing the toast\ncannot be tree-shaken down to the toast: it put 259 KB of source into the\nshared chunk so that a page could eventually say &quot;Could not load the\ntimeline&quot;. Nothing waits for a toast, so the wrapper returns a promise\ncallers are free to ignore and the library arrives in a chunk of its own the\nfirst time one is needed. The one caller that needs more than a toast — the\ncomposer&#39;s file picker — imports the library where it opens the picker.</li>\n<li><strong>The emoji picker is fetched when somebody asks for one.</strong> It was already\nits own chunk — 130 KB gzipped, nearly all of it the emoji set — but the\ncomposer imported it statically, so the browser fetched it alongside the\ncomposer on the home timeline whether or not anybody wanted an emoji. It is a\n<code>defineAsyncComponent</code> now, and the button that opens it stays on screen with\na spinner until the chunk is there, so one press still opens the picker. A\nfailed chunk request leaves that button available, clears the rejected import\npromise, and lets the next press retry instead of leaving a permanently\nrejected picker on the page.</li>\n<li><strong>Vue&#39;s production flags</strong> (<code>__VUE_PROD_DEVTOOLS__</code> and friends, set in\n<code>webpack.common.js</code>). Without them the devtools bridge is compiled in:\n<code>@vue/devtools-api</code> pulls <code>@vue/devtools-kit</code>, which nothing in a released\napp can reach. Measured on its own by building with and without: <strong>31.0 KB</strong>\nof the shared chunk and 2.1 KB of the main entry.</li>\n</ul>\n<p>Neither <code>@nextcloud/dialogs</code> nor the emoji set appears in <code>social-framework.js</code>\nor <code>social-social.js</code> any more, which is the check worth repeating after any\nwork here: read the source maps rather than the sizes.</p>\n<p>Scope hoisting was tried and left off, where it has been since 0.9.3: it is\nworth about 1 KB, and with it on two consecutive builds of the same source\nproduce two different bundles, because Terser mangles the merged scopes\ndifferently each time. CI checks that the committed <code>js/</code> matches <code>src/</code>, so a\nbuild that is not reproducible is worse than a kilobyte.</p>\n<p>The <code>buffer</code> polyfill went with them: nothing had required it since the\ndependency that did was dropped, and the fallback resolved a package into the\nbuild for no caller.</p>\n<h2 id=\"what-is-left-and-why-it-is-still-there\">What is left, and why it is still there</h2>\n<ul>\n<li><strong><code>@nextcloud/vue</code> is a third of the main entry</strong> — 924 KB of the 2.7 MB of\nsource webpack puts into it — and half of that is one file: <code>_l10n.mjs</code>\nships the library&#39;s own translations for forty languages and picks one at\nruntime. Components are already imported one by one\n(<code>@nextcloud/vue/components/NcButton</code>, never the package root), so this is\nnot ours to tree-shake — it needs a change upstream.</li>\n<li><strong>The date picker</strong> is its own chunk, fetched when a poll&#39;s end date is set.\nSo are the routes: every view behind the router is an <code>import()</code>.</li>\n<li><strong>DOMPurify</strong> (130 KB of source, 5% of the entry) is there for profile bios\nonly — post bodies go through <code>MessageContent.js</code>, which builds vnodes rather\nthan markup. It could be deferred the way toasts were, but a bio that renders\na frame late is the worse trade.</li>\n</ul>\n","toc":[{"id":"what-is-left-and-why-it-is-still-there","text":"What is left, and why it is still there","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":null,"anchor":"the-frontend-bundle","manual":false,"prev":{"path":"/docs/performance-what-is-still-open","title":"What is still open"},"next":{"path":"/docs/performance-what-was-fixed-and-what-fixed-it","title":"What was fixed, and what fixed it"},"parent":null},{"slug":"performance-what-was-fixed-and-what-fixed-it","path":"/docs/performance-what-was-fixed-and-what-fixed-it","title":"What was fixed, and what fixed it","description":"The previous survey (2026-09-10, against 0.11.49) is largely answered. Kept here so a reader who finds that report knows why the code no longer matches it.","group":"performance","html":"<p>The previous survey (2026-09-10, against 0.11.49) is largely answered. Kept\nhere so a reader who finds that report knows why the code no longer matches it.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Then</th>\n<th>Now</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Anonymous reads cross-joined the whole <code>social_follow</code> table: the no-viewer branch called <code>selectDestFollowing($aliasDest)</code> without the second argument, so the join had no predicate</td>\n<td>Both branches pass <code>&#39;&#39;</code>. On an instance with no follow rows, anonymous status fetches and public timelines work</td>\n</tr>\n<tr>\n<td><code>social_cache_doc.id_prim</code> — the join key for every avatar and attachment — had no index</td>\n<td><code>Version1000Date20260910000001</code> adds <code>social_cd_idp</code> and <code>social_cd_pidp</code></td>\n</tr>\n<tr>\n<td>Every id/account lookup wrapped the column in <code>LOWER()</code> on unindexed text</td>\n<td>The hot lookups take the <code>*_prim</code> path (<code>limitToIdPrimString()</code> and friends)</td>\n</tr>\n<tr>\n<td>Missing indexes on favourites, bookmarks, hashtag timelines, like/boost counts, both queue drains, and <code>social_client.token</code> — the last one a full scan of the client table on every API request</td>\n<td>All added by <code>Version1000Date20260910000001</code>, which also drops the redundant five-column <code>ipoha</code> index</td>\n</tr>\n<tr>\n<td>Deleting a post left rows in five tables and files on disk</td>\n<td><code>deleteById()</code>/<code>deleteByAuthor()</code> go through the related-row deletion</td>\n</tr>\n<tr>\n<td><code>occ social:reset --uninstall</code> left two tables behind</td>\n<td>Every declared table is in <code>$tables</code>, and <code>tests/Db/SchemaConventionsTest.php</code> fails if a new constant is not</td>\n</tr>\n<tr>\n<td>Two cron loops did unbounded outbound HTTP per row</td>\n<td><code>getRemoteActorsToUpdateDetails()</code> and <code>getStandby()</code> are capped (one remains — see above)</td>\n</tr>\n<tr>\n<td>The admin report list resolved each reported account one at a time, fetching over the network when uncached: one unreachable instance hung the page</td>\n<td><code>ReportService::getReports()</code> resolves them in one batch from the cache only</td>\n</tr>\n<tr>\n<td><code>filterSilencedActors()</code> was dead code, so a silenced account was not silenced</td>\n<td>Called from the three read paths that need it</td>\n</tr>\n<tr>\n<td><code>HashtagService::manageHashtags()</code> ran five hydrated wide queries and one write per hashtag, and reported the same number for every window</td>\n<td><code>StreamRequest::countHashtagsInWindows()</code> is one grouped aggregate over the widest window, with a conditional sum per window</td>\n</tr>\n<tr>\n<td><code>CacheActorsRequest::getSharedInboxes()</code> returned <code>&#39;&#39;</code> for actors with no shared inbox, which the caller turned into a delivery to the host <code>&#39;&#39;</code></td>\n<td>Empty values and local actors are excluded in SQL</td>\n</tr>\n<tr>\n<td>An account deletion was queued for every shared inbox ever cached, read with a <code>SELECT DISTINCT</code> over the unindexed TEXT column, dead servers included</td>\n<td><code>getSharedInboxesSeenSince()</code> groups on the indexed <code>host</code> and keeps servers heard from in the last 90 days; <code>ActivityService</code> drops those whose breaker is open</td>\n</tr>\n<tr>\n<td>The delivery fan-out hydrated every follower into a <code>Follow</code> with a <code>Person</code> and its details to read one string off each</td>\n<td><code>ActivityService::generateInstancePathsFollowers()</code> asks <code>FollowsRequest::getFollowerInboxes()</code> for one row per distinct inbox, resolved in the database — the number of <em>instances</em>, not of followers</td>\n</tr>\n<tr>\n<td><code>MigrationService</code> re-followed on behalf of every local follower from one unbounded read</td>\n<td>Paged at <code>REFOLLOW_PAGE</code>, bounded at <code>REFOLLOW_MAX</code></td>\n</tr>\n<tr>\n<td><code>social_actor.user_id</code> had no index, and it is what resolves the logged-in user&#39;s actor on every authenticated request</td>\n<td><code>Version1000Date20260912000001</code> adds <code>social_a_uid</code>, and the four <code>social_hashtag</code> trend columns got theirs</td>\n</tr>\n<tr>\n<td><code>ReportService</code> and the account entity leaked <code>source</code> on every read, so every Account query carried <code>follow_requests_count</code></td>\n<td><code>source</code> is built by the two credentials routes only; nothing else asks the database for it</td>\n</tr>\n<tr>\n<td><code>getNotCachedDocuments()</code> read every uncached document and fetched each one over HTTP in a single cron slot</td>\n<td>Capped at <code>CACHE_BATCH</code>; the rest is the next run&#39;s, which is what its two siblings already did</td>\n</tr>\n<tr>\n<td><code>deleteStreamFromActor()</code> walked every post that ever addressed an account, inline in the inbox request a peer was waiting on — so the peer timed out, re-sent the <code>Delete</code>, and the walk started again</td>\n<td>Paged by keyset (<code>DETACH_PAGE</code>), bounded per request (<code>DETACH_INLINE</code>), and finished by <code>Cron\\ActorCleanup</code>, which re-queues itself while rows remain</td>\n</tr>\n<tr>\n<td>A page of relationships cost six queries per account — two follow rows, the blocks and mutes, the note, the mute&#39;s expiry</td>\n<td>Five queries for any number of accounts (<code>getBetweenMany()</code>, <code>getNotes()</code>, <code>getExpiries()</code>), and the single-account route goes down the same path so the two cannot disagree</td>\n</tr>\n<tr>\n<td><code>HashtagService::manageHashtags()</code> read every hashtag the instance had ever seen on every cron run</td>\n<td><code>getWithAnyTrend()</code> reads only the rows that claim a trend — the only ones it can change</td>\n</tr>\n<tr>\n<td><code>FollowService::getFollowers()</code> hydrated every follower for a route with no cursor</td>\n<td>Bounded at <code>FOLLOWERS_PAGE</code>; the paging route is <code>/api/v1/accounts/{account}/followers</code></td>\n</tr>\n<tr>\n<td>One dead instance froze the actor-cache refresh: <code>getRemoteActorsToUpdate()</code> took 50 stale rows with no order and no record of having tried, and a failed refresh wrote nothing — so the same 50 unreachable rows came back every twelve minutes and no live profile was refreshed again</td>\n<td>Every attempt is stamped in <code>sync_attempt</code>, the oldest attempt goes first, a failure doubles the wait from an hour, and after ten failures the refresh leaves the actor alone. Nothing is deleted: the row, its followers and its posts stay, and an on-demand fetch still resets the count</td>\n</tr>\n<tr>\n<td><code>Cron\\Cache</code> had no wall-clock budget while <code>Cron\\Queue</code> had one: eleven steps, two of them a request per remote actor, ran until they were done — so a handful of slow peers could hold a cron slot open past the twelve-minute interval</td>\n<td><code>MAX_DURATION</code> of 300 seconds, threaded through the steps and into the two loops. A skipped step is named in the log and the next run starts with it, so the tail of the list is not the part that never runs</td>\n</tr>\n<tr>\n<td>Nothing ever evicted a cached remote actor: a row was written the first time this instance saw an account and only a remote <code>Delete</code> or a domain purge removed one</td>\n<td><code>CacheActorSweepService</code>, bounded per cron pass, removes the ones nobody here follows, that follow nobody here, that wrote no stored post and have no pending relation, after <code>cache_actor_days</code> (180) — with their avatars. <code>occ social:media:usage</code> is what says how much that is worth</td>\n</tr>\n<tr>\n<td><code>StreamRequest::save()</code> wrote the post, then its recipients, then its tags, outside any transaction, and the recipient insert swallowed its failure</td>\n<td>One transaction, and <code>StreamDestRequest::createRecipients()</code> raises. A post that cannot have recipients is not stored at all, so the delivery can be retried into a clean state. The duplicate recipient and hashtag rows an ordinary post produces are skipped by the database rather than caught, which a transaction on PostgreSQL does not survive</td>\n</tr>\n</tbody></table></div>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":null,"anchor":"what-was-fixed-and-what-fixed-it","manual":false,"prev":{"path":"/docs/performance-the-frontend-bundle","title":"The frontend bundle"},"next":{"path":"/docs/performance-the-home-timeline-and-one-thing-that-did-not-work","title":"The home timeline, and one thing that did not work"},"parent":null},{"slug":"performance-the-home-timeline-and-one-thing-that-did-not-work","path":"/docs/performance-the-home-timeline-and-one-thing-that-did-not-work","title":"The home timeline, and one thing that did not work","description":"Home is now the slowest page and the reason is structural: it asks for \"the newest posts addressed to anyone I follow\", where the selection lives in social_stream_dest and the order in…","group":"performance","html":"<p>Home is now the slowest page and the reason is structural: it asks for &quot;the\nnewest posts addressed to anyone I follow&quot;, where the selection lives in\n<code>social_stream_dest</code> and the order in <code>social_stream</code>. The database drives from\nthe follow rows, walks each followed account&#39;s recipient rows, joins the post to\nevery one of them and sorts the result — at 22,642 posts and 325 follows that\njoin produced <strong>16,111 rows to return 20</strong>, with <code>Using temporary; Using filesort</code> over all of them.</p>\n<p>The obvious fix looked like copying the post&#39;s <code>nid</code> onto its recipient row, so\nthat <code>(actor_id, type, nid)</code> could select <em>and</em> order a page from one index. On\na stripped query that measured 25.9 ms → 2.95 ms. <strong>It does not work on the real\none</strong>, and the plan says why: with the filters attached — the hidden-actor\nanti-joins, the mute expiry, the author join — MariaDB still drives from the\nfollows and still sorts, so the sort key on the recipient row changes nothing it\ncan use. The column, its index, the write and a backfill repair step were\nwritten, measured at <strong>no improvement</strong>, and removed again rather than shipped.\nAnyone reaching for that idea again should measure the <em>whole</em> query first.</p>\n<p>What is left, in order of how much it would cost to try:</p>\n<ul>\n<li><strong>A semi-join.</strong> <code>WHERE EXISTS (SELECT 1 FROM social_stream_dest sd JOIN social_follow f …)</code> emits each post once, which removes the deduplication and\nlets the database walk <code>social_stream</code> backwards by primary key and stop after\ntwenty — exactly what made the public timeline 178× faster. The trade is the\nopposite one: it is fast when the people you follow post often and slow when\nthey do not, because then it walks a long way back for twenty rows. Worth\nmeasuring on both shapes of instance before choosing.</li>\n<li><strong>Fan-out on write.</strong> One row per (viewer, post) in a table indexed\n<code>(viewer, nid)</code> makes the home timeline a single index range. It is what the\nlarge implementations do, and it costs a write per follower on every post.</li>\n</ul>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":null,"anchor":"the-home-timeline-and-one-thing-that-did-not-work","manual":false,"prev":{"path":"/docs/performance-what-was-fixed-and-what-fixed-it","title":"What was fixed, and what fixed it"},"next":{"path":"/docs/performance-what-to-do-next","title":"What to do next"},"parent":null},{"slug":"performance-what-to-do-next","path":"/docs/performance-what-to-do-next","title":"What to do next","description":"Aloha Social documentation.","group":"performance","html":"<ol>\n<li><strong>Move the thread walk (<code>getDescendants()</code>, <code>getRepliesTo()</code>) onto\n<code>getStreamNidsSelectSql()</code>.</strong> Every timeline is on it now, and the search\npicks its page from the word index before it hydrates; the thread walk is\nwhat is left of the wide <code>SELECT DISTINCT</code>, and also the one read that is\nstill a query per level.</li>\n<li><strong>Retire the <code>*_dep()</code> methods with the Custom Local API routes</strong> that call\nthem (Technical-Debt.md, item 2): that removes the last wide timeline reads\nwithout rewriting them.</li>\n<li><strong>The schema items</strong>, next time a migration touches those tables. The\n<code>social_follow</code> index order is the one worth doing deliberately: it is why a\nduplicate accepted/pending pair can exist at all.</li>\n<li><strong>An index on <code>social_actor.preferred_username</code></strong>, or a <code>*_prim</code> column for\nit, if the public actor endpoint and webfinger ever show up in a profile.\nBoth still compare <code>LOWER(column)</code> against <code>LOWER(?)</code>.</li>\n</ol>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Performance.md","sections":null,"anchor":"what-to-do-next","manual":false,"prev":{"path":"/docs/performance-the-home-timeline-and-one-thing-that-did-not-work","title":"The home timeline, and one thing that did not work"},"next":null,"parent":null},{"slug":"debt","path":"/docs/debt","title":"Technical debt and legacy code","description":"What in this app is old, borrowed or load-bearing in a way nobody would choose today, what is simply dead, and what it would cost to change. Written for whoever has to decide where…","group":"project","html":"<p>What in this app is old, borrowed or load-bearing in a way nobody would choose\ntoday, what is simply dead, and what it would cost to change. Written for\nwhoever has to decide where refactoring effort goes.</p>\n<p><strong>Verified against:</strong> app version 0.17.0, 2026-09-12, after the wave described\nin <a href=\"/docs/debt-what-has-been-done#what-has-been-done\">What has been done</a>. Every number was measured on that\ntree rather than carried over — except the migration, repair-step, table,\nclass, controller, import and <code>src/</code> file counts, which were re-measured on\n0.19.49 on 2026-09-14 — and\n<a href=\"/docs/debt-reproducing-the-measurements#reproducing-the-measurements\">Reproducing the measurements</a> gives the command\nfor each.</p>\n<p><strong>The support floors are whatever <code>appinfo/info.xml</code> declares.</strong> Nothing else in\nthe repository holds them: the PHPUnit, lint and appstore workflows read the PHP\nand Aloha ranges out of that file, through\n<code>icewind1991/nextcloud-version-matrix</code> and a direct <code>grep php min-version</code>, so\nchanging two attributes there changes what CI tests against. They now say <strong>PHP\n8.3–8.5 and Aloha 35–36</strong>, and <code>composer.json</code>, <code>psalm.xml</code> and the server\nAPI stubs agree with them rather than contradicting them.</p>\n<p>Like <a href=\"/docs/performance\">Performance.md</a>, this file is <strong>not</strong> enforced by\n<code>tests/DocumentationTest.php</code> beyond its title: its claims are structural rather\nthan checkable against a route table, so nothing fails when it goes stale.\nRe-measure before quoting it. Query and scalability behaviour lives in\n<code>Performance.md</code>; the schema is described in <a href=\"Architecture.md\">Architecture.md</a>.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":[{"path":"/docs/debt-the-shape-of-what-is-left","title":"The shape of what is left","description":"The app is 76,325 lines of PHP across 415 files in lib/, and 17,779 lines of JavaScript and Vue across 81 files in src/.","parent":false},{"path":"/docs/debt-age-of-the-code","title":"Age of the code","description":"Run it on a complete checkout: git blame can only attribute lines it has history for, so a shallow or out-of-date clone silently understates the recent share. Measured on a checkout…","parent":false},{"path":"/docs/debt-two-api-generations-in-one-url-namespace","title":"Two API generations in one URL namespace","description":"So /api/v1/stream/home (local: since/limit cursor, default page size 5, no Link header, {status, result} envelope) sits directly beside /api/v1/timelines/home (Mastodon: max_id/since_id…","parent":false},{"path":"/docs/debt-schema-and-migrations","title":"Schema and migrations","description":"Performance.md covers query behaviour and the index and schema-shape hazards. What follows is the debt in the migration set itself.","parent":false},{"path":"/docs/debt-frontend","title":"Frontend","description":"Still Options API. There are setup() blocks now, because the composables need them, but no <script setup> and no wholesale move to composition. That is a style question rather than debt…","parent":false},{"path":"/docs/debt-toolchain","title":"Toolchain","description":"PHPUnit 12, with the mock hygiene it asks for. A double nothing sets an expectation on is a createStub() (about 1,400 of them were createMock()), and the ActivityPub dispatcher the model…","parent":false},{"path":"/docs/debt-remaining-odds-and-ends","title":"Remaining odds and ends","description":"20 @deprecated markers in lib/, 12 of them on methods with live callers, led by CoreRequestBuilder::leftJoinStreamAction (17) and SocialLimitsQueryBuilder::limitPaginate (8). The worst of…","parent":false},{"path":"/docs/debt-translations","title":"Translations","description":"The frontend contains 295 distinct translatable strings. The best-covered locales (de, de_DE, en_GB) carry 135. The median locale across 98 languages carries 21, and 47 carry fewer than…","parent":false},{"path":"/docs/debt-what-is-not-debt","title":"What is not debt","description":"**Classes from outside OCP\\: none.** No OC\\DB\\QueryBuilder\\QueryBuilder, no \\OC::$server, no OC\\SystemConfig, no Doctrine\\DBAL\\Query\\QueryBuilder. The only matches are docblock sentences…","parent":false},{"path":"/docs/debt-what-has-been-done","title":"What has been done","description":"tag, language, updated, quote and quoteAuthorization are columns on social_stream, written where a row is written and read with a per-field fallback to the stored JSON, with a repair step…","parent":false},{"path":"/docs/debt-rough-order-of-value-for-what-is-left","title":"Rough order of value for what is left","description":"Aloha Social documentation.","parent":false},{"path":"/docs/debt-reproducing-the-measurements","title":"Reproducing the measurements","description":"Aloha Social documentation.","parent":false}],"anchor":null,"manual":false,"prev":null,"next":{"path":"/docs/debt-the-shape-of-what-is-left","title":"The shape of what is left"},"parent":null},{"slug":"debt-the-shape-of-what-is-left","path":"/docs/debt-the-shape-of-what-is-left","title":"The shape of what is left","description":"The app is 76,325 lines of PHP across 415 files in lib/, and 17,779 lines of JavaScript and Vue across 81 files in src/.","group":"project","html":"<p>The app is 76,325 lines of PHP across 415 files in <code>lib/</code>, and 17,779 lines of\nJavaScript and Vue across 81 files in <code>src/</code>.</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Theme</th>\n<th>Severity</th>\n<th>Size</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Translation catalogue covers under 40 % of source strings</td>\n<td>Low</td>\n<td>—</td>\n</tr>\n</tbody></table></div>\n<p>The two largest items in every previous version of this document are both gone.\nThe vendored toolkit&#39;s query builder no longer extends a private core class, and\nthe 856-line request model in front of the OCP HTTP client has been deleted\nrather than ported. <code>lib/Tools/</code> is 25 files and 2,657 lines of helpers and\ntraits now — a third of what it was, and nothing in it reaches outside <code>OCP\\</code>.</p>\n<p>**Nothing in <code>lib/</code> names a class outside <code>OCP\\</code> any more,** and a unit test\nholds it there — not the server&#39;s private classes, not Doctrine, not Guzzle.\n<code>\\OC::$server</code>, <code>OC\\SystemConfig</code>, <code>OC\\DB\\Connection</code>, <code>OC\\DB\\SchemaWrapper</code>,\n<code>OC\\DB\\QueryBuilder\\QueryBuilder</code>, <code>OC\\User\\NoUserException</code>,\n<code>OC\\Core\\Command\\Base</code>, every <code>Doctrine\\</code> class and\n<code>GuzzleHttp\\Exception\\ClientException</code> are all gone; the matches that remain\nfor those names are sentences in docblocks explaining what used to be there.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"the-shape-of-what-is-left","manual":false,"prev":{"path":"/docs/debt","title":"Technical debt and legacy code"},"next":{"path":"/docs/debt-age-of-the-code","title":"Age of the code"},"parent":null},{"slug":"debt-age-of-the-code","path":"/docs/debt-age-of-the-code","title":"Age of the code","description":"Run it on a complete checkout: git blame can only attribute lines it has history for, so a shallow or out-of-date clone silently understates the recent share. Measured on a checkout…","group":"project","html":"<p>Lines of <code>lib/</code> by the year they were last touched, from <code>git blame</code>:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Year</th>\n<th>Lines</th>\n<th>Share</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>2018</td>\n<td>7,751</td>\n<td>10.2%</td>\n</tr>\n<tr>\n<td>2019</td>\n<td>8,506</td>\n<td>11.1%</td>\n</tr>\n<tr>\n<td>2020</td>\n<td>3,944</td>\n<td>5.2%</td>\n</tr>\n<tr>\n<td>2021</td>\n<td>10</td>\n<td>0.0%</td>\n</tr>\n<tr>\n<td>2022</td>\n<td>5,394</td>\n<td>7.1%</td>\n</tr>\n<tr>\n<td>2023</td>\n<td>3,491</td>\n<td>4.6%</td>\n</tr>\n<tr>\n<td>2024</td>\n<td>1,018</td>\n<td>1.3%</td>\n</tr>\n<tr>\n<td>2025</td>\n<td>50</td>\n<td>0.1%</td>\n</tr>\n<tr>\n<td>2026</td>\n<td>46,161</td>\n<td>60.5%</td>\n</tr>\n</tbody></table></div>\n<p>Run it on a complete checkout: <code>git blame</code> can only attribute lines it has\nhistory for, so a shallow or out-of-date clone silently understates the recent\nshare. Measured on a checkout hundreds of commits behind, 2026 came out at\n29 % rather than 60 %.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"age-of-the-code","manual":false,"prev":{"path":"/docs/debt-the-shape-of-what-is-left","title":"The shape of what is left"},"next":{"path":"/docs/debt-two-api-generations-in-one-url-namespace","title":"Two API generations in one URL namespace"},"parent":null},{"slug":"debt-two-api-generations-in-one-url-namespace","path":"/docs/debt-two-api-generations-in-one-url-namespace","title":"Two API generations in one URL namespace","description":"So /api/v1/stream/home (local: since/limit cursor, default page size 5, no Link header, {status, result} envelope) sits directly beside /api/v1/timelines/home (Mastodon: max_id/since_id…","group":"project","html":"<p>The app serves two API designs, and they share the <code>/api/v1/</code> prefix.</p>\n<ul>\n<li><strong>Mastodon-compatible</strong> — the controllers built on <code>MastodonApiController</code>, <code>ListController</code>,\n<code>FilterController</code> and others, through <code>StreamService::getTimeline(ProbeOptions)</code>.</li>\n<li><strong>Custom local</strong> — <code>LocalController</code> (1,068 lines), through the five\n<code>@deprecated</code> <code>StreamService::getStream*()</code> methods and the five\n<code>StreamRequest::getTimeline*_dep()</code> query methods behind them.</li>\n</ul>\n<p>So <code>/api/v1/stream/home</code> (local: <code>since</code>/<code>limit</code> cursor, default page size 5, no\n<code>Link</code> header, <code>{status, result}</code> envelope) sits directly beside\n<code>/api/v1/timelines/home</code> (Mastodon: <code>max_id</code>/<code>since_id</code>, page size 20, <code>Link</code>\nheader, bare entity).</p>\n<p><strong>Nineteen of <code>LocalController</code>&#39;s 31 routes had no caller anywhere in <code>src/</code></strong>,\nincluding all eight <code>/api/v1/stream/*</code> and <code>/account/{username}/stream</code>\nendpoints — the ones backed by the <code>_dep</code> query methods. They were marked\ndeprecated in <a href=\"API.md\">API.md</a> for a release and are <strong>removed in 0.19.39</strong>,\nwith the whole query layer behind them: the nine <code>StreamService::getStream*()</code>\nmethods and the seven <code>StreamRequest::getTimeline*_dep()</code> / <code>getTimelineLiked()</code>\n/ <code>getTimelineTag()</code> queries. API.md keeps the table of what replaced them. The\ntwelve routes the frontend does call stay.</p>\n<h2 id=\"routes-are-attributes-now\">Routes are attributes now</h2>\n<p>201 of the 202 routes moved onto the methods they belong to; one stays in\n<code>appinfo/routes.php</code>, and the file explains why. <code>/api/v1/accounts/{id}</code> accepts\nslashes, so it also matches two routes that live in other controllers and has to\nbe offered to the matcher after them — and attribute routes are contributed one\ncontroller at a time in filesystem order, so no arrangement of attributes can\nput it last. The array file is loaded after every attribute route, which is the\nguarantee that one route needs.</p>\n<p><code>tests/DocumentationTest.php</code> reads the attributes by reflection the way the\nserver does, and treats an empty route table as a failure rather than a pass.</p>\n<hr>\n","toc":[{"id":"routes-are-attributes-now","text":"Routes are attributes now","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"two-api-generations-in-one-url-namespace","manual":false,"prev":{"path":"/docs/debt-age-of-the-code","title":"Age of the code"},"next":{"path":"/docs/debt-schema-and-migrations","title":"Schema and migrations"},"parent":null},{"slug":"debt-schema-and-migrations","path":"/docs/debt-schema-and-migrations","title":"Schema and migrations","description":"Performance.md covers query behaviour and the index and schema-shape hazards. What follows is the debt in the migration set itself.","group":"project","html":"<p><code>Performance.md</code> covers query behaviour and the index and schema-shape hazards.\nWhat follows is the debt in the migration set itself.</p>\n<p>All 43 schema steps use the frozen prefix <code>Version1000Date</code>, so only the date\norders them:</p>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Era</th>\n<th>Steps</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>2022-11-18</td>\n<td>1 (creates all 14 original tables)</td>\n</tr>\n<tr>\n<td>2026-06-11</td>\n<td>1 (drops 14 legacy <code>social_3_*</code> tables)</td>\n</tr>\n<tr>\n<td>2026-09-07 onward</td>\n<td>40</td>\n</tr>\n</tbody></table></div>\n<p>There are numbering gaps at <code>20260911000003</code>, <code>000012</code> and <code>000015</code>–<code>000019</code>,\nand most steps were authored in an eight-day window.</p>\n<p>The 2023 block is gone: its three steps repaired instances the 2022 step had\ncreated, and the 2022 step had been edited over the years to produce the\nrepaired shape directly, so what they still did for a new instance was one\ncolumn. Running both paths through the test doubles and diffing the schemas is\nwhat established that.</p>\n<p>One squash candidate is left and is deliberately not taken.\n<code>Version1000Date20260908000001</code> widens a column introduced one day earlier, and\nboth shipped in 0.16.0 — but an instance on 0.15 running Aloha 35 has run\nneither, so folding the width into the creating step would leave it with a\ncolumn too narrow for its own client secrets. The argument that retired the 2023\nsteps does not transfer: the Aloha floor says which server an instance is\non, not which version of this app.</p>\n<p>The drop of fourteen <code>social_3_*</code> tables that <strong>no other file in the tree ever\ncreates</strong> went with the squash: the creating migrations had been deleted long\nbefore, only the drop survived, and it was dead weight on every fresh install.\nThe legacy naming split it addressed is finished — there is no <code>social_a2_*</code>\nprefix anywhere, and all 61 current tables are both read and written.</p>\n<p><code>tests/Migration/schema.json</code> records what the history produced, and\n<code>SquashedSchemaTest</code> holds the one step that replaces it to that. That is what\nany further change to the schema has to go through.</p>\n<h2 id=\"two-columns-written-and-never-read\">Two columns written and never read</h2>\n<p><code>social_stream_dest.id</code> and <code>social_stream_tag.id</code> are autoincrement surrogate\nkeys. The new tests record why they exist: both tables shipped in 2022 with no\nprimary key at all, only a unique index over the columns that identify a row.\nNeither <code>id</code> appears in the column lists in <code>CoreRequestBuilder</code> nor in the\nselect lists of their request builders. These are the two highest-insert-rate\nside tables in the app, and every row pays for a sequence and an index write\nnothing reads. The keys are still worth having — this is a note on the cost.</p>\n<hr>\n","toc":[{"id":"two-columns-written-and-never-read","text":"Two columns written and never read","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"schema-and-migrations","manual":false,"prev":{"path":"/docs/debt-two-api-generations-in-one-url-namespace","title":"Two API generations in one URL namespace"},"next":{"path":"/docs/debt-frontend","title":"Frontend"},"parent":null},{"slug":"debt-frontend","path":"/docs/debt-frontend","title":"Frontend","description":"Still Options API. There are setup() blocks now, because the composables need them, but no <script setup> and no wholesale move to composition. That is a style question rather than debt…","group":"project","html":"<p><strong>Still Options API.</strong> There are <code>setup()</code> blocks now, because the composables\nneed them, but no <code>&lt;script setup&gt;</code> and no wholesale move to composition. That is\na style question rather than debt: the components are consistent with each other.</p>\n<p><strong>The JSDoc typedefs are checked.</strong> <code>jsconfig.json</code> runs <code>checkJs</code> over the\ntypes, services, stores and utilities, and <code>npm run typecheck</code> is a script.\nThe single-file components are checked by <code>vue-tsc</code> in the same script, and\nboth checks allow no errors. There was a baseline of 265 while the components\nwere brought up to it; it is gone, along with the tooling that compared against\nit.</p>\n<p><strong>Five ESLint rules are switched off</strong>, and <code>eslint.config.mjs</code> says why next to\neach. Sorting imports and named imports (247 reports) detaches\nthe comments that explain the side-effect imports; the two component-naming\nrules (8 reports) would rename <code>Search.vue</code>, <code>Poll.vue</code> and friends, which\nchanges what templates say. Neither pair is formatting, which is why they were\nnot taken with the rest. <code>vue/no-boolean-default</code> (10 reports) would turn every\nprop that defaults to true into a negation — <code>link</code> into <code>noLink</code> — at every\ncall site. And <code>vue/no-multiple-template-root</code> is off because this app mounts\nseveral roots and the rule is a Vue 2 leftover. Everything else is on, and the\ntree reports no warnings.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"frontend","manual":false,"prev":{"path":"/docs/debt-schema-and-migrations","title":"Schema and migrations"},"next":{"path":"/docs/debt-toolchain","title":"Toolchain"},"parent":null},{"slug":"debt-toolchain","path":"/docs/debt-toolchain","title":"Toolchain","description":"PHPUnit 12, with the mock hygiene it asks for. A double nothing sets an expectation on is a createStub() (about 1,400 of them were createMock()), and the ActivityPub dispatcher the model…","group":"project","html":"<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Tool</th>\n<th>Pinned</th>\n<th>Status</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>nextcloud/ocp</code></td>\n<td><code>dev-stable35</code></td>\n<td>Matches the declared minimum, so analysis checks this app against the oldest server it claims to support.</td>\n</tr>\n<tr>\n<td>PHPUnit</td>\n<td><code>^12.5</code> (12.5.36)</td>\n<td>Current.</td>\n</tr>\n<tr>\n<td>Psalm</td>\n<td><code>^6.17</code></td>\n<td>Current, running on supported PHP. Its baseline covers six files and seven issues, none of them in <code>lib/Db</code>.</td>\n</tr>\n<tr>\n<td>ESLint</td>\n<td>10.10.0 with <code>@nextcloud/eslint-config</code> 9</td>\n<td>Current, flat config, five rules deliberately off, no warnings.</td>\n</tr>\n<tr>\n<td>Stylelint</td>\n<td><code>^17.15</code></td>\n<td>Current.</td>\n</tr>\n<tr>\n<td>Vitest / jsdom</td>\n<td>5.0 / 30.0</td>\n<td>Current.</td>\n</tr>\n<tr>\n<td>webpack / vue-router / vite</td>\n<td>5.110 / 5.3 / 8.3</td>\n<td>Current.</td>\n</tr>\n<tr>\n<td><code>node-polyfill-webpack-plugin</code></td>\n<td>exactly <code>4.0.0</code></td>\n<td><strong>Blocked upstream.</strong> <code>@nextcloud/webpack-vue-config</code> 6.3.2 peer-pins it; 4.1.0 needs a release there first.</td>\n</tr>\n</tbody></table></div>\n<p><strong>PHPUnit 12, with the mock hygiene it asks for.</strong> A double nothing sets an\nexpectation on is a <code>createStub()</code> (about 1,400 of them were <code>createMock()</code>),\nand the ActivityPub dispatcher the model tests install builds stubs unless a\ntest names the interfaces it expects calls on. What still warns is the shared\nfixture — a mock built once in <code>setUp()</code> that some tests of the class expect on\nand others only stub — and those classes carry\n<code>#[AllowMockObjectsWithoutExpectations]</code>, which is PHPUnit&#39;s own answer to that\nshape. The suite runs in about 190 MB.</p>\n<p><code>terser-webpack-plugin</code> is a direct devDependency because webpack 5.110 stopped\nhoisting it where <code>@nextcloud/webpack-vue-config</code> expects to find it. Worth\nknowing that the build depends on the shared webpack config&#39;s internal layout in\nmore places than that one.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"toolchain","manual":false,"prev":{"path":"/docs/debt-frontend","title":"Frontend"},"next":{"path":"/docs/debt-remaining-odds-and-ends","title":"Remaining odds and ends"},"parent":null},{"slug":"debt-remaining-odds-and-ends","path":"/docs/debt-remaining-odds-and-ends","title":"Remaining odds and ends","description":"20 @deprecated markers in lib/, 12 of them on methods with live callers, led by CoreRequestBuilder::leftJoinStreamAction (17) and SocialLimitsQueryBuilder::limitPaginate (8). The worst of…","group":"project","html":"<p><strong>20 <code>@deprecated</code> markers in <code>lib/</code>, 12 of them on methods with live callers</strong>,\nled by <code>CoreRequestBuilder::leftJoinStreamAction</code> (17) and\n<code>SocialLimitsQueryBuilder::limitPaginate</code> (8). The worst of them went with the\nrequest model — <code>Request::getUrl</code> had 55 callers and had been deprecated since\ntoolkit version 19 — and what is left is concentrated in the query layer.\n<code>ACore::verify</code> still carries its <code>// TODO - Compare this with checkOrigin() - and delete this method.</code> and is down to three callers.</p>\n<p><strong>Two joins that look like one.</strong> <code>CoreRequestBuilder::leftJoinCacheActors()</code>\njoins case-insensitively on the full ActivityPub URL with a hand-written column\nlist; <code>SocialCrossQueryBuilder::leftJoinCacheActor()</code> joins on the indexed\nhashed id, generates its column list from the schema, and pulls the actor&#39;s icon\nwith it. The first is the older, slower path — <code>LOWER()</code> on unindexed text, as\n<code>Performance.md</code> describes. Collapsing them changes which rows match, in\ntimeline queries, so it wants a database to check against.</p>\n<p><strong>Constructor promotion is at 151 of 206 (73 %).</strong> The remaining 56 are the ones\nan automated pass should not touch: constructors that do real work in the body,\nthat forward a parameter to a parent as well as storing it, or whose property\nname differs from the parameter.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"remaining-odds-and-ends","manual":false,"prev":{"path":"/docs/debt-toolchain","title":"Toolchain"},"next":{"path":"/docs/debt-translations","title":"Translations"},"parent":null},{"slug":"debt-translations","path":"/docs/debt-translations","title":"Translations","description":"The frontend contains 295 distinct translatable strings. The best-covered locales (de, de_DE, en_GB) carry 135. The median locale across 98 languages carries 21, and 47 carry fewer than…","group":"project","html":"<p>The frontend contains 295 distinct translatable strings. The best-covered\nlocales (<code>de</code>, <code>de_DE</code>, <code>en_GB</code>) carry 135. The median locale across 98\nlanguages carries 21, and 47 carry fewer than 20. The strings <code>Quote</code>,\n<code>Bookmark</code>, <code>Scheduled</code>, <code>Announcement</code>, <code>Follow requests</code> and <code>Photos</code> appear\nin <strong>zero</strong> translation files.</p>\n<p>The cause is diagnosed in the header of <code>.github/workflows/l10n.yml</code>: nothing in\nthe repository ever extracted the source strings, so nothing was ever pushed for\ntranslation. <code>.tx/config</code> is correct as written — <code>translationfiles/</code> is what\nthe extractor produces, not something the repository holds. The workflow now\nexists; the catalogue has not caught up, and that is a Transifex round trip\nrather than a code change.</p>\n<p>The extraction itself has been run and checked: it reads all 1,625 source\nstrings, and <code>tests/TranslatableStringsTest.php</code> now guards the three ways a\nstring can be written so that it never reaches a translator — a message used\nboth as a singular and as the singular of a plural, which gettext folds into\none entry <code>t()</code> cannot look up; a message that is only a URL or an address,\nwhich ninety-eight locales can only copy back; and a message that is not a\nliteral, which <code>xgettext</code> cannot see at all. Two of those were present and are\nfixed.</p>\n<p>What remains is the one thing outside the repository: <code>TRANSIFEX_API_TOKEN</code> is\nnot set, so <code>l10n.yml</code> extracts and uploads the template as a build artefact\nbut pushes nothing, and <code>l10n-pull.yml</code> does nothing at all. Setting that\nsecret — or registering this app with the organisation&#39;s own translation sync —\nis the whole of the remaining work.</p>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"translations","manual":false,"prev":{"path":"/docs/debt-remaining-odds-and-ends","title":"Remaining odds and ends"},"next":{"path":"/docs/debt-what-is-not-debt","title":"What is not debt"},"parent":null},{"slug":"debt-what-is-not-debt","path":"/docs/debt-what-is-not-debt","title":"What is not debt","description":"**Classes from outside OCP\\: none.** No OC\\DB\\QueryBuilder\\QueryBuilder, no \\OC::$server, no OC\\SystemConfig, no Doctrine\\DBAL\\Query\\QueryBuilder. The only matches are docblock sentences…","group":"project","html":"<p>Each item here is a search that does not need repeating.</p>\n<p>**Classes from outside <code>OCP\\</code>: none.** No <code>OC\\DB\\QueryBuilder\\QueryBuilder</code>, no\n<code>\\OC::$server</code>, no <code>OC\\SystemConfig</code>, no <code>Doctrine\\DBAL\\Query\\QueryBuilder</code>. The\nonly matches are docblock sentences explaining what was removed.</p>\n<p><strong>Untyped properties: none.</strong> All 35 were typed, including six mutable public\nstatics in <code>TArrayTools</code> that were constants in everything but name.</p>\n<p><strong>Deprecated server APIs: none.</strong> <code>IConfig</code>&#39;s app-value methods (deprecated in\n29) and user-value methods (deprecated in 33) are gone in favour of <code>IAppConfig</code>\nand <code>IUserConfig</code>; <code>IConfig</code> is used only for system values, which are not\ndeprecated.</p>\n<p><strong>Vue 2 leftovers: none.</strong> <code>Vue.prototype</code>, <code>new Vue(</code>, <code>$listeners</code>,\n<code>$set</code>/<code>$delete</code>, <code>.sync</code>, <code>filters:</code>, <code>beforeDestroy</code>, <code>functional: true</code> and\n<code>slot-scope</code> all return zero hits in <code>src/</code>. The only occurrences anywhere are\nthe regexes in <code>tests/js/vue3.test.js</code>, which holds each at zero. Vuex is gone\ntoo.</p>\n<p><strong>PHPDoc route annotations: none.</strong> Access control is 100 % PHP 8 attributes,\nwith a regression test asserting the old form is not reintroduced.</p>\n<p><strong>Legacy PHP constructs: none.</strong> Zero occurrences of <code>array()</code>, <code>list()</code>,\n<code>strftime</code>, <code>utf8_encode</code>, <code>each()</code>, <code>create_function</code>, <code>ereg*</code> or\n<code>money_format</code>. No dynamic property creation.</p>\n<p><strong>Raw SQL string concatenation: effectively none.</strong> Not one\n<code>SELECT</code>/<code>INSERT</code>/<code>UPDATE</code>/<code>DELETE</code> string literal in <code>lib/</code>; all <code>IDBConnection</code>\nuses go through the query builder. The single exception is the visibility filter\nin <code>SocialCrossQueryBuilder</code>, which binds its parameters.</p>\n<p><strong>Legacy bootstrap: none.</strong> No <code>appinfo/app.php</code>, no <code>appinfo/application.php</code>.\n<code>lib/AppInfo/Application.php</code> is 71 lines of correct <code>IBootstrap</code> registration.</p>\n<p><strong><code>@nextcloud/vue</code> v9 usage: current.</strong> All 74 imports use the v9 subpath-export\nstyle; zero deep <code>dist/</code> imports, zero removed or renamed components.</p>\n<p><strong>Unlinted code: none.</strong> <code>npm run lint</code> covers <code>src</code>, <code>tests/js</code>, the end-to-end\ntests and the root configuration; <code>npm run stylelint</code> covers <code>src</code> and <code>css</code>.\nNothing in <code>js/</code> is hand-written any more: the administration page was the last\nscript there, and it is a webpack entry like every other now.</p>\n<p><strong>Dead frontend code: none.</strong> The import graph over all 100 files in <code>src/</code>\nresolves, and there are no unused exports.</p>\n<p><strong>Dead model classes: none</strong> (77 checked). <strong>Dead exception classes: none</strong> (48\nchecked). <strong>Unused controllers: none</strong> (28 checked; <code>ClientApiController</code> is the\nabstract base of sixteen of them and <code>SocialPubController</code> is called by\n<code>ActivityPubController</code> rather than routed to).</p>\n<p><strong>Repair steps that re-scan on every upgrade: none.</strong> All five carry a version\nmarker in app config and return early.</p>\n<h2 id=\"a-trap-worth-knowing-before-you-audit-this-app\">A trap worth knowing before you audit this app</h2>\n<p>Aloha controller methods are <strong>admin-required by default</strong> —\n<code>SecurityMiddleware</code> enforces it unless the method carries <code>#[NoAdminRequired]</code>\nor <code>#[PublicPage]</code>. The <em>absence</em> of an attribute is the guard, not a missing\none. Reading the routes as if the attributes grant access rather than relax it\nproduces a long list of false &quot;unauthenticated endpoint&quot; findings.</p>\n<h2 id=\"and-one-about-measuring\">And one about measuring</h2>\n<p>Do not measure this app on a working copy without checking it against a fresh\nclone first. An earlier pass of this report was taken on a checkout hundreds of\ncommits behind <code>origin/master</code>: it reported ten untested controllers that in\nfact have tests, put 45 % of <code>lib/</code> in 2023 or earlier when the real figure is\ndifferent, and recorded a failing test suite that is green on master. Counting\n&quot;dead&quot; methods without treating tests as callers likewise put the figure near\nsixty when twenty survive the check.</p>\n<hr>\n","toc":[{"id":"a-trap-worth-knowing-before-you-audit-this-app","text":"A trap worth knowing before you audit this app","level":2},{"id":"and-one-about-measuring","text":"And one about measuring","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"what-is-not-debt","manual":false,"prev":{"path":"/docs/debt-translations","title":"Translations"},"next":{"path":"/docs/debt-what-has-been-done","title":"What has been done"},"parent":null},{"slug":"debt-what-has-been-done","path":"/docs/debt-what-has-been-done","title":"What has been done","description":"tag, language, updated, quote and quoteAuthorization are columns on social_stream, written where a row is written and read with a per-field fallback to the stored JSON, with a repair step…","group":"project","html":"<h2 id=\"in-2127\">In <a href=\"https://github.com/alohasocial/social/pull/2127\">#2127</a></h2>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Outcome</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Source maps in the release tarball</td>\n<td>Excluded. The tarball was ~22 MB of maps against 6.7 MB of bundles.</td>\n</tr>\n<tr>\n<td>Three disagreeing packaging lists</td>\n<td>One list. <code>build-package.sh</code> calls <code>make appstore</code>; <code>.nextcloudignore</code> deleted.</td>\n</tr>\n<tr>\n<td>The <code>elliptic</code> stub</td>\n<td>Replaced with an <code>overrides</code> pin on the real <code>^6.6.1</code>. The stub claimed a version that has never existed on the registry.</td>\n</tr>\n<tr>\n<td>Cypress husk</td>\n<td>Deleted: 8 files, 1 config, 4 npm scripts, 6 packages, 0 tests.</td>\n</tr>\n<tr>\n<td>Unused npm dependencies</td>\n<td><code>ical.js</code>, <code>uuid</code>, <code>cypress-wait-until</code>, <code>@nextcloud/cypress</code> dropped; <code>buffer</code> and <code>webpack-dev-server</code> declared.</td>\n</tr>\n<tr>\n<td>Dead code</td>\n<td>3 files and 20 methods with no caller anywhere, 4 dead config constants, an 80-line commented-out block, 4 obsolete Psalm suppressions.</td>\n</tr>\n<tr>\n<td>Repair steps re-scanning on every upgrade</td>\n<td>Markers added; <code>RenameDocumentLocalCopy</code> unregistered and deleted.</td>\n</tr>\n<tr>\n<td>Missing indexes</td>\n<td><code>social_actor.user_id</code> and the four unindexed <code>trend_*</code> windows.</td>\n</tr>\n<tr>\n<td>Status-id collisions</td>\n<td>Width 1e6 -&gt; 1e9, <code>rand()</code> -&gt; <code>random_int()</code>, and a collision is retried instead of silently dropping the post.</td>\n</tr>\n<tr>\n<td><code>IInitialStateService</code></td>\n<td>Migrated to <code>IInitialState</code> in four controllers.</td>\n</tr>\n<tr>\n<td><code>Cron\\Queue</code></td>\n<td>Given the wall-clock budget <code>QueueController</code> already had.</td>\n</tr>\n<tr>\n<td>The <code>AP</code> static registry</td>\n<td>Resolved lazily instead of by an <code>AP::init();</code> at file scope.</td>\n</tr>\n<tr>\n<td>Unreachable controller methods</td>\n<td>Six deleted from <code>LocalController</code>.</td>\n</tr>\n<tr>\n<td>Two unbounded loops</td>\n<td><code>NotificationService::clear()</code> and <code>MigrationService::refollowLocalFollowers()</code> bounded.</td>\n</tr>\n<tr>\n<td>The rest of the unbounded work</td>\n<td>Closed in <a href=\"https://github.com/alohasocial/social/pull/2132\">#2132</a>, with the N+1 behind <code>accounts/relationships</code> and the missing transaction around <code>StreamRequest::save()</code>. See <a href=\"/docs/performance\">Performance.md</a>, which tracks that category.</td>\n</tr>\n<tr>\n<td><code>tests/stub.phpstub</code></td>\n<td><code>QueryBuilder::SELECT</code> was the string <code>&#39;select&#39;</code>; Doctrine assigns the int <code>0</code>, so 28 comparisons were verified against fiction. Fixed and pinned by a test.</td>\n</tr>\n<tr>\n<td>Psalm 5 -&gt; 6</td>\n<td>Now runs on supported PHP. Found five real type defects and five orphaned access-control attributes.</td>\n</tr>\n<tr>\n<td>Stylelint 15 -&gt; 17</td>\n<td>Seven deprecated CSS declarations removed.</td>\n</tr>\n<tr>\n<td>Constructor promotion</td>\n<td>107 -&gt; 148 of 204, and 264 redundant <code>@param</code> tags removed with it.</td>\n</tr>\n<tr>\n<td><code>HtmlSanitizer</code>, <code>RemoteAddress</code></td>\n<td>Moved from <code>lib/Tools/</code> to <code>lib/Security/</code>.</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"since-then\">Since then</h2>\n<ul>\n<li><strong>Delivery sends the stored bytes</strong> (0.19.39). <code>ActivityService::bodyFromQueue()</code>\nreturned <code>json_encode(json_decode(...))</code>; it returns the queued string. What\nthis instance writes is encoded once at queue time, so nothing it sends\nchanges; what <code>ForwardService</code> queues verbatim now arrives verbatim, which is\nthe only way a third party&#39;s Linked Data signature survives.</li>\n<li><strong>The superseded Custom Local API is gone</strong> (0.19.39): nineteen routes, the\nnine <code>getStream*()</code> methods and the seven <code>_dep</code> queries, and their tests.</li>\n<li><strong>A browser-test layer</strong> (0.19.58): <code>tests/e2e/</code> and <code>.github/workflows/e2e.yml</code>\n— Playwright against a throwaway Aloha on every pull request. 1,500 unit\ntests and an integration suite could not see a page that stays empty because\na bundle did not load; the smoke suite can.</li>\n</ul>\n<div class=\"md-table\"><table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Outcome</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ESLint 8 (end of life)</td>\n<td><a href=\"https://github.com/alohasocial/social/pull/2129\">#2129</a>: ESLint 10, <code>@nextcloud/eslint-config</code> 9, flat config.</td>\n</tr>\n<tr>\n<td>Nine conflicting dependabot bumps</td>\n<td><a href=\"https://github.com/alohasocial/social/pull/2130\">#2130</a>: vue 3.5.42, webpack 5.110, jsdom 30, vue-router 5 with vite 8 behind it, dialogs 7.5.</td>\n</tr>\n</tbody></table></div>\n<h2 id=\"in-this-wave\">In this wave</h2>\n<h2 id=\"the-five-post-fields-with-no-column\">The five post fields with no column</h2>\n<p><code>tag</code>, <code>language</code>, <code>updated</code>, <code>quote</code> and <code>quoteAuthorization</code> are columns on <code>social_stream</code>, written where a row is written and read with a per-field fallback to the stored JSON, with a repair step backfilling existing rows behind a version marker. <code>language</code> is indexed, which is what a language filter needs.</p>\n<h2 id=\"the-private-core-class-under-the-whole-data-layer\">The private core class under the whole data layer</h2>\n<p><code>ExtendedQueryBuilder</code> holds a builder from <code>IDBConnection::getQueryBuilder()</code> and delegates all 60 <code>IQueryBuilder</code> methods instead of extending <code>OC\\DB\\QueryBuilder\\QueryBuilder</code>. The <code>\\OC::$server</code> reach that fed its private parent is gone, and so are the four <code>Doctrine\\DBAL\\Query\\QueryBuilder</code> imports that existed only to read four constants. Aloha 35 had already broken the old arrangement by adding <code>forUpdate()</code> to the interface.</p>\n<h2 id=\"the-support-floors\">The support floors</h2>\n<p>PHP 8.1 -&gt; 8.3, Aloha 28 -&gt; 35, with <code>composer.json</code>&#39;s platform pin and constraint following.</p>\n<h2 id=\"nextcloud-ocp-two-years-stale\">nextcloud/ocp two years stale</h2>\n<p><code>dev-master</code> at a 2024-10-23 commit -&gt; <code>dev-stable35</code>.</p>\n<h2 id=\"override-unavailable\">#[\\Override] unavailable</h2>\n<p>343 methods carry it; the psalm suppression that named the 8.1 floor is gone.</p>\n<h2 id=\"iconfig-deprecated-methods\">IConfig deprecated methods</h2>\n<p><code>IAppConfig</code> and <code>IUserConfig</code> in five files.</p>\n<h2 id=\"phpunit-9-end-of-life\">PHPUnit 9 (end of life)</h2>\n<p>12.5, via 10. Every data provider static and named by attribute, <code>withConsecutive()</code> and <code>onConsecutiveCalls()</code> rewritten, <code>isType()</code> gone, config migrated.</p>\n<h2 id=\"test-doubles-drifting-from-the-interfaces-they-double\">Test doubles drifting from the interfaces they double</h2>\n<p><code>FakeConnection</code> completed; ten hand-rolled anonymous table classes replaced by one <code>FakeTable</code>; the test container serves an anonymous session because <code>Response</code> resolves one on every render from 35 onward.</p>\n<h2 id=\"vuex-4-no-pinia\">Vuex 4, no Pinia</h2>\n<p>Five Pinia stores, <code>mapStores</code> at the call sites, <code>vuex</code> removed.</p>\n<h2 id=\"three-mixins-four-spellings-of-one-import\">Three mixins, four spellings of one import</h2>\n<p>Three composables in <code>src/composables/</code>.</p>\n<h2 id=\"dead-pre-aloha-25-profile-branch\">Dead pre-Aloha-25 profile branch</h2>\n<p>Deleted.</p>\n<h2 id=\"oc-notification-showtemporary\">OC.Notification.showTemporary</h2>\n<p><code>@nextcloud/dialogs</code>, imported lazily so the Vue-free admin bundle stays 28 KiB rather than 761 KiB.</p>\n<h2 id=\"nineteen-deferred-eslint-rules\">Nineteen deferred ESLint rules</h2>\n<p>Sixteen adopted, ~1,100 reports fixed. Three stay off with the reason next to each.</p>\n<h2 id=\"unlinted-code\">Unlinted code</h2>\n<p>The hand-written admin script and the root configuration are linted; <code>css/</code> is stylelinted.</p>\n<h2 id=\"35-untyped-properties\">35 untyped properties</h2>\n<p>Zero. Six mutable public statics became constants.</p>\n<h2 id=\"the-20222023-migrations-untested\">The 2022–2023 migrations, untested</h2>\n<p><code>CoreSchemaTest</code>, which asks the installed schema rather than one step.</p>\n<h2 id=\"private-core-classes-elsewhere-in-lib\">Private core classes elsewhere in lib/</h2>\n<p><code>OC\\DB\\Connection</code> (a dead import), <code>OC\\DB\\SchemaWrapper</code> (two <code>occ social:reset</code> paths, now <code>IDBConnection::tableExists()</code>/<code>dropTable()</code>), <code>Doctrine\\DBAL\\Schema\\SchemaException</code> (the OCP one exists) and <code>OC\\User\\NoUserException</code> (thrown by this app at this app, now its own). Six analysis suppressions went with them.</p>\n<h2 id=\"every-occ-command-on-a-private-core-class\">Every occ command on a private core class</h2>\n<p>All twenty-one extend Symfony&#39;s <code>Command</code> through the app&#39;s own <code>SocialCommand</code>, whose output is byte-identical to the server&#39;s <code>Base</code> across 109 diffed cases and the rendered <code>--help</code> of every command.</p>\n<h2 id=\"routes-as-an-array\">Routes as an array</h2>\n<p>201 of 202 moved onto the methods; <code>DocumentationTest</code> reads the attributes by reflection and fails on an empty table.</p>\n<h2 id=\"the-2023-migration-repairs\">The 2023 migration repairs</h2>\n<p>Squashed into the step they repair, after measuring that the whole difference they still made was one column.</p>\n<h2 id=\"73-migration-files\">73 migration files</h2>\n<p>Seven. The sixty-seven that only shape tables are one generated step, <code>Version1000Date20221118000002</code>; the six that move rows are untouched. It was generated by replaying the history against a recording schema, <code>tests/Migration/schema.json</code> is that replay&#39;s output, and <code>SquashedSchemaTest</code> fails if the two ever part. Every step in it is guarded, so it brings up an empty database, completes a half-upgraded one and does nothing on a current one — there is no floor on the version an instance may upgrade from.</p>\n<h2 id=\"corerequestbuilder-reimplementing-the-builders-helpers\">CoreRequestBuilder reimplementing the builder&#39;s helpers</h2>\n<p>36 methods gone — eleven with no caller, twenty-five identical to the builder&#39;s — and 84 call sites now say <code>$qb-&gt;limitToId($id)</code>. The file lost 450 lines.</p>\n<h2 id=\"typedefs-nothing-checked\">Typedefs nothing checked</h2>\n<p><code>jsconfig.json</code> plus <code>npm run typecheck</code>, which found a placeholder relationship missing two fields the server always sends, and a pagination cursor typed as a number while ids are strings.</p>\n<h2 id=\"the-hand-rolled-http-request-model\">The hand-rolled HTTP request model</h2>\n<p>Deleted. Requests go to <code>IClient</code> directly, and the signing string was pinned by a test run against both trees before and after — byte for byte identical.</p>\n<h2 id=\"real-defects-found-on-the-way\">Real defects found on the way</h2>\n<p>An instance&#39;s <code>local</code> flag was bound as a string because a parameter type was passed to the wrong function. <code>Profile.vue</code>&#39;s &quot;User not found&quot; panel could never appear because one query was being asked twice under two names. And GET <code>/@{username}/outbox</code> was shadowed by its own POST, because two route attributes on one method registered under one name — the endpoint a remote server fetches an outbox from was served by the registration the documentation calls not implemented. Pinning the federation wire found five more: a delivery that signed one path and sent to another, a non-default port silently dropped when fetching a remote object, a <code>?tag[]=</code> in an id that was a TypeError, a report forward whose digest covered different bytes from the ones sent, and a webfinger response with no subject writing a garbage account name.</p>\n<hr>\n","toc":[{"id":"in-2127","text":"In #2127","level":2},{"id":"since-then","text":"Since then","level":2},{"id":"in-this-wave","text":"In this wave","level":2},{"id":"the-five-post-fields-with-no-column","text":"The five post fields with no column","level":2},{"id":"the-private-core-class-under-the-whole-data-layer","text":"The private core class under the whole data layer","level":2},{"id":"the-support-floors","text":"The support floors","level":2},{"id":"nextcloud-ocp-two-years-stale","text":"nextcloud/ocp two years stale","level":2},{"id":"override-unavailable","text":"#[\\Override] unavailable","level":2},{"id":"iconfig-deprecated-methods","text":"IConfig deprecated methods","level":2},{"id":"phpunit-9-end-of-life","text":"PHPUnit 9 (end of life)","level":2},{"id":"test-doubles-drifting-from-the-interfaces-they-double","text":"Test doubles drifting from the interfaces they double","level":2},{"id":"vuex-4-no-pinia","text":"Vuex 4, no Pinia","level":2},{"id":"three-mixins-four-spellings-of-one-import","text":"Three mixins, four spellings of one import","level":2},{"id":"dead-pre-aloha-25-profile-branch","text":"Dead pre-Aloha-25 profile branch","level":2},{"id":"oc-notification-showtemporary","text":"OC.Notification.showTemporary","level":2},{"id":"nineteen-deferred-eslint-rules","text":"Nineteen deferred ESLint rules","level":2},{"id":"unlinted-code","text":"Unlinted code","level":2},{"id":"35-untyped-properties","text":"35 untyped properties","level":2},{"id":"the-20222023-migrations-untested","text":"The 2022–2023 migrations, untested","level":2},{"id":"private-core-classes-elsewhere-in-lib","text":"Private core classes elsewhere in lib/","level":2},{"id":"every-occ-command-on-a-private-core-class","text":"Every occ command on a private core class","level":2},{"id":"routes-as-an-array","text":"Routes as an array","level":2},{"id":"the-2023-migration-repairs","text":"The 2023 migration repairs","level":2},{"id":"73-migration-files","text":"73 migration files","level":2},{"id":"corerequestbuilder-reimplementing-the-builders-helpers","text":"CoreRequestBuilder reimplementing the builder's helpers","level":2},{"id":"typedefs-nothing-checked","text":"Typedefs nothing checked","level":2},{"id":"the-hand-rolled-http-request-model","text":"The hand-rolled HTTP request model","level":2},{"id":"real-defects-found-on-the-way","text":"Real defects found on the way","level":2}],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"what-has-been-done","manual":false,"prev":{"path":"/docs/debt-what-is-not-debt","title":"What is not debt"},"next":{"path":"/docs/debt-rough-order-of-value-for-what-is-left","title":"Rough order of value for what is left"},"parent":null},{"slug":"debt-rough-order-of-value-for-what-is-left","path":"/docs/debt-rough-order-of-value-for-what-is-left","title":"Rough order of value for what is left","description":"Aloha Social documentation.","group":"project","html":"<ol>\n<li>Collapse the two cache-actor joins, with a database to check against.</li>\n<li>Finish the l10n round trip — a Transifex round trip, not a code change.</li>\n<li>Web Push and a streaming API, so mobile clients stop polling.</li>\n</ol>\n<hr>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"rough-order-of-value-for-what-is-left","manual":false,"prev":{"path":"/docs/debt-what-has-been-done","title":"What has been done"},"next":{"path":"/docs/debt-reproducing-the-measurements","title":"Reproducing the measurements"},"parent":null},{"slug":"debt-reproducing-the-measurements","path":"/docs/debt-reproducing-the-measurements","title":"Reproducing the measurements","description":"Aloha Social documentation.","group":"project","html":"<pre><code class=\"language-bash\"># The support floors, and the places that should agree with them\ngrep -oE &#39;(php|nextcloud) min-version=&quot;[^&quot;]+&quot; max-version=&quot;[^&quot;]+&quot;&#39; appinfo/info.xml\ngrep -nE &#39;&quot;php&quot;: |platform&#39; composer.json | head -3\ngrep -rn &#39;php min-version\\|nextcloud-version-matrix&#39; .github/workflows/*.yml | wc -l\n\n# Sizes\nfind lib -name &#39;*.php&#39; | wc -l &amp;&amp; find lib -name &#39;*.php&#39; -exec cat {} + | wc -l\nfind src -type f \\( -name &#39;*.js&#39; -o -name &#39;*.vue&#39; \\) | wc -l\n\n# Classes from outside OCP\\ (expect only docblock prose)\ngrep -rn &#39;OC\\\\DB\\\\QueryBuilder\\\\QueryBuilder\\|OC::\\$server\\|OC\\\\SystemConfig\\|Doctrine\\\\DBAL\\\\Query&#39; lib --include=&#39;*.php&#39;\n\n# Untyped properties (expect 0)\ngrep -rnE &#39;^\\s*(var|private|protected|public|static|readonly)(\\s+(static|readonly))*\\s+\\$\\w+&#39; lib --include=&#39;*.php&#39; | wc -l\n\n# Deprecated server config APIs (expect 0)\ngrep -rn &#39;config-&gt;getAppValue\\|config-&gt;setAppValue\\|config-&gt;getUserValue\\|config-&gt;setUserValue&#39; lib --include=&#39;*.php&#39; | wc -l\n\n# @deprecated methods that still have callers\ngrep -rn &#39;@deprecated&#39; lib --include=&#39;*.php&#39; | wc -l\ngrep -rn &#39;leftJoinStreamAction(&#39; lib --include=&#39;*.php&#39; | grep -v &#39;function &#39; | wc -l\n\n# Constructor promotion adoption\npython3 - &lt;&lt;&#39;PY&#39;\nimport re, glob\np = n = 0\nfor f in glob.glob(&#39;lib/**/*.php&#39;, recursive=True):\n    for m in re.finditer(r&#39;function\\s+__construct\\s*\\((.*?)\\)\\s*[:{]&#39;, open(f).read(), re.S):\n        a = m.group(1)\n        if re.search(r&#39;\\b(private|protected|public|readonly)\\s&#39;, a): p += 1\n        elif a.strip(): n += 1\nprint(&#39;promoted&#39;, p, &#39;of&#39;, p + n)\nPY\n\n# Custom Local API routes with no caller in src/\npython3 - &lt;&lt;&#39;PY&#39;\nimport re, glob\nroutes = [m.groups() for l in open(&#39;appinfo/routes.php&#39;)\n          if (m := re.search(r&quot;&#39;name&#39; =&gt; &#39;Local#(\\w+)&#39;.*?&#39;url&#39; =&gt; &#39;([^&#39;]+)&#39;&quot;, l))]\nsrc = &#39;&#39;.join(open(p, errors=&#39;replace&#39;).read() for p in glob.glob(&#39;src/**/*&#39;, recursive=True)\n              if p.endswith((&#39;.js&#39;, &#39;.vue&#39;)))\nfor name, url in routes:\n    if url.split(&#39;{&#39;)[0].rstrip(&#39;/&#39;).lstrip(&#39;/&#39;) not in src:\n        print(&#39;uncalled:&#39;, url)\nPY\n\n# Data providers that are not static (expect 0). Matching on the name alone\n# also finds methods like getDatabaseProvider(), so ask which methods the\n# #[DataProvider] attributes actually name.\npython3 - &lt;&lt;&#39;PY&#39;\nimport re, glob\nnamed = set()\nfor f in glob.glob(&#39;tests/**/*.php&#39;, recursive=True):\n    named |= set(re.findall(r&quot;#\\[DataProvider\\(&#39;(\\w+)&#39;\\)\\]&quot;, open(f).read()))\nfor f in glob.glob(&#39;tests/**/*.php&#39;, recursive=True):\n    for m in re.finditer(r&#39;public (static )?function (\\w+)\\(&#39;, open(f).read()):\n        if m.group(2) in named and not m.group(1):\n            print(&#39;not static:&#39;, f, m.group(2))\nPY\n\n# ESLint rules this codebase does not adopt\ngrep -c &quot;&#39;: &#39;off&#39;&quot; eslint.config.mjs\n\n# Translation coverage\ngrep -rhoE &quot;\\b[tn]\\(&#39;social&#39;,\\s*&#39;[^&#39;]*&#39;&quot; src | sort -u | wc -l\npython3 -c &quot;import json,glob; print(sorted((len(json.load(open(f))[&#39;translations&#39;]), f) for f in glob.glob(&#39;l10n/*.json&#39;))[-3:])&quot;\n\n# Suites\ncomposer test:unit &amp;&amp; composer psalm &amp;&amp; composer lint \\\n  &amp;&amp; vendor/bin/php-cs-fixer fix --dry-run \\\n  &amp;&amp; npm run lint &amp;&amp; npm run stylelint &amp;&amp; npm test &amp;&amp; npm run build\n</code></pre>\n","toc":[],"source":"https://github.com/AlohaSocial/social/blob/master/docs/Technical-Debt.md","sections":null,"anchor":"reproducing-the-measurements","manual":false,"prev":{"path":"/docs/debt-rough-order-of-value-for-what-is-left","title":"Rough order of value for what is left"},"next":null,"parent":null},{"slug":"get-started","path":"/get-started","title":"Get started","description":"Find your place on the fediverse and make the first post.","group":"start","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"docs/configuration","path":"/docs/configuration","title":"Configuration reference","description":"All configuration options: occ commands, config.php settings, environment variables and server requirements.","group":"admin","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"docs/maintenance","path":"/docs/maintenance","title":"Maintenance and updates","description":"Upgrades, backups, monitoring and disaster recovery.","group":"admin","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"docs/contributing","path":"/docs/contributing","title":"Contributing","description":"Code style, pull requests, tests and the release workflow.","group":"project","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"developers/docs","path":"/developers/docs","title":"Developer chapters overview","description":"Where the long-form chapters for extending the app live.","group":"developer","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"developers/docs/protocol","path":"/developers/docs/protocol","title":"Protocol chapter","description":"ActivityPub and AT Protocol details, as implemented.","group":"developer","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"developers/docs/federation","path":"/developers/docs/federation","title":"Federation chapter","description":"Server-to-server delivery, retries and propagation.","group":"developer","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"developers/docs/api","path":"/developers/docs/api","title":"API chapter","description":"Endpoints, authentication and response shapes.","group":"developer","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null},{"slug":"developers/docs/operations","path":"/developers/docs/operations","title":"Operations chapter","description":"Deployment, scaling and monitoring of a deployment.","group":"developer","html":"","toc":[],"source":null,"sections":null,"anchor":null,"manual":true,"prev":null,"next":null,"parent":null}];

export const DOC_BY_PATH: Record<string, DocPage> = Object.fromEntries(
  DOC_PAGES.map((page) => [page.path, page]),
);

export function getDocBySlug(slug: string): DocPage | undefined {
  return DOC_BY_PATH[`/docs/${slug}`];
}

export function pagesInGroup(groupId: string): DocPage[] {
  return DOC_PAGES.filter((page) => page.group === groupId);
}
